-- ----------------------------
-- Table structure for audit_task
-- ----------------------------
DROP TABLE IF EXISTS `audit_task`;
CREATE TABLE `audit_task`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `target_id` bigint UNSIGNED NOT NULL COMMENT '被审核对象ID',
  `target_type` tinyint UNSIGNED NOT NULL COMMENT '被审核对象类型, 1-图库作品, 2-话题帖子',
  `api_task_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '审核服务返回的任务ID',
  `media_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '被审核的图片或视频URL',
  `audit_type` tinyint NOT NULL COMMENT '审核类型, 1-图片, 2-视频',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '任务状态: 0-处理中, 1-处理成功, 2-处理失败',
  `result_suggestion` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核建议: pass, review, block',
  `result_details` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核结果详情 (JSON格式)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `uk_api_task_id`(`api_task_id` ASC) USING BTREE,
  INDEX `idx_target_status`(`target_id` ASC, `target_type` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '内容审核异步任务表' ROW_FORMAT = Dynamic;

