-- ----------------------------
-- Table structure for bak_20260901_a105_logistics
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_a105_logistics`;
CREATE TABLE `bak_20260901_a105_logistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `logistics_name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流服务商名称',
  `brand` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流商品牌',
  `phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '服务商电话，如0563-8888888，限30字',
  `logistics_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流方式 1:快递物流; 2:冷链运输; 3:航空运输;',
  `expected_time_str` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '预计送达（省会/一线城市）如：24~36小时',
  `delay_time_num` int UNSIGNED NOT NULL COMMENT '确认送达延后时间(小时h)',
  `is_to_shop` tinyint UNSIGNED NOT NULL COMMENT '是否送货到店 0:不到店需自提; 1:可配送到店; 2:需另付费配送到店',
  `transfer_cost` decimal(10, 2) UNSIGNED NOT NULL COMMENT '航空运输-空运短运费',
  `is_separate_display` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否单独展示 0:否; 1:是;',
  `is_enable` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否启用该配置 0:否; 1:是;',
  `rule_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流规则id',
  `first_heavy` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）计重用：首重(g)  单位(g/扎)',
  `first_heavy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）计重用：首重价格',
  `charge_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）计费类型 1:计重; 2:计件;',
  `continue_heavy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）计重用：续重单价(元/kg)',
  `is_transfer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否中转 0:否; 1:是;',
  `need_pick_fee` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否需要提货费和中转费 0:否; 1:是;',
  `small_item_recommend` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否小件推荐物流（推荐角标） 0:否; 1:是;',
  `logistics_shift` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流班次 0:无 1:早班物流 2:午班物流 3:晚班物流',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '仓库排序值 升序',
  `show_sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '展示排序值 升序',
  `description` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流描述',
  `delivery_time` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '每日交货时间',
  `picker_phone` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拉货人手机号',
  `need_fill_express_price` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否需要填报运费 0-不需要 1-必填 2-选填',
  `need_fill_weight` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否需要填报重量 0-不需要 1-必填 2-选填',
  `need_weight_photo` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否需要上传称重照片 0-不需要 1-必填 2-选填',
  `out_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '小程序端是否能出库 0-否 1-是',
  `pack_timeout_punish_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启超时打包处罚 0:否; 1:是;',
  `promotion_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否活动物流 0-否 1-是 默认0',
  `promotion_start` datetime NULL DEFAULT NULL COMMENT '活动开始时间',
  `promotion_end` datetime NULL DEFAULT NULL COMMENT '活动结束时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `send_area` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '废弃）寄送区域，限255字',
  `is_invoice_marked` tinyint NOT NULL DEFAULT 0 COMMENT '是否合作可开票物流商 0:否 1:是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_name`(`logistics_name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 990013 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货物流基础费用配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for bak_20260901_a105_order
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_a105_order`;
CREATE TABLE `bak_20260901_a105_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_purchaser采购方表主键id',
  `vip_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '会员卡名称',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号（唯一）',
  `order_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:普通订单 1:代下订单 默认0',
  `delivery_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '物流配送方式 1：物流配送 2：自提 3：自提打包 默认1',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `partner_model` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认0 历史订单 1、不合并服务费且不包邮 2、合并服务费且不包邮 3、合并服务费且包邮',
  `merchant_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信支付商户号',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appId',
  `open_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信openId',
  `distribution_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '配送方式 0-无 1-送货上门 2-城市仓自提',
  `is_addition` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否加单 0:否; 1:是;',
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单平台 0：微信 1：抖音',
  `has_third_good` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单是否包含第三方平台商品，默认0不包含，1包含',
  `is_zq_settlement` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否结算给珍情 0:没有 1:已结算',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号，当天同一货架号发货单号相同',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次编号：yyyy-MM-dd',
  `order_num` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '每天流水号',
  `total_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '花材总扎数',
  `total_weight` int UNSIGNED NOT NULL COMMENT '花材总重(g)',
  `origin_total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原花材总重 单位：克',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '按物流和重量场次结束时生成的货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `zone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区-货架号',
  `express` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '运输方式配置表id',
  `express_region` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '运输方式下对应的配送区域id',
  `real_express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际物流id 0时不改物流',
  `real_express_region` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际物流配送区域id',
  `express_time` tinyint NULL DEFAULT NULL COMMENT '航空物流：0: 早、 1: 中、 2:晚班',
  `express_price` decimal(20, 2) UNSIGNED NOT NULL COMMENT '预估运费',
  `before_activity_express_price` decimal(10, 2) UNSIGNED NULL DEFAULT 0.00 COMMENT '原物流价格（活动前）',
  `activity_express_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动物流名称',
  `coupon_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单剩余优惠金额(用于结算)',
  `origin_coupon_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单原优惠金额',
  `platform_reduce_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台满减优惠金额（剩余）',
  `origin_platform_reduce_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '原平台满减优惠金额',
  `add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加价（元）',
  `origin_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原加价（元）',
  `warehouse_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '城市仓加价（元）',
  `origin_warehouse_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '原城市仓加价（元）',
  `express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓物流加价（元）',
  `origin_express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原城市仓物流加价（元）',
  `ot_exp_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '繁花物流一次性加价（实际）',
  `origin_ot_exp_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '繁花物流一次性加价（原）',
  `delivery_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '配送费（元）',
  `origin_delivery_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原始配送费（元）',
  `modify_express_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '变更物流后预估运费',
  `is_change_express` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已修改物流 0:否; 1:是;',
  `actual_express_price` decimal(20, 2) UNSIGNED NULL DEFAULT NULL COMMENT '实际运费',
  `origin_supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商品合计供货价',
  `product_total_price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '商品合计价格（供货价+基础服务费）* 购买数量',
  `origin_product_total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原商品合计价格（供货价+基础服务费）* 购买数量',
  `service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总服务费（服务费单价*花材总重量）',
  `origin_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总服务费（服务费单价*花材总重量）',
  `extra_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '额外服务费',
  `origin_extra_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原额外服务费',
  `vip_discount_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'vip减免服务费',
  `origin_vip_discount_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原vip减免服务费',
  `platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台总补贴',
  `origin_platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原平台总补贴',
  `subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总单品补贴',
  `origin_subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总单品补贴',
  `negate_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓负加价',
  `origin_negate_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原城市仓负加价',
  `base_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总基础服务费：二级分类基础服务费 * 数量',
  `origin_base_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总基础服务费：二级分类基础服务费 * 数量',
  `total_price` decimal(20, 2) UNSIGNED NOT NULL COMMENT '订单合计金额=商品合计金额+运费+服务费',
  `origin_total_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原订单合计金额=商品合计金额+运费+服务费',
  `origin_use_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '下单时原使用寻梦币',
  `use_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当前订单使用寻梦币金额，不含发货前退款的',
  `rebate_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单返点给用户的寻梦币金额',
  `origin_rebate_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原订单返点给用户的寻梦币金额',
  `actual_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付金额 = 订单合计金额 - 订单使用寻梦币金额',
  `origin_actual_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原实付金额（最初付的钱，不含部分退），用于微信退款',
  `apply_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后申请商品总金额',
  `actual_refund` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后阶段实际退款金额（不超过申请售后商品的总价格+服务费）',
  `actual_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后阶段赔付寻梦币（小于等于售后申请商品总金额）',
  `paid_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付阶段总赔付金额（小于等于商品金额+服务费-实际退款金额）',
  `paid_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付阶段总赔付寻梦币（小于等于总供货价-售后赔付寻梦币）',
  `pay_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付方式 0：微信支付 1：寻梦平台账户支付 9:分销余额 10:通联支付',
  `pay_on_delivery` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否到付 0:否; 1:是 默认：0',
  `receive_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人名称',
  `receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人手机号',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `district` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `detail` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `receive_address` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址',
  `nation_code` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '86' COMMENT '国际电话区号 默认86',
  `adcode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址adcode',
  `buyer_memo` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '买家留言',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台备注',
  `order_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单状态 0:待付款 1:已付款待发货 2:已发货待收货 3:已完成 4:已关闭 5:已取消',
  `after_sale_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单售后状态 0:无售后 1:售后申请中 2:售后同意 3:售后拒绝',
  `after_sale_agree_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后同意类型 0:无 1:发货前售后同意; 2:发货后售后同意;',
  `after_sale_count` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后申请次数，（待发货：取消订单不计）',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单退款状态 0:无退款 1:申请退款中 2:退款成功 3:退款失败 4:极速退款中 5:极速退款成功 6:极速退款失败',
  `print_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已打印 0:否; 1:是;',
  `wx_pay_time` datetime NULL DEFAULT NULL COMMENT '微信付款时间',
  `wx_pay_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信付款编号',
  `send_time` datetime NULL DEFAULT NULL COMMENT '发货时间',
  `delay_ddl` datetime NULL DEFAULT NULL COMMENT '人工延迟后的售后截止时间，空表示未人工延迟',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认收货时间',
  `extra_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '额外信息',
  `coupon_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户优惠券id，0:没有用优惠券',
  `is_comment` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单是否已评价 0：未评价 1：已评价 默认0',
  `is_open_after_sale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启售后 0：关闭（正常售后） 1：开启（开启后强制用户端显示售后按钮）',
  `is_deliver` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）是否已配送 0:否; 1:是;（配货用字段）',
  `is_bond` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否履约（代供应商履约标记） 0:否; 1:是;',
  `is_cotton` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否保温棉 0:否; 1:是;',
  `flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '旗帜 0:灰',
  `bear_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后承担方 0:无; 1:梦晟; 2:昆明;',
  `is_bear_station_fee` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商是否承担提货站运费 0:否; 1:是;',
  `origin_total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原提货站运费总价=单价*sum(origin_item_num)',
  `total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '提货站运费当前总价=单价*sum(item_num)',
  `is_presale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为预售订单 0：不是 1：是 默认0',
  `is_sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为代卖订单 0-不是 1-是',
  `order_tag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:正 1：场 2：加',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `pid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销推广id',
  `unqualified_way` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '质检不合格处理方式 0:无 1:退货 2:降级 3:换货',
  `assign_customer_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分配客服id',
  `assign_customer_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分配客服姓名',
  `ship_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '微信发货状态 默认0 无需发货 1 待发货 2 已发货',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id，代下单时为下单客服userid',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `partner_add_service_fee` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '分销商加价服务费（元）',
  `origin_partner_add_service_fee` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '原始分销商加价服务费（退款前）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_send_no`(`send_no` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_purchaserid_wareid`(`purchaser_id` ASC, `ware_id` ASC) USING BTREE,
  INDEX `idx_roundno_paytime_ordersn`(`round_no` ASC, `wx_pay_time` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_tel_ordersn_wareid`(`receive_tel` ASC, `order_sn` ASC, `ware_id` ASC) USING BTREE,
  INDEX `idx_is_sale_agency`(`is_sale_agency` ASC) USING BTREE,
  INDEX `idx_wxpaytime_ordersn`(`wx_pay_time` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_zone_shelf`(`zone_shelf` ASC) USING BTREE,
  INDEX `idx_wareid_ptime_ostatus`(`ware_id` ASC, `wx_pay_time` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_partnerid_ordersn`(`partner_id` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_helpid_roundno_status`(`help_id` ASC, `round_no` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_codex_ml_partner_status_round`(`partner_id` ASC, `order_status` ASC, `round_no` ASC, `purchaser_id` ASC, `total_item_num` ASC) USING BTREE,
  INDEX `idx_partner_round_status_order_sn`(`partner_id` ASC, `round_no` ASC, `order_status` ASC, `order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 93013092 AVG_ROW_LENGTH = 1264 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货用户订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for bak_20260901_a105_order_info
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_a105_order_info`;
CREATE TABLE `bak_20260901_a105_order_info`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单orderSn',
  `send_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单发货单',
  `api_order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '三方订单号',
  `has_cotton` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有保温品 默认0 没有 1有',
  `cotton_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '保温品信息',
  `promote_merchant_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推广商家 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_sendno`(`send_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2105960 AVG_ROW_LENGTH = 330 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单详情表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bak_20260901_a105_order_item
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_a105_order_item`;
CREATE TABLE `bak_20260901_a105_order_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方用户id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `order_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '每天货架号',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '按物流和重量 场次结束时生成的货架号',
  `sub_shelf_sn` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'xm_bulky_order表order_sn：用户订单号',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次编号：yyyy-MM-dd',
  `supplier_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商订单号',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_product商品表主键id',
  `product_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '等级123456->ABCDEO',
  `sku_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品图片',
  `spec_and_num` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格数量+规格名称',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单商品描述',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单商品备注，限128字',
  `supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价单价',
  `pay_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付单价',
  `platform_discount_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台补贴单价 元/扎',
  `subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '单品补贴单价 元/扎',
  `coupon_pay_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '优惠后实付单价',
  `total_discount_refundable` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `origin_total_discount_refundable` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总的优惠后的金额（可退）',
  `coupon_discount_per_bundle` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '每一扎优惠券优惠多少（元）',
  `full_reduction_discount_per_bundle` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '每一扎满减的优惠多少（元）',
  `add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加价单价（元）',
  `total_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当前剩余平台加价合计',
  `origin_total_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '创建时平台加价合计',
  `warehouse_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '城市仓加价单价（元）',
  `negate_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓负加价单价（元）',
  `station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '提货站运费单价（扎item_num）',
  `express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓物流加价单价（元）',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单商品数量',
  `origin_item_num` int UNSIGNED NOT NULL COMMENT '订单创建时商品数量，值不变',
  `after_sale_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后退的商品数量（生成送货单的商品数量=购买数量-售后退的数量）',
  `after_sale_refund` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后退的金额（由售后退的数量计算得来或者是客服手动填入）',
  `bond_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）代履约的商品数量（这部分商品供货价的钱不结算给供应商）',
  `after_sale_supplier_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商售后承担商品数量（小于等于售后退的商品数量，小于等于item_num-bond_item_num）',
  `actual_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付单价x数量',
  `origin_actual_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原实付单价x数量',
  `service_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '服务费单价',
  `partner_add_service_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '每扎分销商加价服务费（元）',
  `total_partner_add_service_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '该商品行总分销商加价服务费（元）',
  `total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价x数量',
  `origin_total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原供货价x数量',
  `total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品总重量 g',
  `origin_total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原商品总重',
  `is_comment` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否评价 0:未评价; 1:已评价;',
  `after_sale_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单售后状态 0:无售后 1:售后申请中 2:售后同意 3:售后拒绝',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款状态 0:无退款 1:申请退款中 2:退款成功',
  `printer_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小票打印状态 0：未打印  1：已打印',
  `printer_time` int UNSIGNED NULL DEFAULT 0 COMMENT '打印时间',
  `is_deliver` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已配货 0:未配货; 1:已配货;（配货用字段）',
  `is_rebate` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否返点 0:否; 1:是;',
  `third_good_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '第三方商品id，默认0，大于0 表示三方平台商品',
  `is_no_quality_issue` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否7天0质检 默认 0不是 1是',
  `is_prefer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为优选商品 默认0不是 1是',
  `quality_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否品质花材 0-否 1-是',
  `deliver_time` datetime NULL DEFAULT NULL COMMENT '订单商品配货时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_roundno`(`round_no` ASC) USING BTREE,
  INDEX `idx_sid_rno_osn`(`supplier_id` ASC, `round_no` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_round_product_user`(`round_no` ASC, `product_id` ASC, `purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36755432 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货订单商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bak_20260901_a105_package
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_a105_package`;
CREATE TABLE `bak_20260901_a105_package`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` tinyint NOT NULL DEFAULT 0 COMMENT '类型 1昆明-店 2昆明-仓 3仓-店',
  `round_no` date NOT NULL COMMENT '场次',
  `ware_id` int NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `province` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '目的省',
  `city` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '目的城市',
  `send_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号',
  `shelf_sn` int NOT NULL DEFAULT 0 COMMENT '货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `self_take_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '自提方式 0-非自提 1-自提不打包 2-自提打包',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  `min_shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '最小货架号（type=2时专用）',
  `max_shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '最大货架号（type=2时专用）',
  `serial_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '序号',
  `package_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '包裹数量 序号为1时填',
  `total_weight` decimal(10, 3) UNSIGNED NOT NULL DEFAULT 0.000 COMMENT '总重（kg）序号为1时填',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '总扎数 序号为1时填',
  `express_id` bigint NOT NULL DEFAULT 0 COMMENT '物流表主键',
  `region_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流区域主键id',
  `origin_express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '原物流id',
  `origin_region_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '原物流区域id',
  `express_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '航空物流 0 无 1 早 2 中 3 晚班 和订单表express_time枚举不一样',
  `express_status` tinyint NOT NULL DEFAULT 0 COMMENT '包裹状态 0:待打包 10:打包完成 20:发货完成',
  `pickup_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '揽收状态 0-待揽收 1-已揽收',
  `pickup_time` datetime NULL DEFAULT NULL COMMENT '揽收时间',
  `pickup_operator_id` bigint NULL DEFAULT 0 COMMENT '揽收操作账号id',
  `pickup_operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '揽收操作人名称快照',
  `pickup_abnormal` tinyint NOT NULL DEFAULT 1 COMMENT '揽收是否异常：1-异常(默认)、0-正常',
  `abnormal_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '揽收异常原因',
  `report_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '填报价格（物流商手动填报）',
  `waybill_price_id` bigint NULL DEFAULT NULL COMMENT '关联的第三方运单报价记录id，为空表示普通包裹报价',
  `reconcile_sub_bill_id` bigint NOT NULL DEFAULT 0 COMMENT '运费子对账单id，0=未生成包裹对账详情',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核驳回理由',
  `out_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '出库类型：0：打包出库 1：未打包出库',
  `express_actual_weight` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际重量，单位KG',
  `express_actual_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际价格',
  `express_user_id` bigint NOT NULL DEFAULT 0 COMMENT '打包人id',
  `express_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '打包人姓名',
  `package_user_id` bigint NOT NULL DEFAULT 0 COMMENT '打包人id',
  `package_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '打包人姓名',
  `url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '打包完成url',
  `ship_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流url',
  `package_time` datetime NULL DEFAULT NULL COMMENT '打包完成时间',
  `express_modifier_id` bigint NOT NULL DEFAULT 0 COMMENT '物流修改人id',
  `express_modifier_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流修改人姓名',
  `express_modify_time` datetime NULL DEFAULT NULL COMMENT '物流修改时间',
  `express_time` datetime NULL DEFAULT NULL COMMENT '出库时间',
  `package_id` tinyint NOT NULL DEFAULT 0 COMMENT '物流包裹主键id',
  `package_info` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流包裹名称',
  `suggest_pack_id` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '推荐物流包裹主键id',
  `suggest_pack_info` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '推荐物流包裹名称',
  `valid_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有效包裹 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`, `round_no`) USING BTREE,
  INDEX `idx_sendno_type`(`send_no` ASC, `type` ASC) USING BTREE,
  INDEX `idx_round_pickup`(`round_no` ASC, `pickup_flag` ASC, `express_status` ASC) USING BTREE,
  INDEX `idx_round_ware_pickup`(`round_no` ASC, `ware_id` ASC, `pickup_flag` ASC) USING BTREE,
  INDEX `idx_express_round_pickup`(`express_id` ASC, `round_no` ASC, `pickup_flag` ASC) USING BTREE,
  INDEX `idx_package_waybill_price_id`(`waybill_price_id` ASC) USING BTREE,
  INDEX `idx_package_send_outbound_quote`(`send_no` ASC, `express_status` ASC, `valid_status` ASC, `data_status` ASC, `report_price` ASC, `waybill_price_id` ASC) USING BTREE,
  INDEX `idx_round_send_ware_serial`(`round_no` ASC, `send_no` ASC, `ware_id` ASC, `serial_num` ASC) USING BTREE,
  INDEX `idx_package_reconcile_sub_bill`(`reconcile_sub_bill_id` ASC, `pickup_flag` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 980817198 AVG_ROW_LENGTH = 355 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流包裹打包状态' ROW_FORMAT = Dynamic PARTITION BY RANGE (year(`round_no`))
PARTITIONS 9
(PARTITION `p2023` VALUES LESS THAN (2024) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2024` VALUES LESS THAN (2025) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2025` VALUES LESS THAN (2026) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2026` VALUES LESS THAN (2027) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2027` VALUES LESS THAN (2028) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2028` VALUES LESS THAN (2029) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2029` VALUES LESS THAN (2030) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2030` VALUES LESS THAN (2031) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p_future` VALUES LESS THAN (MAXVALUE) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 )
;

-- ----------------------------
-- Table structure for bak_20260901_a105_partner_bind
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_a105_partner_bind`;
CREATE TABLE `bak_20260901_a105_partner_bind`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `start_sell_weight` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '起售重量kg 默认0kg',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-不启用 1-启用',
  `shipping_area_initialized` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '繁花独立配送范围是否已完成首次初始化 0-否 1-是',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `large_customer_pack_flag` tinyint NOT NULL DEFAULT 0 COMMENT '大客户单独打包开关 0-关 1-开',
  `large_customer_pack_weight` decimal(10, 2) NOT NULL DEFAULT 10.00 COMMENT '大客户单独打包起重重量kg',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pid_wid`(`partner_id` ASC, `ware_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 33 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销城市仓绑定表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bak_20260901_a105_purchaser
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_a105_purchaser`;
CREATE TABLE `bak_20260901_a105_purchaser`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `zq_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '珍情用户id',
  `platform` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认0，0表示未区分，1、花材批发、2花仓酷，3、双用户(历史数据)',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认0  大于0 城市仓',
  `xm_account` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '寻梦账号(手机号)',
  `xm_com_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '寻梦公司账号',
  `company_direct_sale_store` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '寻梦平台账号店铺类型：1：直营店铺 2：头部商家 0：无',
  `company_level` tinyint UNSIGNED NOT NULL DEFAULT 6 COMMENT '寻梦平台账号店铺合作等级：1、2、3、4、5、6 默认最低等级',
  `xm_coin` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '寻梦币',
  `xm_coin_income` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '寻梦币收入',
  `xm_coin_expend` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '寻梦币支出',
  `xm_coin_give` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '补贴寻梦币余额',
  `xm_coin_rebate` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '返点寻梦币余额',
  `xm_coin_paid` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付寻梦币余额',
  `phone_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '手机号',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '密码',
  `salt` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '盐值',
  `app_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appId',
  `open_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信openId',
  `zc_open_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '资材openId',
  `session_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信登录会话KEY',
  `gender` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '性别：0：未知 1男，2女',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `country` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `area_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分区 1-一区 2-二区 3-三区 4-四区 5-五区 6-繁花北区 7-繁花南区 8-繁花西区',
  `auto_area_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否自动分区 0-否 1-是 默认1',
  `nickname` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户昵称或网络名称',
  `remark` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台备注，限20字符',
  `avatar_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户头像图片',
  `pic_avatar_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花现用户头像图片',
  `pic_user_background_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花现用户背景图片',
  `pic_user_introduction` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花现用户简介',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `ma_help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '资材推广员id',
  `pid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销推广员id（分销用户的id）',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最近一次登录时间',
  `last_login_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最近一次登录IP地址',
  `class_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '分类类型 1:外部类型; 2:内部类型;',
  `contact_supplier_count` int UNSIGNED NOT NULL DEFAULT 3 COMMENT '可联系供应商次数，默认3次',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '预设货架号',
  `config_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认物流id',
  `first_buy_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '首次购买时间',
  `last_buy_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近购买时间',
  `last_second_buy_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '上上次购买时间',
  `buy_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '购买次数（按场次来，场次结束后更新）',
  `ma_first_buy_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '资材首次购买时间',
  `ma_last_buy_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '资材最近购买时间',
  `ma_month_buy_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '资材近30天购买次数',
  `bb_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否绑定B2b 0-否 1-是',
  `month_consumption` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '近一个月消费金额',
  `total_consumption` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '总消费金额',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品数据',
  `last_recall_time` datetime NULL DEFAULT NULL COMMENT '上次召回时间',
  `month_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '月商品数据',
  `block_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否黑名单 0-否 1-下单拉黑 2-登录拉黑',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '用户状态 0：正常 -1：禁用  -100：删除',
  `holiday_white_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否节日白名单 0-否 1-是',
  `internal_employee_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否为内部员工：0-否 1-是',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `phone_change_time` datetime NULL DEFAULT NULL COMMENT '最近一次手机号换绑时间',
  `phone_change_version` int NOT NULL DEFAULT 0 COMMENT '手机号换绑版本',
  `express_recommend_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流推荐白名单：0-否，1-是',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_phone_number_app_id`(`phone_number` ASC, `app_id` ASC) USING BTREE,
  INDEX `idx_xm_account`(`xm_account` ASC) USING BTREE COMMENT '寻梦账号手机号',
  INDEX `idx_helpid`(`help_id` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE,
  INDEX `idx_appid_ctime`(`app_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_ftime`(`first_buy_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 999217 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货采购方用户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bak_20260901_a105_send_order
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_a105_send_order`;
CREATE TABLE `bak_20260901_a105_send_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '发货单表主键id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发货单号，当天同一货架号发货单号相同（唯一），限32字',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次编号：yyyy-MM-dd',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_purchaser采购方表主键id',
  `order_num` int UNSIGNED NULL DEFAULT 0,
  `ware_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货单流水号，每个城市仓从1开始',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '按物流和重量场次结束时生成的货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `zone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `shelf` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `delivery_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '物流配送方式 1:物流配送 2:自提 默认1',
  `distribution_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '配送方式 0-无 1-送货上门 2-城市仓自提',
  `actual_total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际重量（g）',
  `expend_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实际支出运费（人工输入）',
  `pickup_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提货费，确认结算时计入最终运费',
  `express_price_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '运费结算状态 0-未填报 1-待结算 2-已结算',
  `freight_price_mode` tinyint NOT NULL DEFAULT 0 COMMENT '运费填报模式 0-未确定 1-包裹 2-运单 3-混合',
  `package_report_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '包裹填报价格合计',
  `waybill_report_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '第三方运单填报价格合计',
  `reconcile_sub_bill_id` bigint NOT NULL DEFAULT 0 COMMENT '运费子对账单id，0=未生成对账单',
  `compensate_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '补偿/赔付金额(抵减应付物流商,人工输入)',
  `expend_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '服务费支出（人工输入）',
  `estimate_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '预估运费（系统维护）',
  `actual_package_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '实际包裹信息',
  `config_id` bigint UNSIGNED NOT NULL COMMENT '物流商id',
  `express_region` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流配送区域id',
  `real_express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际物流id 0时不改物流',
  `real_express_region` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际物流配送区域id',
  `month_buy` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30日购买次数',
  `receive_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人名称，限32字',
  `receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人手机号，限20字',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `district` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `receive_address` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货地址，限128字',
  `nation_code` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `adcode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址adcode',
  `longitude` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注 限128字',
  `city_remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市仓备注（自己人看） 限128字',
  `logistics_remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流专属备注，限128字',
  `send_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货单状态 0:待发货; 1:待收货; 2:已完成; 3:已取消',
  `logistics_status` tinyint NOT NULL DEFAULT 0 COMMENT '是否发送物流0.未发送1.发送',
  `express_change_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流变更状态 0:无; 1:申请中; 2:已同意; 3:已变更;',
  `print_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已打印 0:否; 1:是;',
  `is_sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0,
  `new_buyer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否是新用户 0:否 1:是',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `order_create_time` datetime NULL DEFAULT NULL COMMENT '订单创建时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `waybill_print_status` tinyint NOT NULL DEFAULT 0 COMMENT '电子面单打印状态 0未打印 1已打印 -1打印失败',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_send_no`(`send_no` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_roundno_wareid_shelfsn`(`round_no` ASC, `ware_id` ASC, `shelf_sn` ASC) USING BTREE,
  INDEX `idx_purchaserid_roundno`(`purchaser_id` ASC, `round_no` ASC) USING BTREE,
  INDEX `idx_receivetel_roundno`(`receive_tel` ASC, `round_no` ASC) USING BTREE,
  INDEX `idx_roundno_help_id_status`(`round_no` ASC, `help_id` ASC, `new_buyer` ASC, `send_status` ASC) USING BTREE,
  INDEX `idx_zone_shelf`(`zone_shelf` ASC) USING BTREE,
  INDEX `idx_reconcile_sub_bill`(`reconcile_sub_bill_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9400000395 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货发货单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bak_20260901_a105_wms_area
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_a105_wms_area`;
CREATE TABLE `bak_20260901_a105_wms_area`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '（唯一）分区编码，限10字',
  `area_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区名称，限10字',
  `start_shelf` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '开始货架号',
  `end_shelf` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '结束货架号（>=开始货架号）',
  `ware_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '仓库类型 0-寻梦批发 1-城市仓',
  `sort_config` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架排序配置 0-正常排序 1-专放小件 2-专放大件 3-自提早班 4-特小件 5-自提 6-早班 7-代卖',
  `sub_area` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子区间配置',
  `segment_area` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分段配置',
  `pack_income_config` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区打包收益配置，限4096字',
  `delivery_income` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '配货收益配置 元每扎',
  `standby` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否备用 0:否 1:是 默认0',
  `sequence` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '排序 顺序',
  `remark` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注，限32字',
  `area_manager_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分区负责人id',
  `area_manager_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区负责人名称',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户姓名',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新用户姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态 0-关闭 1-启用',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_code`(`code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 105 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货货架分区表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bak_20260901_cd9_backup_express
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_cd9_backup_express`;
CREATE TABLE `bak_20260901_cd9_backup_express`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `config_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流id',
  `sort_config_str` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '件型列表[1,2,3]',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-停用 1-启用',
  `sort_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '排序逻辑 1-优先生成 2-最后生成',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_configid`(`config_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '备用区物流配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bak_20260901_cd9_bind
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_cd9_bind`;
CREATE TABLE `bak_20260901_cd9_bind`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `start_sell_weight` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '起售重量kg 默认0kg',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-不启用 1-启用',
  `shipping_area_initialized` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '繁花独立配送范围是否已完成首次初始化 0-否 1-是',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `large_customer_pack_flag` tinyint NOT NULL DEFAULT 0 COMMENT '大客户单独打包开关 0-关 1-开',
  `large_customer_pack_weight` decimal(10, 2) NOT NULL DEFAULT 10.00 COMMENT '大客户单独打包起重重量kg',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pid_wid`(`partner_id` ASC, `ware_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 33 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销城市仓绑定表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bak_20260901_cd9_city
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_cd9_city`;
CREATE TABLE `bak_20260901_cd9_city`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市仓名称，限10字',
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '绑定结算供应商id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '绑定采购方id',
  `express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流配置id',
  `region_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流区域id',
  `store_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货门店id',
  `city_store_open` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '城市仓小时达营业状态 0-关闭 1-开启',
  `add_price` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 1.00 COMMENT '基础加价（元）',
  `add_price_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '加价开关 0-正常 1-支持负值',
  `distance` float(8, 2) UNSIGNED NOT NULL DEFAULT 5.00 COMMENT '配送范围km',
  `distance_price` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '距离收费系数（元/km）',
  `weight_price` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '重量收费系数（元/kg）',
  `express_add_price` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '物流加价系数 元/kg 范围0-20',
  `start_sell_weight` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '起售重量kg 默认0kg',
  `distribution_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '配送方式 0-都支持 1-只送货上门 2-只自提',
  `longitude` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `district` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `detail` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址',
  `business_address` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '营业地址',
  `city_code` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市代码',
  `adcode` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市仓adcode',
  `contact_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名，限32字',
  `contact_tel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人电话，限32字',
  `logistics_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '直营仓物流电话，限20字',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-已创建 1-已开通 2-已关闭 3-临时关闭',
  `operate_status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '营业状态 0-关 1-开 默认开',
  `phone_switch` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '电话展示开关 0-关 1-开 默认开',
  `flash_sale_switch` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '秒杀商品开关 0-关 1-开 默认开',
  `cotton_switch` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温棉开关 0-关 1-开 默认关',
  `cotton_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温棉数量 最大50',
  `board_switch` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温板开关 0-关 1-开 默认关',
  `board_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温板数量 最大50',
  `hour_delivery_switch` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '小时达开关 0-关 1-开 默认开',
  `xmmaterials_open` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '资材开关 0-关 1-开 默认开',
  `change_add_price_switch` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '城市仓加价开关 0-关 1-开 默认开',
  `single_delivery_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否单独发货 0-否 1-是',
  `coupon_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '城市仓优惠券开关 0-否 1-是 默认开',
  `promote_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推广合作 0-否 1-是',
  `service_fee_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '服务费开关 0-关 1-开 默认关 关闭1.6元每公斤 开启1元每公斤',
  `audit_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核状态 0-待审核 1-已通过 2-已驳回',
  `audit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '后台备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `delivery_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）临时加字段为了兼容资材',
  `share_ratio` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）临时加字段为了兼容资材',
  `promote_merchant_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推广商家 0-否 1-是',
  `large_customer_pack_flag` tinyint NOT NULL DEFAULT 0 COMMENT '大客户单独打包开关 0-关 1-开',
  `large_customer_pack_weight` decimal(10, 2) NOT NULL DEFAULT 10.00 COMMENT '大客户单独打包起重重量kg',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sid`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_appid`(`app_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 900204 AVG_ROW_LENGTH = 399 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for bak_20260901_cd9_common
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_cd9_common`;
CREATE TABLE `bak_20260901_cd9_common`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` tinyint UNSIGNED NOT NULL COMMENT '类型 1:运费预收系数 2:服务费单价 3:极速退款时间 11:自营店返点 12:头部商家返点 13:一级合作返点 14:二级及以下返点 21:商品加价规则',
  `type_str` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '类型说明',
  `price` decimal(10, 3) UNSIGNED NOT NULL DEFAULT 0.000 COMMENT '值 type=21时，0:按rank表加价 1:阶梯加价',
  `config_str` varchar(4098) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配置json 默认空串',
  `tips` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配置含义',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_type`(`type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货全局变量' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bak_20260901_cd9_daily_shelf
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_cd9_daily_shelf`;
CREATE TABLE `bak_20260901_cd9_daily_shelf`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货位号数字',
  `zone` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货位号',
  `zone_shelf` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区货位号',
  `sub_shelf_sn` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货位号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_roundno`(`round_no` ASC) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_round_zone_shelf_sn`(`round_no` ASC, `zone` ASC, `shelf_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1684097 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '每日货位表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bak_20260901_cd9_daily_shelf_test
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_cd9_daily_shelf_test`;
CREATE TABLE `bak_20260901_cd9_daily_shelf_test`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货位号数字',
  `zone` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货位号',
  `zone_shelf` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区货位号',
  `sub_shelf_sn` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货位号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_roundno`(`round_no` ASC) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1449112 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '每日货位表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bak_20260901_cd9_logistics
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_cd9_logistics`;
CREATE TABLE `bak_20260901_cd9_logistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `logistics_name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流服务商名称',
  `brand` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流商品牌',
  `phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '服务商电话，如0563-8888888，限30字',
  `logistics_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流方式 1:快递物流; 2:冷链运输; 3:航空运输;',
  `expected_time_str` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '预计送达（省会/一线城市）如：24~36小时',
  `delay_time_num` int UNSIGNED NOT NULL COMMENT '确认送达延后时间(小时h)',
  `is_to_shop` tinyint UNSIGNED NOT NULL COMMENT '是否送货到店 0:不到店需自提; 1:可配送到店; 2:需另付费配送到店',
  `transfer_cost` decimal(10, 2) UNSIGNED NOT NULL COMMENT '航空运输-空运短运费',
  `is_separate_display` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否单独展示 0:否; 1:是;',
  `is_enable` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否启用该配置 0:否; 1:是;',
  `rule_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流规则id',
  `first_heavy` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）计重用：首重(g)  单位(g/扎)',
  `first_heavy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）计重用：首重价格',
  `charge_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）计费类型 1:计重; 2:计件;',
  `continue_heavy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）计重用：续重单价(元/kg)',
  `is_transfer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否中转 0:否; 1:是;',
  `need_pick_fee` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否需要提货费和中转费 0:否; 1:是;',
  `small_item_recommend` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否小件推荐物流（推荐角标） 0:否; 1:是;',
  `logistics_shift` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流班次 0:无 1:早班物流 2:午班物流 3:晚班物流',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '仓库排序值 升序',
  `show_sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '展示排序值 升序',
  `description` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流描述',
  `delivery_time` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '每日交货时间',
  `picker_phone` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拉货人手机号',
  `need_fill_express_price` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否需要填报运费 0-不需要 1-必填 2-选填',
  `need_fill_weight` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否需要填报重量 0-不需要 1-必填 2-选填',
  `need_weight_photo` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否需要上传称重照片 0-不需要 1-必填 2-选填',
  `out_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '小程序端是否能出库 0-否 1-是',
  `pack_timeout_punish_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启超时打包处罚 0:否; 1:是;',
  `promotion_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否活动物流 0-否 1-是 默认0',
  `promotion_start` datetime NULL DEFAULT NULL COMMENT '活动开始时间',
  `promotion_end` datetime NULL DEFAULT NULL COMMENT '活动结束时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `send_area` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '废弃）寄送区域，限255字',
  `is_invoice_marked` tinyint NOT NULL DEFAULT 0 COMMENT '是否合作可开票物流商 0:否 1:是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_name`(`logistics_name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 990013 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货物流基础费用配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for bak_20260901_cd9_order
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_cd9_order`;
CREATE TABLE `bak_20260901_cd9_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_purchaser采购方表主键id',
  `vip_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '会员卡名称',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号（唯一）',
  `order_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:普通订单 1:代下订单 默认0',
  `delivery_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '物流配送方式 1：物流配送 2：自提 3：自提打包 默认1',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `partner_model` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认0 历史订单 1、不合并服务费且不包邮 2、合并服务费且不包邮 3、合并服务费且包邮',
  `merchant_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信支付商户号',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appId',
  `open_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信openId',
  `distribution_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '配送方式 0-无 1-送货上门 2-城市仓自提',
  `is_addition` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否加单 0:否; 1:是;',
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单平台 0：微信 1：抖音',
  `has_third_good` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单是否包含第三方平台商品，默认0不包含，1包含',
  `is_zq_settlement` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否结算给珍情 0:没有 1:已结算',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号，当天同一货架号发货单号相同',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次编号：yyyy-MM-dd',
  `order_num` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '每天流水号',
  `total_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '花材总扎数',
  `total_weight` int UNSIGNED NOT NULL COMMENT '花材总重(g)',
  `origin_total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原花材总重 单位：克',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '按物流和重量场次结束时生成的货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `zone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区-货架号',
  `express` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '运输方式配置表id',
  `express_region` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '运输方式下对应的配送区域id',
  `real_express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际物流id 0时不改物流',
  `real_express_region` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际物流配送区域id',
  `express_time` tinyint NULL DEFAULT NULL COMMENT '航空物流：0: 早、 1: 中、 2:晚班',
  `express_price` decimal(20, 2) UNSIGNED NOT NULL COMMENT '预估运费',
  `before_activity_express_price` decimal(10, 2) UNSIGNED NULL DEFAULT 0.00 COMMENT '原物流价格（活动前）',
  `activity_express_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动物流名称',
  `coupon_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单剩余优惠金额(用于结算)',
  `origin_coupon_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单原优惠金额',
  `platform_reduce_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台满减优惠金额（剩余）',
  `origin_platform_reduce_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '原平台满减优惠金额',
  `add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加价（元）',
  `origin_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原加价（元）',
  `warehouse_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '城市仓加价（元）',
  `origin_warehouse_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '原城市仓加价（元）',
  `express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓物流加价（元）',
  `origin_express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原城市仓物流加价（元）',
  `ot_exp_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '繁花物流一次性加价（实际）',
  `origin_ot_exp_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '繁花物流一次性加价（原）',
  `delivery_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '配送费（元）',
  `origin_delivery_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原始配送费（元）',
  `modify_express_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '变更物流后预估运费',
  `is_change_express` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已修改物流 0:否; 1:是;',
  `actual_express_price` decimal(20, 2) UNSIGNED NULL DEFAULT NULL COMMENT '实际运费',
  `origin_supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商品合计供货价',
  `product_total_price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '商品合计价格（供货价+基础服务费）* 购买数量',
  `origin_product_total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原商品合计价格（供货价+基础服务费）* 购买数量',
  `service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总服务费（服务费单价*花材总重量）',
  `origin_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总服务费（服务费单价*花材总重量）',
  `extra_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '额外服务费',
  `origin_extra_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原额外服务费',
  `vip_discount_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'vip减免服务费',
  `origin_vip_discount_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原vip减免服务费',
  `platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台总补贴',
  `origin_platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原平台总补贴',
  `subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总单品补贴',
  `origin_subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总单品补贴',
  `negate_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓负加价',
  `origin_negate_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原城市仓负加价',
  `base_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总基础服务费：二级分类基础服务费 * 数量',
  `origin_base_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总基础服务费：二级分类基础服务费 * 数量',
  `total_price` decimal(20, 2) UNSIGNED NOT NULL COMMENT '订单合计金额=商品合计金额+运费+服务费',
  `origin_total_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原订单合计金额=商品合计金额+运费+服务费',
  `origin_use_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '下单时原使用寻梦币',
  `use_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当前订单使用寻梦币金额，不含发货前退款的',
  `rebate_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单返点给用户的寻梦币金额',
  `origin_rebate_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原订单返点给用户的寻梦币金额',
  `actual_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付金额 = 订单合计金额 - 订单使用寻梦币金额',
  `origin_actual_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原实付金额（最初付的钱，不含部分退），用于微信退款',
  `apply_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后申请商品总金额',
  `actual_refund` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后阶段实际退款金额（不超过申请售后商品的总价格+服务费）',
  `actual_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后阶段赔付寻梦币（小于等于售后申请商品总金额）',
  `paid_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付阶段总赔付金额（小于等于商品金额+服务费-实际退款金额）',
  `paid_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付阶段总赔付寻梦币（小于等于总供货价-售后赔付寻梦币）',
  `pay_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付方式 0：微信支付 1：寻梦平台账户支付 9:分销余额 10:通联支付',
  `pay_on_delivery` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否到付 0:否; 1:是 默认：0',
  `receive_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人名称',
  `receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人手机号',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `district` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `detail` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `receive_address` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址',
  `nation_code` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '86' COMMENT '国际电话区号 默认86',
  `adcode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址adcode',
  `buyer_memo` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '买家留言',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台备注',
  `order_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单状态 0:待付款 1:已付款待发货 2:已发货待收货 3:已完成 4:已关闭 5:已取消',
  `after_sale_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单售后状态 0:无售后 1:售后申请中 2:售后同意 3:售后拒绝',
  `after_sale_agree_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后同意类型 0:无 1:发货前售后同意; 2:发货后售后同意;',
  `after_sale_count` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后申请次数，（待发货：取消订单不计）',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单退款状态 0:无退款 1:申请退款中 2:退款成功 3:退款失败 4:极速退款中 5:极速退款成功 6:极速退款失败',
  `print_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已打印 0:否; 1:是;',
  `wx_pay_time` datetime NULL DEFAULT NULL COMMENT '微信付款时间',
  `wx_pay_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信付款编号',
  `send_time` datetime NULL DEFAULT NULL COMMENT '发货时间',
  `delay_ddl` datetime NULL DEFAULT NULL COMMENT '人工延迟后的售后截止时间，空表示未人工延迟',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认收货时间',
  `extra_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '额外信息',
  `coupon_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户优惠券id，0:没有用优惠券',
  `is_comment` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单是否已评价 0：未评价 1：已评价 默认0',
  `is_open_after_sale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启售后 0：关闭（正常售后） 1：开启（开启后强制用户端显示售后按钮）',
  `is_deliver` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）是否已配送 0:否; 1:是;（配货用字段）',
  `is_bond` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否履约（代供应商履约标记） 0:否; 1:是;',
  `is_cotton` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否保温棉 0:否; 1:是;',
  `flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '旗帜 0:灰',
  `bear_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后承担方 0:无; 1:梦晟; 2:昆明;',
  `is_bear_station_fee` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商是否承担提货站运费 0:否; 1:是;',
  `origin_total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原提货站运费总价=单价*sum(origin_item_num)',
  `total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '提货站运费当前总价=单价*sum(item_num)',
  `is_presale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为预售订单 0：不是 1：是 默认0',
  `is_sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为代卖订单 0-不是 1-是',
  `order_tag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:正 1：场 2：加',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `pid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销推广id',
  `unqualified_way` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '质检不合格处理方式 0:无 1:退货 2:降级 3:换货',
  `assign_customer_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分配客服id',
  `assign_customer_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分配客服姓名',
  `ship_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '微信发货状态 默认0 无需发货 1 待发货 2 已发货',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id，代下单时为下单客服userid',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `partner_add_service_fee` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '分销商加价服务费（元）',
  `origin_partner_add_service_fee` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '原始分销商加价服务费（退款前）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_send_no`(`send_no` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_purchaserid_wareid`(`purchaser_id` ASC, `ware_id` ASC) USING BTREE,
  INDEX `idx_roundno_paytime_ordersn`(`round_no` ASC, `wx_pay_time` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_tel_ordersn_wareid`(`receive_tel` ASC, `order_sn` ASC, `ware_id` ASC) USING BTREE,
  INDEX `idx_is_sale_agency`(`is_sale_agency` ASC) USING BTREE,
  INDEX `idx_wxpaytime_ordersn`(`wx_pay_time` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_zone_shelf`(`zone_shelf` ASC) USING BTREE,
  INDEX `idx_wareid_ptime_ostatus`(`ware_id` ASC, `wx_pay_time` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_partnerid_ordersn`(`partner_id` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_helpid_roundno_status`(`help_id` ASC, `round_no` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_codex_ml_partner_status_round`(`partner_id` ASC, `order_status` ASC, `round_no` ASC, `purchaser_id` ASC, `total_item_num` ASC) USING BTREE,
  INDEX `idx_partner_round_status_order_sn`(`partner_id` ASC, `round_no` ASC, `order_status` ASC, `order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 93013092 AVG_ROW_LENGTH = 1264 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货用户订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for bak_20260901_cd9_order_info
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_cd9_order_info`;
CREATE TABLE `bak_20260901_cd9_order_info`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单orderSn',
  `send_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单发货单',
  `api_order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '三方订单号',
  `has_cotton` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有保温品 默认0 没有 1有',
  `cotton_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '保温品信息',
  `promote_merchant_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推广商家 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_sendno`(`send_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2105960 AVG_ROW_LENGTH = 330 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单详情表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bak_20260901_cd9_order_item
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_cd9_order_item`;
CREATE TABLE `bak_20260901_cd9_order_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方用户id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `order_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '每天货架号',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '按物流和重量 场次结束时生成的货架号',
  `sub_shelf_sn` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'xm_bulky_order表order_sn：用户订单号',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次编号：yyyy-MM-dd',
  `supplier_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商订单号',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_product商品表主键id',
  `product_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '等级123456->ABCDEO',
  `sku_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品图片',
  `spec_and_num` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格数量+规格名称',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单商品描述',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单商品备注，限128字',
  `supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价单价',
  `pay_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付单价',
  `platform_discount_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台补贴单价 元/扎',
  `subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '单品补贴单价 元/扎',
  `coupon_pay_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '优惠后实付单价',
  `total_discount_refundable` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `origin_total_discount_refundable` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总的优惠后的金额（可退）',
  `coupon_discount_per_bundle` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '每一扎优惠券优惠多少（元）',
  `full_reduction_discount_per_bundle` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '每一扎满减的优惠多少（元）',
  `add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加价单价（元）',
  `total_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当前剩余平台加价合计',
  `origin_total_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '创建时平台加价合计',
  `warehouse_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '城市仓加价单价（元）',
  `negate_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓负加价单价（元）',
  `station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '提货站运费单价（扎item_num）',
  `express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓物流加价单价（元）',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单商品数量',
  `origin_item_num` int UNSIGNED NOT NULL COMMENT '订单创建时商品数量，值不变',
  `after_sale_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后退的商品数量（生成送货单的商品数量=购买数量-售后退的数量）',
  `after_sale_refund` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后退的金额（由售后退的数量计算得来或者是客服手动填入）',
  `bond_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）代履约的商品数量（这部分商品供货价的钱不结算给供应商）',
  `after_sale_supplier_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商售后承担商品数量（小于等于售后退的商品数量，小于等于item_num-bond_item_num）',
  `actual_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付单价x数量',
  `origin_actual_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原实付单价x数量',
  `service_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '服务费单价',
  `partner_add_service_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '每扎分销商加价服务费（元）',
  `total_partner_add_service_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '该商品行总分销商加价服务费（元）',
  `total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价x数量',
  `origin_total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原供货价x数量',
  `total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品总重量 g',
  `origin_total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原商品总重',
  `is_comment` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否评价 0:未评价; 1:已评价;',
  `after_sale_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单售后状态 0:无售后 1:售后申请中 2:售后同意 3:售后拒绝',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款状态 0:无退款 1:申请退款中 2:退款成功',
  `printer_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小票打印状态 0：未打印  1：已打印',
  `printer_time` int UNSIGNED NULL DEFAULT 0 COMMENT '打印时间',
  `is_deliver` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已配货 0:未配货; 1:已配货;（配货用字段）',
  `is_rebate` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否返点 0:否; 1:是;',
  `third_good_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '第三方商品id，默认0，大于0 表示三方平台商品',
  `is_no_quality_issue` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否7天0质检 默认 0不是 1是',
  `is_prefer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为优选商品 默认0不是 1是',
  `quality_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否品质花材 0-否 1-是',
  `deliver_time` datetime NULL DEFAULT NULL COMMENT '订单商品配货时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_roundno`(`round_no` ASC) USING BTREE,
  INDEX `idx_sid_rno_osn`(`supplier_id` ASC, `round_no` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_round_product_user`(`round_no` ASC, `product_id` ASC, `purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36755432 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货订单商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bak_20260901_cd9_package
-- ----------------------------
DROP TABLE IF EXISTS `bak_20260901_cd9_package`;
CREATE TABLE `bak_20260901_cd9_package`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` tinyint NOT NULL DEFAULT 0 COMMENT '类型 1昆明-店 2昆明-仓 3仓-店',
  `round_no` date NOT NULL COMMENT '场次',
  `ware_id` int NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `province` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '目的省',
  `city` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '目的城市',
  `send_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号',
  `shelf_sn` int NOT NULL DEFAULT 0 COMMENT '货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `self_take_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '自提方式 0-非自提 1-自提不打包 2-自提打包',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  `min_shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '最小货架号（type=2时专用）',
  `max_shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '最大货架号（type=2时专用）',
  `serial_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '序号',
  `package_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '包裹数量 序号为1时填',
  `total_weight` decimal(10, 3) UNSIGNED NOT NULL DEFAULT 0.000 COMMENT '总重（kg）序号为1时填',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '总扎数 序号为1时填',
  `express_id` bigint NOT NULL DEFAULT 0 COMMENT '物流表主键',
  `region_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流区域主键id',
  `origin_express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '原物流id',
  `origin_region_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '原物流区域id',
  `express_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '航空物流 0 无 1 早 2 中 3 晚班 和订单表express_time枚举不一样',
  `express_status` tinyint NOT NULL DEFAULT 0 COMMENT '包裹状态 0:待打包 10:打包完成 20:发货完成',
  `pickup_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '揽收状态 0-待揽收 1-已揽收',
  `pickup_time` datetime NULL DEFAULT NULL COMMENT '揽收时间',
  `pickup_operator_id` bigint NULL DEFAULT 0 COMMENT '揽收操作账号id',
  `pickup_operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '揽收操作人名称快照',
  `pickup_abnormal` tinyint NOT NULL DEFAULT 1 COMMENT '揽收是否异常：1-异常(默认)、0-正常',
  `abnormal_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '揽收异常原因',
  `report_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '填报价格（物流商手动填报）',
  `waybill_price_id` bigint NULL DEFAULT NULL COMMENT '关联的第三方运单报价记录id，为空表示普通包裹报价',
  `reconcile_sub_bill_id` bigint NOT NULL DEFAULT 0 COMMENT '运费子对账单id，0=未生成包裹对账详情',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核驳回理由',
  `out_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '出库类型：0：打包出库 1：未打包出库',
  `express_actual_weight` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际重量，单位KG',
  `express_actual_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际价格',
  `express_user_id` bigint NOT NULL DEFAULT 0 COMMENT '打包人id',
  `express_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '打包人姓名',
  `package_user_id` bigint NOT NULL DEFAULT 0 COMMENT '打包人id',
  `package_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '打包人姓名',
  `url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '打包完成url',
  `ship_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流url',
  `package_time` datetime NULL DEFAULT NULL COMMENT '打包完成时间',
  `express_modifier_id` bigint NOT NULL DEFAULT 0 COMMENT '物流修改人id',
  `express_modifier_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流修改人姓名',
  `express_modify_time` datetime NULL DEFAULT NULL COMMENT '物流修改时间',
  `express_time` datetime NULL DEFAULT NULL COMMENT '出库时间',
  `package_id` tinyint NOT NULL DEFAULT 0 COMMENT '物流包裹主键id',
  `package_info` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流包裹名称',
  `suggest_pack_id` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '推荐物流包裹主键id',
  `suggest_pack_info` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '推荐物流包裹名称',
  `valid_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有效包裹 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`, `round_no`) USING BTREE,
  INDEX `idx_sendno_type`(`send_no` ASC, `type` ASC) USING BTREE,
  INDEX `idx_round_pickup`(`round_no` ASC, `pickup_flag` ASC, `express_status` ASC) USING BTREE,
  INDEX `idx_round_ware_pickup`(`round_no` ASC, `ware_id` ASC, `pickup_flag` ASC) USING BTREE,
  INDEX `idx_express_round_pickup`(`express_id` ASC, `round_no` ASC, `pickup_flag` ASC) USING BTREE,
  INDEX `idx_package_waybill_price_id`(`waybill_price_id` ASC) USING BTREE,
  INDEX `idx_package_send_outbound_quote`(`send_no` ASC, `express_status` ASC, `valid_status` ASC, `data_status` ASC, `report_price` ASC, `waybill_price_id` ASC) USING BTREE,
  INDEX `idx_round_send_ware_serial`(`round_no` ASC, `send_no` ASC, `ware_id` ASC, `serial_num` ASC) USING BTREE,
  INDEX `idx_package_reconcile_sub_bill`(`reconcile_sub_bill_id` ASC, `pickup_flag` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 980817198 AVG_ROW_LENGTH = 355 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流包裹打包状态' ROW_FORMAT = Dynamic PARTITION BY RANGE (year(`round_no`))
PARTITIONS 9
(PARTITION `p2023` VALUES LESS THAN (2024) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2024` VALUES LESS THAN (2025) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
