DROP TABLE IF EXISTS `blk_wx_pay_certificate_mch_backup_20260718`;
CREATE TABLE `blk_wx_pay_certificate_mch_backup_20260718`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `mch_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '微信支付商户号',
  `private_key_content` mediumblob NULL COMMENT 'apiclient_key.pem 原始内容',
  `private_cert_content` mediumblob NULL COMMENT 'apiclient_cert.pem 原始内容',
  `p12_content` mediumblob NULL COMMENT 'apiclient_cert.p12 原始内容',
  `public_key_content` mediumblob NULL COMMENT 'pub_key.pem 原始内容',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0正常，-100删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mch_id`(`mch_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 447 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '微信支付证书内容' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulk_purchase_audit_log
-- ----------------------------
DROP TABLE IF EXISTS `bulk_purchase_audit_log`;
CREATE TABLE `bulk_purchase_audit_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'demand/quote/confirm/order/print/label/settle',
  `biz_id` bigint NOT NULL COMMENT 'print类型固定存order_id',
  `biz_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务单号',
  `action` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '动作',
  `before_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '变更前',
  `after_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '变更后',
  `reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原因',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `operator_end` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'admin/supplier/pda/system',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_biz`(`biz_type` ASC, `biz_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2541 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '集采操作审计' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulk_purchase_demand
-- ----------------------------
DROP TABLE IF EXISTS `bulk_purchase_demand`;
CREATE TABLE `bulk_purchase_demand`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `demand_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '需求编号 BPP+yyyyMMdd+10011+6位随机',
  `theme` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '采购主题',
  `publish_supplier_id` bigint NOT NULL COMMENT '发布供应商ID(库存归属+结算付款方)',
  `publish_supplier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发布供应商名称',
  `round_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次 yyyy-MM-dd',
  `second_id` bigint NOT NULL COMMENT '二级分类ID',
  `second_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '二级分类名称快照',
  `spec_num` int NOT NULL COMMENT '每扎枝数快照',
  `spec_unit` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格单位快照 如 枝/扎',
  `rank_codes` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '采购等级快照 逗号分隔 如 1,2,3；0无等级 1A 2B 3C 4D 5E 6O',
  `demand_num` int NOT NULL COMMENT '原需求枝数',
  `append_num` int NOT NULL DEFAULT 0 COMMENT '累计追加枝数',
  `min_quote_num` int NOT NULL COMMENT '最低报价数量(总可供量下限)',
  `scope_type` tinyint NOT NULL COMMENT '供应商范围 1全部 2指定基地 3品质优选 4近30天销量阈值 5指定供应商 6白名单',
  `scope_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '范围参数JSON',
  `dounan_quote_end_time` datetime NOT NULL COMMENT '斗南报价截止时间',
  `non_dounan_quote_end_time` datetime NOT NULL COMMENT '非斗南报价截止时间',
  `dounan_check_in_end_time` datetime NOT NULL COMMENT '斗南签到截止时间',
  `non_dounan_check_in_end_time` datetime NOT NULL COMMENT '非斗南签到截止时间',
  `collect_end_time` datetime NOT NULL COMMENT '采集兜底完结时间 = 场次日期+1天 12:00:00',
  `status` tinyint NOT NULL COMMENT '0草稿 1报价中 2待定采 3已确认 4已完成 5已关闭',
  `terminate_type` tinyint NULL DEFAULT NULL COMMENT '终止方式 1自然截止 2人工提前终止',
  `close_reason` tinyint NULL DEFAULT NULL COMMENT '关闭原因 1无人报价 2人工终止',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '定采时间',
  `confirm_by` bigint NULL DEFAULT NULL COMMENT '定采操作人',
  `confirm_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '定采操作人名称',
  `confirm_reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '超采原因',
  `finish_type` tinyint NULL DEFAULT NULL COMMENT '完结方式 1运营手动完成采集 2兜底自动完结',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '完成采集时间',
  `finish_by` bigint NULL DEFAULT NULL COMMENT '完成采集操作人 兜底为空',
  `finish_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '完成采集操作人名称',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `create_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_demand_no`(`demand_no` ASC) USING BTREE,
  INDEX `idx_status_round`(`status` ASC, `round_no` ASC) USING BTREE,
  INDEX `idx_status_collect_end`(`status` ASC, `collect_end_time` ASC) USING BTREE,
  INDEX `idx_second`(`second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 462 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '集采需求(采集计划)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulk_purchase_demand_supplier
-- ----------------------------
DROP TABLE IF EXISTS `bulk_purchase_demand_supplier`;
CREATE TABLE `bulk_purchase_demand_supplier`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `demand_id` bigint NOT NULL COMMENT '需求ID',
  `demand_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '需求编号',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID，0=全部供应商哨兵行',
  `supplier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供应商名称',
  `supplier_tag` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基地',
  `is_dounan` tinyint NOT NULL DEFAULT 0 COMMENT '0非斗南 1斗南；哨兵行无意义',
  `month_sell_count` bigint NULL DEFAULT NULL COMMENT '近30天销量快照',
  `hit_condition` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '命中条件说明',
  `source` tinyint NOT NULL COMMENT '1发布快照 2报价中追加',
  `append_by` bigint NULL DEFAULT NULL COMMENT '追加操作人',
  `append_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '追加操作人名称',
  `append_reason` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '追加原因',
  `append_time` datetime NULL DEFAULT NULL COMMENT '追加时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_demand_supplier`(`demand_id` ASC, `supplier_id` ASC) USING BTREE,
  INDEX `idx_supplier`(`supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4879 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '集采需求可见供应商快照' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulk_purchase_label
-- ----------------------------
DROP TABLE IF EXISTS `bulk_purchase_label`;
CREATE TABLE `bulk_purchase_label`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `label_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '二维码内容 全局唯一，格式 供货单号-等级-4位序号',
  `order_id` bigint NOT NULL COMMENT '供货单ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供货单号',
  `rank_code` tinyint NOT NULL COMMENT '等级 0无 1A 2B 3C 4D 5E 6O',
  `seq_no` int NOT NULL COMMENT '该单该等级内的序号 从1递增',
  `status` tinyint NOT NULL COMMENT '10已生成 30已扫码入库 90已作废',
  `scan_time` datetime NULL DEFAULT NULL COMMENT '扫码时间',
  `scan_by` bigint NULL DEFAULT NULL COMMENT '扫码人',
  `scan_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扫码人名称',
  `product_id` bigint NULL DEFAULT NULL COMMENT '入库落到的商品ID',
  `revoke_count` int NOT NULL DEFAULT 0 COMMENT '被撤销次数；撤销后可重扫，留痕用',
  `void_time` datetime NULL DEFAULT NULL COMMENT '作废时间',
  `void_reason` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作废原因',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_label_code`(`label_code` ASC) USING BTREE,
  UNIQUE INDEX `uk_order_rank_seq`(`order_id` ASC, `rank_code` ASC, `seq_no` ASC) USING BTREE,
  INDEX `idx_order_status`(`order_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1024 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '集采花材标签(一扎一码)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulk_purchase_order
-- ----------------------------
DROP TABLE IF EXISTS `bulk_purchase_order`;
CREATE TABLE `bulk_purchase_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供货单号 BPO+...',
  `shelf_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '集采货架码',
  `demand_id` bigint NOT NULL COMMENT '需求ID',
  `demand_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '需求编号',
  `quote_id` bigint NOT NULL COMMENT '冻结的报价版本ID',
  `publish_supplier_id` bigint NOT NULL COMMENT '发布供应商:库存归属+结算付款方',
  `supplier_id` bigint NOT NULL COMMENT '供货供应商ID',
  `supplier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供货供应商名称',
  `supplier_tag` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基地',
  `is_dounan` tinyint NOT NULL DEFAULT 0 COMMENT '0非斗南 1斗南',
  `round_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次 yyyy-MM-dd',
  `second_id` bigint NOT NULL COMMENT '二级分类ID',
  `second_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '二级分类名称',
  `spec_num` int NOT NULL COMMENT '每扎枝数快照',
  `total_supply_num` int NOT NULL COMMENT '冻结:该供应商报价总可供枝数',
  `confirm_num` int NOT NULL COMMENT '定采枝数',
  `check_in_end_time` datetime NOT NULL COMMENT '签到截止 生成时按斗南/非斗南落快照',
  `check_in_time` datetime NULL DEFAULT NULL COMMENT '签到时间',
  `check_in_by` bigint NULL DEFAULT NULL COMMENT '签到操作人',
  `check_in_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签到操作人名称',
  `plate_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车牌/物流单号',
  `delivery_addr` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货地点',
  `delivery_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货备注：签到后现场记录供应商实际送到多少，仅留痕，不参与产出与结算计算',
  `late_flag` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1送货迟到',
  `output_end_time` datetime NOT NULL COMMENT '产出截止时间 = 场次日期+1天 12:00:00',
  `actual_num` int NOT NULL DEFAULT 0 COMMENT '标签盘点产出枝数 = 各等级 scanned_stem_num 之和',
  `settle_num` int NULL DEFAULT NULL COMMENT '应结算枝数 = 各等级 settle_stem_num 之和',
  `settle_num_modified` tinyint NOT NULL DEFAULT 0 COMMENT '0未人工改 1已人工改',
  `over_flag` tinyint NOT NULL DEFAULT 0 COMMENT '超量标识 0否 1是；提交盘点时置位，人工处理后清除',
  `inventory_by` bigint NULL DEFAULT NULL COMMENT '当前占用盘点的人；同一单同时只允许一个盘点任务',
  `inventory_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当前盘点人名称',
  `inventory_start_time` datetime NULL DEFAULT NULL COMMENT '开始盘点时间',
  `inventory_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '盘点备注；少于定采时必填',
  `inventory_submit_by` bigint NULL DEFAULT NULL COMMENT '提交盘点人',
  `inventory_submit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交盘点人名称',
  `inventory_submit_time` datetime NULL DEFAULT NULL COMMENT '提交盘点时间',
  `over_exception_type` tinyint NULL DEFAULT NULL COMMENT '超量异常类型 1供应商自身超送 2混货/错贴标签',
  `over_handle_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '超量处理说明',
  `over_handle_by` bigint NULL DEFAULT NULL COMMENT '超量处理人',
  `over_handle_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '超量处理人名称',
  `over_handle_time` datetime NULL DEFAULT NULL COMMENT '超量处理时间',
  `total_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '应结算金额，单位元，最小到分',
  `plan_settle_time` datetime NULL DEFAULT NULL COMMENT '计划结算时间 = 盘点完成+3天',
  `settle_time` datetime NULL DEFAULT NULL COMMENT '实际结算时间',
  `settle_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否已结算 0否 1是；与 status=40 同一条SQL置位，不会漂移',
  `settle_type` tinyint NULL DEFAULT NULL COMMENT '结算方式 1到期自动 2人工手动',
  `settle_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手动结算原因；自动结算为空',
  `settle_by` bigint NULL DEFAULT NULL COMMENT '手动结算操作人；自动结算为空',
  `settle_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手动结算操作人名称；自动结算为空',
  `status` tinyint NOT NULL COMMENT '10待签到 20待盘点 30待结算 40已结算 90已取消',
  `cancel_type` tinyint NULL DEFAULT NULL COMMENT '取消方式 1运营手动 2产出截止自动',
  `cancel_reason` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取消原因',
  `cancel_by` bigint NULL DEFAULT NULL COMMENT '取消操作人',
  `cancel_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取消操作人名称',
  `cancel_time` datetime NULL DEFAULT NULL COMMENT '取消时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_no`(`order_no` ASC) USING BTREE,
  UNIQUE INDEX `uk_demand_supplier`(`demand_id` ASC, `supplier_id` ASC) USING BTREE,
  UNIQUE INDEX `uk_round_shelf`(`round_no` ASC, `shelf_code` ASC) USING BTREE,
  INDEX `idx_supplier_status`(`supplier_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_status_output_end`(`status` ASC, `output_end_time` ASC) USING BTREE,
  INDEX `idx_status_settle`(`status` ASC, `plan_settle_time` ASC) USING BTREE,
  INDEX `idx_round`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 349 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '集采供货单(含定采明细与结算)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulk_purchase_order_rank
-- ----------------------------
DROP TABLE IF EXISTS `bulk_purchase_order_rank`;
CREATE TABLE `bulk_purchase_order_rank`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_id` bigint NOT NULL COMMENT '供货单ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供货单号',
  `rank_code` tinyint NOT NULL COMMENT '等级 0无 1A 2B 3C 4D 5E 6O',
  `price` decimal(10, 2) NOT NULL COMMENT '冻结报价(该等级)，单位元，最小到分',
  `plan_label_num` int NOT NULL DEFAULT 0 COMMENT '计划标签张数(只增不减)',
  `printed_label_num` int NOT NULL DEFAULT 0 COMMENT '已生成标签张数',
  `scanned_label_num` int NOT NULL DEFAULT 0 COMMENT '已扫码合格扎数',
  `scanned_stem_num` int NOT NULL DEFAULT 0 COMMENT '标签盘点枝数 = 扎数*规格，只读',
  `settle_label_num` int NULL DEFAULT NULL COMMENT '盘点扎数 = 该等级扫码合格扎数；人工改应结算枝数时不跟着变，仅作核对用',
  `settle_stem_num` int NULL DEFAULT NULL COMMENT '应结算枝数 默认=scanned_stem_num，人工可按等级调；结算按这个算',
  `amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '= settle_stem_num*price，单位元，最小到分',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_rank`(`order_id` ASC, `rank_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 710 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '集采供货单等级维度(打印/盘点/结算)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulk_purchase_over_compensate
-- ----------------------------
DROP TABLE IF EXISTS `bulk_purchase_over_compensate`;
CREATE TABLE `bulk_purchase_over_compensate`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_id` bigint NOT NULL COMMENT '超量的供货单ID(当前标签供应商)',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '超量的供货单号',
  `demand_id` bigint NOT NULL COMMENT '需求ID；被占用方只能来自同一需求',
  `supplier_id` bigint NOT NULL COMMENT '当前标签供应商ID',
  `occupied_supplier_id` bigint NOT NULL COMMENT '被占用供应商ID',
  `occupied_supplier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '被占用供应商名称',
  `occupied_order_id` bigint NOT NULL COMMENT '被占用供应商在该需求下的供货单ID',
  `occupied_order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '被占用供应商的供货单号',
  `rank_code` tinyint NOT NULL COMMENT '等级 0无 1A 2B 3C 4D 5E 6O',
  `occupied_num` int NOT NULL COMMENT '被占用枝数',
  `price` decimal(10, 2) NOT NULL COMMENT '被占用方该等级的冻结报价，单位元，最小到分',
  `compensate_type` tinyint NOT NULL COMMENT '补偿方式 1登记补款 2线下补偿 3无需补偿',
  `compensate_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '补偿金额 默认=occupied_num*price',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `handler_id` bigint NULL DEFAULT NULL COMMENT '处理人',
  `handler_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处理人名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order`(`order_id` ASC) USING BTREE,
  INDEX `idx_occupied`(`occupied_supplier_id` ASC) USING BTREE,
  INDEX `idx_demand`(`demand_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '集采超量补偿(被占用供应商)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulk_purchase_product_mapping
-- ----------------------------
DROP TABLE IF EXISTS `bulk_purchase_product_mapping`;
CREATE TABLE `bulk_purchase_product_mapping`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `publish_supplier_id` bigint NOT NULL COMMENT '发布供应商ID',
  `second_id` bigint NOT NULL COMMENT '二级分类ID',
  `rank_code` tinyint NOT NULL COMMENT '等级 0无 1A 2B 3C 4D 5E 6O',
  `product_id` bigint NOT NULL COMMENT '商品ID',
  `source` tinyint NOT NULL COMMENT '1沿用现有商品 2自动创建集采SKU',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_publish_second_rank`(`publish_supplier_id` ASC, `second_id` ASC, `rank_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '集采库存商品映射' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulk_purchase_quote
-- ----------------------------
DROP TABLE IF EXISTS `bulk_purchase_quote`;
CREATE TABLE `bulk_purchase_quote`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `quote_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '报价单号 BPQ+... 每版本一个新号',
  `demand_id` bigint NOT NULL COMMENT '需求ID',
  `demand_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '需求编号',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `supplier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供应商名称',
  `version` int NOT NULL COMMENT '报价版本 从1递增',
  `total_supply_num` int NOT NULL COMMENT '总可供枝数',
  `is_current` tinyint NOT NULL DEFAULT 1 COMMENT '0历史 1当前有效',
  `select_status` tinyint NOT NULL DEFAULT 0 COMMENT '0待定 1已中选 2未中选',
  `submit_time` datetime NOT NULL COMMENT '提交时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quote_no`(`quote_no` ASC) USING BTREE,
  UNIQUE INDEX `uk_demand_supplier_version`(`demand_id` ASC, `supplier_id` ASC, `version` ASC) USING BTREE,
  INDEX `idx_demand_current`(`demand_id` ASC, `is_current` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 500 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '集采报价(版本化)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulk_purchase_quote_rank
-- ----------------------------
DROP TABLE IF EXISTS `bulk_purchase_quote_rank`;
CREATE TABLE `bulk_purchase_quote_rank`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `quote_id` bigint NOT NULL COMMENT '报价ID',
  `demand_id` bigint NOT NULL COMMENT '需求ID',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `rank_code` tinyint NOT NULL COMMENT '等级 0无 1A 2B 3C 4D 5E 6O',
  `price` decimal(10, 2) NOT NULL COMMENT '含税到厂价，单位元，最小到分',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_quote_rank`(`quote_id` ASC, `rank_code` ASC) USING BTREE,
  INDEX `idx_demand_supplier`(`demand_id` ASC, `supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1011 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '集采报价等级价格' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulk_purchase_scan_reject_log
-- ----------------------------
DROP TABLE IF EXISTS `bulk_purchase_scan_reject_log`;
CREATE TABLE `bulk_purchase_scan_reject_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `label_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '扫到的标签码原文，最长 128',
  `label_id` bigint NULL DEFAULT NULL COMMENT '标签ID',
  `order_id` bigint NULL DEFAULT NULL COMMENT '供货单ID',
  `rank_code` tinyint NULL DEFAULT NULL COMMENT '等级 0无 1A 2B 3C 4D 5E 6O',
  `reject_reason` tinyint NOT NULL COMMENT '2重复扫码 3标签已作废 4跨订单 5标签不存在 6供货单状态不允许',
  `fail_msg` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '失败说明',
  `first_scan_time` datetime NULL DEFAULT NULL COMMENT '重复时回带首次扫码时间',
  `first_scan_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '重复时回带首次扫码人',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order`(`order_id` ASC) USING BTREE,
  INDEX `idx_label`(`label_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 63 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '集采扫码失败流水' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulk_purchase_white_list
-- ----------------------------
DROP TABLE IF EXISTS `bulk_purchase_white_list`;
CREATE TABLE `bulk_purchase_white_list`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `supplier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供应商名称',
  `supplier_tag` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基地',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '0已移除 1有效',
  `remark` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_supplier`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '集采供应商白名单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulky_open_app
-- ----------------------------
DROP TABLE IF EXISTS `bulky_open_app`;
CREATE TABLE `bulky_open_app`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `partner_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分销商名称',
  `app_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appKey',
  `app_secret` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appSecret',
  `enable` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否启用 0-否 1-是',
  `access_token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'access_token',
  `expire_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'token过期时间',
  `callback_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '回调url',
  `order_callback` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单回调url',
  `try_enable` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否重试 0:不重试 1：重试',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_appkey`(`app_key` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货开放app' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulky_open_app_api_config
-- ----------------------------
DROP TABLE IF EXISTS `bulky_open_app_api_config`;
CREATE TABLE `bulky_open_app_api_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `app_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '应用id',
  `method` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '接口',
  `method_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '接口名称',
  `enable` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货开放app接口配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulky_order_extra
-- ----------------------------
DROP TABLE IF EXISTS `bulky_order_extra`;
CREATE TABLE `bulky_order_extra`  (
  `id` bigint NOT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulky_pay_app
-- ----------------------------
DROP TABLE IF EXISTS `bulky_pay_app`;
CREATE TABLE `bulky_pay_app`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '小程序/公众号 appId',
  `app_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'app 名称',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_app_id`(`app_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '支付接入方 app' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulky_pay_app_mch_bind
-- ----------------------------
DROP TABLE IF EXISTS `bulky_pay_app_mch_bind`;
CREATE TABLE `bulky_pay_app_mch_bind`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `channel_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `scene` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'PREPAY/PAY_NOTIFY/REFUND/REFUND_NOTIFY/QUERY，未配置的场景回落到 PREPAY',
  `mch_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `priority` int NOT NULL DEFAULT 0 COMMENT '数值小的优先',
  `status` tinyint NOT NULL DEFAULT 1,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_app_channel_scene_mch`(`app_id` ASC, `channel_code` ASC, `scene` ASC, `mch_no` ASC) USING BTREE,
  INDEX `idx_lookup`(`app_id` ASC, `channel_code` ASC, `scene` ASC, `status` ASC, `priority` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'app 与商户的多场景绑定' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulky_pay_biz_notify_config
-- ----------------------------
DROP TABLE IF EXISTS `bulky_pay_biz_notify_config`;
CREATE TABLE `bulky_pay_biz_notify_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '* 表示适用于所有 app',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '* 表示适用于所有业务类型',
  `ingress_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'DIRECT' COMMENT 'DELEGATED 业务方接渠道回调后转发验签 / DIRECT 渠道直连支付中心',
  `notify_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'DIRECT 模式下的业务方接收地址',
  `notify_secret` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '业务通知 HMAC-SHA256 密钥，业务方据此确认请求确实来自支付中心',
  `max_retries` int NOT NULL DEFAULT 8,
  `backoff_base_ms` bigint NOT NULL DEFAULT 5000,
  `backoff_max_ms` bigint NOT NULL DEFAULT 1800000,
  `alert_enabled` tinyint NOT NULL DEFAULT 1,
  `status` tinyint NOT NULL DEFAULT 1,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_app_biz`(`app_id` ASC, `biz_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '下游业务方接入配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulky_pay_biz_notify_task
-- ----------------------------
DROP TABLE IF EXISTS `bulky_pay_biz_notify_task`;
CREATE TABLE `bulky_pay_biz_notify_task`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `out_trade_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `event_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'PAY_SUCCESS/REFUND_SUCCESS/REFUND_FAILED',
  `ref_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款事件为 out_refund_no，支付事件为空；与前两列共同构成事件幂等键',
  `notify_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `payload` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0待投递 1已送达 2重试超限失败',
  `retry_count` int NOT NULL DEFAULT 0,
  `max_retries` int NOT NULL DEFAULT 8,
  `next_retry_at` datetime NOT NULL,
  `last_error` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_event`(`out_trade_no` ASC, `event_type` ASC, `ref_no` ASC) USING BTREE,
  INDEX `idx_dispatch`(`status` ASC, `next_retry_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '业务方通知任务（模式二）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulky_pay_mch
-- ----------------------------
DROP TABLE IF EXISTS `bulky_pay_mch`;
CREATE TABLE `bulky_pay_mch`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `mch_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '支付中心内部商户号，支付单一经创建即锁定，永不变更',
  `mch_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `channel_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'wxpay/wxb2b/tlpay/tlb2b/entpay',
  `channel_mch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '渠道侧商户号：微信 mchid、通联 cusid',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mch_no`(`mch_no` ASC) USING BTREE,
  INDEX `idx_channel`(`channel_code` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户主档' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulky_pay_mch_config
-- ----------------------------
DROP TABLE IF EXISTS `bulky_pay_mch_config`;
CREATE TABLE `bulky_pay_mch_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `mch_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `config_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '凭证 JSON，私钥/证书以 PEM 字符串存放，运行时直接注入 SDK，不落磁盘',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '渠道模块据此判断本地 SDK 客户端缓存是否过期',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mch_no`(`mch_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户凭证' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulky_pay_order
-- ----------------------------
DROP TABLE IF EXISTS `bulky_pay_order`;
CREATE TABLE `bulky_pay_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `out_trade_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '支付中心单号，全局唯一，即渠道侧商户订单号',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务类型，内核只透传不解释',
  `biz_order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务单号，内核只透传不解释',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `channel_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '下单时锁定，回调/退款/查单一律不得重新路由',
  `mch_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '下单时锁定，回调/退款/查单一律不得重新路由',
  `pay_type` int NOT NULL DEFAULT -1 COMMENT '业务方语义的支付方式整型码，由适配层按渠道映射，兼容 purchaser 存量',
  `channel_pay_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '渠道交易号，下单阶段为预支付标识，支付成功后为真实交易号',
  `amount` decimal(12, 2) NOT NULL COMMENT '订单金额（元）',
  `refunded_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '已成功退款累计（元）',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0待支付 1支付成功 2已关闭 3支付失败',
  `subject` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `open_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `client_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `notify_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '下单时下发给渠道的回调地址，排查用',
  `expire_time` datetime NULL DEFAULT NULL,
  `pay_time` datetime NULL DEFAULT NULL,
  `channel_payload` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '渠道下单返回的唤起参数，供重复 prepay 直接复用',
  `fail_reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_out_trade_no`(`out_trade_no` ASC) USING BTREE,
  INDEX `idx_biz_order`(`biz_type` ASC, `biz_order_sn` ASC) USING BTREE,
  INDEX `idx_channel_pay_id`(`channel_pay_id` ASC) USING BTREE,
  INDEX `idx_status_expire`(`status` ASC, `expire_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '支付单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulky_pay_refund
-- ----------------------------
DROP TABLE IF EXISTS `bulky_pay_refund`;
CREATE TABLE `bulky_pay_refund`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `out_refund_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '支付中心退款单号，渠道侧幂等键',
  `out_trade_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `channel_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `mch_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '取自原支付单，不重新路由',
  `channel_refund_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `refund_amount` decimal(12, 2) NOT NULL,
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0处理中 1成功 2失败',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `refund_time` datetime NULL DEFAULT NULL,
  `fail_reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_out_refund_no`(`out_refund_no` ASC) USING BTREE,
  INDEX `idx_out_trade_no`(`out_trade_no` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '退款单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bulky_pay_route_rule
-- ----------------------------
DROP TABLE IF EXISTS `bulky_pay_route_rule`;
CREATE TABLE `bulky_pay_route_rule`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '* 表示适用于所有 app',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '* 表示适用于所有业务类型',
  `channel_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `priority` int NOT NULL DEFAULT 0 COMMENT '数值小的先尝试，构成降级链',
  `status` tinyint NOT NULL DEFAULT 1,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_app_biz_channel`(`app_id` ASC, `biz_type` ASC, `channel_code` ASC) USING BTREE,
  INDEX `idx_lookup`(`app_id` ASC, `biz_type` ASC, `status` ASC, `priority` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '渠道路由规则，取代 purchaser 散落在 Redis 的 B2B/通联开关' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_order
-- ----------------------------
DROP TABLE IF EXISTS `city_order`;
CREATE TABLE `city_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小时达订单号',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appId',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `coupon_user_id` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '用户优惠券id，0:没有用优惠券',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓供应商id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '【用户】采购方id',
  `open_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信openId',
  `date` date NOT NULL DEFAULT '2024-01-01' COMMENT '日期',
  `order_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '【订单】城市仓流水号',
  `order_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '【订单】订单状态 0:待付款 1:已付款待发货 2:已发货待收货 3:已完成 4:已关闭 5:已取消',
  `after_sale_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '【订单】售后状态 0-无 1-申请中 2-售后同意 3-售后拒绝',
  `send_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '【订单】配送状态 0-未配送 1-配送中 2-已送达 3-已取消',
  `product_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '【订单】商品总价（元）',
  `delivery_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '【订单】配送费（元）',
  `total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '【订单】订单总价（元）',
  `total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '【订单】商品总重(g)',
  `origin_actual_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '【支付】用户原实付金额（元）',
  `actual_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '【支付】用户实付金额（元）',
  `supplier_due_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '【结算】商家应收（元）',
  `supplier_settle_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '【结算】商家结算金额（元）',
  `pick_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '【订单】配送方式 0-送货上门 1-自提',
  `buyer_memo` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '【用户】买家留言',
  `receive_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '【用户】收件人名称',
  `receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '【用户】收件人电话',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `district` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `adcode` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'adcode',
  `detail` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `longitude` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `pay_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付单号',
  `pay_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付方式 0：微信支付 1：寻梦平台账户支付 6：B2b支付 10：通联支付',
  `merchant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户号',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '支付时间',
  `send_time` datetime NULL DEFAULT NULL COMMENT '发货时间',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认收货时间',
  `cancel_time` datetime NULL DEFAULT NULL COMMENT '取消时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE,
  INDEX `idx_date_wareid`(`date` ASC, `ware_id` ASC) USING BTREE,
  INDEX `idx_paytime`(`pay_time` ASC) USING BTREE,
  INDEX `idx_pid`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 174 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓小时达订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for city_order_item
-- ----------------------------
DROP TABLE IF EXISTS `city_order_item`;
CREATE TABLE `city_order_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小时达订单号',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `product_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级123456->ABCDEO',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `spec_and_num` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格数量+规格名称',
  `pay_price` decimal(10, 2) UNSIGNED NULL DEFAULT 0.00 COMMENT '实付单价（元）',
  `product_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商品价格单价（元）',
  `weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '单个重量（g）',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单商品数量',
  `origin_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原订单商品数量',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 197 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓小时达订单商品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for city_order_log
-- ----------------------------
DROP TABLE IF EXISTS `city_order_log`;
CREATE TABLE `city_order_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 1-订单 2-售后',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小时达订单号',
  `refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后id',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '内容，限255字',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ordersn_type`(`order_sn` ASC, `type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 168 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓小时达订单日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for city_order_refund
-- ----------------------------
DROP TABLE IF EXISTS `city_order_refund`;
CREATE TABLE `city_order_refund`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小时达订单号',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `apply_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请金额',
  `refund_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `refund_item` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款商品id json [1,2,3]',
  `after_sale_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后状态 0-已创建 1-同意 2-拒绝 3-取消',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款状态 0-无 1-同意退款 2-退款成功 3-退款失败',
  `apply_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '申请原因，限255字',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝原因，限255字',
  `wx_refund_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信退款单号',
  `wx_refund_success_time` datetime NULL DEFAULT NULL COMMENT '退款成功时间',
  `pictures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '退款凭证图片链接数组',
  `videos` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '退款凭证视频链接数组',
  `remark` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注，限64字',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态 默认0：正常 -100：删除',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人id',
  `operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `agree_time` datetime NULL DEFAULT NULL COMMENT '售后同意时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_agreetime`(`agree_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 77 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓小时达售后表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for city_order_trade_record
-- ----------------------------
DROP TABLE IF EXISTS `city_order_trade_record`;
CREATE TABLE `city_order_trade_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓小时达交易记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_print_set
-- ----------------------------
DROP TABLE IF EXISTS `city_print_set`;
CREATE TABLE `city_print_set`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `ware_id` int NOT NULL COMMENT '城市仓id',
  `auto_print` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '自动打印 0不是 1：是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓小票自动打印' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_receipt_print
-- ----------------------------
DROP TABLE IF EXISTS `city_receipt_print`;
CREATE TABLE `city_receipt_print`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `ware_id` int NOT NULL COMMENT '公司ID',
  `machine_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '打印机终端号',
  `msign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '打印机特殊密钥',
  `access_token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '打印机token',
  `refresh_token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '打印机refresh_token',
  `expires_in` int NULL DEFAULT NULL COMMENT '令牌有效时间，单位s',
  `apply_time` int NULL DEFAULT NULL COMMENT '令牌申请时间',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态， 1 => 正常 -1 => 删除',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `over_time` int NULL DEFAULT NULL COMMENT '过期时间',
  `is_used` tinyint NULL DEFAULT NULL COMMENT '是否默认： 1 => 默认 0 => 非默认',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '名称',
  `type` tinyint NULL DEFAULT 1 COMMENT '类别：1=>易联云 2=>优声云 3:商鹏 4：中午 5：飞鹅',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ware_id`(`ware_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 42 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓小票打印' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_warehouse
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse`;
CREATE TABLE `city_warehouse`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市仓名称，限10字',
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '绑定结算供应商id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '绑定采购方id',
  `express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流配置id',
  `region_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流区域id',
  `store_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货门店id',
  `city_store_open` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '城市仓小时达营业状态 0-关闭 1-开启',
  `add_price` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 1.00 COMMENT '基础加价（元）',
  `add_price_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '加价开关 0-正常 1-支持负值',
  `distance` float(8, 2) UNSIGNED NOT NULL DEFAULT 5.00 COMMENT '配送范围km',
  `distance_price` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '距离收费系数（元/km）',
  `weight_price` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '重量收费系数（元/kg）',
  `express_add_price` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '物流加价系数 元/kg 范围0-20',
  `start_sell_weight` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '起售重量kg 默认0kg',
  `distribution_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '配送方式 0-都支持 1-只送货上门 2-只自提',
  `longitude` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `district` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `detail` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址',
  `business_address` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '营业地址',
  `city_code` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市代码',
  `adcode` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市仓adcode',
  `contact_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名，限32字',
  `contact_tel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人电话，限32字',
  `logistics_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '直营仓物流电话，限20字',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-已创建 1-已开通 2-已关闭 3-临时关闭',
  `operate_status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '营业状态 0-关 1-开 默认开',
  `phone_switch` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '电话展示开关 0-关 1-开 默认开',
  `flash_sale_switch` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '秒杀商品开关 0-关 1-开 默认开',
  `cotton_switch` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温棉开关 0-关 1-开 默认关',
  `cotton_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温棉数量 最大50',
  `board_switch` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温板开关 0-关 1-开 默认关',
  `board_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温板数量 最大50',
  `hour_delivery_switch` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '小时达开关 0-关 1-开 默认开',
  `xmmaterials_open` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '资材开关 0-关 1-开 默认开',
  `change_add_price_switch` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '城市仓加价开关 0-关 1-开 默认开',
  `single_delivery_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否单独发货 0-否 1-是',
  `coupon_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '城市仓优惠券开关 0-否 1-是 默认开',
  `promote_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推广合作 0-否 1-是',
  `service_fee_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '服务费开关 0-关 1-开 默认关 关闭1.6元每公斤 开启1元每公斤',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '后台备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `delivery_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）临时加字段为了兼容资材',
  `share_ratio` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）临时加字段为了兼容资材',
  `promote_merchant_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推广商家 0-否 1-是',
  `large_customer_pack_flag` tinyint NOT NULL DEFAULT 0 COMMENT '大客户单独打包开关 0-关 1-开',
  `large_customer_pack_weight` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 6.00 COMMENT '大客户单独打包起重重量kg',
  `logistics_unit_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '繁花物流单价元/kg，null未配置，0为零元',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sid`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_appid`(`app_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 900204 AVG_ROW_LENGTH = 399 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for city_warehouse_class_banner
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_class_banner`;
CREATE TABLE `city_warehouse_class_banner`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级分类id 0为总横幅',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '横幅内容 限255字',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_wid_fid`(`ware_id` ASC, `first_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 797 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓横幅表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_warehouse_class_first_add_price
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_class_first_add_price`;
CREATE TABLE `city_warehouse_class_first_add_price`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级123456->ABCDEO',
  `add_price` decimal(6, 2) NOT NULL DEFAULT 0.00 COMMENT '加价（元）可以为负',
  `enable` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '开关 0-关 1-开',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_firstid_ranknum_wareid`(`first_id` ASC, `rank_num` ASC, `ware_id` ASC) USING BTREE,
  INDEX `idx_wareid`(`ware_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 384 AVG_ROW_LENGTH = 61 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓一级分类加价表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_warehouse_class_second_add_price
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_class_second_add_price`;
CREATE TABLE `city_warehouse_class_second_add_price`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级123456->ABCDEO',
  `add_price` decimal(6, 2) NOT NULL DEFAULT 0.00 COMMENT '加价（元）可以为负',
  `enable` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '开关 0-关 1-开',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_secondid_ranknum_wareid`(`second_id` ASC, `rank_num` ASC, `ware_id` ASC) USING BTREE,
  INDEX `idx_wareid`(`ware_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 784 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓二级分类加价表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_warehouse_copy1
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_copy1`;
CREATE TABLE `city_warehouse_copy1`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市仓名称，限10字',
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '绑定结算供应商id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '绑定采购方id',
  `express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流配置id',
  `store_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货门店id',
  `city_store_open` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '城市仓小时达营业状态 0-关闭 1-开启',
  `distribution_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '配送方式 0-都支持 1-只送货上门 2-只自提',
  `add_price` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 1.00 COMMENT '基础加价（元）',
  `add_price_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '加价开关 0-正常 1-支持负值',
  `distance` float(8, 2) UNSIGNED NOT NULL DEFAULT 5.00 COMMENT '配送范围km',
  `distance_price` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '距离收费系数（元/km）',
  `weight_price` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '重量收费系数（元/kg）',
  `express_add_price` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '物流加价系数 元/kg 范围0-20',
  `start_sell_weight` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '起售重量kg 默认6kg',
  `share_ratio` decimal(1, 0) UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）',
  `longitude` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `district` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `detail` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址',
  `business_address` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '营业地址',
  `city_code` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市代码',
  `adcode` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市仓adcode',
  `contact_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名，限32字',
  `contact_tel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人电话，限32字',
  `logistics_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '直营仓物流电话，限20字',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-已创建 1-已开通 2-已关闭',
  `operate_status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '营业状态 0-关 1-开 默认开',
  `phone_switch` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '电话展示开关 0-关 1-开 默认开',
  `flash_sale_switch` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '秒杀商品开关 0-关 1-开 默认开',
  `cotton_switch` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温棉开关 0-关 1-开 默认关',
  `cotton_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温棉数量 最大50',
  `board_switch` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温板开关 0-关 1-开 默认关',
  `board_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温板数量 最大50',
  `hour_delivery_switch` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '小时达开关 0-关 1-开 默认开',
  `xmmaterials_open` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '资材开关 0-关 1-开 默认开',
  `change_add_price_switch` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '城市仓加价开关 0-关 1-开 默认开',
  `single_delivery_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否单独发货 0-否 1-是',
  `coupon_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '城市仓优惠券开关 0-否 1-是 默认开',
  `promote_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推广合作 0-否 1-是',
  `service_fee_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '服务费开关 0-关 1-开 默认关 关闭1.6元每公斤 开启1元每公斤',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 604 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for city_warehouse_data_statistics
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_data_statistics`;
CREATE TABLE `city_warehouse_data_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `yyyy_mm_dd` date NOT NULL COMMENT '年月日，如2024-06-18',
  `ware_id` int NOT NULL COMMENT '城市仓id',
  `all_total_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '用户支付金额',
  `turnover` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '营业额',
  `supplier_due` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商所得',
  `send_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货单数',
  `order_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单数',
  `item_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品扎数',
  `base_item_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '基地扎数',
  `total_weight` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日总重（kg）排除自提订单',
  `new_purchaser_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日新用户数',
  `old_purchaser_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日老用户数',
  `ware_product_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '城市仓商品加价',
  `ware_express_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '城市仓物流加价',
  `ware_material_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '城市仓资材加价',
  `express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '运费',
  `delivery_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '配送费',
  `service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '服务费',
  `refer_service_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '服务费支出',
  `delta_service_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '服务费 = 服务费收入-服务费支出',
  `add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '加价',
  `rebate_xm_coin` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '用户返点',
  `subsidy_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '单品补贴金额',
  `cotton_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '保温棉金额',
  `after_sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '售后金额（按处理时间）',
  `all_refund_express_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '运费退款',
  `all_express_fill` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '运费补差',
  `total_station_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商承担的集货站运费',
  `supplier_after_sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商售后承担',
  `ware_after_sale_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓售后承担',
  `pack_bear_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '打包承担金额',
  `express_bear_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '物流承担金额',
  `supplier_punish` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商处罚',
  `take_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日供应商抽点',
  `take_xm_coin_return` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日供应商抽点返还',
  `total_income` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '收入合计',
  `vip_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '会员收入',
  `vip_discount_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'vip减免服务费',
  `flash_sale_discount_in` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '秒杀活动补贴增加',
  `flash_sale_discount_out` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '秒杀活动补贴减少',
  `platform_coupon_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台承担优惠券',
  `coupon_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '其他承担优惠券',
  `platform_reduce_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台满减金额',
  `complain_return_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申诉退回金额',
  `quality_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '质检收入',
  `discount_express_price` decimal(10, 0) NOT NULL DEFAULT 0 COMMENT '优惠运费',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_date_wareid`(`yyyy_mm_dd` ASC, `ware_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 315 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓数据统计' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_warehouse_express_record
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_express_record`;
CREATE TABLE `city_warehouse_express_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型 1-扣运费 2-补运费',
  `round_no` date NOT NULL COMMENT '场次 yyyy-MM-dd',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `send_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货单数',
  `warehouse_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '城市仓加价（可能为负）',
  `express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓物流加价',
  `service_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '城市仓服务费支出=服务费-服务费减免',
  `platform_coupon_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '平台承担的订单剩余优惠金额',
  `coupon_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '城市仓/分销商承担的订单剩余优惠金额',
  `express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实际运费（填写）',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-已创建 1-已确认 2-已结算',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注 限128字',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新用户名称',
  `settle_time` datetime NULL DEFAULT NULL COMMENT '结算时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_roundno_wareid`(`round_no` ASC, `ware_id` ASC, `partner_id` ASC, `type` ASC) USING BTREE,
  INDEX `idx_settletime`(`settle_time` ASC) USING BTREE,
  INDEX `idx_wareidtypestatus`(`ware_id` ASC, `type` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 598 AVG_ROW_LENGTH = 180 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓物流费用记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for city_warehouse_fhh_logistics_fee
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_fhh_logistics_fee`;
CREATE TABLE `city_warehouse_fhh_logistics_fee`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `partner_id` int NOT NULL COMMENT '繁花140',
  `ware_id` int NOT NULL COMMENT '城市仓ID，0为任务执行标记',
  `receiver_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '截单时城市仓老板ID',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次日期',
  `cutoff_stage` tinyint UNSIGNED NOT NULL COMMENT '0白场1晚场',
  `unit_price` decimal(10, 2) NOT NULL COMMENT '冻结单价元/kg',
  `valid_weight_g` bigint UNSIGNED NOT NULL DEFAULT 0,
  `amount` decimal(12, 2) NOT NULL DEFAULT 0.00,
  `settle_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0未结算1已结算',
  `settle_biz_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `settle_time` datetime NULL DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_partner_ware_round_stage`(`partner_id` ASC, `ware_id` ASC, `round_no` ASC, `cutoff_stage` ASC) USING BTREE,
  INDEX `idx_round_settle`(`round_no` ASC, `settle_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 388 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '繁花城市仓物流费场次快照' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_warehouse_log
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_log`;
CREATE TABLE `city_warehouse_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `user_type` tinyint NOT NULL COMMENT '用户类型 0:系统 1:平台 3:城市仓',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作内容',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_wareid_ctime`(`ware_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_warehouse_promote_fee_log
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_promote_fee_log`;
CREATE TABLE `city_warehouse_promote_fee_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ware_id` int NOT NULL COMMENT '城市仓id',
  `supplier_id` bigint NOT NULL COMMENT '供应商id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id，0-纯城市仓 140-繁花包干',
  `type` int NOT NULL COMMENT '变动类型 1-结算收入 2-提现支出 3-提现退回',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '变动原因说明',
  `item_num` int UNSIGNED NULL DEFAULT 0 COMMENT '关联扎数（月结可选）',
  `amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '推广费余额变动额，正增负减',
  `old_money` decimal(12, 2) NOT NULL COMMENT '变动前推广费余额',
  `new_money` decimal(12, 2) NOT NULL COMMENT '变动后推广费余额',
  `biz_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '业务单号，如提现编码 TXxxx、月结 yyyy-MM',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_supplier_time`(`supplier_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_ware_time`(`ware_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 133 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓推广费账单流水' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_warehouse_promote_income_statistics
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_promote_income_statistics`;
CREATE TABLE `city_warehouse_promote_income_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `statistics_start_date` date NOT NULL COMMENT '统计开始场次日期，固定为当月1日',
  `statistics_end_date` date NOT NULL COMMENT '统计截止场次日期',
  `ware_id` int UNSIGNED NOT NULL COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id，0-纯城市仓 140-繁花包干',
  `order_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单基础扎数，统计订单状态1/2/3',
  `punish_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '处罚扣减扎数',
  `statistics_time` datetime NOT NULL COMMENT '最近一次统计完成时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_start_ware_partner`(`statistics_start_date` ASC, `ware_id` ASC, `partner_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4715 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓包干预计收益统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_warehouse_promote_settle
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_promote_settle`;
CREATE TABLE `city_warehouse_promote_settle`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ware_id` int NOT NULL COMMENT '城市仓id',
  `supplier_id` bigint NOT NULL COMMENT '供应商id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id，0-纯城市仓 140-繁花',
  `month` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '结算月份 yyyy-MM',
  `item_num` int NOT NULL DEFAULT 0 COMMENT '结算扎数',
  `unit_price` decimal(4, 2) NOT NULL COMMENT '单价 1.6或1.8',
  `money` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '结算金额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ware_month_pid`(`ware_id` ASC, `month` ASC, `partner_id` ASC) USING BTREE,
  INDEX `idx_ware_id`(`ware_id` ASC) USING BTREE,
  INDEX `idx_month`(`month` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 110 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓推广费月结汇总' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_warehouse_remark
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_remark`;
CREATE TABLE `city_warehouse_remark`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `valid_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '生效类型 1-长期有效 2-临时有效',
  `valid_start` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '生效场次开始',
  `valid_end` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '生效场次结束',
  `remark` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注信息，限64字',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-正常 1-关闭',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_wareid`(`ware_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓备注表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_warehouse_shipping_area
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_shipping_area`;
CREATE TABLE `city_warehouse_shipping_area`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `area` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配送范围数组[{\"x\":1,\"y\":2}]',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_wareid`(`ware_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 44 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓配送范围配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for city_warehouse_user
-- ----------------------------
DROP TABLE IF EXISTS `city_warehouse_user`;
CREATE TABLE `city_warehouse_user`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `nickname` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '姓名',
  `is_sub` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为子账号 0:否; 1:是;',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_userid_wareid`(`user_id` ASC, `ware_id` ASC) USING BTREE,
  INDEX `idx_wareid`(`ware_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 72 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓管理员' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for class_second_avg_price
-- ----------------------------
DROP TABLE IF EXISTS `class_second_avg_price`;
CREATE TABLE `class_second_avg_price`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `platform` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '渠道 1-批发 2-城市仓 3-优花速达 4-繁花惠',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '成交扎数',
  `total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '成交总价',
  `avg_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '成交均价',
  `coupon_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '优惠券总金额',
  `subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '单品补贴总金额',
  `supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价总金额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_roundno_sid_rank_platform`(`round_no` ASC, `second_id` ASC, `rank_num` ASC, `platform` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1666728 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '二级分类均价表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for common_coupon_mail
-- ----------------------------
DROP TABLE IF EXISTS `common_coupon_mail`;
CREATE TABLE `common_coupon_mail`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int NOT NULL DEFAULT 0 COMMENT '分销商id',
  `ware_id` int NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `coupon_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '优惠券编号',
  `coupon_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '优惠券名称',
  `user_type` tinyint NOT NULL DEFAULT 0 COMMENT '可领券的用户类型 1:新客&老客; 2:新客; 3:老客; 4:指定用户;',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 139 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '通用优惠券邮箱表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for community_activity
-- ----------------------------
DROP TABLE IF EXISTS `community_activity`;
CREATE TABLE `community_activity`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `activity_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动名称',
  `community_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '社群名称/备注',
  `activity_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动唯一码（用于生成链接）',
  `link_token` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'C端链接密钥',
  `start_time` datetime NOT NULL COMMENT '有效期开始',
  `end_time` datetime NOT NULL COMMENT '有效期结束',
  `win_rate` int UNSIGNED NOT NULL DEFAULT 100 COMMENT '中奖概率（0-100，100=必中）',
  `participant_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '已参与人数（含未中奖）',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0=正常 -100=删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_activity_code`(`activity_code` ASC) USING BTREE,
  UNIQUE INDEX `uk_link_token`(`link_token` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE,
  INDEX `idx_end_time_data_status`(`end_time` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '社群抽券活动表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for community_activity_coupon_pool
-- ----------------------------
DROP TABLE IF EXISTS `community_activity_coupon_pool`;
CREATE TABLE `community_activity_coupon_pool`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `activity_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '活动id',
  `coupon_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '优惠券编号',
  `total_stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '总库存（投放数量）',
  `remain_stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '剩余库存',
  `send_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '已领取数量',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_activity_coupon`(`activity_id` ASC, `coupon_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '社群活动券池表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for community_activity_log
-- ----------------------------
DROP TABLE IF EXISTS `community_activity_log`;
CREATE TABLE `community_activity_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `activity_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '活动id',
  `action_content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '编辑日志展示文案',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_activity_time`(`activity_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 40 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '社群活动编辑日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for community_activity_record
-- ----------------------------
DROP TABLE IF EXISTS `community_activity_record`;
CREATE TABLE `community_activity_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `activity_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '活动id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '繁花用户ID',
  `biz_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '抽券请求幂等号',
  `draw_status` tinyint NOT NULL DEFAULT 0 COMMENT '0=处理中 1=已中奖 2=未中奖',
  `coupon_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '中奖优惠券编号，未中奖为空',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_activity_user`(`activity_id` ASC, `purchaser_id` ASC) USING BTREE,
  INDEX `idx_biz_no`(`biz_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20123 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '社群活动参与记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for customer_area_type
-- ----------------------------
DROP TABLE IF EXISTS `customer_area_type`;
CREATE TABLE `customer_area_type`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '大区名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '客服分区表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for daily_shelf
-- ----------------------------
DROP TABLE IF EXISTS `daily_shelf`;
CREATE TABLE `daily_shelf`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货位号数字',
  `zone` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货位号',
  `zone_shelf` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区货位号',
  `sub_shelf_sn` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货位号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `warehouse_config_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '白场截单城市仓合并及物流配置快照',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_roundno`(`round_no` ASC) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_round_zone_shelf_sn`(`round_no` ASC, `zone` ASC, `shelf_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1787186 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '每日货位表' ROW_FORMAT = Dynamic;

-- ----------------------------
