-- ----------------------------
-- Table structure for distributor_pickup_inventory_scan_log
-- ----------------------------
DROP TABLE IF EXISTS `distributor_pickup_inventory_scan_log`;
CREATE TABLE `distributor_pickup_inventory_scan_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次日期',
  `code_content` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '扫码内容',
  `enter_item_id` bigint NOT NULL COMMENT '入场商品ID',
  `order_item_id` bigint NULL DEFAULT NULL COMMENT '订单商品ID',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单号',
  `shelf_sn` int NOT NULL COMMENT '货架号',
  `sub_shelf_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '子货架号',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区-货架',
  `supplier_id` bigint NULL DEFAULT NULL COMMENT '供应商ID',
  `partner_id` int NULL DEFAULT NULL COMMENT '分销商ID',
  `product_id` bigint NULL DEFAULT NULL COMMENT '商品ID',
  `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `second_id` bigint NULL DEFAULT NULL COMMENT '二级分类ID',
  `rank_num` int NULL DEFAULT NULL COMMENT '等级',
  `maturity` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生熟度',
  `user_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人手机号',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '数据状态：0正常，-100删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_date_code_status`(`date` ASC, `code_content` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_date_shelf_status`(`date` ASC, `shelf_sn` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_enter_item`(`enter_item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销商提货盘点扫码日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for enter_item_record_log
-- ----------------------------
DROP TABLE IF EXISTS `enter_item_record_log`;
CREATE TABLE `enter_item_record_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `code_content` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '扫码内容',
  `date` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `zone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区-货架',
  `enter_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'enter_item表主键id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名称',
  `op` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作 1：增加 2：减少',
  `is_man` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否人工 0不是 1是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '默认0 删除-100',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_code_content`(`code_content` ASC) USING BTREE COMMENT '二维码内容',
  INDEX `idx_date`(`date` ASC) USING BTREE,
  INDEX `idx_enterItem`(`enter_item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 447 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '扫码枪商品盘点表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for express_concat
-- ----------------------------
DROP TABLE IF EXISTS `express_concat`;
CREATE TABLE `express_concat`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `express_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流名称',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `config_id_str` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '物流id配置',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 211 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流联系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for fee_config
-- ----------------------------
DROP TABLE IF EXISTS `fee_config`;
CREATE TABLE `fee_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `platform` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '渠道 1-大件 2-花仓酷 3-优花 4-繁花 5-分销',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称',
  `base_add_price` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有基础加价',
  `express_price` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有运费',
  `subsidy_price` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有单品补贴',
  `service_fee` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有服务费 0-不收 1-收 2-看配置',
  `service_fee_mch` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否收老板服务费',
  `category_add_price` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓分销商分类加价',
  `express_add_price` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓物流加价',
  `delivery_fee` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓配送费',
  `self_take` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有自提',
  `sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有到场货',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_platform`(`platform` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '费用配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for fhh_member_level_config
-- ----------------------------
DROP TABLE IF EXISTS `fhh_member_level_config`;
CREATE TABLE `fhh_member_level_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `level` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '会员等级',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '等级名称，限20字',
  `rate` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 1.00 COMMENT '积分速率',
  `max_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '最大扎数 右开',
  `coupon_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '专属优惠券',
  `extra_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '额外信息',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '繁花会员等级配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for fhh_member_level_history
-- ----------------------------
DROP TABLE IF EXISTS `fhh_member_level_history`;
CREATE TABLE `fhh_member_level_history`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '扎数',
  `old_level_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '旧等级id',
  `old_level_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '旧等级名称',
  `level_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '新等级id',
  `level_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '新等级名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pid`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 567 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '繁花会员等级更新记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for fhh_region_order_statistics
-- ----------------------------
DROP TABLE IF EXISTS `fhh_region_order_statistics`;
CREATE TABLE `fhh_region_order_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `round_no` date NOT NULL COMMENT '场次日期',
  `province` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '省',
  `city` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '市',
  `purchaser_id` bigint NOT NULL DEFAULT 0 COMMENT '采购商ID，0表示未知采购商',
  `total_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '订单合计金额',
  `warehouse_add_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '分销商商品加价',
  `express_add_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '分销商物流加价',
  `service_fee` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '服务费',
  `total_weight` bigint NOT NULL DEFAULT 0 COMMENT '物流配送订单总重量（克）',
  `coupon_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '优惠券金额',
  `ot_exp_add_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '一次性物流加价',
  `platform_reduce_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '平台满减金额',
  `extra_service_fee` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '额外服务费',
  `send_num` int NOT NULL DEFAULT 0 COMMENT '发货单数',
  `order_num` int NOT NULL DEFAULT 0 COMMENT '订单数',
  `item_num` int NOT NULL DEFAULT 0 COMMENT '商品扎数',
  `supply_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '供货价',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_fhh_region_round_province_city_purchaser`(`round_no` ASC, `province` ASC, `city` ASC, `purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 168 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '繁花地域城市采购商日统计' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for flash_sale_apply
-- ----------------------------
DROP TABLE IF EXISTS `flash_sale_apply`;
CREATE TABLE `flash_sale_apply`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `plan_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '计划ID',
  `product_id` bigint NOT NULL COMMENT '商品ID',
  `flash_product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '秒杀商品ID',
  `reduce_type` tinyint NOT NULL DEFAULT 1 COMMENT '扣减类型 1.默认不扣减原商品库库存 2.扣减原商品库库存',
  `price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `second_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级分类名称',
  `sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商主键id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '提交数目',
  `sold_num` int NOT NULL DEFAULT 0 COMMENT '已售出数目',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0-待审核 1-审核通过 2.审核拒绝',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_planid_num_status`(`plan_id` ASC, `num` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 152 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '秒杀申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for flash_sale_permission
-- ----------------------------
DROP TABLE IF EXISTS `flash_sale_permission`;
CREATE TABLE `flash_sale_permission`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方主键id',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '采购方名称',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态（0:申请 1:通过 2:拒绝 3:取消权限）',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '驳回理由 限255字',
  `review_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核人id',
  `review_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `apply_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '申请时间',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_applytime`(`apply_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '秒杀权限表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for flash_sale_plan
-- ----------------------------
DROP TABLE IF EXISTS `flash_sale_plan`;
CREATE TABLE `flash_sale_plan`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `session_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '场次id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `second_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级分类名称',
  `sku_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `plan_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '计划扎数',
  `current_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '参与计划扎数',
  `supplier_min_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商最低供货扎数',
  `supplier_max_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商最高供货扎数',
  `start_time` datetime NOT NULL COMMENT '售卖开始时间',
  `end_time` datetime NOT NULL COMMENT '售卖结束时间',
  `max_supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '最高供货价',
  `subsidy_amount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '每扎补贴金额（元）',
  `limit_sale` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否限购 默认 0：不限购 1：限购',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-已创建 1-已发布 2-已上线',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_secondid`(`second_id` ASC) USING BTREE,
  INDEX `idx_endtime`(`end_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4462 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '秒杀计划表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for flash_sale_session
-- ----------------------------
DROP TABLE IF EXISTS `flash_sale_session`;
CREATE TABLE `flash_sale_session`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `round_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子场次名称',
  `session_start_time` datetime NULL DEFAULT NULL COMMENT '场次开始时间',
  `session_end_time` datetime NULL DEFAULT NULL COMMENT '场次结束时间',
  `start_time` time NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` time NULL DEFAULT NULL COMMENT '结束时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_roundno`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 835 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '秒杀场次表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for gallery_visit_user_daily
-- ----------------------------
DROP TABLE IF EXISTS `gallery_visit_user_daily`;
CREATE TABLE `gallery_visit_user_daily`  (
  `stat_date` date NOT NULL COMMENT '统计日期',
  `user_id` bigint NOT NULL COMMENT '访问用户ID',
  `open_count` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '从大件金刚位进入图库首页次数',
  `page_view_count` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '图库页面累计进入次数',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`stat_date`, `user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '图库用户每日访问聚合表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for gengxin
-- ----------------------------
DROP TABLE IF EXISTS `gengxin`;
CREATE TABLE `gengxin`  (
  `order_sn` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `supplier_id` int NULL DEFAULT NULL
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for gift_user
-- ----------------------------
DROP TABLE IF EXISTS `gift_user`;
CREATE TABLE `gift_user`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 1-采购方 2-供应商',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `user_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名称、供应商名称',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `supplier_tag` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商基地',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '礼物状态 0-未领取 1-已领取 2-采购方已下单',
  `send_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货状态 0-未发货 1-已发货',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '采购方订单号',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注，限255字',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `take_time` datetime NULL DEFAULT NULL COMMENT '领取时间',
  `order_time` datetime NULL DEFAULT NULL COMMENT '采购方下单时间',
  `round_no` date NULL DEFAULT NULL COMMENT '下单场次',
  `send_time` datetime NULL DEFAULT NULL COMMENT '发货时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_type_userid`(`type` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '礼物用户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for group_tag_relation
-- ----------------------------
DROP TABLE IF EXISTS `group_tag_relation`;
CREATE TABLE `group_tag_relation`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `group_id` bigint NOT NULL DEFAULT 0 COMMENT '标签组id',
  `tag_id` bigint NOT NULL DEFAULT 0 COMMENT '标签id',
  `rank_A` tinyint NOT NULL DEFAULT 0 COMMENT '等级A：0-不是 1-是',
  `rank_B` tinyint NOT NULL DEFAULT 0 COMMENT '等级B：0-不是 1-是',
  `rank_C` tinyint NOT NULL DEFAULT 0 COMMENT '等级C：0-不是 1-是',
  `rank_D` tinyint NOT NULL DEFAULT 0 COMMENT '等级D：0-不是 1-是',
  `rank_E` tinyint NOT NULL DEFAULT 0 COMMENT '等级E：0-不是 1-是',
  `rank_O` tinyint NOT NULL DEFAULT 0 COMMENT '等级O：0-不是 1-是',
  `rank_free` tinyint NOT NULL DEFAULT 1 COMMENT '标签体系重构-无等级：1-该规格在标签组内对所有商品等级统一生效，不再区分rank_A~rank_O',
  `need_flag` tinyint NOT NULL DEFAULT 0 COMMENT '标签体系重构-该基础标签在本组内是否必填：0-否 1-是（同一基础标签下各规格行取值一致）',
  `sort_num` int NOT NULL DEFAULT 0 COMMENT '标签体系重构-该规格行在本组内的排序，行级全局升序：基础标签之间按其首行先后，同一基础标签内的规格按各自行先后',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_groupid_tagid`(`group_id` ASC, `tag_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1654 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '标签组和标签关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for help_change_record
-- ----------------------------
DROP TABLE IF EXISTS `help_change_record`;
CREATE TABLE `help_change_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int NOT NULL DEFAULT 0 COMMENT '分销商id',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `user_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户手机号',
  `old_data` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '修改前数据：某某[312312]',
  `new_data` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '修改后数据：某某[312312]',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 160 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销推广员修改日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for holiday_limit
-- ----------------------------
DROP TABLE IF EXISTS `holiday_limit`;
CREATE TABLE `holiday_limit`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `limit_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '限制数量 0不限',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_roundno`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '节日限单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_app_version
-- ----------------------------
DROP TABLE IF EXISTS `hub_app_version`;
CREATE TABLE `hub_app_version`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `version_code` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '版本号(整数,用于比较,如1002)',
  `version_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '版本名称(展示用,如2.3.0)',
  `download_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'apk下载地址',
  `force_update` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否强制更新：0-否 1-是',
  `change_log` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新说明',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态：0-停用 1-启用(参与最新版本判定)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_version_code`(`version_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-司机APP版本发布记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_area
-- ----------------------------
DROP TABLE IF EXISTS `hub_area`;
CREATE TABLE `hub_area`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '片区名称',
  `leader_id` bigint NOT NULL DEFAULT 0 COMMENT '组长子账号id',
  `leader_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '组长姓名',
  `remark` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：1-正常 -100-删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-片区表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_device
-- ----------------------------
DROP TABLE IF EXISTS `hub_device`;
CREATE TABLE `hub_device`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `device_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '终端设备编号(808终端号,当前厂家为12位数字,预留字母/横杠/更长号段)',
  `imei` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'IMEI',
  `sim_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'SIM卡号',
  `vehicle_id` bigint NOT NULL DEFAULT 0 COMMENT '绑定车辆id(0=未绑定)',
  `auth_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '鉴权码(注册下发)',
  `model` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '设备型号,如GH-205',
  `online_status` tinyint NOT NULL DEFAULT 0 COMMENT '在线状态：0-离线 1-在线',
  `acc_status` tinyint NOT NULL DEFAULT 0 COMMENT 'ACC点火状态：0-熄火 1-点火',
  `acc_status_update_time` datetime NULL DEFAULT NULL COMMENT 'ACC状态更新时间',
  `last_acc_on_time` datetime NULL DEFAULT NULL COMMENT '最近一次ACC点火时间',
  `last_location_time` datetime NULL DEFAULT NULL COMMENT '最后定位时间',
  `last_lng` double(10, 6) NOT NULL DEFAULT 0.000000 COMMENT '最后经度(GCJ02)',
  `last_lat` double(10, 6) NOT NULL DEFAULT 0.000000 COMMENT '最后纬度(GCJ02)',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：1-启用 2-停用 -100-删除',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_device_no`(`device_no` ASC) USING BTREE,
  INDEX `idx_vehicle_id`(`vehicle_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-设备档案表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_device_bind_log
-- ----------------------------
DROP TABLE IF EXISTS `hub_device_bind_log`;
CREATE TABLE `hub_device_bind_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `device_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '终端设备编号',
  `from_vehicle_id` bigint NOT NULL DEFAULT 0 COMMENT '原绑定车辆id(0=无)',
  `to_vehicle_id` bigint NOT NULL DEFAULT 0 COMMENT '新绑定车辆id(0=解绑)',
  `op_type` tinyint NOT NULL DEFAULT 1 COMMENT '操作类型：1-绑定 2-换绑 3-迁移 4-解绑',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人子账号id',
  `operator_name` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_device_no`(`device_no` ASC) USING BTREE,
  INDEX `idx_to_vehicle_id`(`to_vehicle_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-设备绑定操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_dispatch_checkin
-- ----------------------------
DROP TABLE IF EXISTS `hub_dispatch_checkin`;
CREATE TABLE `hub_dispatch_checkin`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `dispatch_id` bigint NOT NULL DEFAULT 0 COMMENT '派车单id',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次:yyyy-MM-dd',
  `driver_id` bigint NOT NULL DEFAULT 0 COMMENT '司机子账号id',
  `station_id` bigint NOT NULL DEFAULT 0 COMMENT '签到基地id',
  `checkin_type` tinyint NOT NULL DEFAULT 1 COMMENT '签到类型：1-驶达 2-驶离',
  `valid` tinyint NOT NULL DEFAULT 1 COMMENT '是否有效：1-有效 0-无效',
  `checkin_lng` double(10, 6) NOT NULL DEFAULT 0.000000 COMMENT '签到经度',
  `checkin_lat` double(10, 6) NOT NULL DEFAULT 0.000000 COMMENT '签到纬度',
  `location_source` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '定位方式：GPS / LBS',
  `accuracy` double(10, 2) NOT NULL DEFAULT 0.00 COMMENT '定位精度(米)',
  `signal_level` int NOT NULL DEFAULT 0 COMMENT 'GPS 信号强度',
  `offset_distance` int NOT NULL DEFAULT 0 COMMENT '距集货站定位点的偏移距离(米)',
  `source` tinyint NOT NULL DEFAULT 1 COMMENT '签到来源：1-APP人工 2-设备自动',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '自动签到确认时刻(事实发生时间见create_time);手动签到为NULL',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `offsite_depart` tinyint NOT NULL DEFAULT 0 COMMENT '是否非斗南发车：0-否 1-是(仅发车签到)',
  `offsite_reason` tinyint NOT NULL DEFAULT 0 COMMENT '非斗南发车原因：0-无 1-外出维修保养 2-其他原因',
  `offsite_reason_remark` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '非斗南发车其他原因说明(业务限50字)',
  `offsite_photos` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '非斗南发车现场照片URL(逗号分隔,1~3张)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_dispatch_id`(`dispatch_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 261 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-派车签到记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_dispatch_order
-- ----------------------------
DROP TABLE IF EXISTS `hub_dispatch_order`;
CREATE TABLE `hub_dispatch_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `dispatch_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '派车单号',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次:yyyy-MM-dd',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型：1-内部车辆 2-外部车辆',
  `vehicle_id` bigint NOT NULL DEFAULT 0 COMMENT '车辆id',
  `vehicle_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '车辆名称/车型',
  `plate_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '车牌号',
  `driver_id` bigint NOT NULL DEFAULT 0 COMMENT '司机子账号id',
  `driver_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '司机姓名',
  `driver_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '司机电话',
  `platform` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台(外部车)',
  `fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '费用(外部车)',
  `start_station_id` bigint NOT NULL DEFAULT 0 COMMENT '始发地基地id',
  `start_station_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '始发地名称',
  `end_station_id` bigint NOT NULL DEFAULT 0 COMMENT '目的地基地id',
  `end_station_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '目的地名称',
  `responsible_base_id` bigint NOT NULL DEFAULT 0 COMMENT '主要负责基地id',
  `responsible_base_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主要负责基地名称',
  `checkin_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '签到次数(含驶达/驶离,每签一次+1)',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态：1-已派车 2-执行中 3-已完成 4-已撤销 5-异常终止 6-超时终止',
  `sign_status` tinyint NOT NULL DEFAULT 0 COMMENT '签到状态：0-未开始 1-正常签到 2-异常签到 3-进行中',
  `abnormal_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '异常签到原因(拼接)，正常签到为空',
  `settle_status` tinyint NOT NULL DEFAULT 0 COMMENT '结算状态(外部车)：0-未结算 1-已结算 2-已退回',
  `settle_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '结算金额(外部车补录)',
  `total_mileage` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '总里程(km)',
  `total_duration` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '行驶时长(分钟,扣除等待)',
  `dounan_depart_time` datetime NULL DEFAULT NULL COMMENT '斗南发车签到时间(首个有效驶离@始发地),NULL=尚无发车签到',
  `direct_minutes` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '斗南→主基地单向直达分钟(首个有效主基地驶达-发车),0=不可算',
  `support_base_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否存在支援基地(有效签到中含主基地以外的中间基地):0-否 1-是',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_dispatch_no`(`dispatch_no` ASC) USING BTREE,
  INDEX `idx_vehicle_id`(`vehicle_id` ASC) USING BTREE,
  INDEX `idx_driver_id`(`driver_id` ASC) USING BTREE,
  INDEX `idx_round_no`(`round_no` ASC) USING BTREE,
  INDEX `idx_plate_round`(`plate_no` ASC, `round_no` ASC) USING BTREE,
  INDEX `idx_status_responsible`(`status` ASC, `responsible_base_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9136 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-派车单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_dispatch_template
-- ----------------------------
DROP TABLE IF EXISTS `hub_dispatch_template`;
CREATE TABLE `hub_dispatch_template`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '模板名称',
  `start_station_id` bigint NOT NULL DEFAULT 0 COMMENT '始发地基地id',
  `start_station_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '始发地名称',
  `end_station_id` bigint NOT NULL DEFAULT 0 COMMENT '目的地基地id',
  `end_station_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '目的地名称',
  `route_summary` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主要线路(展示用)',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：1-正常 -100-删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-派车模板表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_dispatch_template_assignment
-- ----------------------------
DROP TABLE IF EXISTS `hub_dispatch_template_assignment`;
CREATE TABLE `hub_dispatch_template_assignment`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `template_id` bigint NOT NULL DEFAULT 0 COMMENT '模板id',
  `vehicle_id` bigint NOT NULL DEFAULT 0 COMMENT '车辆id',
  `responsible_base_id` bigint NOT NULL DEFAULT 0 COMMENT '主要负责基地id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tpl_vehicle`(`template_id` ASC, `vehicle_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-派车模板分配明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_driver_profile
-- ----------------------------
DROP TABLE IF EXISTS `hub_driver_profile`;
CREATE TABLE `hub_driver_profile`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint NOT NULL DEFAULT 0 COMMENT '子账号用户id(派车关联一律用此id)',
  `driver_license_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '驾驶证图片',
  `id_card_front_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证正面',
  `id_card_back_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证反面',
  `qualification_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '从业资格证',
  `source` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '来源：1-内部员工 2-外部注册',
  `audit_status` tinyint NOT NULL DEFAULT 1 COMMENT '审核状态(外部司机)：0-待审核 1-通过 2-驳回',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：1-正常 -100-删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-司机资料表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_external_settlement
-- ----------------------------
DROP TABLE IF EXISTS `hub_external_settlement`;
CREATE TABLE `hub_external_settlement`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次:yyyy-MM-dd',
  `car_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '外部车辆数',
  `total_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '应结金额',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '单据状态：0-未结算 1-已结算 2-已退回',
  `audit_user_id` bigint NOT NULL DEFAULT 0 COMMENT '审核人id',
  `audit_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人姓名',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_round_no`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9110 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-外部派车结算单(场次)表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_permission_change_log
-- ----------------------------
DROP TABLE IF EXISTS `hub_permission_change_log`;
CREATE TABLE `hub_permission_change_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `role_id` int NOT NULL DEFAULT 0 COMMENT '变更的角色id',
  `role_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '变更的角色名称(冗余快照)',
  `before_codes` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '变更前权限码,逗号分隔',
  `after_codes` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '变更后权限码,逗号分隔',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人子账号id',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '变更时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_role_time`(`role_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-权限变更审计日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_role_permission
-- ----------------------------
DROP TABLE IF EXISTS `hub_role_permission`;
CREATE TABLE `hub_role_permission`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `role_id` int NOT NULL DEFAULT 0 COMMENT '运营端角色id(xm_bulky_auth_role.id)',
  `permission_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '权限码(HubPermissionEnum.code)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_role_code`(`role_id` ASC, `permission_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 160 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-角色权限配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_station
-- ----------------------------
DROP TABLE IF EXISTS `hub_station`;
CREATE TABLE `hub_station`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `base_id` bigint NOT NULL COMMENT '关联基地 xm_bulky_base_config.id',
  `area_id` bigint NOT NULL DEFAULT 0 COMMENT '所属片区id(hub_area.id)',
  `area_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '所属片区名称',
  `area_leader` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '组长姓名',
  `contact_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `fence_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '围栏类型:1-圆形 2-多边形',
  `fence_radius` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '圆形围栏半径(米)',
  `fence_points` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '多边形围栏坐标点(json)',
  `departure_time` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发车时间 如21:00',
  `trip_mileage` decimal(10, 2) NULL DEFAULT NULL COMMENT '行程里程/到基地的距离(KM)',
  `dounan_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否斗南固定起终点:0-否 1-是',
  `avg_depart_time` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '统计-平均发车时间 HH:mm,空串=无数据',
  `avg_depart_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '统计-平均发车时间样本数(趟)',
  `direct_avg_minutes` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '统计-斗南单向直达平均用时(分钟),0=无数据',
  `direct_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '统计-直达用时样本数(趟)',
  `single_avg_minutes` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '统计-单基地任务平均净用时(分钟,扣主基地等待),0=无数据',
  `single_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '统计-单基地任务样本数(趟)',
  `multi_avg_minutes` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '统计-多基地任务平均净用时(分钟,扣所有中间基地等待),0=无数据',
  `multi_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '统计-多基地任务样本数(趟)',
  `stat_calc_time` datetime NULL DEFAULT NULL COMMENT '统计-最近重算时间,NULL=从未统计',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态:1-正常 -100-删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_base`(`base_id` ASC) USING BTREE,
  INDEX `idx_area_id`(`area_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 56 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-集货站hub扩展配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_taxi_register
-- ----------------------------
DROP TABLE IF EXISTS `hub_taxi_register`;
CREATE TABLE `hub_taxi_register`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `register_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '登记单号',
  `reimburse_id` bigint NOT NULL DEFAULT 0 COMMENT '所属场次报销单id',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次:yyyy-MM-dd',
  `platform` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '货拉拉' COMMENT '平台',
  `plate_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '车牌号',
  `driver_id` bigint NOT NULL DEFAULT 0 COMMENT '内部员工子账号id',
  `driver_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '员工姓名',
  `driver_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `start_station_id` bigint NOT NULL DEFAULT 0 COMMENT '始发地基地id',
  `start_station_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '始发地名称',
  `end_station_id` bigint NOT NULL DEFAULT 0 COMMENT '目的地基地id(默认斗南)',
  `end_station_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '目的地名称',
  `responsible_base_id` bigint NOT NULL DEFAULT 0 COMMENT '主要负责基地id',
  `responsible_base_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主要负责基地名称',
  `other_base_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '其他基地id列表(json)',
  `other_base_names` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '其他基地名称列表(json)',
  `fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际费用',
  `pay_voucher_imgs` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '支付凭证图片(json)',
  `invoice_imgs` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '发票图片(json)',
  `materials` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '材料',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_reimburse_id`(`reimburse_id` ASC) USING BTREE,
  INDEX `idx_round_no`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-临时打车登记表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_taxi_reimburse
-- ----------------------------
DROP TABLE IF EXISTS `hub_taxi_reimburse`;
CREATE TABLE `hub_taxi_reimburse`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `reimburse_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '报销单号',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次:yyyy-MM-dd',
  `car_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '打车数量',
  `total_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '费用合计',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 3 COMMENT '单据状态：0-已提交 1-已报销 2-已退回 3-待提交 4-已撤回',
  `audit_user_id` bigint NOT NULL DEFAULT 0 COMMENT '审核人id',
  `audit_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人姓名',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `payment_voucher_imgs` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '财务打款凭证(json)',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_reimburse_no`(`reimburse_no` ASC) USING BTREE,
  INDEX `idx_round_no`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-打车报销单(场次)表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_track_point
-- ----------------------------
DROP TABLE IF EXISTS `hub_track_point`;
CREATE TABLE `hub_track_point`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `dispatch_id` bigint NOT NULL DEFAULT 0 COMMENT '派车单id',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次:yyyy-MM-dd',
  `vehicle_id` bigint NOT NULL DEFAULT 0 COMMENT '车辆id',
  `driver_id` bigint NOT NULL DEFAULT 0 COMMENT '司机子账号id',
  `lng` double(10, 6) NOT NULL DEFAULT 0.000000 COMMENT '经度(火星坐标系)',
  `lat` double(10, 6) NOT NULL DEFAULT 0.000000 COMMENT '纬度(火星坐标系)',
  `speed` decimal(6, 2) NOT NULL DEFAULT 0.00 COMMENT '速度(km/h)',
  `source` tinyint NOT NULL DEFAULT 1 COMMENT '轨迹来源：1-APP人工 2-设备自动',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gps_time` datetime NULL DEFAULT NULL COMMENT '定位时间:设备GPS时间(盲区补报为原始时间)/APP上报时刻,里程与回放按此排序',
  PRIMARY KEY (`id`, `create_time`) USING BTREE,
  INDEX `idx_dispatch_create`(`dispatch_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1138 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-轨迹回传点表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_vehicle
-- ----------------------------
DROP TABLE IF EXISTS `hub_vehicle`;
CREATE TABLE `hub_vehicle`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `vehicle_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '车辆编号',
  `plate_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '云A' COMMENT '车牌号',
  `type_id` bigint NOT NULL DEFAULT 0 COMMENT '车型id(自有车)',
  `type_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '车型名称(外部车可文本填写)',
  `load_standard` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '载荷(标准框)',
  `fuel_consumption` decimal(6, 2) NULL DEFAULT NULL COMMENT '百公里油耗(L/100KM)',
  `owner_user_id` bigint NOT NULL DEFAULT 0 COMMENT '车辆责任人子账号id',
  `owner_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '车辆责任人姓名',
  `default_station_id` bigint NOT NULL DEFAULT 0 COMMENT '默认目的地(基地id)',
  `source` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '来源：1-自有 2-外部',
  `platform` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '来源平台(外部车)',
  `driving_years` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '行驶年限',
  `driving_license_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '行驶证图片',
  `cert_imgs` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '车辆证照图片(json)',
  `bank_holder` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收款人(默认同司机姓名)',
  `bank_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开户行',
  `bank_account` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '银行卡号',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：1-可用 2-维修 3-待审核 4-停用 -100-删除(自有/外部车统一)',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_plate_no`(`plate_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 134 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-车辆档案表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hub_vehicle_type
-- ----------------------------
DROP TABLE IF EXISTS `hub_vehicle_type`;
CREATE TABLE `hub_vehicle_type`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '车型名称',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：1-正常 -100-删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流-车型表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hubflow_auto_signin_config
-- ----------------------------
DROP TABLE IF EXISTS `hubflow_auto_signin_config`;
CREATE TABLE `hubflow_auto_signin_config`  (
  `id` tinyint UNSIGNED NOT NULL,
  `radius_meters` int UNSIGNED NOT NULL DEFAULT 500,
  `duration_minutes` int UNSIGNED NOT NULL DEFAULT 3,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hubflow_base_areas
-- ----------------------------
DROP TABLE IF EXISTS `hubflow_base_areas`;
CREATE TABLE `hubflow_base_areas`  (
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `leader` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `sort_no` int UNSIGNED NOT NULL DEFAULT 0,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`name`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hubflow_dispatch_order_nodes
-- ----------------------------
DROP TABLE IF EXISTS `hubflow_dispatch_order_nodes`;
CREATE TABLE `hubflow_dispatch_order_nodes`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `dispatch_order_id` bigint UNSIGNED NOT NULL,
  `station_id` bigint UNSIGNED NULL DEFAULT NULL,
  `station_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `sort_no` int UNSIGNED NOT NULL DEFAULT 0,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_dispatch_order`(`dispatch_order_id` ASC, `sort_no` ASC) USING BTREE,
  INDEX `idx_order_nodes_order_sort_station`(`dispatch_order_id` ASC, `sort_no` ASC, `station_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 580 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hubflow_dispatch_orders
-- ----------------------------
DROP TABLE IF EXISTS `hubflow_dispatch_orders`;
CREATE TABLE `hubflow_dispatch_orders`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '内部车辆',
  `base_id` bigint UNSIGNED NULL DEFAULT NULL,
  `base_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `trip_date` date NULL DEFAULT NULL,
  `taxi_registration_no` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `start_station_id` bigint UNSIGNED NULL DEFAULT NULL,
  `start_station_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `end_station_id` bigint UNSIGNED NULL DEFAULT NULL,
  `end_station_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `route_name` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `vehicle_id` bigint UNSIGNED NULL DEFAULT NULL,
  `vehicle_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `driver_id` bigint UNSIGNED NULL DEFAULT NULL,
  `driver_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `external_driver_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `destination` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `planned_at` datetime NULL DEFAULT NULL,
  `mileage_km` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `fee` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '-',
  `other_base_names` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `payment_voucher_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `invoice_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `reimburse_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '待报销',
  `reimburse_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `reimburse_time` datetime NULL DEFAULT NULL,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '待装车',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_no`(`no` ASC) USING BTREE,
  INDEX `idx_orders_status_type_start`(`status` ASC, `type` ASC, `start_station_id` ASC, `trip_date` ASC) USING BTREE,
  INDEX `idx_taxi_registration_no`(`taxi_registration_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 261 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hubflow_driver_certificates
-- ----------------------------
DROP TABLE IF EXISTS `hubflow_driver_certificates`;
CREATE TABLE `hubflow_driver_certificates`  (
  `user_id` bigint UNSIGNED NOT NULL,
  `driver_license_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `id_card_front_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `id_card_back_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `qualification_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hubflow_drivers
-- ----------------------------
DROP TABLE IF EXISTS `hubflow_drivers`;
CREATE TABLE `hubflow_drivers`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `role` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '司机',
  `vehicle` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
