-- ----------------------------
-- Table structure for idx_city_list
-- ----------------------------
DROP TABLE IF EXISTS `idx_city_list`;
CREATE TABLE `idx_city_list`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `idx` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '首字母 如A,B,C',
  `city_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市名称',
  `city_pinyin` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市拼音',
  `is_hot` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否热门城市 默认0不是 1是',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3610 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for invoicing_application
-- ----------------------------
DROP TABLE IF EXISTS `invoicing_application`;
CREATE TABLE `invoicing_application`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `identification_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '纳税人识别号',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态（0:待审核 1:通过 2:驳回 3:未提交）',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '驳回理由 限255字',
  `review_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核人id',
  `review_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `apply_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '申请时间',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_applytime`(`apply_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 583 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '开票申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for legacy_purchaser_split
-- ----------------------------
DROP TABLE IF EXISTS `legacy_purchaser_split`;
CREATE TABLE `legacy_purchaser_split`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `old_user_id` bigint NOT NULL COMMENT '拆分前公共账号ID',
  `bulky_user_id` bigint NULL DEFAULT NULL COMMENT '大件批发账号ID',
  `hck_user_id` bigint NULL DEFAULT NULL COMMENT '花仓库账号ID',
  `retained_platform` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '原ID归属：BULKY/HCK',
  `evidence_begin_date` date NOT NULL COMMENT '归属判定开始日期',
  `paid_only` tinyint NOT NULL DEFAULT 0 COMMENT '是否仅按已支付订单判定',
  `bulky_order_count` bigint NOT NULL DEFAULT 0,
  `hck_order_count` bigint NOT NULL DEFAULT 0,
  `other_order_count` bigint NOT NULL DEFAULT 0,
  `unclassified_row_count` bigint NOT NULL DEFAULT 0 COMMENT '保留在原账号的不可判平台记录数',
  `migration_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'RUNNING/SUCCESS/FAILED',
  `affected_rows_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '各表迁移行数',
  `error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `complete_time` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_legacy_purchaser_split_old_user`(`old_user_id` ASC) USING BTREE,
  INDEX `idx_legacy_purchaser_split_bulky_user`(`bulky_user_id` ASC) USING BTREE,
  INDEX `idx_legacy_purchaser_split_hck_user`(`hck_user_id` ASC) USING BTREE,
  INDEX `idx_legacy_purchaser_split_status`(`migration_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '公共采购商账号拆分审计' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_actual_price
-- ----------------------------
DROP TABLE IF EXISTS `logistics_actual_price`;
CREATE TABLE `logistics_actual_price`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `send_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发货单号',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货位号',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场次 yyyy-MM-dd',
  `carrier_id` bigint NULL DEFAULT NULL COMMENT '承运配置id（logistics_carrier.id）',
  `quote_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '生效报价（系统计价）',
  `expend_express_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '实际运费',
  `diff_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '差价（实际-报价）',
  `status` int NOT NULL DEFAULT 0 COMMENT '状态 0-待确认 1-已确认',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_send_no`(`send_no` ASC) USING BTREE,
  INDEX `idx_round`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流实际费用对账表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_bill_import_log
-- ----------------------------
DROP TABLE IF EXISTS `logistics_bill_import_log`;
CREATE TABLE `logistics_bill_import_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场次 yyyy-MM-dd',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `status` int NOT NULL DEFAULT 0 COMMENT '状态 0-处理中 1-成功 2-失败',
  `result` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处理结果',
  `link` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结果文件链接',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人id',
  `operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流对账导入日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_carrier
-- ----------------------------
DROP TABLE IF EXISTS `logistics_carrier`;
CREATE TABLE `logistics_carrier`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `provider_id` bigint NOT NULL COMMENT '物流商id（logistics_provider.id）',
  `config_id` bigint NULL DEFAULT NULL COMMENT '关联旧物流配置id（xm_bulky_logistics_cost_config.id），1:1',
  `partner_id` bigint NOT NULL DEFAULT 0 COMMENT '分销商id（partner.id），0为平台',
  `carrier_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '承运/物流方式名称',
  `logistics_type` int NOT NULL DEFAULT 1 COMMENT '物流类型 1-快递 2-冷链 3-航空',
  `phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客服电话',
  `description` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述',
  `expected_time_str` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预计送达时间，如 24~36小时',
  `expected_time_hours` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '预计送达时长（小时）',
  `delivery_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '每日交货时间，如 02:00',
  `sort_num` int NOT NULL DEFAULT 0 COMMENT '排序值',
  `is_enable` int NOT NULL DEFAULT 1 COMMENT '是否启用 0-否 1-是',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_provider`(`provider_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 990023 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流承运配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_carrier_account_bind
-- ----------------------------
DROP TABLE IF EXISTS `logistics_carrier_account_bind`;
CREATE TABLE `logistics_carrier_account_bind`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `account_type` tinyint NOT NULL COMMENT '账号类型 1-主账号xm_admin 2-子账号xm_bulky_sub_account',
  `account_id` bigint NOT NULL COMMENT '账号id',
  `carrier_id` bigint NOT NULL COMMENT '承运配置id logistics_carrier.id',
  `provider_id` bigint NOT NULL COMMENT '物流商id logistics_provider.id（carrier 所属物流商）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0正常 -100删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_account`(`account_type` ASC, `account_id` ASC, `data_status` ASC) USING BTREE,
  INDEX `uk_account_carrier`(`account_type` ASC, `account_id` ASC, `carrier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 980817234 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '后台账号与承运配置绑定表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_carrier_config
-- ----------------------------
DROP TABLE IF EXISTS `logistics_carrier_config`;
CREATE TABLE `logistics_carrier_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `carrier_id` bigint NOT NULL COMMENT '承运id（logistics_carrier.id）',
  `config_id` bigint NOT NULL COMMENT '旧物流配置id（xm_bulky_logistics_cost_config.id），即一个旧物流方式',
  `config_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配置名称（展示用，可空，空则由 configId 推断）',
  `sort_num` int NOT NULL DEFAULT 0 COMMENT '排序',
  `is_enable` int NOT NULL DEFAULT 1 COMMENT '是否启用 0-否 1-是',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_carrier`(`carrier_id` ASC) USING BTREE,
  INDEX `idx_config`(`config_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 900216 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流承运-配置映射表（carrier 一对多 config）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_carrier_region
-- ----------------------------
DROP TABLE IF EXISTS `logistics_carrier_region`;
CREATE TABLE `logistics_carrier_region`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `provider_id` bigint NOT NULL DEFAULT 0 COMMENT '物流商id（logistics_provider.id）',
  `carrier_id` bigint NOT NULL COMMENT '承运配置id（logistics_carrier.id）',
  `region_id` int NOT NULL COMMENT 'xm_region.id',
  `adcode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '城市编码',
  `region_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '省/市/区完整名，以 / 分隔',
  `xm_special_line` tinyint NOT NULL DEFAULT 0 COMMENT '寻梦冷链专线标识 0-关闭 1-打开',
  `picker_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '提货员姓名',
  `picker_mobile` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '提货员手机号',
  `delivery_time` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '每日交货时间，如 02:00',
  `expected_time_str` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '预计送达时间，如 24~36小时',
  `expected_time_hours` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '预计送达时长（小时），0表示沿用承运配置',
  `description` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '物流描述',
  `trans_city` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '中转城市，限100字',
  `pay_on_delivery` tinyint NOT NULL DEFAULT 0 COMMENT '物流结算方式 0:其他 1:到付 2:日结 3:月结',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_carrier_region`(`carrier_id` ASC, `region_id` ASC) USING BTREE,
  INDEX `idx_carrier`(`carrier_id` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_region_special_line`(`region_id` ASC, `data_status` ASC, `xm_special_line` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 931101076 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '物流承运区域主档（carrier+region 唯一）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_freight_reconcile_bill
-- ----------------------------
DROP TABLE IF EXISTS `logistics_freight_reconcile_bill`;
CREATE TABLE `logistics_freight_reconcile_bill`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `bill_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '总账单号 ZDZ+yyyyMMddHHmmss+随机数',
  `bill_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '总账单名称，缺省自动\"start~end 场次总对账单\"',
  `round_start` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次范围开始 yyyy-MM-dd',
  `round_end` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次范围结束 yyyy-MM-dd',
  `filter_provider_id` bigint NOT NULL DEFAULT 0 COMMENT '生成时的品牌筛选快照，0=未筛',
  `filter_carrier_id` bigint NOT NULL DEFAULT 0 COMMENT '生成时的产品筛选快照，0=未筛',
  `order_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货单数(子账单汇总)',
  `package_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '包裹数(子账单汇总)',
  `act_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '应付金额(子账单汇总，Σ实付-补偿)',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人名',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bill_no`(`bill_no` ASC) USING BTREE,
  INDEX `idx_bill_name`(`bill_name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 900206 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '运费总对账单(按场次范围手动生成)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_freight_reconcile_detail
-- ----------------------------
DROP TABLE IF EXISTS `logistics_freight_reconcile_detail`;
CREATE TABLE `logistics_freight_reconcile_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `total_bill_id` bigint NOT NULL DEFAULT 0 COMMENT '总对账单id',
  `sub_bill_id` bigint NOT NULL DEFAULT 0 COMMENT '子对账单id',
  `package_record_id` bigint NOT NULL DEFAULT 0 COMMENT '包裹记录id',
  `package_id` int NULL DEFAULT NULL COMMENT '业务包裹id',
  `send_order_id` bigint NOT NULL DEFAULT 0 COMMENT '发货单id',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号',
  `provider_id` bigint NOT NULL DEFAULT 0 COMMENT '物流品牌id快照',
  `provider_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流品牌名称快照',
  `carrier_id` bigint NOT NULL DEFAULT 0 COMMENT '物流产品id快照',
  `carrier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流产品名称快照',
  `config_id` bigint NOT NULL DEFAULT 0 COMMENT '包裹物流配置id快照',
  `quote_mode` tinyint NOT NULL DEFAULT 1 COMMENT '报价方式 1-普通包裹 2-第三方运单',
  `waybill_price_id` bigint NULL DEFAULT NULL COMMENT '第三方运单报价记录id',
  `mail_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '第三方运单号',
  `round_no` date NULL DEFAULT NULL COMMENT '场次',
  `report_time` datetime NULL DEFAULT NULL COMMENT '填报/运单匹配时间',
  `report_operator_id` bigint NOT NULL DEFAULT 0 COMMENT '填报/匹配人id',
  `report_operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '填报/匹配人',
  `package_info` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '包裹信息',
  `total_weight` decimal(12, 3) NOT NULL DEFAULT 0.000 COMMENT '包裹重量',
  `express_actual_weight` decimal(12, 3) NOT NULL DEFAULT 0.000 COMMENT '物流实际重量',
  `report_price` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '填报价格',
  `zone` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货位号',
  `receive_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人',
  `receive_tel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货电话',
  `receive_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 -100删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sub_bill`(`sub_bill_id` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_total_bill`(`total_bill_id` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_package_record`(`package_record_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 900224 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '运费对账包裹详情快照' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_freight_reconcile_sub_bill
-- ----------------------------
DROP TABLE IF EXISTS `logistics_freight_reconcile_sub_bill`;
CREATE TABLE `logistics_freight_reconcile_sub_bill`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `bill_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子账单号 DZ+yyyyMMddHHmmss+随机数',
  `total_bill_id` bigint NOT NULL DEFAULT 0 COMMENT '总账单id',
  `provider_id` bigint NOT NULL DEFAULT 0 COMMENT '物流品牌id快照，无归属=0',
  `provider_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流品牌名称快照',
  `carrier_id` bigint NOT NULL DEFAULT 0 COMMENT '物流产品id快照(logistics_carrier.id)，无归属=0',
  `carrier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流产品名称快照，无归属时取物流配置名',
  `config_id` bigint NOT NULL DEFAULT 0 COMMENT '无归属子账单的物流配置id(仅 carrier_id=0 时>0)',
  `order_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货单数',
  `package_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '包裹数',
  `act_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '应付金额(Σ实付-补偿)',
  `original_payable_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '原应付金额(生成时Σ包裹填报价格)',
  `adjust_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '累计调账金额(实际应付-原应付)',
  `payable_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '实际应付金额',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0-已生成 1-已同步 2-已确认(保留)',
  `sync_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '同步次数',
  `revoke_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '撤回次数',
  `confirm_operator_id` bigint NOT NULL DEFAULT 0 COMMENT '物流商确认人id(保留)',
  `confirm_operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流商确认人名(保留)',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认时间(保留)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bill_no`(`bill_no` ASC) USING BTREE,
  INDEX `idx_total_bill`(`total_bill_id` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_carrier`(`carrier_id` ASC, `status` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 900214 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '运费子对账单(按物流产品拆分)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_freight_settle_operation
-- ----------------------------
DROP TABLE IF EXISTS `logistics_freight_settle_operation`;
CREATE TABLE `logistics_freight_settle_operation`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `send_order_id` bigint NOT NULL COMMENT '发货单id',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发货单号',
  `freight_price_mode` tinyint NOT NULL COMMENT '结算时价格模式',
  `package_price_snapshot` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '包裹价格快照',
  `waybill_price_snapshot` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '运单价格快照',
  `suggested_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '系统建议金额',
  `confirmed_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '人工确认金额',
  `difference_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '人工金额减系统建议金额',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '人工结算原因',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `operation_time` datetime NOT NULL COMMENT '操作时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 -100删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_freight_settle_send`(`send_order_id` ASC, `operation_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '发货单运费人工结算审计记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_message
-- ----------------------------
DROP TABLE IF EXISTS `logistics_message`;
CREATE TABLE `logistics_message`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `msg_type` tinyint NOT NULL COMMENT '消息类型 1-物流商提交审批 2-审批通过 3-审批拒绝 4-平台公告',
  `target_type` tinyint NOT NULL COMMENT '投放类型 1-指定承运 2-全平台广播',
  `carrier_id` bigint NOT NULL DEFAULT 0 COMMENT '关联承运配置id logistics_carrier.id；广播为0',
  `provider_id` bigint NOT NULL DEFAULT 0 COMMENT '承运归属物流商id logistics_provider.id；广播为0',
  `biz_type` tinyint NOT NULL DEFAULT 0 COMMENT '业务类型 0-无 1-报价单',
  `biz_id` bigint NOT NULL DEFAULT 0 COMMENT '业务id，如 logistics_quote.id，供前端跳转',
  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题',
  `content` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '正文',
  `creator_account_type` tinyint NOT NULL DEFAULT 0 COMMENT '触发者账号类型 0-系统 1-主账号 2-子账号',
  `creator_account_id` bigint NOT NULL DEFAULT 0 COMMENT '触发者账号id',
  `creator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '触发者名称',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0正常 -100删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_carrier`(`carrier_id` ASC, `data_status` ASC, `id` ASC) USING BTREE,
  INDEX `idx_target`(`target_type` ASC, `data_status` ASC, `id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 108 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流平台消息主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_message_read
-- ----------------------------
DROP TABLE IF EXISTS `logistics_message_read`;
CREATE TABLE `logistics_message_read`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `message_id` bigint NOT NULL COMMENT 'logistics_message.id',
  `reader_type` tinyint NOT NULL COMMENT '阅读方 1-物流商(read_key=carrier_id) 2-平台运营 3-平台财务(read_key=0)',
  `read_key` bigint NOT NULL DEFAULT 0 COMMENT '物流商存 carrier_id；平台组固定0（整组共享）',
  `read_account_type` tinyint NOT NULL DEFAULT 0 COMMENT '实际阅读人账号类型',
  `read_account_id` bigint NOT NULL DEFAULT 0 COMMENT '实际阅读人账号id',
  `read_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '实际阅读人名称',
  `read_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_msg_reader`(`message_id` ASC, `reader_type` ASC, `read_key` ASC) USING BTREE,
  INDEX `idx_reader`(`reader_type` ASC, `read_key` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流平台消息已读表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_order
-- ----------------------------
DROP TABLE IF EXISTS `logistics_order`;
CREATE TABLE `logistics_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `send_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发货单号',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单号',
  `carrier_id` bigint NULL DEFAULT NULL COMMENT '承运配置id（logistics_carrier.id）',
  `provider_id` bigint NULL DEFAULT NULL COMMENT '物流商id',
  `logistics_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物流单号',
  `mail_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '运单号',
  `logistics_type` int NULL DEFAULT NULL COMMENT '物流类型 1快递 2冷链 3航空',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场次 yyyy-MM-dd',
  `print_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '打印面单数据',
  `status` int NOT NULL DEFAULT 0 COMMENT '状态 0-已下单 1-已打印 2-已取消',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_send_no`(`send_no` ASC) USING BTREE,
  INDEX `idx_mail_no`(`mail_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流下单单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_package_abnormal_tag
-- ----------------------------
DROP TABLE IF EXISTS `logistics_package_abnormal_tag`;
CREATE TABLE `logistics_package_abnormal_tag`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `tag_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标签名称',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1-启用 0-停用',
  `sort_no` int NOT NULL DEFAULT 0 COMMENT '排序值，越小越靠前',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '最近操作人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近操作人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0-正常 -100-删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tag_status`(`status` ASC, `data_status` ASC, `sort_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 900105 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '包裹异常标签字典' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_package_operation
-- ----------------------------
DROP TABLE IF EXISTS `logistics_package_operation`;
CREATE TABLE `logistics_package_operation`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `package_id` bigint NOT NULL COMMENT '包裹id（xm_bulky_wms_express_package.id）',
  `op_type` tinyint NOT NULL COMMENT '操作类型：1-揽收、2-确认、3-异常恢复、4-填报、5-审核通过、6-驳回、7-提交审核',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `op_time` datetime NULL DEFAULT NULL COMMENT '操作时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注（驳回理由、填报价格快照等）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_package_op`(`package_id` ASC, `op_type` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_operator`(`operator_id` ASC, `op_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 647 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '包裹操作记录（揽收/确认/填报/审核等操作人留痕）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_package_tag_relation
-- ----------------------------
DROP TABLE IF EXISTS `logistics_package_tag_relation`;
CREATE TABLE `logistics_package_tag_relation`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `package_id` bigint NOT NULL COMMENT '包裹id',
  `tag_id` bigint NOT NULL COMMENT '异常标签id',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '设置人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '设置人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '设置时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_package_tag`(`package_id` ASC, `tag_id` ASC) USING BTREE,
  INDEX `idx_tag_id`(`tag_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '包裹异常标签关系' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_pickup_fee_operation
-- ----------------------------
DROP TABLE IF EXISTS `logistics_pickup_fee_operation`;
CREATE TABLE `logistics_pickup_fee_operation`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `request_send_order_id` bigint NOT NULL COMMENT '本次请求传入的发货单id',
  `request_send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '本次请求传入的发货单号',
  `send_order_id` bigint NOT NULL COMMENT '实际保存提货费的发货单id',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '实际保存提货费的发货单号',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次 yyyy-MM-dd',
  `ware_id` int NOT NULL DEFAULT 0 COMMENT '城市仓id，普通发货单为0',
  `partner_id` int NOT NULL DEFAULT 0 COMMENT '合作方id，无合作方为0',
  `original_pickup_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '修改前提货费',
  `new_pickup_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '修改后提货费',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `operation_time` datetime NOT NULL COMMENT '操作时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 -100删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pickup_fee_send_order`(`send_order_id` ASC, `operation_time` ASC) USING BTREE,
  INDEX `idx_pickup_fee_operator`(`operator_id` ASC, `operation_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '发货单提货费修改日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_price_change_record
-- ----------------------------
DROP TABLE IF EXISTS `logistics_price_change_record`;
CREATE TABLE `logistics_price_change_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `logistics_id` bigint NOT NULL DEFAULT 0 COMMENT '物流id',
  `logistics_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '变更明细',
  `operate_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1077 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流改价变更记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_provider
-- ----------------------------
DROP TABLE IF EXISTS `logistics_provider`;
CREATE TABLE `logistics_provider`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `provider_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '物流商名称',
  `login_account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '登录账号',
  `password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '登录密码(BCrypt)',
  `salt` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '密码盐',
  `contact` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注：合作说明、特殊要求等',
  `landline` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '座机',
  `support_logistics_types` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1,2,3' COMMENT '支持运输方式，英文逗号分隔：1-快递 2-冷链 3-航空',
  `access_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开放接口 accessKey',
  `access_secret` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开放接口 secret',
  `token` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当前登录 token',
  `status` int NOT NULL DEFAULT 1 COMMENT '状态 0-禁用 1-启用',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_login_account`(`login_account` ASC) USING BTREE,
  INDEX `idx_access_key`(`access_key` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 900211 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流商主体表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_provider_account_bind
-- ----------------------------
DROP TABLE IF EXISTS `logistics_provider_account_bind`;
CREATE TABLE `logistics_provider_account_bind`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `account_type` tinyint NOT NULL COMMENT '账号类型 1-主账号xm_admin 2-子账号xm_bulky_sub_account',
  `account_id` bigint NOT NULL COMMENT '账号id',
  `provider_id` bigint NOT NULL COMMENT '物流商id logistics_provider.id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0正常 -100删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_account_provider`(`account_type` ASC, `account_id` ASC, `provider_id` ASC) USING BTREE,
  INDEX `idx_account`(`account_type` ASC, `account_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '后台账号与物流商绑定表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_provider_checkin
-- ----------------------------
DROP TABLE IF EXISTS `logistics_provider_checkin`;
CREATE TABLE `logistics_provider_checkin`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `provider_id` bigint NOT NULL DEFAULT 0 COMMENT '物流商id',
  `provider_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流商名称快照',
  `round_no` date NOT NULL COMMENT '场次',
  `checkin_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '签到方式 0-手动 1-NFC',
  `checkin_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '签到时间',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人名称',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_provider_round_status`(`provider_id` ASC, `round_no` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_round_status`(`round_no` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流商场次签到表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_provider_config
-- ----------------------------
DROP TABLE IF EXISTS `logistics_provider_config`;
CREATE TABLE `logistics_provider_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `provider_id` bigint NOT NULL DEFAULT 0 COMMENT '物流商id',
  `config_id` bigint NOT NULL DEFAULT 0 COMMENT 'xm_bulky_logistics_cost_config.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_config_id`(`config_id` ASC) USING BTREE,
  INDEX `idx_provider_data_status`(`provider_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流商配置归属表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_quote
-- ----------------------------
DROP TABLE IF EXISTS `logistics_quote`;
CREATE TABLE `logistics_quote`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `provider_id` bigint NOT NULL COMMENT '物流商id（logistics_provider.id）',
  `carrier_id` bigint NOT NULL COMMENT '承运配置id（logistics_carrier.id）',
  `start_round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生效开始场次 yyyy-MM-dd',
  `end_round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生效结束场次 yyyy-MM-dd',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '审核状态 0-待审核 1-通过 2-驳回 3-草稿 -1-删除',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `submit_time` datetime NULL DEFAULT NULL COMMENT '提交时间',
  `operator_account_type` tinyint NULL DEFAULT NULL COMMENT '提交操作人账号类型 1-主账号 2-子账号',
  `operator_account_id` bigint NULL DEFAULT NULL COMMENT '提交操作人账号id（物流商自提为本人，运营代提交为运营账号）',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交操作人名称',
  `review_id` bigint NULL DEFAULT NULL COMMENT '审核人id',
  `review_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人名称',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_carrier_status`(`carrier_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_provider`(`provider_id` ASC) USING BTREE,
  INDEX `idx_round`(`start_round_no` ASC, `end_round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 434 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流报价单（审核+按场次生效版本头）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_quote_region
-- ----------------------------
DROP TABLE IF EXISTS `logistics_quote_region`;
CREATE TABLE `logistics_quote_region`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `quote_id` bigint NOT NULL DEFAULT 0 COMMENT '已废弃：老报价单头id，新代码不再写入，默认0',
  `carrier_id` bigint NULL DEFAULT NULL COMMENT '承运配置id（logistics_carrier.id，冗余便于查询/分组）',
  `carrier_region_id` bigint NULL DEFAULT NULL COMMENT '区域主档id（logistics_carrier_region.id）',
  `status` tinyint NOT NULL DEFAULT 3 COMMENT '审核状态 0-待审核 1-通过 2-驳回 3-草稿 -1-删除',
  `start_round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '生效开始场次 yyyy-MM-dd',
  `end_round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '生效结束场次 yyyy-MM-dd',
  `enable_status` tinyint NOT NULL DEFAULT 1 COMMENT '停启用 1-启用 0-停用（审核通过之上第二道闸，仅启用参与询价）',
  `source` tinyint NOT NULL DEFAULT 0 COMMENT '报价来源 1-物流商提交 2-运营代提交 3-历史迁移',
  `submit_time` datetime NULL DEFAULT NULL COMMENT '提交时间',
  `operator_account_type` tinyint NULL DEFAULT NULL COMMENT '提交操作人账号类型 1-主账号 2-子账号',
  `operator_account_id` bigint NULL DEFAULT NULL COMMENT '提交操作人账号id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交操作人名称',
  `review_id` bigint NULL DEFAULT NULL COMMENT '审核人id',
  `review_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人名称',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `region_id` int NULL DEFAULT NULL COMMENT 'xm_region.id',
  `adcode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '城市编码',
  `region_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '城市名称',
  `xm_special_line` tinyint NOT NULL DEFAULT 0 COMMENT '寻梦冷链专线标识 0-关闭 1-打开',
  `charge_type` tinyint NOT NULL DEFAULT 0 COMMENT '计费方式 0-单价 1-底价 2-多首重 3-箱型 4-重量区间',
  `price_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '阶梯费用json数组 如：[{\"limit\":20,\"price\":5,\"type\":0}]',
  `activity_price_data` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动阶梯价json数组，与price_data阶梯一一对应 如：[{\"price\":5}]',
  `multi_price_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '多首重收费配置json数组',
  `weight_range_data` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '重量区间收费配置json数组，charge_type=4使用',
  `trunk_charge_type` tinyint NOT NULL DEFAULT 0 COMMENT '重量区间模式-干线费计费方式 0-固定金额 1-重量单价(元/KG)',
  `shop_charge_type` tinyint NOT NULL DEFAULT 0 COMMENT '重量区间模式-到店费计费方式 0-固定金额 1-重量单价(元/KG)',
  `first_heavy` decimal(10, 2) NULL DEFAULT NULL COMMENT '首重(g)',
  `first_heavy_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '首重价格',
  `delivery_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '每日交货时间，如 02:00',
  `expected_time_str` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预计送达时间，如 24~36小时',
  `description` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流描述',
  `picker_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '提货员姓名',
  `picker_mobile` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '提货员手机号',
  `trans_city` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '中转城市，限100字',
  `pay_on_delivery` tinyint NOT NULL DEFAULT 0 COMMENT '物流结算方式 0:其他 1:到付 2:日结 3:月结',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `legacy_region_id` bigint NULL DEFAULT NULL COMMENT '对应 xm_bulky_logistics_cost_region.id（审核通过双写产生）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_legacy_region`(`legacy_region_id` ASC) USING BTREE,
  INDEX `idx_quote`(`quote_id` ASC) USING BTREE,
  INDEX `idx_carrier_region_status`(`carrier_id` ASC, `region_id` ASC, `status` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_carrier_effective`(`carrier_id` ASC, `status` ASC, `enable_status` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 931102520 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流报价区域明细（按场次生效版本明细）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_reconcile_bill
-- ----------------------------
DROP TABLE IF EXISTS `logistics_reconcile_bill`;
CREATE TABLE `logistics_reconcile_bill`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `bill_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '对账单号 RB+yyyyMMdd+序号',
  `bill_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '对账单名称',
  `round_start` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次范围开始 yyyy-MM-dd',
  `round_end` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次范围结束 yyyy-MM-dd',
  `order_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货单数(明细汇总)',
  `pre_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '预收金额(明细汇总)',
  `act_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '实际结算金额(明细汇总)',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0-已生成 1-已确认',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人名',
  `confirm_operator_id` bigint NOT NULL DEFAULT 0 COMMENT '确认人id',
  `confirm_operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '确认人名',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bill_no`(`bill_no` ASC) USING BTREE,
  INDEX `idx_bill_name`(`bill_name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流对账单(按场次范围手动生成)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_reconcile_bill_item
-- ----------------------------
DROP TABLE IF EXISTS `logistics_reconcile_bill_item`;
CREATE TABLE `logistics_reconcile_bill_item`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `bill_id` bigint NOT NULL DEFAULT 0 COMMENT '对账单主表id',
  `item_type` tinyint NOT NULL DEFAULT 0 COMMENT '明细类型 1-批发物流产品 2-城市仓 3-分销商',
  `target_id` bigint NOT NULL DEFAULT 0 COMMENT '物流商id(config_id)/城市仓id/分销商id',
  `target_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流产品/城市仓/分销商名称(冗余)',
  `order_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货单数',
  `pre_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '预收金额(批发=预估运费汇总;城市仓/分销=0)',
  `act_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '实际结算金额(批发=实付-补偿;城市仓/分销=补运费为正/扣运费为负)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_bill_id`(`bill_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流对账单明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_route
-- ----------------------------
DROP TABLE IF EXISTS `logistics_route`;
CREATE TABLE `logistics_route`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `mail_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '运单号',
  `logistics_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物流单号',
  `route_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '轨迹json',
  `route_status` int NULL DEFAULT NULL COMMENT '轨迹状态',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_mail_no`(`mail_no` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流轨迹缓存' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_session_settlement
-- ----------------------------
DROP TABLE IF EXISTS `logistics_session_settlement`;
CREATE TABLE `logistics_session_settlement`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `settle_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次结算单号 SS+yyyyMMdd+序号',
  `biz_type` tinyint NOT NULL DEFAULT 0 COMMENT '业务类型 1-城市仓 2-分销商',
  `target_id` bigint NOT NULL DEFAULT 0 COMMENT '城市仓id(city_warehouse.id)/分销商id(partner.id)',
  `target_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市仓/分销商名称(冗余)',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次 yyyy-MM-dd',
  `op_type` tinyint NOT NULL DEFAULT 1 COMMENT '操作类型 1-扣运费 2-补运费',
  `amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际运费金额(正数,方向由op_type决定)',
  `order_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货单数量(确认结算时快照)',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '结算状态 0-已创建 1-已结算(锁定)',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人名',
  `settle_operator_id` bigint NOT NULL DEFAULT 0 COMMENT '结算人id',
  `settle_operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '结算人名',
  `settle_time` datetime NULL DEFAULT NULL COMMENT '结算时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_settle_no`(`settle_no` ASC) USING BTREE,
  INDEX `idx_round_no`(`round_no` ASC) USING BTREE,
  INDEX `idx_target`(`biz_type` ASC, `target_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓/分销场次结算单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_settle_adjust
-- ----------------------------
DROP TABLE IF EXISTS `logistics_settle_adjust`;
CREATE TABLE `logistics_settle_adjust`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `adjust_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '调账单号 TZ+yyyyMMdd+序号',
  `source` tinyint NOT NULL DEFAULT 0 COMMENT '来源 1-包裹调账 2-子对账单调账',
  `ref_id` bigint NOT NULL DEFAULT 0 COMMENT '关联记录id(包裹记录id/子对账单id)',
  `ref_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '关联单号(包裹对应发货单号send_no/子对账单号bill_no)',
  `provider_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流品牌/物流产品名称',
  `carrier_id` bigint NOT NULL DEFAULT 0 COMMENT '物流产品id(logistics_carrier.id)',
  `period` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '周期(场次或场次范围 开始~结束)',
  `orig_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '原金额',
  `new_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '新金额',
  `diff_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '差额(新-原, 负=待退款 正=补收)',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '调账原因',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人名',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_adjust_no`(`adjust_no` ASC) USING BTREE,
  INDEX `idx_ref_no`(`ref_no` ASC) USING BTREE,
  INDEX `idx_source`(`source` ASC) USING BTREE,
  INDEX `idx_carrier_status`(`carrier_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '结算调账记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_transport_package
-- ----------------------------
DROP TABLE IF EXISTS `logistics_transport_package`;
CREATE TABLE `logistics_transport_package`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `task_id` bigint NOT NULL COMMENT '运输任务id',
  `package_id` bigint NOT NULL COMMENT '包裹id（xm_bulky_wms_express_package.id）',
  `driver_id` bigint NOT NULL COMMENT '司机子账号id（冗余，反查包裹归属免join）',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '包裹自身场次（可与任务场次不同）',
  `load_time` datetime NOT NULL COMMENT '装车时间',
  `load_type` tinyint NOT NULL COMMENT '1-司机扫码 2-运营补绑',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_package`(`package_id` ASC) USING BTREE,
  INDEX `idx_task`(`task_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '物流-运输任务包裹表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_transport_task
-- ----------------------------
DROP TABLE IF EXISTS `logistics_transport_task`;
CREATE TABLE `logistics_transport_task`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `provider_id` bigint NOT NULL COMMENT '物流商id（logistics_provider.id）',
  `driver_id` bigint NOT NULL COMMENT '司机子账号id（xm_bulky_sub_account.id）',
  `driver_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '司机姓名快照',
  `driver_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '司机手机号快照',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '场次yyyy-MM-dd，取首次扫码时刻的当前场次',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1-未发车 2-已发车 3-已完成',
  `active_flag` tinyint NULL DEFAULT 1 COMMENT '进行中=1，完成时置NULL；与driver_id组唯一键，保证一司机同时仅一个进行中任务',
  `package_count` int NOT NULL DEFAULT 0 COMMENT '当前绑定包裹数（冗余）',
  `depart_time` datetime NULL DEFAULT NULL COMMENT '发车时间',
  `depart_lng` decimal(10, 6) NULL DEFAULT NULL COMMENT '发车经度',
  `depart_lat` decimal(10, 6) NULL DEFAULT NULL COMMENT '发车纬度',
  `depart_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发车位置逆地理地址',
  `arrive_time` datetime NULL DEFAULT NULL COMMENT '到达时间（代确认时为运营填写的实际到达时间）',
  `arrive_lng` decimal(10, 6) NULL DEFAULT NULL COMMENT '到达经度',
  `arrive_lat` decimal(10, 6) NULL DEFAULT NULL COMMENT '到达纬度',
  `arrive_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '到达位置逆地理地址',
  `arrive_type` tinyint NULL DEFAULT NULL COMMENT '1-司机确认 2-运营代确认',
  `arrive_operator_id` bigint NULL DEFAULT NULL COMMENT '代确认操作人id',
  `arrive_operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '代确认操作人姓名',
  `arrive_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '代确认原因',
  `last_lng` decimal(10, 6) NULL DEFAULT NULL COMMENT '最后定位经度（冗余，列表页直读不解析轨迹大字段）',
  `last_lat` decimal(10, 6) NULL DEFAULT NULL COMMENT '最后定位纬度',
  `last_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最后定位逆地理地址',
  `last_gps_time` datetime NULL DEFAULT NULL COMMENT '最后定位时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0-正常 -100-删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_driver_active`(`driver_id` ASC, `active_flag` ASC) USING BTREE,
  INDEX `idx_round_provider`(`round_no` ASC, `provider_id` ASC) USING BTREE,
  INDEX `idx_driver_round`(`driver_id` ASC, `round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '物流-司机运输任务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_transport_track
-- ----------------------------
DROP TABLE IF EXISTS `logistics_transport_track`;
CREATE TABLE `logistics_transport_track`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `task_id` bigint NOT NULL COMMENT '运输任务id',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务场次，按场次归档用',
  `points` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '轨迹点，JSON Lines：一行一个{\"lng\",\"lat\",\"t\",\"addr\"}',
  `point_count` int NOT NULL DEFAULT 0 COMMENT '轨迹点数',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_task`(`task_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '物流-运输轨迹表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for logistics_waybill_price
-- ----------------------------
DROP TABLE IF EXISTS `logistics_waybill_price`;
CREATE TABLE `logistics_waybill_price`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `batch_no` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '导入批次号',
  `row_no` int NOT NULL COMMENT 'Excel行号',
  `carrier_id` bigint NOT NULL COMMENT '导入时选择的承运产品id',
  `config_id` bigint NULL DEFAULT NULL COMMENT '匹配到的旧物流配置id',
  `mail_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Excel第三方运单号原值',
  `dedup_mail_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成功计价运单号去重键，失败/空运单号为NULL',
  `receiver_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Excel收件人快照',
  `receiver_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Excel手机号快照',
  `destination_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Excel目的地址快照',
  `report_price` decimal(10, 2) NULL DEFAULT NULL COMMENT 'Excel填报价格',
  `weight` decimal(12, 3) NULL DEFAULT NULL COMMENT 'Excel重量',
  `package_info` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Excel包裹信息',
  `logistics_order_id` bigint NULL DEFAULT NULL COMMENT '匹配的xm_bulky_logistics_order.id',
  `logistics_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '寻梦物流订单号快照',
  `send_order_id` bigint NULL DEFAULT NULL COMMENT '匹配的xm_bulky_send_order.id',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发货单号快照',
  `match_status` tinyint NOT NULL DEFAULT 0 COMMENT '0待匹配 1成功 2空号 3未找到 4重复 5多条匹配 6发货单不存在 7已结算 8物流不匹配 9数据非法 10未找到可报价包裹 11报价被驳回待重新匹配',
  `match_source` tinyint NOT NULL DEFAULT 0 COMMENT '0未匹配 1自动 2人工',
  `apply_status` tinyint NOT NULL DEFAULT 0 COMMENT '0未计价 1已计入发货单',
  `fail_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '失败原因',
  `import_operator_id` bigint NULL DEFAULT NULL COMMENT '导入人id',
  `import_operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '导入人名称',
  `match_operator_id` bigint NULL DEFAULT NULL COMMENT '人工匹配人id',
  `match_operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人工匹配人名称',
  `match_time` datetime NULL DEFAULT NULL COMMENT '匹配时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 -100删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_waybill_dedup_mail_no`(`dedup_mail_no` ASC) USING BTREE,
  INDEX `idx_waybill_batch`(`batch_no` ASC, `row_no` ASC) USING BTREE,
  INDEX `idx_waybill_carrier_status`(`carrier_id` ASC, `match_status` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_waybill_send_no`(`send_no` ASC, `apply_status` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '第三方运单价格导入明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for machine_prepare_log
-- ----------------------------
DROP TABLE IF EXISTS `machine_prepare_log`;
CREATE TABLE `machine_prepare_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `code_content` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `date` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `zone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `shelf` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `enter_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'enter_item表主键id',
  `delivery_income` decimal(10, 2) UNSIGNED NULL DEFAULT NULL,
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `op` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作 1：增加 2：减少',
  `op_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认 0 扫码枪 1：人工 2:质检',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '默认0 删除-100',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_code_content`(`code_content` ASC) USING BTREE COMMENT '二维码内容',
  INDEX `idx_date_userid`(`date` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_enteritemid`(`enter_item_id` ASC) USING BTREE,
  INDEX `idx_supplierid_shelfsn`(`supplier_id` ASC, `shelf_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7264 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '扫码枪配货日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for member_coupon_record
-- ----------------------------
DROP TABLE IF EXISTS `member_coupon_record`;
CREATE TABLE `member_coupon_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint NOT NULL DEFAULT 0 COMMENT '用户id',
  `level` tinyint NOT NULL DEFAULT 0 COMMENT '用户会员等级',
  `coupon_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '优惠券配置',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发放时间',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '领取状态：0-未领取 1-已领取',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_roundno`(`round_no` ASC) USING BTREE,
  INDEX `idx_pid_roundno`(`purchaser_id` ASC, `round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20811111213278 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员优惠券发放记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for member_exp_log
-- ----------------------------
DROP TABLE IF EXISTS `member_exp_log`;
CREATE TABLE `member_exp_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 1-增加 2-减少',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `old_exp` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '旧成长值（非负）',
  `exp` int NOT NULL DEFAULT 0 COMMENT '成长值',
  `new_exp` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '新成长值（非负）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE,
  INDEX `idx_uid_order_sn_type`(`purchaser_id` ASC, `order_sn` ASC, `type` ASC) USING BTREE,
  INDEX `idx_purchaser_type_time_exp`(`purchaser_id` ASC, `type` ASC, `create_time` ASC, `exp` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15227 AVG_ROW_LENGTH = 58 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员成长值变动表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for member_level_config
-- ----------------------------
DROP TABLE IF EXISTS `member_level_config`;
CREATE TABLE `member_level_config`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `level` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '会员等级',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '等级名称，限20字',
  `exp` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '成长值要去',
  `coupon_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '专属优惠券',
  `rate` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 1.00 COMMENT '积分速率',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '等级图标',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '等级描述',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员等级配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for member_level_history
-- ----------------------------
DROP TABLE IF EXISTS `member_level_history`;
CREATE TABLE `member_level_history`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `platform` tinyint NOT NULL DEFAULT 1 COMMENT '平台：1-批发 2-繁花',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '扎数',
  `old_level_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '旧等级id',
  `old_level_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '旧等级名称',
  `level_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '新等级id',
  `level_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '新等级名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pid_ctime`(`purchaser_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1112 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员等级记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for member_point_bill
-- ----------------------------
DROP TABLE IF EXISTS `member_point_bill`;
CREATE TABLE `member_point_bill`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 1-增加 2-减少',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `old_point` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '旧积分值（非负）',
  `point` int NOT NULL DEFAULT 0 COMMENT '积分变动值',
  `new_point` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '新积分值（非负）',
  `reason` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pid_ctime`(`purchaser_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员积分账单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for membership
-- ----------------------------
DROP TABLE IF EXISTS `membership`;
CREATE TABLE `membership`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id，唯一',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appId',
  `vip_level` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '会员等级',
  `level_time` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '评级时间 yyyy-MM-dd',
  `point` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '会员积分',
  `exp` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '会员成长值',
  `rolling_exp_365` int NULL DEFAULT 0 COMMENT '365天滚动成长值',
  `protection_start_time` datetime NULL DEFAULT NULL COMMENT '保级开始时间',
  `protection_status` tinyint NULL DEFAULT 0 COMMENT '保级状态：0-正常，1-保级中',
  `last_level_check_time` datetime NULL DEFAULT NULL COMMENT '最后等级评定时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_membership_protection_status`(`protection_status` ASC) USING BTREE,
  INDEX `idx_membership_last_check_time`(`last_level_check_time` ASC) USING BTREE,
  INDEX `idx_appid_level`(`app_id` ASC, `vip_level` ASC) USING BTREE,
  INDEX `idx_vip_level_user_id`(`vip_level` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_app_id_id`(`app_id` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 86546 AVG_ROW_LENGTH = 155 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for merchant_apply_info
-- ----------------------------
DROP TABLE IF EXISTS `merchant_apply_info`;
CREATE TABLE `merchant_apply_info`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `merchant_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户类型 1-城市仓 2-分销商',
  `merchant_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户id',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `merchant_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户名称',
  `contact_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名',
  `contact_tel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人电话',
  `email` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电子邮箱',
  `wechat_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信号',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `district` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `detail_address` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `warehouse_area` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '仓库面积',
  `door_photo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '门头照片链接',
  `license_photo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '营业执照照片链接',
  `site_photos` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '场地照片链接json',
  `advantage_desc` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '合作优势说明',
  `agree_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否勾选协议 0-否 1-是',
  `submit_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '提交状态 0-草稿 1-待审核 2-已驳回 3-已通过',
  `reject_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '驳回原因',
  `submit_time` datetime NULL DEFAULT NULL COMMENT '提交时间',
  `audit_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核人id',
  `audit_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人姓名',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `pass_page_viewed_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已查看审核通过页面 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_merchant_type_id`(`merchant_type` ASC, `merchant_id` ASC) USING BTREE,
  INDEX `idx_ware_id`(`ware_id` ASC) USING BTREE,
  INDEX `idx_partner_id`(`partner_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户入驻申请资料表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for merchant_audit_log
-- ----------------------------
DROP TABLE IF EXISTS `merchant_audit_log`;
CREATE TABLE `merchant_audit_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `record_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '记录类型 1-提交审核 2-审核操作 3-考核处理',
  `merchant_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户类型 1-城市仓 2-分销商',
  `merchant_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户id',
  `merchant_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户名称',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `ware_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市仓名称',
  `partner_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `partner_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分销商名称',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appId',
  `business_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '经营状态 1-正常经营 2-已下线',
  `audit_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核状态 0-待审核 1-已通过 2-已驳回',
  `action` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '动作',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '原因',
  `content` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细内容',
  `extra_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '扩展信息json',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_partner_action_time`(`partner_id` ASC, `action` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_ware_action_time`(`ware_id` ASC, `action` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 160 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户审批日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mibei_product
-- ----------------------------
DROP TABLE IF EXISTS `mibei_product`;
CREATE TABLE `mibei_product`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '寻梦二级分类id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '寻梦等级',
  `ranking` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '同分类同等级下的排名',
  `price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '价格',
  `supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价',
  `inventory` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '库存',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_secondid_rank_num_ranking`(`second_id` ASC, `rank_num` ASC, `ranking` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3098 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '米贝商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mibei_product_summary
-- ----------------------------
DROP TABLE IF EXISTS `mibei_product_summary`;
CREATE TABLE `mibei_product_summary`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `second_id` bigint NOT NULL COMMENT '寻梦二级分类id',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类名',
  `total_inventory` int NULL DEFAULT NULL COMMENT '二级分类总库存',
  `seller_num` int NULL DEFAULT NULL COMMENT '二级分类供应商数量',
  `xm_total_inventory` int NULL DEFAULT NULL COMMENT '寻梦库存',
  `xm_supplier_num` int NULL DEFAULT NULL COMMENT '寻梦供应商数量',
  `inventory_diff_ratio` decimal(12, 4) NULL DEFAULT NULL COMMENT '库存差值比例 (米贝库存-寻梦库存)/寻梦库存',
  `supplier_diff_ratio` decimal(12, 4) NULL DEFAULT NULL COMMENT '供应商差值比例 (米贝供应商数-寻梦供应商数)/寻梦供应商数',
  `summary_date` date NULL DEFAULT NULL COMMENT '数据日期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_second_id`(`second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4481 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '米贝商品二级分类汇总表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner
-- ----------------------------
DROP TABLE IF EXISTS `partner`;
CREATE TABLE `partner`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分销商名称',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '绑定结算供应商id',
  `app_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'app_id',
  `contact_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名，限32字',
  `contact_tel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人电话，限32字',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态 0-已创建 1-已开通 2-已关闭',
  `service_fee_add_price_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '服务费加价开关 0-否 1-是',
  `service_fee_add_price` decimal(6, 2) NOT NULL DEFAULT 0.00 COMMENT '服务费加价系数 元/kg 范围0-20',
  `service_fee_merge` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '服务费是否合并到花材 0-否 1-是',
  `free_shipping_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否包邮 0不包邮 1包邮',
  `open_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有开放平台 0-否 1-是',
  `coupon_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '分销商优惠券开关：0=否，1=是',
  `coupon_use_flag` tinyint NOT NULL DEFAULT 0 COMMENT '分销商优惠券当天使用优惠券数量限制为1张开关：0-不限制 1-限制',
  `add_price_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '加价开关 0-正常 1-支持负值',
  `b2b_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否是b2b门店：0-不是 1-是',
  `promote_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推广合作 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_appid`(`app_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2911 AVG_ROW_LENGTH = 245 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销商' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner_class_first_add_price
-- ----------------------------
DROP TABLE IF EXISTS `partner_class_first_add_price`;
CREATE TABLE `partner_class_first_add_price`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `partner_region_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销区域id',
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级123456->ABCDEO',
  `add_price` decimal(6, 2) NOT NULL DEFAULT 0.00 COMMENT '加价（元）',
  `enable` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '开关 0-关 1-开',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_firstid_ranknum_pid_prid`(`first_id` ASC, `rank_num` ASC, `partner_id` ASC, `partner_region_id` ASC) USING BTREE,
  INDEX `idx_pid`(`partner_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 485 AVG_ROW_LENGTH = 61 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销商一级分类加价表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner_class_second
-- ----------------------------
DROP TABLE IF EXISTS `partner_class_second`;
CREATE TABLE `partner_class_second`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片url',
  `rank_auth` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'rank权限[1,2,3,4,5,6]',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_appid_secondid`(`app_id` ASC, `second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7326 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销商二级分类配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner_class_second_add_price
-- ----------------------------
DROP TABLE IF EXISTS `partner_class_second_add_price`;
CREATE TABLE `partner_class_second_add_price`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级123456->ABCDEO',
  `add_price` decimal(6, 2) NOT NULL DEFAULT 0.00 COMMENT '加价（元）可以为负',
  `price_unit` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '加价单位：0-历史兼容 1-元/kg 2-元/扎',
  `enable` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '开关 0-关 1-开',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_secondid_ranknum_partnerid`(`second_id` ASC, `rank_num` ASC, `partner_id` ASC) USING BTREE,
  INDEX `idx_partnerid`(`partner_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 488 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销商二级分类加价表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner_class_second_add_price_log
-- ----------------------------
DROP TABLE IF EXISTS `partner_class_second_add_price_log`;
CREATE TABLE `partner_class_second_add_price_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `operation_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '同一次保存的操作批次号',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级0-6：无等级、A、B、C、D、E、O',
  `current_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '保存前当前加价',
  `change_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '本次加价值',
  `final_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '保存后的最终加价',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_operation_second_rank`(`operation_no` ASC, `second_id` ASC, `rank_num` ASC) USING BTREE,
  INDEX `idx_partner_second_operation_id`(`partner_id` ASC, `second_id` ASC, `operation_no` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 884 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销商二级分类等级加价操作日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner_common_class
-- ----------------------------
DROP TABLE IF EXISTS `partner_common_class`;
CREATE TABLE `partner_common_class`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '常用分类名称',
  `second_ids` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级分类id列表，英文逗号分隔',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_partner`(`partner_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销商常用分类表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner_config
-- ----------------------------
DROP TABLE IF EXISTS `partner_config`;
CREATE TABLE `partner_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `partner_id` int UNSIGNED NOT NULL COMMENT '分销商id',
  `show_phone_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否展示用户联系电话：1-展示(开), 0-不展示(关)',
  `contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最后修改人ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `menu_access_password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分销后台菜单访问密码BCrypt密文',
  `menu_access_salt` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分销后台菜单访问密码盐',
  `menu_access_password_version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '菜单访问密码版本号',
  `protected_menu_codes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '开启密码保护的菜单code JSON数组',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_partner_id`(`partner_id` ASC) USING BTREE COMMENT '确保一个分销商只有一条配置记录'
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销商联系配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner_data_statistics
-- ----------------------------
DROP TABLE IF EXISTS `partner_data_statistics`;
CREATE TABLE `partner_data_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `yyyy_mm_dd` date NOT NULL COMMENT '年月日，如2024-06-18',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `all_total_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '用户支付金额',
  `turnover` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '营业额',
  `supplier_due` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商所得',
  `service_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '服务费收入',
  `refer_service_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '服务费支出',
  `delta_service_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '服务费=服务费收入-服务费支出',
  `partner_product_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分销商商品加价',
  `partner_express_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分销商物流加价',
  `ot_exp_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '一次性加价',
  `express_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '运费',
  `add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '加价',
  `rebate_xm_coin` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '用户返点',
  `subsidy_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '单品补贴金额',
  `cotton_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '保温棉金额',
  `supply_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供货价（废弃）',
  `after_sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '售后金额（按处理时间）',
  `supplier_after_sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商售后金额',
  `partner_after_sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分销商售后金额',
  `pack_bear_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '打包承担金额',
  `express_bear_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '物流承担金额',
  `supplier_punish` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商处罚',
  `take_xm_coin` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '当日供应商抽点',
  `take_xm_coin_return` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '当日供应商抽点返还',
  `total_income` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '收入合计',
  `all_refund_express_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '运费退款',
  `all_express_fill` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '运费补差',
  `total_station_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商承担的集货站运费',
  `purchaser_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '下单用户数',
  `send_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货单数',
  `order_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单数',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品扎数',
  `base_item_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '基地扎数',
  `total_weight` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日总重（kg）',
  `flash_sale_discount_in` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '秒杀活动补贴增加',
  `flash_sale_discount_out` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '秒杀活动补贴减少',
  `platform_coupon_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台承担优惠券',
  `coupon_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '其他承担优惠券',
  `platform_reduce_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平台满减金额',
  `complain_return_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申诉退回金额',
  `extra_service_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '额外服务费',
  `quality_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '质检收入',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_date_pid`(`yyyy_mm_dd` ASC, `partner_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销商数据统计' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for partner_logistics_config
-- ----------------------------
DROP TABLE IF EXISTS `partner_logistics_config`;
CREATE TABLE `partner_logistics_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `config_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流商id',
  `name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流别名',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序 升序',
  `is_enable` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否启用 0-否 1-是 默认1',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否启用 0-否 1-是 默认1',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pid_cid`(`partner_id` ASC, `config_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36297 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销物流配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner_logistics_region_price
-- ----------------------------
DROP TABLE IF EXISTS `partner_logistics_region_price`;
CREATE TABLE `partner_logistics_region_price`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `province_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '省id',
  `province_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省名称',
  `city_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '市id',
  `city_name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市名称',
  `district_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '区id',
  `district_name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区名称',
  `adcode` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市adcode',
  `express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流配置id（一个城市一个物流）',
  `express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '物流加价系数 元/kg 范围0-20',
  `express_add_price_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `express_add_price_merge` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '物流加价是否合并到花材 0-否 1-是 默认1',
  `default_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否默认物流 0-否 1-是',
  `self_pick_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否自提：0-否，1-是',
  `cotton_switch` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温棉开关 0-关 1-开 默认关',
  `region_switch` tinyint NOT NULL DEFAULT 1 COMMENT '区域物流启用开关：0-未启用 1-启用',
  `cotton_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温棉数量 最大50',
  `start_weight_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '起发重量开关 0-关 1-开 默认关',
  `start_sell_weight` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 6.00 COMMENT '起售重量kg 默认6kg',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_c_e`(`city_id` ASC, `express_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4490 AVG_ROW_LENGTH = 170 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销商物流区域加价表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner_promoter
-- ----------------------------
DROP TABLE IF EXISTS `partner_promoter`;
CREATE TABLE `partner_promoter`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `commission_ratio` decimal(6, 3) UNSIGNED NOT NULL DEFAULT 0.000 COMMENT '提成比例 限0~1',
  `sale_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否达人 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_partnerid`(`partner_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 AVG_ROW_LENGTH = 119 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销商推广员表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner_supplier
-- ----------------------------
DROP TABLE IF EXISTS `partner_supplier`;
CREATE TABLE `partner_supplier`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `add_price_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否加价 0-否 1-是 默认1',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_partnerid_supplierid`(`partner_id` ASC, `supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 52 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销商专属供应商' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner_template
-- ----------------------------
DROP TABLE IF EXISTS `partner_template`;
CREATE TABLE `partner_template`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `category_show_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '金刚位展示样式 0-默认 1-两排8个 2-一排全展示',
  `template_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '模板id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_appid`(`app_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销模板配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner_user
-- ----------------------------
DROP TABLE IF EXISTS `partner_user`;
CREATE TABLE `partner_user`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `nickname` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名称',
  `is_sub` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否子账号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_userid_partnerid`(`user_id` ASC, `partner_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 185 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销商用户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for partner_warehouse_bind
-- ----------------------------
DROP TABLE IF EXISTS `partner_warehouse_bind`;
CREATE TABLE `partner_warehouse_bind`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `start_sell_weight` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '起售重量kg 默认0kg',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-不启用 1-启用',
  `shipping_area_initialized` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '繁花独立配送范围是否已完成首次初始化 0-否 1-是',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `large_customer_pack_flag` tinyint NOT NULL DEFAULT 0 COMMENT '大客户单独打包开关 0-关 1-开',
  `large_customer_pack_weight` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 6.00 COMMENT '大客户单独打包起重重量kg',
  `merge_delivery_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '合并发货开关 0-关 1-开',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pid_wid`(`partner_id` ASC, `ware_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 60 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销城市仓绑定表' ROW_FORMAT = Dynamic;

-- ----------------------------
