  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pid_wid_status`(`partner_id` ASC, `ware_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9090012 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分销城市仓配送范围配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
