-- ----------------------------
-- Table structure for pic_home_page
-- ----------------------------
DROP TABLE IF EXISTS `pic_home_page`;
CREATE TABLE `pic_home_page`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `show_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '显示类型 1-banner 3-宫格图 4-专题一 5-专题二 6-我的首页 7-资讯首页',
  `router_type` tinyint UNSIGNED NOT NULL COMMENT '跳转类型：1-分类 2-作品 3-花艺师 4-话题 5-帖子 6-长图',
  `title` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题，限32字',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片，限255字',
  `url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '跳转目标',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序 升序',
  `show_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否展示 0-否 1-是 默认1',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '图库首页配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for pic_lib
-- ----------------------------
DROP TABLE IF EXISTS `pic_lib`;
CREATE TABLE `pic_lib`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '作品ID',
  `category_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分类ID',
  `group_id` bigint UNSIGNED NULL DEFAULT 0 COMMENT '作品组ID',
  `user_id` bigint UNSIGNED NULL DEFAULT 0 COMMENT '发布者ID ',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '描述',
  `cover_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '封面图片URL',
  `image_urls` varchar(8192) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片URL列表',
  `view_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '浏览量',
  `collection_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '收藏数',
  `comment_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '评论数',
  `like_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '点赞数',
  `share_count` int NOT NULL DEFAULT 0 COMMENT '分享数',
  `download_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '下载数',
  `hot_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否热门 0-否 1-是',
  `top_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否置顶 0-否 1-是',
  `recommend_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推荐 0-否 1-是',
  `notify_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否通知用户 1-是 0-否',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '排序 升序',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  `version` int NOT NULL DEFAULT 1 COMMENT '乐观锁版本号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `content_updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '内容更新时间',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态 (默认为3, 0-不展示, 1-展示, 2-草稿, 3-待审核, 4-不通过)',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核通过/不通过的原因',
  `reviewer_id` bigint NOT NULL DEFAULT 0 COMMENT '审核员id',
  `reviewer_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核员姓名',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_userid`(`user_id` ASC) USING BTREE,
  INDEX `idx_groupid`(`group_id` ASC) USING BTREE,
  INDEX `idx_cid`(`category_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1574 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '图库作品表' ROW_FORMAT = DYNAMIC;

