-- Table structure for pic_lib_category_map_backup
-- ----------------------------
DROP TABLE IF EXISTS `pic_lib_category_map_backup`;
CREATE TABLE `pic_lib_category_map_backup`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `pic_id` bigint UNSIGNED NOT NULL COMMENT '作品ID',
