  `group_cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '作品组封面',
  `group_sort` bigint UNSIGNED NOT NULL DEFAULT 1 COMMENT '排序值',
  `group_show` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否展示：0-不展示，1-展示',
  `last_bind_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '作品最后绑定时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_last_bind_time`(`last_bind_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '图库作品组表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for pic_my_page
-- ----------------------------
DROP TABLE IF EXISTS `pic_my_page`;
CREATE TABLE `pic_my_page`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '用户id',
  `show_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '展示类型：1-banner',
  `router_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '跳转类型',
