  `my_comment` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '发布数',
  `my_follow` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '关注数',
  `my_like` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '点赞数',
  `my_star` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '收藏数',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '跳转目标',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
