-- ----------------------------
-- Table structure for pic_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `pic_operation_log`;
CREATE TABLE `pic_operation_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `target_type` tinyint NOT NULL COMMENT '被修改对象类型, 1-图库图片, 2-话题帖子',
  `target_id` bigint UNSIGNED NOT NULL COMMENT '被操作对象ID',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作者id',
  `user_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作者姓名',
  `content` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作内容',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_target`(`target_id` ASC, `target_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '花现操作记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for pic_review_record
-- ----------------------------
DROP TABLE IF EXISTS `pic_review_record`;
CREATE TABLE `pic_review_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
