  `reason` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核通过/不通过的原因',
  `review_status` tinyint NOT NULL DEFAULT 0 COMMENT '审核状态 (默认为0, 0-待审核, 1-通过, 2-不通过)',
  `reviewer_id` bigint NOT NULL DEFAULT 0 COMMENT '审核员id',
  `reviewer_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核员姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `review_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '审核时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '审核记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for pic_search_record
-- ----------------------------
DROP TABLE IF EXISTS `pic_search_record`;
CREATE TABLE `pic_search_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint NOT NULL DEFAULT 0 COMMENT '用户id',
