-- ----------------------------
-- Table structure for pic_user
-- ----------------------------
DROP TABLE IF EXISTS `pic_user`;
CREATE TABLE `pic_user`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户id',
  `nickname` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花艺师姓名，限20字',
  `phone_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '绑定批发小程序手机号',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花艺师头像，限255字',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花艺师照片',
  `background` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '背景图片',
  `introduction` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '简介，限255字',
  `lib_groups` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花艺师所属作品组的id列表',
  `follows` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '关注数',
  `status_show` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否展示：0-不展示，1-展示',
  `status_display` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否推荐：0-不推荐，1-推荐',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态 0-停用 1-正常',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `identity` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '身份：1-花艺师，2-达人,3-普通用户',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 60 AVG_ROW_LENGTH = 927 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '图库花艺师表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for pic_user_information
-- ----------------------------
DROP TABLE IF EXISTS `pic_user_information`;
CREATE TABLE `pic_user_information`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `recipient_id` bigint NOT NULL COMMENT '被通知的用户id',
  `content` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '通知内容',
  `sender_id` bigint NOT NULL COMMENT '触发消息的用户的ID',
  `target_type` tinyint NOT NULL DEFAULT 0 COMMENT '来源类型, 1-作品, 2-帖子, 3-评论, 4-话题, 5-被关注,6-被点赞,',
  `target_id` bigint NOT NULL DEFAULT 0 COMMENT '来源 id',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0-未读，1-已读',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '通知时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_recipient_time`(`recipient_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 57 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '图库用户首页消息通知表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for point_log
-- ----------------------------
DROP TABLE IF EXISTS `point_log`;
CREATE TABLE `point_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 1-增加 2-减少 3-过期',
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '平台 1-批发 2-资材 3-繁花',
  `point` int NOT NULL COMMENT '积分数量',
  `remaining_point` int NOT NULL COMMENT '剩余积分',
  `source_type` int NOT NULL COMMENT '积分来源 1-购物获得 2-兑换商品 3-过期扣除 4-评价获得 5-每日打卡 6-抽奖发放',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联订单号',
  `expire_time` datetime NOT NULL COMMENT '积分有效期',
  `is_expired` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已过期 0-未过期 1-已过期',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_expire`(`user_id` ASC, `is_expired` ASC, `expire_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5662033 AVG_ROW_LENGTH = 134 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '积分变动记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for point_mall_category
-- ----------------------------
DROP TABLE IF EXISTS `point_mall_category`;
CREATE TABLE `point_mall_category`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '积分商城分类表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for point_mall_exchange_log
-- ----------------------------
DROP TABLE IF EXISTS `point_mall_exchange_log`;
CREATE TABLE `point_mall_exchange_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `cost_point` int UNSIGNED NULL DEFAULT 0 COMMENT '消耗积分',
  `left_point` int UNSIGNED NULL DEFAULT 0 COMMENT '剩余积分',
  `product_id` int UNSIGNED NULL DEFAULT 0 COMMENT '兑换商品id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '兑换商品名称',
  `exchange_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '兑换数量',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '积分商城兑换记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for point_mall_order
-- ----------------------------
DROP TABLE IF EXISTS `point_mall_order`;
CREATE TABLE `point_mall_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '平台 1-批发 2-繁花 3-优花速达',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `coupon_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '优惠券no',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `price` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单价格（积分）',
  `pic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '兑换数量',
  `order_status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '订单状态 1：待发货 2：待收货 3：已完成 4：已取消',
  `express_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流单号',
  `receive_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '收货人姓名',
  `receive_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '收货人地址',
  `receive_tel` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '收货人电话',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ordersn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 473 AVG_ROW_LENGTH = 243 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '积分商城订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for point_mall_product
-- ----------------------------
DROP TABLE IF EXISTS `point_mall_product`;
CREATE TABLE `point_mall_product`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '平台 1-批发 2-繁花 3-优花速达',
  `category_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分类id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品描述',
  `price` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '兑换需要积分',
  `pic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `remain_stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '剩余库存',
  `limit_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '领取规则 0:限领 >0 每n天限领',
  `limit_exchange` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '限制兑换次数',
  `coupon_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '优惠券编号',
  `product_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品状态 0：未上架 1：已上架',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0-正常 1-删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_cateid`(`category_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 AVG_ROW_LENGTH = 963 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '积分商城商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for pop_search_config
-- ----------------------------
DROP TABLE IF EXISTS `pop_search_config`;
CREATE TABLE `pop_search_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint NOT NULL DEFAULT 0 COMMENT '类型：0-鲜花 1-供应商',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '热榜内容',
  `sort_num` tinyint NOT NULL DEFAULT 0 COMMENT '排序值',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0-正常 -100-删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '热门搜索内容配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for post_follow
-- ----------------------------
DROP TABLE IF EXISTS `post_follow`;
CREATE TABLE `post_follow`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `follower_id` bigint NOT NULL COMMENT '关注者id',
  `followed_id` bigint NOT NULL COMMENT '被关注的资讯id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_fid_fedid`(`follower_id` ASC, `followed_id` ASC) USING BTREE,
  INDEX `idx_fid_fedid`(`followed_id` ASC, `follower_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '资讯关注表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for post_lib
-- ----------------------------
DROP TABLE IF EXISTS `post_lib`;
CREATE TABLE `post_lib`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '资讯ID',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '发布者ID ',
  `user_identity` tinyint UNSIGNED NOT NULL DEFAULT 2 COMMENT '发布者身份: 1-普通用户, 2-花艺师',
  `topic_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '话题ID',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '描述',
  `cover_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '封面图片URL',
  `image_urls` varchar(8192) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片URL列表',
  `view_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '浏览量',
  `collection_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '收藏数',
  `comment_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '评论数',
  `like_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '点赞数',
  `share_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分享数',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 2 COMMENT '状态 (默认为3, 0-不展示, 1-展示, 2-草稿, 3-待审核, 4-不通过)',
  `top_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否置顶 0-否 1-是',
  `hot_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否热门 0-否 1-是',
  `recommend_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推荐 0-否 1-是',
  `notify_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否通知用户 1-是 0-否',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `version` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '乐观锁版本号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核通过/不通过的原因',
  `reviewer_id` bigint NULL DEFAULT NULL COMMENT '审核员id',
  `reviewer_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核员姓名',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_userid`(`user_id` ASC) USING BTREE,
  INDEX `idx_topic`(`topic_id` ASC) USING BTREE,
  INDEX `idx_status_created_view`(`status` ASC, `created_at` ASC, `view_count` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 102 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '资讯表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for product_display_scores
-- ----------------------------
DROP TABLE IF EXISTS `product_display_scores`;
CREATE TABLE `product_display_scores`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `hidden_score` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '隐藏分',
  `display_score` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '展示分',
  `comment_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '评论条数',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for product_punish_record
-- ----------------------------
DROP TABLE IF EXISTS `product_punish_record`;
CREATE TABLE `product_punish_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `product_id` bigint NOT NULL DEFAULT 0 COMMENT '处罚的商品id',
  `punish_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '处罚类型：1-商品降权 2-商品冻结',
  `punish_reason` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '处罚原因',
  `punish_start` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '处罚开始时间',
  `punish_end` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '处罚预计结束时间',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '处罚员id',
  `operator_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '处罚人姓名',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_product_id_time`(`product_id` ASC, `punish_start` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 125 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品处罚降权记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for province_area
-- ----------------------------
DROP TABLE IF EXISTS `province_area`;
CREATE TABLE `province_area`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `province` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `adcode` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'adcode',
  `area_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分区 见 customer_area_type 表',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `fhh_area_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '繁花分区：6-繁花北区，7-繁花南区，8-繁花西区',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_province`(`province` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '省份分区表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for purchase_statistics
-- ----------------------------
DROP TABLE IF EXISTS `purchase_statistics`;
CREATE TABLE `purchase_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `today_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当天购买扎数',
  `today_subsidy_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当天购买补贴扎数',
  `three_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '3天购买扎数',
  `three_subsidy_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '3天购买补贴扎数',
  `seven_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '7天购买扎数',
  `seven_subsidy_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '7天购买补贴扎数',
  `fourteen_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '14天购买扎数',
  `fourteen_subsidy_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '14天购买补贴扎数',
  `thirty_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '30天购买扎数',
  `thirty_subsidy_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '30天购买补贴扎数',
  `today_user_tag` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '当天用户标签',
  `today_user_tag_record` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当天用户标签记录 时间、扎数、补贴扎数、标签',
  `thirty_user_tag` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '30天用户标签',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_roundno_purchaserid`(`round_no` ASC, `purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1145 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '购买统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for purchaser_area_log
-- ----------------------------
DROP TABLE IF EXISTS `purchaser_area_log`;
CREATE TABLE `purchaser_area_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `province` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `area_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分区',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pid`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 92739 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购方大区变更记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for purchaser_bill
-- ----------------------------
DROP TABLE IF EXISTS `purchaser_bill`;
CREATE TABLE `purchaser_bill`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `balance` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '账单余额（大于0为应退小于0为应补）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pid`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购方账单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for purchaser_bill_detail
-- ----------------------------
DROP TABLE IF EXISTS `purchaser_bill_detail`;
CREATE TABLE `purchaser_bill_detail`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 1-应退 2-应补 3-已退 4-已补',
  `old_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '旧余额',
  `amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '金额 应退正 应补负 已退负 已补正',
  `new_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '新余额',
  `remark` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注 限2048字',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pid`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_ctime_pid`(`create_time` ASC, `purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 175274 AVG_ROW_LENGTH = 132 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购方账单明细表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for purchaser_extra_info
-- ----------------------------
DROP TABLE IF EXISTS `purchaser_extra_info`;
CREATE TABLE `purchaser_extra_info`  (
  `id` bigint NOT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for purchaser_mail
-- ----------------------------
DROP TABLE IF EXISTS `purchaser_mail`;
CREATE TABLE `purchaser_mail`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '内容',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-未读 1-已读',
  `coupon_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '优惠券编号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pid_ctime`(`purchaser_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_con_pid`(`coupon_no` ASC, `purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 269 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户邮箱表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for purchaser_recall_log
-- ----------------------------
DROP TABLE IF EXISTS `purchaser_recall_log`;
CREATE TABLE `purchaser_recall_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `recall_time` datetime NOT NULL COMMENT '召回时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pid`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_recalltime_pid`(`recall_time` ASC, `purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 120 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购方召回记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for purchaser_use_recall_record
-- ----------------------------
DROP TABLE IF EXISTS `purchaser_use_recall_record`;
CREATE TABLE `purchaser_use_recall_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购用户ID',
  `last_use_time` datetime NULL DEFAULT NULL COMMENT '最近使用时间',
  `last_recall_time` datetime NULL DEFAULT NULL COMMENT '最近召回时间',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_purchaser_id`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_app_id`(`app_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 86641 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购用户使用与召回记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qixi_lottery_chance
-- ----------------------------
DROP TABLE IF EXISTS `qixi_lottery_chance`;
CREATE TABLE `qixi_lottery_chance`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `round_no` date NOT NULL COMMENT '场次',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `free_total` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '本场免费抽奖总次数',
  `free_used` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '本场已消耗免费抽奖次数',
  `order_total` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '本场下单加赠总次数，最多2次',
  `order_used` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '本场已消耗下单加赠次数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_round_purchaser`(`round_no` ASC, `purchaser_id` ASC) USING BTREE,
  INDEX `idx_purchaser_round`(`purchaser_id` ASC, `round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 75061 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '繁花七夕抽奖次数' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qixi_lottery_prize_display
-- ----------------------------
DROP TABLE IF EXISTS `qixi_lottery_prize_display`;
CREATE TABLE `qixi_lottery_prize_display`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '前端识别奖品和转盘落点的稳定ID',
  `display_index` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '转盘展示位置，从0开始',
  `prize_code` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '奖品编码：1~6为真实奖品，7为不可抽中的锦鲤展示项',
  `display_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '奖级展示名称',
  `prize_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '奖品展示名称',
  `is_max` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否展示锦鲤角标：0否 1是',
  `prize_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '展示类型：1积分 2优惠券',
  `point_value` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '积分展示值',
  `coupon_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '优惠券编码，锦鲤展示项为空',
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '奖品图片地址',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_display_index`(`display_index` ASC) USING BTREE,
  INDEX `idx_prize_draw_status`(`prize_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '繁花七夕抽奖奖品展示配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qixi_lottery_probability
-- ----------------------------
DROP TABLE IF EXISTS `qixi_lottery_probability`;
CREATE TABLE `qixi_lottery_probability`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `vip_level` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0=VIP0 1=VIP1-2 3=VIP3 4=VIP4',
  `prize_code` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '1参与奖 2幸运奖 3三等奖 4二等奖 5一等奖 6七夕大奖',
  `weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '万分比权重',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_vip_level_prize`(`vip_level` ASC, `prize_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 101 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '繁花七夕抽奖概率' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qixi_lottery_record
-- ----------------------------
DROP TABLE IF EXISTS `qixi_lottery_record`;
CREATE TABLE `qixi_lottery_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `request_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单次抽奖幂等请求号',
  `round_no` date NOT NULL COMMENT '场次',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `vip_level` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '抽奖时用户实时VIP等级',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0处理中 1成功 2失败',
  `original_prize_code` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '按概率抽中的原始奖品编码',
  `actual_prize_code` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '库存顺延后的实际奖品编码',
  `prize_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '实际发放奖品名称快照',
  `coupon_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '实际发放优惠券编码',
  `point` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际发放积分数',
  `chance_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '1免费 2下单加赠',
  `display_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '中奖滚动列表脱敏用户名',
  `failure_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发奖失败原因',
  `award_time` datetime NULL DEFAULT NULL COMMENT '发奖成功时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_request_no`(`request_no` ASC) USING BTREE,
  INDEX `idx_pid`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_roundno`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 75233 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '繁花七夕抽奖流水' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for quick_ordering_item
-- ----------------------------
DROP TABLE IF EXISTS `quick_ordering_item`;
CREATE TABLE `quick_ordering_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '平台类型 0：大件批发 1：花仓库',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '二级分类名称',
  `spec` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规格数字',
  `spec_num` int NOT NULL COMMENT '规格单位 如：枝/扎',
  `remain_stock` int NOT NULL COMMENT '库存',
  `preference` tinyint NOT NULL COMMENT '偏好 1:品质优先 2：低价优先 3：销量优先',
  `rank_num` tinyint NOT NULL COMMENT '等级',
  `pic_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '二级分类图片',
  `avg_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '均价',
  `num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '期望购买数量',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态 0正常 -1：已保存至常购清单 -100：删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_second_id_rank`(`second_id` ASC, `rank_num` ASC) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 234 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购单商品' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for quick_ordering_list
-- ----------------------------
DROP TABLE IF EXISTS `quick_ordering_list`;
CREATE TABLE `quick_ordering_list`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '平台类型 0：大件批发 1：花仓库',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '常购清单名称',
  `item_list_str` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '关联采购清单商品id',
  `total_kind` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '花材种类',
  `total_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '总扎数',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态 0：正常 -100：删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '常购清单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for red_packet_log
-- ----------------------------
DROP TABLE IF EXISTS `red_packet_log`;
CREATE TABLE `red_packet_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `user_tag` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户标签',
  `amount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '奖品类型',
  `time_period` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '所属时间段',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_userid`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 75228 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '红包日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for refund_complain
-- ----------------------------
DROP TABLE IF EXISTS `refund_complain`;
CREATE TABLE `refund_complain`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `pid` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'pid',
  `refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '申诉id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pid`(`pid` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 83 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '售后申诉关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for saas_admin
-- ----------------------------
DROP TABLE IF EXISTS `saas_admin`;
CREATE TABLE `saas_admin`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '用户id、店铺id',
  `account_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '账号名称',
  `account_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '账号类型 0：普通账户 1：超管',
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '平台：1 ：普通分销 2：城市仓分销',
  `real_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '真实姓名',
  `phone` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '手机号',
  `salt` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '盐值',
  `password` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '密码',
  `openid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信openid微店运营端小程序一键登录使用',
  `authorizer_app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '授权的小程序AppId',
  `authorizer_app_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '小程序名称（店铺名称）',
  `category` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认 0：鲜花 1：蛋糕',
  `auth_time` bigint UNSIGNED NULL DEFAULT 0 COMMENT '授权时间',
  `xm_admin_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '寻梦用户id（绑定客服id）',
  `applyment_status` tinyint UNSIGNED NULL DEFAULT 4 COMMENT '是否成为特约商户 1：是 2：正在审核 3：审核失败 4：未提交申请',
  `weapp_status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否绑定小程序 1：当前登录用户没有绑定小程序 2：已绑定小程序，正在审核当中 3：已绑定小程序审核失败 4：已成功绑定小程序',
  `xm_authorization` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '授权到寻梦代运营 0：已授权 1：授权',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `data_status` int NULL DEFAULT 0 COMMENT '状态：默认0：正常  -100：删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_acc_name`(`account_name` ASC) USING BTREE,
  UNIQUE INDEX `uni_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_xm_authorization`(`xm_authorization` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦微店服务商用户' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for saas_app
-- ----------------------------
DROP TABLE IF EXISTS `saas_app`;
CREATE TABLE `saas_app`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '店铺名称',
  `category` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认 0：鲜花 1：蛋糕',
  `admin_id` bigint NOT NULL DEFAULT 0 COMMENT '用户id',
  `app_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'app_id',
  `merchant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商户号',
  `channel_id` bigint UNSIGNED NULL DEFAULT 0 COMMENT '渠道id，小助手授权设置',
  `com_id` bigint UNSIGNED NULL DEFAULT 0 COMMENT '公司id，小助手授权设置',
  `nickname` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '昵称',
  `template_id` bigint NOT NULL DEFAULT 0 COMMENT '总店id',
  `avatar` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '头像',
  `phone` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `wechat` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信号',
  `notice` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '公告',
  `address` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '地址信息',
  `is_template` tinyint NULL DEFAULT 0 COMMENT '是否是模板 1-是 0-不是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_tid_name`(`template_id` ASC, `name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for saas_app_audit
-- ----------------------------
DROP TABLE IF EXISTS `saas_app_audit`;
CREATE TABLE `saas_app_audit`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appId',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业名称',
  `audit_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核id',
  `audit_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核状态 默认0：无 1：审核中 2：完成 3：审核失败',
  `audit_result` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核结果',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0：正常 -100：删除',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_app_id_audit_type`(`app_id` ASC, `audit_status` ASC) USING BTREE COMMENT '小程序appId和审核类型'
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '小程序提审记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for saas_app_pay
-- ----------------------------
DROP TABLE IF EXISTS `saas_app_pay`;
CREATE TABLE `saas_app_pay`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `app_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `app_secret` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `mch_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `mch_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for saas_bank
-- ----------------------------
DROP TABLE IF EXISTS `saas_bank`;
CREATE TABLE `saas_bank`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `bank_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '银行行联号',
  `bank` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '银行全称',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_bank`(`bank` ASC) USING BTREE COMMENT '银行名称'
) ENGINE = InnoDB AUTO_INCREMENT = 195693 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '开户行名称及行联号' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for saas_merchant_progress
-- ----------------------------
DROP TABLE IF EXISTS `saas_merchant_progress`;
CREATE TABLE `saas_merchant_progress`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `admin_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户用户id',
  `shop_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '店铺id',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序id',
  `app_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序审核状态，默认0：未申请，1：申请审核中，2：注册成功，3：注册失败',
  `is_set_signature` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序有没有设置介绍，默认0：没有 1：有',
  `is_set_name` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序有没有设置名称，默认0：没有 1：有',
  `is_set_head_url` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序有没有设置头像，默认0：没有 1：有',
  `merchant_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户名称',
  `applyment_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '特约商户入驻状态，默认0：未申请，1：申请审核中 2：入驻成功 3：审核失败',
  `bind_assistant` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '绑定小助手状态，默认0：未绑定，1：已绑定',
  `app_online` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序有没有上线 默认0：没有 1：有',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作id',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人名称',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_app_id`(`app_id` ASC) USING BTREE COMMENT '小程序appid',
  INDEX `idx_admin_id`(`admin_id` ASC) USING BTREE COMMENT '用户id'
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户入驻进度' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for saas_region
-- ----------------------------
DROP TABLE IF EXISTS `saas_region`;
CREATE TABLE `saas_region`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `adcode` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市编码',
  `area` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市地区',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3629 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for saas_tester
-- ----------------------------
DROP TABLE IF EXISTS `saas_tester`;
CREATE TABLE `saas_tester`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appid',
  `app_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序名称',
  `wechat_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信id',
  `userstr` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '人员对应的唯一字符串',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0：正常 -100：删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '小程序体验者列表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for saas_user_legal_info
-- ----------------------------
DROP TABLE IF EXISTS `saas_user_legal_info`;
CREATE TABLE `saas_user_legal_info`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业名称',
  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业代码',
  `code_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '企业代码类型 1：统一社会信用代码（18 位） 2：组织机构代码（9 位 xxxxxxxx-x） 3：营业执照注册号(15 位)',
  `legal_persona_wechat` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '法人微信号',
  `legal_persona_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '法人姓名',
  `component_phone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '联系电话',
  `qualifications` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '营业资质，如《食品经营许可证》',
  `data_status` tinyint NULL DEFAULT 0 COMMENT '状态：默认0：未创建小程序 1：已创建小程序  -100：删除',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for saas_user_register_info
-- ----------------------------
DROP TABLE IF EXISTS `saas_user_register_info`;
CREATE TABLE `saas_user_register_info`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `admin_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_mini_shop_admin的主键id',
  `info` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '营业执照、身份证、银行卡信息',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_admin_id`(`admin_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '小程序版本：用户上传的营业执照、身份证、银行卡信息' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for sale_agency_downgrade
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_downgrade`;
CREATE TABLE `sale_agency_downgrade`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `pic_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `item_list` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花材列表',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人',
  `operator_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作人姓名',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0:正常 -100 删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_agencyOrderId`(`agency_order_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_item
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_item`;
CREATE TABLE `sale_agency_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖计划单号',
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖订单号',
  `plan_item_id` bigint NOT NULL DEFAULT 0 COMMENT '对应寄售计划详情主键',
  `round_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类主键',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花材名称',
  `sale_num` int UNSIGNED NOT NULL COMMENT '寄售数量',
  `sale_rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '寄售级别',
  `sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '寄售价格（单个花材)',
  `sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配置',
  `transfer_stock_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原库存转入数量',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'product表主键',
  `stock_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '库存数量',
  `warehouse_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '入库数量',
  `outbound_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '出库数量',
  `refund_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '退回数量',
  `loss_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '报损数量',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供货商id',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供货商姓名',
  `detail_status` int NOT NULL DEFAULT 0 COMMENT 'detail表同步状态 0.未同步 1.同步',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order`(`agency_order_id` ASC) USING BTREE,
  INDEX `idx_plan_second`(`agency_plan_order` ASC, `second_id` ASC) USING BTREE,
  INDEX `idx_rno_sid`(`round_no` ASC, `supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 714 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '代卖花材表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_item_detail
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_item_detail`;
CREATE TABLE `sale_agency_item_detail`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `second_id` bigint NOT NULL DEFAULT 0 COMMENT '花材主键',
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖计划号',
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖订单号',
  `agency_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '对应代卖花材主键',
  `sort` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '第几把',
  `barcode` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `origin_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '初始定价',
  `origin_rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '初始级别',
  `origin_sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '初始sku_config',
  `onsale_rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售卖等级',
  `onsale_sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '售卖sku_config',
  `sale_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '最终售卖价格',
  `status` int NOT NULL DEFAULT 0 COMMENT '状态 0:待定级定价、1:待入库、2:售卖中 3:已售卖、10:完成、-1:报损、-2:退回 -3缺货',
  `apply_status` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核状态（0:无状态 1:报损待审核）',
  `report_loss_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'report_loss主键',
  `compensation_per` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '赔付比例0-100',
  `rate_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '定级人',
  `rate_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '定级人姓名',
  `inbound_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '入库人',
  `inbound_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '入库人姓名',
  `inbound_time` datetime NULL DEFAULT NULL COMMENT '入库时间',
  `outbound_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '出库人',
  `outbound_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '出库人姓名',
  `outbound_time` datetime NULL DEFAULT NULL COMMENT '出库时间',
  `outbound_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '出库类型（0:未出库 1:正常出库 2:其他场景出库）',
  `draw_ratio` decimal(3, 3) NOT NULL DEFAULT 0.000 COMMENT '抽点比例',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '出库场次编号：yyyy-MM-dd',
  `shelf_sn` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '出库货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '出库子货架号',
  `zone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `shelf` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `enter_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'enter_item主键id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号',
  `code_content` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供货商id',
  `sale_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 10003 COMMENT '售卖供应商ID',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `inspection_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '质检人id',
  `inspection_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `inspection_zone_shelf` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_orderid`(`agency_order_id` ASC) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_createtime_secondid_status`(`create_time` ASC, `second_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_enteritemId`(`enter_item_id` ASC) USING BTREE,
  INDEX `idx_itemId`(`agency_item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 90010766 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '花材明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_item_detail_log
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_item_detail_log`;
CREATE TABLE `sale_agency_item_detail_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `item_detail_id` bigint NOT NULL COMMENT '花材明细id',
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖计划号',
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖订单号',
  `op_type` int NOT NULL COMMENT '1:定级定价 2:出库 3、退回 4、报损 5、更改定级 6、入库 7报损申请、取消或拒绝',
  `old_rank` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '老级别',
  `new_rank` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '新级别',
  `detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '详细信息',
  `pic` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图片或视频',
  `operate_id` bigint NOT NULL COMMENT '操作人',
  `operate_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_detailid_optype`(`item_detail_id` ASC, `op_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7333 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '花材变更记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_night_sale_log
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_night_sale_log`;
CREATE TABLE `sale_agency_night_sale_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `supplier_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `operator_id` bigint NOT NULL COMMENT '操作人ID',
  `operator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '操作人名称',
  `operator_type` tinyint NOT NULL COMMENT '操作来源 1:平台 2:供应商',
  `night_sale_flag` tinyint NOT NULL COMMENT '晚场状态 0:关闭 1:开启',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '操作备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_supplier_id_create_time`(`supplier_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 48 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '代卖晚场开启关闭日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_on_sale_price
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_on_sale_price`;
CREATE TABLE `sale_agency_on_sale_price`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'second主键',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花材名称',
  `sku_price` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '价格',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `update_online` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新到线上 0:不更新 1:更新',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_secondid`(`second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 40 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '代卖售卖价目表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_order
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_order`;
CREATE TABLE `sale_agency_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖计划单号',
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖订单号',
  `plan_item_id` bigint NOT NULL COMMENT '对应寄售计划详情主键',
  `round_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次',
  `type` tinyint NOT NULL DEFAULT 0 COMMENT '1.自主寄售 2.转入寄售 3.收购 4.退货转寄售 5:新代卖转到场货（废弃） 6:超时转入',
  `second_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT 'second主键',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0:待审核、1:审核通过、2: 入库中、 3:售卖中 10:完结 -1:取消 -2:审核失败）',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后状态（0:无 1:退回审核 2:退回成功  3.取消审核）',
  `refuse_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退回价格',
  `refund_reason` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `refund_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退回图片',
  `freight` decimal(10, 2) UNSIGNED NOT NULL COMMENT '集货站运费',
  `freight_flag` tinyint NOT NULL DEFAULT 1 COMMENT '是否计算运费 1:计算 0：不计算',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商主键id',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商姓名',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '插入时间',
  `cancel_time` datetime NULL DEFAULT NULL COMMENT '取消时间',
  `rate_time` datetime NULL DEFAULT NULL COMMENT '定级完成时间',
  `zone_shelf` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架号',
  `sub_shelf_sn` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '质检人id',
  `user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '质检人姓名',
  `settle_flag` tinyint NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_orderid`(`agency_order_id` ASC) USING BTREE,
  INDEX `idx_roundNo`(`round_no` ASC) USING BTREE,
  INDEX `idx_supplierId_status_creatTime`(`supplier_id` ASC, `status` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18943 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寄售订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_order_sku_price_record
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_order_sku_price_record`;
CREATE TABLE `sale_agency_order_sku_price_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖计划单号',
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖订单号',
  `plan_item_id` bigint NOT NULL COMMENT '对应寄售计划详情主键',
  `sku_price` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '价格',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '插入时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_orderid`(`agency_order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 80 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寄售订单价格快照表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_permission
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_permission`;
CREATE TABLE `sale_agency_permission`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态（0:申请 1:通过 2:拒绝 3:取消权限）',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '驳回理由 限255字',
  `review_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核人id',
  `review_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `apply_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '申请时间',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `night_sale_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否参与晚场加单 0:不参与 1:参与',
  `operator_type` tinyint NOT NULL DEFAULT 0 COMMENT '操作来源 0:系统 1:平台 2:供应商端',
  `operator_id` bigint NOT NULL DEFAULT 1 COMMENT '操作人ID，系统为1',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '系统' COMMENT '操作人姓名',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '晚场状态最后更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_applytime`(`apply_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 561 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '代卖权限表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_plan
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_plan`;
CREATE TABLE `sale_agency_plan`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `round_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖计划单号',
  `agency_plan_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '（废弃）代卖发布场次',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `second_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级分类名称',
  `release_id` int NOT NULL COMMENT '发布人id',
  `release_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发布人名称',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '-1:已删除 0:创建 1:审核通过',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发布时间',
  `start_time` datetime NOT NULL COMMENT '计划开始时间',
  `end_time` datetime NOT NULL COMMENT '计划结束时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order`(`agency_plan_order` ASC) USING BTREE,
  INDEX `idx_roundno_secondid`(`round_no` ASC, `second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 161 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '代卖计划表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_plan_item
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_plan_item`;
CREATE TABLE `sale_agency_plan_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代卖计划单号',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类主键',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级分类名称',
  `rank_a` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '级别A是否包含 0不包含 1包含',
  `rank_b` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '级别B是否包含 0不包含 1包含',
  `rank_c` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '级别C是否包含 0不包含 1包含',
  `rank_d` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '级别D是否包含 0不包含 1包含',
  `rank_e` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '级别E是否包含 0不包含 1包含',
  `rank_o` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '级别O是否包含 0不包含 1包含',
  `sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '是否包含sku属性——{\"properties\":[\"中\",\"熟\"],\"skuName\":\"成熟度\"}',
  `num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '计划售卖数量',
  `float_ratio` int UNSIGNED NOT NULL DEFAULT 10 COMMENT '上浮数量',
  `limit_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '限制单个用户提交数量 0不限制',
  `submit_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '已提交数量',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '-1:删除 0:发布 1:审核通过 10:结束',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_status`(`agency_plan_order` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 554 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '代卖计划花材表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_plan_price
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_plan_price`;
CREATE TABLE `sale_agency_plan_price`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `second_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT 'second主键',
  `version` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新版本',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花材名称',
  `price_a` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'A级价格',
  `price_b` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'B级价格',
  `price_c` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'C级价格',
  `price_d` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'D级价格',
  `price_e` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'E级价格',
  `price_o` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'O级价格',
  `sku_price` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '价格',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_secondid`(`second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 63 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '代卖价目表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_receipt
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_receipt`;
CREATE TABLE `sale_agency_receipt`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 0-正常入库 1-无标签花材入库',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级123456->ABCDEO',
  `sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '数量 不大于10000',
  `purchase_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '收购价 元',
  `sell_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售卖价 元',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否入库 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 79 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '到场货入库单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_report_loss
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_report_loss`;
CREATE TABLE `sale_agency_report_loss`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代卖订单号',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'second表主键',
  `rank_num` int NOT NULL DEFAULT 0 COMMENT '花材级别',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花材名称',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '报损数量',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0:待审核 1:通过 2:驳回 -1取消',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '报损原因',
  `pic_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '报损图片',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '报损价格',
  `submit_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '提交人id',
  `submit_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '提交人姓名',
  `apply_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `apply_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核人id',
  `apply_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人姓名',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_orderid`(`agency_order_id` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 73 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报损申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_statistics
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_statistics`;
CREATE TABLE `sale_agency_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `date` date NULL DEFAULT NULL COMMENT '年月日',
  `warehouse_list` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '入库的id汇总',
  `out_of_warehouse_list` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '出库列表汇总',
  `ab_out_list` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '其他出库列表汇总',
  `loss_list` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '报损列表汇总',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 581 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_agency_stock
-- ----------------------------
DROP TABLE IF EXISTS `sale_agency_stock`;
CREATE TABLE `sale_agency_stock`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '计划单号',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类主键',
  `rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '寄售等级',
  `sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `in_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '库存入库（包含报损、其他出库和修改定级）',
  `out_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '出库数量',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常 1:完结',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ctime_status`(`create_time` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 189 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_inspection_item
-- ----------------------------
DROP TABLE IF EXISTS `sale_inspection_item`;
CREATE TABLE `sale_inspection_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `enter_item_id` bigint UNSIGNED NOT NULL COMMENT 'enter_item主键',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次',
  `code_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '扫码内容',
  `second_id` bigint UNSIGNED NOT NULL COMMENT 'second主键',
  `sale_detail_id` bigint UNSIGNED NOT NULL COMMENT 'saleItemDetial的主键',
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'agency_order_id',
  `sale_item_id` bigint UNSIGNED NOT NULL COMMENT 'saleItem的主键',
  `sort` int UNSIGNED NOT NULL COMMENT '第几把',
  `level` tinyint UNSIGNED NULL DEFAULT NULL,
  `product_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '质检人id',
  `user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `zone` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `zone_shelf` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `sub_shelf_sn` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `date_status` tinyint NULL DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_enterItemId`(`enter_item_id` ASC) USING BTREE,
  INDEX `idx_roundNo`(`round_no` ASC) USING BTREE,
  INDEX `idx_itemId`(`sale_item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 987 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质检退货转代卖花材' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_wms_in_order
-- ----------------------------
DROP TABLE IF EXISTS `sale_wms_in_order`;
CREATE TABLE `sale_wms_in_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `in_order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '入库单号(RK开头)',
  `in_type` tinyint NOT NULL DEFAULT 0 COMMENT '入库类型 1:采购入库 2:退货转代卖 3:超时转代卖 4:无标签入库 5:盘点入库 6:降级入库 7:场地退回入库',
  `round_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次',
  `relate_id` bigint NOT NULL DEFAULT 0 COMMENT '关联记录ID (降级/场地退回时对应出库单id)',
  `pre_in_num` int NOT NULL DEFAULT 0 COMMENT '预计入库总扎数',
  `actual_in_num` int NOT NULL DEFAULT 0 COMMENT '已实际入库扎数',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人ID',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0:未入库 1:部分入库(配货中) 2:已全部入库 -1:已取消',
  `print_status` tinyint NOT NULL DEFAULT 0 COMMENT '打印状态 0:未打印 1:已打印',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '入库完成时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sn`(`in_order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 100 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '到场货入库单表' ROW_FORMAT = Dynamic;

