  `total_sys_num` int NOT NULL DEFAULT 0 COMMENT '盘点开始时系统在库总扎数',
  `total_actual_num` int NOT NULL DEFAULT 0 COMMENT '实际扫描总扎数',
  `total_diff_num` int NOT NULL DEFAULT 0 COMMENT '总差异数',
