  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_check_sn`(`check_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库存盘点任务表' ROW_FORMAT = Dynamic;

