  `sale_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '销售供应商id',
  `wms_stock_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '关联库存汇总 (sku) ID',
