  `sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '出库时售卖单价',
  `distributer_id` bigint NOT NULL DEFAULT 0 COMMENT '入库人ID',
  `distributer_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '入库人姓名',
  `distribute_time` datetime NULL DEFAULT NULL COMMENT '配货(入库)时间',
  `packer_id` bigint NOT NULL DEFAULT 0 COMMENT '出库人ID',
  `packer_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '出库人姓名',
