-- ----------------------------
-- Table structure for sale_wms_out_order
-- ----------------------------
DROP TABLE IF EXISTS `sale_wms_out_order`;
CREATE TABLE `sale_wms_out_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `out_order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '出库单号(CK开头)',
  `out_type` tinyint NOT NULL DEFAULT 0 COMMENT '出库类型 1:销售出库 2:补货出库 3:报废出库 4:盘亏出库 5:降级出库 6:退货出库',
  `round_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次',
  `relate_order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '关联业务订单号(如补货申请单号或销售订单号)',
  `relate_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '关联记录ID',
  `total_apply_num` int NOT NULL DEFAULT 0 COMMENT '单据申请出库总扎数',
  `total_actual_num` int NOT NULL DEFAULT 0 COMMENT '实际扫码出库总扎数',
  `total_refund_num` int NOT NULL DEFAULT 0 COMMENT '整单累计退货扎数',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '最后操作人ID',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最后操作人姓名',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0:待出库 1:部分出库 2:已全部出库 -1:已取消',
  `review_status` tinyint NOT NULL DEFAULT 0 COMMENT '审核状态 0:未审核 1:审核通过 2:拒绝',
  `refund_status` tinyint NOT NULL DEFAULT 0 COMMENT '退货状态 0:无需退货 1:需要退货 2:已部分退货 3:已全部退货',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认完成(提货结束)时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_out_sn`(`out_order_sn` ASC) USING BTREE,
  INDEX `idx_relate_sn`(`relate_order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 573 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '到场货出库主表' ROW_FORMAT = Dynamic;

