  `refund_type` tinyint NOT NULL DEFAULT 1 COMMENT '退货类型 1:补货退回',
  `round_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次',
  `apply_user_id` bigint NOT NULL DEFAULT 0 COMMENT '申请人ID',
  `apply_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '申请人姓名',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '退货原因',
  `relate_pictures` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证据图片',
  `relate_video` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '证据视频',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0:待入库 1:部分入库 2:已全部入库 -1:已拒绝',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_return_sn`(`refund_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '到场货退货申请单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_wms_restock_account
-- ----------------------------
DROP TABLE IF EXISTS `sale_wms_restock_account`;
CREATE TABLE `sale_wms_restock_account`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint NOT NULL COMMENT '补货账号ID',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电话',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称',
  `area` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '区',
  `area_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '区code',
  `region` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '大区',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_purchase_id`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '补货账号信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_wms_restock_plan
-- ----------------------------
DROP TABLE IF EXISTS `sale_wms_restock_plan`;
CREATE TABLE `sale_wms_restock_plan`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `plan_sn` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划单号（RP开头）',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次',
  `serial_no` int NULL DEFAULT NULL COMMENT '场次内流水号，从1开始',
  `total_need_num` int NOT NULL DEFAULT 0 COMMENT '待补总量',
  `allocated_num` int NOT NULL DEFAULT 0 COMMENT '已分配补货总量',
  `prepare_num` int NULL DEFAULT 0 COMMENT '已配货扎数',
  `insufficient_variety_count` int NOT NULL DEFAULT 0 COMMENT '库存不足品种数',
  `insufficient_total_num` int NOT NULL DEFAULT 0 COMMENT '库存不足总扎数',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1=待出库, 2=配货中, 3=已完成',
  `print_flag` tinyint NOT NULL DEFAULT 0 COMMENT '打印标记 0=未打印, 1=已打印',
  `out_order_sn` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交后关联的出库单号',
  `restock_strategy` tinyint NOT NULL DEFAULT 1 COMMENT '补货策略 1=手动调级, 2=后台提1级, 3=后台提1/2级',
  `submitter_id` bigint NULL DEFAULT NULL COMMENT '提交人ID',
  `submitter_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_plan_sn`(`plan_sn` ASC) USING BTREE,
  INDEX `idx_out_order_sn`(`out_order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 413 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '补货计划主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_wms_restock_plan_item
-- ----------------------------
DROP TABLE IF EXISTS `sale_wms_restock_plan_item`;
CREATE TABLE `sale_wms_restock_plan_item`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `plan_id` bigint NULL DEFAULT NULL COMMENT '归属plan ID（提交前为null）',
  `parent_id` bigint NULL DEFAULT NULL COMMENT '拆分来源 item ID',
  `restock_type` tinyint(1) NULL DEFAULT NULL COMMENT '补货类型: 1=仅缺货补货, 2=仅退货补货, 3=两者皆有',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区-货架',
  `enter_item_id` bigint NOT NULL COMMENT '入场花材ID',
  `order_item_id` bigint NULL DEFAULT NULL COMMENT '客户订单商品ID',
  `order_sn` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户订单号',
  `summary_id` bigint NULL DEFAULT NULL COMMENT '关联 summary ID（提交时回填）',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '货架号，流水号',
  `second_id` bigint NULL DEFAULT NULL COMMENT '二级分类',
  `product_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `need_rank_num` int NULL DEFAULT NULL COMMENT '需补等级',
  `need_sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '需补规格',
  `need_num` int NOT NULL DEFAULT 0 COMMENT '需补扎数',
  `prepare_num` int NULL DEFAULT 0 COMMENT '已配货扎数',
  `allocated_0_num` int NOT NULL DEFAULT 0 COMMENT '同级分配扎数',
  `allocated_0_product_id` bigint NULL DEFAULT NULL COMMENT '同级到场货商品ID',
  `out_order_item_id_0` bigint NULL DEFAULT NULL COMMENT '同级关联出库明细ID',
  `allocated_1_num` int NOT NULL DEFAULT 0 COMMENT '提1级分配扎数',
  `allocated_1_product_id` bigint NULL DEFAULT NULL COMMENT '提1级到场货商品ID',
  `out_order_item_id_1` bigint NULL DEFAULT NULL COMMENT '提1级关联出库明细ID',
  `allocated_2_num` int NOT NULL DEFAULT 0 COMMENT '提2级分配扎数',
  `allocated_2_product_id` bigint NULL DEFAULT NULL COMMENT '提2级到场货商品ID',
  `out_order_item_id_2` bigint NULL DEFAULT NULL COMMENT '提2级关联出库明细ID',
  `status` tinyint NULL DEFAULT 0 COMMENT '0=待提交,1=已设置补货策略,2=已提交待出库,3=部分出库,4=已完成',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  `allocated_downgrade_num` int NOT NULL DEFAULT 0 COMMENT '降一级补货分配扎数',
  `allocated_downgrade_product_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '降一级补货的到场货商品ID（xm_bulky_product.id）',
  `out_order_item_id_downgrade` bigint UNSIGNED NULL DEFAULT NULL COMMENT '降一级补货关联出库明细ID（sale_wms_out_order_item.id）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_plan_id`(`plan_id` ASC) USING BTREE,
  INDEX `idx_enter_item_id`(`enter_item_id` ASC) USING BTREE,
  INDEX `idx_plan_second_rank`(`plan_id` ASC, `second_id` ASC, `need_rank_num` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 350 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '补货计划明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_wms_restock_plan_summary
-- ----------------------------
DROP TABLE IF EXISTS `sale_wms_restock_plan_summary`;
CREATE TABLE `sale_wms_restock_plan_summary`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场次',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区',
  `second_id` bigint NULL DEFAULT NULL COMMENT '二级分类',
  `need_rank_num` int NULL DEFAULT NULL COMMENT '需补等级',
  `need_sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '需补规格',
  `product_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `need_num` int NULL DEFAULT NULL COMMENT '该类花材汇总扎数',
  `plan_id` bigint NULL DEFAULT NULL COMMENT '关联 plan ID（提交前 null，提交后回填）',
  `status` tinyint NULL DEFAULT 0 COMMENT '0=待提交,1=已设置补货策略,2=已提交待出库,3=部分出库,4=已完成',
  `prepare_num` int NULL DEFAULT 0 COMMENT '已配货扎数',
  `source_supply_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '品类来源供货价（提交时快照）',
  `price_gap_too_high` tinyint NULL DEFAULT 0 COMMENT '提交时该品类是否存在补货价格差价过高 0=否 1=是',
  `allocated_0_num` int NULL DEFAULT NULL COMMENT '同级分配扎数',
  `allocated_0_product_id` bigint NULL DEFAULT NULL COMMENT '同级到场货商品ID',
  `allocated_0_supply_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '提交时同级到场货商品供货价',
  `out_order_item_id_0` bigint NULL DEFAULT NULL COMMENT '同级关联出库明细ID',
  `allocated_1_num` int NULL DEFAULT NULL COMMENT '提1级分配扎数',
  `allocated_1_product_id` bigint NULL DEFAULT NULL COMMENT '提1级到场货商品ID',
  `allocated_1_supply_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '提交时提1级到场货商品供货价',
  `out_order_item_id_1` bigint NULL DEFAULT NULL COMMENT '提1级关联出库明细ID',
  `allocated_2_num` int NULL DEFAULT NULL COMMENT '提2级分配扎数',
  `allocated_2_product_id` bigint NULL DEFAULT NULL COMMENT '提2级到场货商品ID',
  `allocated_2_supply_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '提交时提2级到场货商品供货价',
  `out_order_item_id_2` bigint NULL DEFAULT NULL COMMENT '提2级关联出库明细ID',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人姓名',
  `data_status` int NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `allocated_downgrade_num` int NOT NULL DEFAULT 0 COMMENT '降一级补货分配扎数',
  `allocated_downgrade_product_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '降一级补货的到场货商品ID（xm_bulky_product.id）',
  `allocated_downgrade_supply_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '提交时降一级补货商品的供货单价快照（元/扎）',
  `out_order_item_id_downgrade` bigint UNSIGNED NULL DEFAULT NULL COMMENT '降一级补货关联出库明细ID（sale_wms_out_order_item.id）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_round_no`(`round_no` ASC) USING BTREE,
  INDEX `idx_zone`(`zone` ASC) USING BTREE,
  INDEX `idx_plan_id`(`plan_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 590 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '补货计划花材汇总表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_wms_restock_plan_zone
-- ----------------------------
DROP TABLE IF EXISTS `sale_wms_restock_plan_zone`;
CREATE TABLE `sale_wms_restock_plan_zone`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `plan_id` bigint NULL DEFAULT NULL COMMENT '归属 plan ID',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区',
  `data_status` int NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_plan_id`(`plan_id` ASC) USING BTREE,
  INDEX `idx_zone`(`zone` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 502 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '补货计划-区关联中间表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_wms_restock_relation
-- ----------------------------
DROP TABLE IF EXISTS `sale_wms_restock_relation`;
CREATE TABLE `sale_wms_restock_relation`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `sub_account_id` bigint NOT NULL COMMENT '质检账号ID',
  `purchaser_id` bigint NOT NULL COMMENT '补货账号ID',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sub_account_id`(`sub_account_id` ASC) USING BTREE,
  INDEX `idx_purchase_id`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质检账号与补货账号绑定关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sale_wms_stock
-- ----------------------------
DROP TABLE IF EXISTS `sale_wms_stock`;
CREATE TABLE `sale_wms_stock`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `second_id` bigint NOT NULL DEFAULT 0 COMMENT '二级分类ID',
  `product_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花材名称',
  `rank_num` int NOT NULL DEFAULT 0 COMMENT '等级',
  `sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格配置',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '关联商品 xm_bulky_product.id',
  `sale_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '销售供应商id',
  `total_num` int NOT NULL DEFAULT 0 COMMENT '实物总库存',
  `current_avg_cost` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平均成本（废弃）',
  `total_cost_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '当前总库存成本',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人ID',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `uk_sku`(`second_id` ASC, `rank_num` ASC, `sale_supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 154 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '到场货库存汇总表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for search_rank_result
-- ----------------------------
DROP TABLE IF EXISTS `search_rank_result`;
CREATE TABLE `search_rank_result`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `app_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appid',
  `type` tinyint NOT NULL DEFAULT 0 COMMENT '类型：0-鲜花 1-供应商',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '搜索内容',
  `rank_num` int NOT NULL DEFAULT 0 COMMENT '排名',
  `search_num` bigint NOT NULL DEFAULT 0 COMMENT '搜索量',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_roundNo_appId`(`round_no` ASC, `app_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 961 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '鲜花与店铺每日搜索榜单结果表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for second_average_price
-- ----------------------------
DROP TABLE IF EXISTS `second_average_price`;
CREATE TABLE `second_average_price`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次\"yyyy-mm-dd\"',
  `second_id` bigint NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `average_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '场次均价',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_secondId_data`(`round_no` ASC, `second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13798 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '二级分类均价表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for second_rank_result
-- ----------------------------
DROP TABLE IF EXISTS `second_rank_result`;
CREATE TABLE `second_rank_result`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `type` tinyint NOT NULL DEFAULT 0 COMMENT '榜单类型：1-热销榜，2-增速榜，3-新品榜',
  `product_id` bigint NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `rank_num` int NOT NULL DEFAULT 0 COMMENT '排名',
  `sale_num` bigint NOT NULL DEFAULT 0 COMMENT '销量',
  `growth_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '增速',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_date_type`(`round_no` ASC, `type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5552 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '每日榜单结果表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for spec_config
-- ----------------------------
DROP TABLE IF EXISTS `spec_config`;
CREATE TABLE `spec_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '规格配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for statistics_category_data
-- ----------------------------
DROP TABLE IF EXISTS `statistics_category_data`;
CREATE TABLE `statistics_category_data`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级分类id',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '扎数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_roundno_ranknum_secondid`(`round_no` ASC, `rank_num` ASC, `second_id` ASC) USING BTREE,
  INDEX `idx_roundno_firstid`(`round_no` ASC, `first_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 697 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分类销量统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for statistics_city_data
-- ----------------------------
DROP TABLE IF EXISTS `statistics_city_data`;
CREATE TABLE `statistics_city_data`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `province` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '扎数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_roundno_city`(`round_no` ASC, `city` ASC) USING BTREE,
  INDEX `idx_roundno_province`(`round_no` ASC, `province` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1452 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市销量统计表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for statistics_express_data
-- ----------------------------
DROP TABLE IF EXISTS `statistics_express_data`;
CREATE TABLE `statistics_express_data`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `config_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流id',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '扎数',
  `express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '预收运费',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_roundno_configid`(`round_no` ASC, `config_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 528 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for statistics_supplier_data
-- ----------------------------
DROP TABLE IF EXISTS `statistics_supplier_data`;
CREATE TABLE `statistics_supplier_data`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '扎数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_roundno_sid`(`round_no` ASC, `supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2671 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商销量统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for subsidy_price_city_toggle
-- ----------------------------
DROP TABLE IF EXISTS `subsidy_price_city_toggle`;
CREATE TABLE `subsidy_price_city_toggle`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `city_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市名称，例：昆明市',
  `show_subsidy` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否展示补贴价：1=展示，0=不展示',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_city_name`(`city_name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '按城市开关控制补贴价是否展示' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for subsidy_strategy
-- ----------------------------
DROP TABLE IF EXISTS `subsidy_strategy`;
CREATE TABLE `subsidy_strategy`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `strategy_tag` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '补贴策略tag',
  `strategy_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '策略名称',
  `subsidy_ratio` decimal(10, 4) UNSIGNED NOT NULL DEFAULT 1.0000 COMMENT '补贴比例',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tag`(`strategy_tag` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '补贴策略表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_account_change_type
-- ----------------------------
DROP TABLE IF EXISTS `supplier_account_change_type`;
CREATE TABLE `supplier_account_change_type`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '类型名称',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_type`(`type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 82 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商余额变动类型表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_agency_downgrade
-- ----------------------------
DROP TABLE IF EXISTS `supplier_agency_downgrade`;
CREATE TABLE `supplier_agency_downgrade`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `pic_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `item_list` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花材列表',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人',
  `operator_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作人姓名',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0:正常 -100 删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_agencyOrderId`(`agency_order_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_agency_item
-- ----------------------------
DROP TABLE IF EXISTS `supplier_agency_item`;
CREATE TABLE `supplier_agency_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖计划单号',
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖订单号',
  `plan_item_id` bigint NOT NULL DEFAULT 0 COMMENT '对应寄售计划详情主键',
  `round_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类主键',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花材名称',
  `sale_num` int UNSIGNED NOT NULL COMMENT '寄售数量',
  `sale_rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '寄售级别',
  `sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '寄售价格（单个花材)',
  `sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配置',
  `transfer_stock_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原库存转入数量',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'product表主键',
  `stock_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '库存数量',
  `warehouse_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '入库数量',
  `outbound_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '出库数量',
  `refund_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '退回数量',
  `loss_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '报损数量',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供货商id',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供货商姓名',
  `detail_status` int NOT NULL DEFAULT 0 COMMENT 'detail表同步状态 0.未同步 1.同步',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order`(`agency_order_id` ASC) USING BTREE,
  INDEX `idx_plan_second`(`agency_plan_order` ASC, `second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 158 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '代卖花材表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_agency_item_detail
-- ----------------------------
DROP TABLE IF EXISTS `supplier_agency_item_detail`;
CREATE TABLE `supplier_agency_item_detail`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `second_id` bigint NOT NULL DEFAULT 0 COMMENT '花材主键',
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖计划号',
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖订单号',
  `agency_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '对应代卖花材主键',
  `sort` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '第几把',
  `origin_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '初始定价',
  `origin_rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '初始级别',
  `origin_sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '初始sku_config',
  `onsale_rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售卖等级',
  `onsale_sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '售卖sku_config',
  `sale_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '最终售卖价格',
  `status` int NOT NULL DEFAULT 0 COMMENT '状态 0:待定级定价、1:待入库、2:售卖中 3:已售卖、10:完成、-1:报损、-2:退回 -3缺货',
  `apply_status` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核状态（0:无状态 1:报损待审核）',
  `report_loss_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'report_loss主键',
  `compensation_per` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '赔付比例0-100',
  `rate_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '定级人',
  `rate_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '定级人姓名',
  `inbound_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '入库人',
  `inbound_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '入库人姓名',
  `inbound_time` datetime NULL DEFAULT NULL COMMENT '入库时间',
  `outbound_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '出库人',
  `outbound_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '出库人姓名',
  `outbound_time` datetime NULL DEFAULT NULL COMMENT '出库时间',
  `outbound_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '出库类型（0:未出库 1:正常出库 2:其他场景出库）',
  `draw_ratio` decimal(3, 3) NOT NULL DEFAULT 0.000 COMMENT '抽点比例',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '出库场次编号：yyyy-MM-dd',
  `shelf_sn` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '出库货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '出库子货架号',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  `enter_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'enter_item主键id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号',
  `code_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配对对应二维码',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供货商id',
  `sale_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 10003 COMMENT '售卖供应商ID',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供货商姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_orderid`(`agency_order_id` ASC) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 270 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '花材明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_agency_item_detail_log
-- ----------------------------
DROP TABLE IF EXISTS `supplier_agency_item_detail_log`;
CREATE TABLE `supplier_agency_item_detail_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `item_detail_id` bigint NOT NULL COMMENT '花材明细id',
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖计划号',
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖订单号',
  `op_type` int NOT NULL COMMENT '1:定级定价 2:出库 3、退回 4、报损 5、更改定级 6、入库 7报损申请、取消或拒绝',
  `old_rank` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '老级别',
  `new_rank` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '新级别',
  `detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '详细信息',
  `pic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片或视频',
  `operate_id` bigint NOT NULL COMMENT '操作人',
  `operate_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_detailid_optype`(`item_detail_id` ASC, `op_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 140 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '花材变更记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_agency_order
-- ----------------------------
DROP TABLE IF EXISTS `supplier_agency_order`;
CREATE TABLE `supplier_agency_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖计划单号',
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖订单号',
  `plan_item_id` bigint NOT NULL COMMENT '对应寄售计划详情主键',
  `round_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次',
  `type` tinyint NOT NULL DEFAULT 0 COMMENT '1.自主寄售 2.转入寄售',
  `second_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT 'second主键',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0:待审核、1:审核通过、2: 入库中、 3:售卖中 10:完结 -1:取消 -2:审核失败）',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后状态（0:无 1:退回审核 2:退回成功  3.取消审核）',
  `refuse_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退回价格',
  `refund_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退回理由',
  `refund_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退回图片',
  `freight` decimal(10, 2) UNSIGNED NOT NULL COMMENT '集货站运费',
  `freight_flag` tinyint NOT NULL DEFAULT 1 COMMENT '是否计算运费 1:计算 0：不计算',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商主键id',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商姓名',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '插入时间',
  `cancel_time` datetime NULL DEFAULT NULL COMMENT '取消时间',
  `rate_time` datetime NULL DEFAULT NULL COMMENT '定级完成时间',
  `zone_shelf` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架号',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '质检人id',
  `user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '质检人姓名',
  `settle_flag` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '结算状态 0:未结算 1:已结算',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_orderid`(`agency_order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 158 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寄售订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_agency_permission
-- ----------------------------
DROP TABLE IF EXISTS `supplier_agency_permission`;
CREATE TABLE `supplier_agency_permission`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态（0:申请 1:通过 2:拒绝 3:取消权限）',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '驳回理由 限255字',
  `review_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核人id',
  `review_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `apply_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '申请时间',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_applytime`(`apply_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '代卖权限表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_agency_plan
-- ----------------------------
DROP TABLE IF EXISTS `supplier_agency_plan`;
CREATE TABLE `supplier_agency_plan`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `round_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代卖计划单号',
  `agency_plan_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '（废弃）代卖发布场次',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `second_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级分类名称',
  `release_id` int NOT NULL COMMENT '发布人id',
  `release_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发布人名称',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '-1:已删除 0:创建 1:审核通过',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发布时间',
  `start_time` datetime NOT NULL COMMENT '计划开始时间',
  `end_time` datetime NOT NULL COMMENT '计划结束时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order`(`agency_plan_order` ASC) USING BTREE,
  INDEX `idx_roundno_secondid`(`round_no` ASC, `second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '代卖计划表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_agency_plan_item
-- ----------------------------
DROP TABLE IF EXISTS `supplier_agency_plan_item`;
CREATE TABLE `supplier_agency_plan_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代卖计划单号',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类主键',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级分类名称',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '是否包含sku属性——{\"properties\":[\"中\",\"熟\"],\"skuName\":\"成熟度\"}',
  `num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '计划售卖数量',
  `float_ratio` int UNSIGNED NOT NULL DEFAULT 10 COMMENT '上浮数量',
  `limit_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '限制单个用户提交数量 0不限制',
  `submit_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '已提交数量',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '-1:删除 0:发布 1:审核通过 10:结束',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_status`(`agency_plan_order` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 58 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '代卖计划花材表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_agency_report_loss
-- ----------------------------
DROP TABLE IF EXISTS `supplier_agency_report_loss`;
CREATE TABLE `supplier_agency_report_loss`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `agency_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代卖订单号',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'second表主键',
  `rank_num` int NOT NULL DEFAULT 0 COMMENT '花材级别',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花材名称',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '报损数量',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0:待审核 1:通过 2:驳回 -1取消',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '报损原因',
  `pic_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '报损图片',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '报损价格',
  `submit_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '提交人id',
  `submit_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '提交人姓名',
  `apply_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `apply_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核人id',
  `apply_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人姓名',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_orderid`(`agency_order_id` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报损申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_agency_statistics
-- ----------------------------
DROP TABLE IF EXISTS `supplier_agency_statistics`;
CREATE TABLE `supplier_agency_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `date` date NULL DEFAULT NULL COMMENT '年月日',
  `warehouse_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '入库的id汇总',
  `out_of_warehouse_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '出库列表汇总',
  `ab_out_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '其他出库列表汇总',
  `loss_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '报损列表汇总',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_agency_stock
-- ----------------------------
DROP TABLE IF EXISTS `supplier_agency_stock`;
CREATE TABLE `supplier_agency_stock`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `agency_plan_order` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '计划单号',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类主键',
  `rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '寄售等级',
  `sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `in_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '库存入库（包含报损、其他出库和修改定级）',
  `out_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '出库数量',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常 1:完结',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ctime_status`(`create_time` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_match_replace_apply
-- ----------------------------
DROP TABLE IF EXISTS `supplier_match_replace_apply`;
CREATE TABLE `supplier_match_replace_apply`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `start_round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开始场次',
  `end_round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '结束场次',
  `supplier_id` bigint NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 1:审核通过 2.已完成 3:已删除',
  `day_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '白场代卖',
  `night_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '晚场代卖',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_supplierid`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_start_end_status_dataStatus_supplierId`(`start_round_no` ASC, `end_round_no` ASC, `supplier_id` ASC, `status` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 88 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商代配申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_match_replace_black
-- ----------------------------
DROP TABLE IF EXISTS `supplier_match_replace_black`;
CREATE TABLE `supplier_match_replace_black`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注 限255字',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_supplierid`(`supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商代配黑名单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_match_replace_detail
-- ----------------------------
DROP TABLE IF EXISTS `supplier_match_replace_detail`;
CREATE TABLE `supplier_match_replace_detail`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `o_id` bigint NOT NULL DEFAULT 0 COMMENT '代配申请ID',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代配场次',
  `supplier_id` bigint NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '代配扎数',
  `single_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '配货单价',
  `total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '配货总价',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '配货状态 1.代配中 2.代配完成',
  `day_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '白场代卖',
  `night_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '晚场代卖',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_oid`(`o_id` ASC) USING BTREE,
  INDEX `idx_roundno_supplierid_status`(`round_no` ASC, `supplier_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 103 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商代配详情表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for supplier_rank_result
-- ----------------------------
DROP TABLE IF EXISTS `supplier_rank_result`;
CREATE TABLE `supplier_rank_result`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint NOT NULL DEFAULT 0 COMMENT '供应商id',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `type` tinyint NOT NULL DEFAULT 0 COMMENT '榜单类型：0-热卖榜 1-好评回购榜',
  `first_type` tinyint NOT NULL DEFAULT 0 COMMENT '一级分类类型：0-总榜 1-单头玫瑰 2-多头玫瑰 3-紫罗兰 4-洋桔梗 5-康乃馨 6-配花 7-配叶',
  `first_id` bigint NOT NULL DEFAULT 0 COMMENT '一级分类id',
  `rank_num` tinyint NOT NULL DEFAULT 0 COMMENT '排名',
  `sale_num` bigint NOT NULL DEFAULT 0 COMMENT '销量',
  `repurchase_num` bigint NOT NULL DEFAULT 0 COMMENT '回购数',
  `comment_num` bigint NOT NULL DEFAULT 0 COMMENT '好评数',
  `repurchase_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '好评回购率',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_rounNo_supId`(`round_no` ASC, `supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6127 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '店铺每日一级分类销量榜' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sys_popup_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_popup_config`;
CREATE TABLE `sys_popup_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '弹窗名称，限20字',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '弹窗类型：1-独立弹窗, 2-复合弹窗',
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片url',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序值 升序',
  `show_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否展示 0-否 1-是',
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `pop_scene` tinyint NOT NULL DEFAULT 0 COMMENT '领券场景：0-邮箱领券 1-会员领券 2-配图无领券',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场景描述',
  `show_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '展示类型 0-始终展示 1-每日一次',
  `style_type` tinyint NOT NULL DEFAULT 2 COMMENT '展示方式 0-默认样式 1-会员样式 2-配图',
  `start_time` datetime NULL DEFAULT NULL COMMENT '展示开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '展示结束时间',
  `interaction_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '弹窗交互类型 1-关闭弹窗 2-领取优惠券 3-跳转小程序链接',
  `jump_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '跳转地址 仅弹窗交互为3时使用',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_appid`(`app_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 53 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '弹窗配置表' ROW_FORMAT = Dynamic;

