-- ----------------------------
-- Table structure for tl_transfer
-- ----------------------------
DROP TABLE IF EXISTS `tl_transfer`;
CREATE TABLE `tl_transfer`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `record_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '提现编码（唯一）',
  `out_biz_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户订单号',
  `account_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'tl_account表主键id',
  `biz_user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收款会员编码',
  `tl_user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收款通联会员id',
  `owner_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收款人姓名',
  `payee_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '对公对私标志 0-对公 1-个人',
  `config_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流id',
  `apply_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请金额（元）',
  `apply_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '申请状态 0-申请中 1-同意 2-拒绝',
  `withdraw_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '打款状态 0-未打款 1-打款中 2-打款成功 3-打款失败',
  `pic_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图片列表，限512字',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '原因，限255字',
  `ip` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'ip',
  `check_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `check_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核用户id',
  `check_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核用户名称',
  `success_time` datetime NULL DEFAULT NULL COMMENT '打款成功时间',
  `transfer_resp` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '提交打款接口返回结果',
  `query_transfer_resp` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '查询打款接口返回结果',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_code`(`record_code` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '通联打款表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tmp_activity_region
-- ----------------------------
DROP TABLE IF EXISTS `tmp_activity_region`;
CREATE TABLE `tmp_activity_region`  (
  `region_id` bigint UNSIGNED NOT NULL COMMENT '物流区域表主键id',
  `price_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '活动阶梯费用json数组，最多5组 如：[{\"price\":5}]',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`region_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '活动物流区域表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for topics
-- ----------------------------
DROP TABLE IF EXISTS `topics`;
CREATE TABLE `topics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '话题发起人ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '话题标题',
  `header_image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '头图URL',
  `cover_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '封面图片URL',
  `show_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否展示 0-否 1-是 默认1',
  `recommend_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推荐, 0-否 1-是',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序值',
  `views` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '浏览数',
  `comments` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '评论数',
  `likes` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '点赞数',
  `followers` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '关注数',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除 ',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_title`(`title` ASC) USING BTREE,
  INDEX `idx_userid`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '话题表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for topics_comment
-- ----------------------------
DROP TABLE IF EXISTS `topics_comment`;
CREATE TABLE `topics_comment`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
