  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_followid_topicid`(`follow_id` ASC, `topic_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 72 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '话题关注表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for topics_like
-- ----------------------------
DROP TABLE IF EXISTS `topics_like`;
CREATE TABLE `topics_like`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
