  PRIMARY KEY (`id`) USING BTREE,
  INDEX `uk_likeid_topicid`(`like_id` ASC, `topic_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '话题点赞表' ROW_FORMAT = DYNAMIC;

