-- ----------------------------
-- Table structure for user_comment
-- ----------------------------
DROP TABLE IF EXISTS `user_comment`;
CREATE TABLE `user_comment`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '评论ID',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '评论者用户ID',
  `target_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '评论对象ID',
  `parent_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '回复的父评论ID (0代表评论话题)',
  `root_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '祖先ID',
  `target_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '评论对象类型, 默认0, 0-未知, 1-图库图片, 2-资讯, 3-评论 ',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '评论内容',
  `like_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '评论被点赞数',
  `version` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '乐观锁版本号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  `target_deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '目标是否被删除 (0:正常; 1:删除)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_parent_id`(`parent_id` ASC) USING BTREE,
  INDEX `idx_rootid`(`root_id` ASC) USING BTREE,
  INDEX `idx_target_type_id_deleted`(`target_type` ASC, `target_id` ASC, `target_deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 117 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户评论表' ROW_FORMAT = Dynamic;

