  `save_amount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '优惠券节省金额',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_userId`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 33 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户优惠券节省金额表' ROW_FORMAT = Dynamic;

