) ENGINE = InnoDB AUTO_INCREMENT = 44 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户收藏作品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for user_view
