-- ----------------------------
-- Table structure for wms_after_sale_punish_review
-- ----------------------------
DROP TABLE IF EXISTS `wms_after_sale_punish_review`;
CREATE TABLE `wms_after_sale_punish_review`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `refund_id` bigint UNSIGNED NOT NULL COMMENT '售后退款ID，关联xm_bulky_refund.id',
  `order_item_id` bigint UNSIGNED NOT NULL COMMENT '订单商品ID，关联xm_bulky_order_item.id',
  `wms_punish_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '审核同意后生成的仓库处罚ID',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `duty_type` tinyint UNSIGNED NOT NULL COMMENT '售后责任类型，当前1-质检 3-配货 4-打包',
  `after_sale_handle_time` datetime NOT NULL COMMENT '售后处理时间',
  `round_no` date NOT NULL COMMENT '场次',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区-货架',
  `area_manager_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分区负责人ID',
  `area_manager_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区负责人姓名',
  `channel` tinyint UNSIGNED NOT NULL COMMENT '真实渠道 1-大件批发 2-优花速达 3-繁花惠 4-分销商 5-城市仓',
  `channel_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '渠道名称快照',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓ID快照',
  `ware_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市仓名称快照',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商ID快照',
  `partner_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分销商名称快照',
  `area_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '客服分区ID，关联customer_area_type.id，0-未设置',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省份快照',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市快照',
  `platform_bear_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '本次退款平台承担金额快照，允许为负',
  `duty_user_id` bigint UNSIGNED NOT NULL COMMENT '当前责任人ID',
  `duty_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '当前责任人姓名',
  `duty_user_role` int UNSIGNED NOT NULL COMMENT '当前责任人角色ID',
  `punish_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '当前预处罚金额，允许为负；创建正式处罚时必须大于0',
  `punish_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '当前处罚备注',
  `pic_url` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '售后原始图片和视频URL',
  `punish_pic_url` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '仓库处罚佐证图片和视频URL，默认取售后素材',
  `review_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核状态 0-待审核 1-同意处罚 2-无需处罚',
  `review_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核人ID',
  `review_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人姓名',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0-正常 -100-删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_refund_duty`(`refund_id` ASC, `duty_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 56 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '售后仓库预处罚审核表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_after_sale_punish_review_log
-- ----------------------------
DROP TABLE IF EXISTS `wms_after_sale_punish_review_log`;
CREATE TABLE `wms_after_sale_punish_review_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `review_id` bigint UNSIGNED NOT NULL COMMENT '售后预处罚审核ID',
  `action_content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '处理记录展示文案',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当前责任人和处罚金额JSON快照',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人ID',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '处理时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_review_time`(`review_id` ASC, `create_time` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 111 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '售后预处罚处理记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_check_item_log
-- ----------------------------
DROP TABLE IF EXISTS `wms_check_item_log`;
CREATE TABLE `wms_check_item_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `code_content` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `date` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `zone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `shelf` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `order_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'order_item表主键id',
  `enter_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'enter_item表主键id',
  `plan_item_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '关联补货明细ID(sale_wms_restock_plan_item.id)',
  `restock_seq_no` int NOT NULL DEFAULT 0 COMMENT '补货单内流水号，从1开始',
  `need_rank_num` int NOT NULL DEFAULT 0 COMMENT '需求补货等级',
  `allocated_rank_num` int NOT NULL DEFAULT 0 COMMENT '分配等级',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `restock_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补货的供应商id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名称',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '手机号',
  `op` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作 1：降1级 2：降2级 3：退货 4:缺货 5：退货补货 7:缺货不补 8：退货不补转代卖 9退货补货转代卖',
  `sub_op` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作 4:缺货补货 7:缺货不补 的补充说明，是否处罚 0：处罚 1：不处罚 操作3、5退货时是否是冷库花 0：不是 1：是',
  `cold_flag` tinyint NOT NULL DEFAULT 0 COMMENT '退货类操作(op=3/5/8/9)是否为冷库花 0-否 1-是',
  `op_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认 0 扫码枪 1：人工',
  `confirm_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否二次确认 0未确认 1确认',
  `re_qualify_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '复检员id',
  `re_qualify_user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '复检员名称',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `pictures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `video` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `allow_downgrade_restock` tinyint NOT NULL DEFAULT 0 COMMENT '该扎是否允许降一级补货：0不允许，1允许',
  `restock_prepared` tinyint NOT NULL DEFAULT 0 COMMENT '该扎降一级补货有效配货状态：0未配货或已撤销，1已配货，用于累计赔付',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_code_content`(`code_content` ASC) USING BTREE COMMENT '二维码内容',
  INDEX `idx_oid`(`order_item_id` ASC) USING BTREE COMMENT 'orderItemId',
  INDEX `idx_data_op_supplier`(`date` ASC, `op` ASC, `supplier_id` ASC) USING BTREE,
  INDEX `idx_eid`(`enter_item_id` ASC) USING BTREE,
  INDEX `idx_enter_item_id`(`enter_item_id` ASC) USING BTREE,
  INDEX `idx_plan_item_id`(`plan_item_id` ASC) USING BTREE,
  INDEX `idx_data_user_op`(`date` ASC, `op` ASC, `user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14234 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质检日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_entry_inventory
-- ----------------------------
DROP TABLE IF EXISTS `wms_entry_inventory`;
CREATE TABLE `wms_entry_inventory`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `part` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区：0-总仓',
  `team_id` int NOT NULL DEFAULT 0 COMMENT '库存归属团队，0-总仓',
  `team_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '团队名称快照',
  `sku_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'sku类型：1-生产耗材 2-农资商品 3-设备资产 4-租赁资产',
  `sku_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物资 SKU ID',
  `sku_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku名称',
  `specification` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格型号',
  `brand` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '品牌',
  `invoice_info` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发票/收据信息',
  `reason_type` tinyint NOT NULL DEFAULT 0 COMMENT '入库原因：0-初始入库 1-借入 2-其他',
  `source_apply_id` bigint NULL DEFAULT NULL COMMENT '来源物资申领单ID，非空表示由申领审批发放产生',
  `purchase_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '采购原因',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `in_inventory` int NOT NULL DEFAULT 0 COMMENT '入库数量',
  `remain_inventory` int NOT NULL DEFAULT 0 COMMENT '当前剩余可用数量',
  `unit_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '个' COMMENT '入库单位名称',
  `device_number` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '设备编号 (针对设备资产)',
  `lease_subject` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '承租主体 (针对租赁资产)',
  `lessor` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '出租人 (针对租赁资产)',
  `contract_info` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '合同信息',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作入库的用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作入库的用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_skuid_remaining`(`sku_id` ASC, `remain_inventory` ASC) USING BTREE,
  INDEX `idx_sku_team_remain`(`sku_id` ASC, `team_id` ASC, `remain_inventory` ASC) USING BTREE,
  INDEX `idx_team_status_sku`(`team_id` ASC, `data_status` ASC, `sku_id` ASC) USING BTREE,
  INDEX `idx_source_apply`(`source_apply_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 254 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'WMS 入库单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_entry_inventory_trace
-- ----------------------------
DROP TABLE IF EXISTS `wms_entry_inventory_trace`;
CREATE TABLE `wms_entry_inventory_trace`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `part` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区：0-总仓',
  `team_id` int NULL DEFAULT NULL COMMENT '库存归属团队，0-总仓，失败未归属可为空',
  `team_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '团队名称快照',
  `sku_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'sku类型：1-生产耗材 2-农资商品 3-设备资产 4-租赁资产',
  `sku_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物资 SKU ID',
  `sku_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku名称',
  `specification` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格型号',
  `brand` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '品牌',
  `trace_class` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '业务类型 1-入库 2-出库',
  `trace_sub_class` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '业务子类型：10-预出库 20-正式出库 30-修改入库 40-出库回滚 50-借调入库 60-借调出库',
  `quantity_change` int NOT NULL DEFAULT 0 COMMENT '数量变化 (+为增, -为减)',
  `unit_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '个' COMMENT '库存单位名称',
  `recipient` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '领用人',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注，限255字',
  `invoice_info` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发票/收据信息',
  `reason_type` tinyint NOT NULL DEFAULT 0 COMMENT '入库原因：0-初始入库 1-借入 2-其他',
  `outbound_reason` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '出库原因：0-正常出库 1-报损 2-其他 3-跨区域借调 4-修改箱子',
  `outbound_failed` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '出库是否失败：0-正常 1-失败',
  `failure_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '失败原因',
  `purchase_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '采购原因',
  `device_number` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '设备编号 (针对设备资产)',
  `lease_subject` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '承租主体 (针对租赁资产)',
  `lessor` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '出租人 (针对租赁资产)',
  `contract_info` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '合同信息',
  `shelf` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架号',
  `related_order` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '关联订单',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_class_sku`(`trace_class` ASC, `sku_id` ASC) USING BTREE,
  INDEX `idx_team_failed_time`(`team_id` ASC, `outbound_failed` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_sku_team_time`(`sku_id` ASC, `team_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 514 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'wms库存流水表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_inventory_check
-- ----------------------------
DROP TABLE IF EXISTS `wms_inventory_check`;
CREATE TABLE `wms_inventory_check`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `sku_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'SKU ID',
  `category` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '货品类型：1-纸箱 2-农资销售 3-其他物资',
  `sku_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'SKU类型：1-生产耗材 2-农资商品 3-设备资产 4-租赁资产',
  `sku_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货品名称快照',
  `specification` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格型号快照',
  `brand` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '品牌快照',
  `unit_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '库存单位快照',
  `voucher_urls` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '凭证图片URL列表',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注说明',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '盘点人ID',
  `operator_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '盘点人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '盘点时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '数据状态：0-正常 -100-删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sku_time`(`sku_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_category_spec_time`(`category` ASC, `specification`(128) ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'WMS库存盘点单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_inventory_check_detail
-- ----------------------------
DROP TABLE IF EXISTS `wms_inventory_check_detail`;
CREATE TABLE `wms_inventory_check_detail`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `check_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '盘点单ID',
  `sku_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'SKU ID',
  `part` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '库存区域：0-总仓',
  `team_id` int NOT NULL DEFAULT 0 COMMENT '库存归属团队，0-总仓',
  `team_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '团队名称快照',
  `period_no` int UNSIGNED NOT NULL DEFAULT 0 COMMENT 'SKU库区独立盘点期次',
  `actual_quantity` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '实盘数量',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '盘点时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '数据状态：0-正常 -100-删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sku_part_period`(`sku_id` ASC, `part` ASC, `period_no` ASC) USING BTREE,
  INDEX `idx_check_id`(`check_id` ASC) USING BTREE,
  INDEX `idx_sku_part_period`(`sku_id` ASC, `part` ASC, `period_no` ASC) USING BTREE,
  INDEX `idx_sku_team_period`(`sku_id` ASC, `team_id` ASC, `period_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'WMS库存盘点区域明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_inventory_relation
-- ----------------------------
DROP TABLE IF EXISTS `wms_inventory_relation`;
CREATE TABLE `wms_inventory_relation`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `trace_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '流水表的ID',
  `entry_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '入库表的ID',
  `quantity` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '从该入库记录修改的数量',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_trace_id`(`trace_id` ASC) USING BTREE,
  INDEX `idx_entry_id`(`entry_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 443 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'WMS 流水与入库关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_material_apply
-- ----------------------------
DROP TABLE IF EXISTS `wms_material_apply`;
CREATE TABLE `wms_material_apply`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `apply_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申领单号 SL+yyyyMMdd+3位序列',
  `team_id` int NOT NULL COMMENT '申领大区（打包团队）ID',
  `team_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '大区名称快照',
  `sku_id` bigint NOT NULL COMMENT '物资SKU ID',
  `sku_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '物资类别（sku名称）快照',
  `specification` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '物资规格快照',
  `unit_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '单位快照',
  `apply_quantity` int NOT NULL COMMENT '申领数量',
  `issued_quantity` int NULL DEFAULT NULL COMMENT '实际发放数量，仅已同意有值',
  `voucher_info` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '[]' COMMENT '凭证图片URL JSON数组',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '申领备注',
  `status` tinyint NOT NULL DEFAULT 10 COMMENT '10-待审核 20-已同意 30-已拒绝 40-已撤销',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '拒绝原因',
  `applicant_id` bigint NOT NULL COMMENT '申领人（打包负责人）ID',
  `applicant_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '申领人名称快照',
  `auditor_id` bigint NULL DEFAULT NULL COMMENT '审核人（仓库管理员）ID',
  `auditor_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '审核人名称快照',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '同意或拒绝时间',
  `cancel_time` datetime NULL DEFAULT NULL COMMENT '撤销时间',
  `entry_id` bigint NULL DEFAULT NULL COMMENT '同意后生成的大区入库批次ID',
  `trace_id` bigint NULL DEFAULT NULL COMMENT '同意后生成的库房出库流水ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '申请时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0-正常 -100-删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_apply_no`(`apply_no` ASC) USING BTREE,
  INDEX `idx_status_id`(`status` ASC, `id` ASC) USING BTREE,
  INDEX `idx_team_status_id`(`team_id` ASC, `status` ASC, `id` ASC) USING BTREE,
  INDEX `idx_applicant_id`(`applicant_id` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '物资申领单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `wms_operation_log`;
CREATE TABLE `wms_operation_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `sku_id` bigint NOT NULL DEFAULT 0 COMMENT '操作的物资sku_id',
  `entry_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作入库单id',
  `trace_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作的流水表id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作者id',
  `user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作者姓名',
  `content` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作内容',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_entryId`(`entry_id` ASC) USING BTREE,
  INDEX `idx_traceid_createtime`(`trace_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 119 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '操作记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_prepare_record
-- ----------------------------
DROP TABLE IF EXISTS `wms_prepare_record`;
CREATE TABLE `wms_prepare_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架号',
  `sub_shelf_sn` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  `enter_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'enter_item表主键id',
  `delivery_income` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '配货收益配置 元每扎',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名称',
  `op` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作 1：增加 2：减少',
  `op_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认 0 扫码枪 1：人工',
  `num` int NOT NULL DEFAULT 0 COMMENT '数量',
  `role_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '角色类型 0：配货员 1：质检员 2：供应商',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '默认0 删除-100',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_date_user_op`(`date` ASC, `user_id` ASC, `op` ASC) USING BTREE COMMENT '场次用户操作',
  INDEX `idx_enter_item_id`(`enter_item_id` ASC) USING BTREE,
  INDEX `idx_role_type`(`role_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 331 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '配货记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_punish
-- ----------------------------
DROP TABLE IF EXISTS `wms_punish`;
CREATE TABLE `wms_punish`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '0：客服导入 1：设箱错误 2：配货错误 3：供应商配货错误 4：未配货处罚 5：超时打包处罚 6：质检任务未完成处罚 7：配货超时处罚 8：售后自动质检处罚 9：售后自动配货处罚 10：售后自动打包处罚 11：售后仓库物流处罚 12：好花视频任务未完成处罚 13：错误质检判罚 ',
  `punish_source` tinyint NOT NULL DEFAULT 0 COMMENT '0：人工处罚 1：系统处罚',
  `duty_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '责任人id',
  `duty_user_role` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '责任人role_id',
  `duty_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '责任人名称',
  `punish_role_type` tinyint NOT NULL DEFAULT 0 COMMENT '处罚角色 1-打包 2-副总 3-区域负责人 4-场地 5-业务 6-基地 7-车队 8-供应商 9-质检 10-配货',
  `area_manager_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分区负责人id',
  `area_manager_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区负责人名称',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `date` date NOT NULL COMMENT '场次',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区-货架',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货位',
  `shelf_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配货超时货架明细JSON',
  `punish_reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '处罚原因',
  `punish_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '处罚备注',
  `punish_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '处罚金额',
  `punish_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '处罚状态 0-待确定 1-已确定 2-已撤销',
  `pic_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '佐证材料',
  `after_sale_pic_url` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '关联售后的原始图片和视频URL',
  `appeal_status` tinyint NOT NULL DEFAULT 0 COMMENT '申诉状态 0：无申诉 1：申诉中 2：申诉失败 3申诉成功',
  `appeal_count` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '已成功受理的申诉提交次数',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝原因 限255字',
  `reject_pic` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申诉拒绝图片URL列表，后端按逗号分隔存储',
  `appeal_pic` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '申诉照片',
  `appeal_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '申诉内容',
  `appeal_time` datetime NULL DEFAULT NULL COMMENT '申诉时间',
  `supplier_punish_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '对应供应商处罚id',
  `relation_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '配货对应enter_item_id,包裹对应package_id',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后退款ID，关联xm_bulky_refund.id',
  `order_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单商品ID，关联xm_bulky_order_item.id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_time`(`create_time` DESC, `duty_user_id` ASC) USING BTREE,
  INDEX `idx_ordersn_userid`(`order_sn` ASC, `duty_user_id` ASC) USING BTREE,
  INDEX `idx_date`(`date` ASC) USING BTREE,
  INDEX `idx_refund_id`(`refund_id` ASC) USING BTREE,
  INDEX `idx_inspection_punish_dedup`(`type` ASC, `duty_user_id` ASC, `date` ASC, `zone_shelf` ASC, `sub_shelf_sn` ASC, `punish_status` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1169 AVG_ROW_LENGTH = 455 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仓库处罚表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_sku_inventory
-- ----------------------------
DROP TABLE IF EXISTS `wms_sku_inventory`;
CREATE TABLE `wms_sku_inventory`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id（对应skuid）',
  `part` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区：0-总仓',
  `category` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分类类型:1-纸箱 2-农资销售 3-其他物资',
  `sku_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'sku类型：1-生产耗材 2-农资商品 3-设备资产 4-租赁资产',
  `sku_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku名称',
  `specification` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格型号',
  `brand` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '品牌',
  `entry_stock` int NOT NULL DEFAULT 0 COMMENT '物理库存',
  `unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单位',
  `status_bind` tinyint NOT NULL DEFAULT 0 COMMENT '绑定状态：0-未绑定 1-已绑定',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0-存在 -100-删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 67 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '批发wms sku库存表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_sku_mapping
-- ----------------------------
DROP TABLE IF EXISTS `wms_sku_mapping`;
CREATE TABLE `wms_sku_mapping`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品skuId',
  `sku_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'wms中物资skuId',
  `business_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '业务类型：1-包装配置 2-商品SKU',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_skuid`(`sku_id` ASC) USING BTREE,
  INDEX `idx_pid_type`(`product_id` ASC, `business_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 52 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'wms sku农资映射表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wms_stock_operation_failure_log
-- ----------------------------
DROP TABLE IF EXISTS `wms_stock_operation_failure_log`;
CREATE TABLE `wms_stock_operation_failure_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `type` tinyint NOT NULL COMMENT '失败原因类型：1-程序内部原因 2-外部原因',
  `num` int NOT NULL DEFAULT 0 COMMENT '操作数量（正=期望出库扣减, 负=期望回滚增加）',
  `part` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '分区：0-总仓',
  `wms_sku_id` bigint NULL DEFAULT NULL COMMENT 'SKU ID',
  `request_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '失败时的请求参数(JSON)',
  `error_msg` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '错误信息',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注，限255字',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常 -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE,
  INDEX `idx_sku_id`(`wms_sku_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物资库存操作失败日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wx_b2b_order
-- ----------------------------
DROP TABLE IF EXISTS `wx_b2b_order`;
CREATE TABLE `wx_b2b_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `mch_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户id',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '寻梦订单号orderSn',
  `out_trade_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '向B2b下单号',
  `order_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'B2b订单号',
  `refund_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'B2b退款单号',
  `out_refund_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '寻梦退款单号',
  `refund_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款状态',
  `refund_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款描述',
  `order_amount` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单金额',
  `refund_amount` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款金额',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0正常 -100删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_out_trade_no_refund_id`(`out_trade_no` ASC, `refund_id` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE,
  INDEX `idx_refundid`(`refund_id` ASC) USING BTREE,
  INDEX `idx_uid`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 275 AVG_ROW_LENGTH = 202 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'wxb2b退款表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wx_b2b_order_info
-- ----------------------------
DROP TABLE IF EXISTS `wx_b2b_order_info`;
CREATE TABLE `wx_b2b_order_info`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `open_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户openId',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appId',
  `mch_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户id',
  `out_trade_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'B2b下单单号',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '寻梦订单号orderSn',
  `order_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'B2b订单号',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '支付时间',
  `wxpay_transaction_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信单号',
  `send_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货状态 0未发货 1已发货',
  `data_status` int NULL DEFAULT 0 COMMENT '状态：0正常 -100删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_userid_mchid_ordersn`(`user_id` ASC, `mch_id` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_ordersn_mchid_status`(`order_sn` ASC, `mch_id` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_wxid`(`wxpay_transaction_id` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE,
  INDEX `idx_outordersn_mchid_status`(`out_trade_no` ASC, `mch_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 623 AVG_ROW_LENGTH = 263 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'wxb2b订单信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wx_customer_group
-- ----------------------------
DROP TABLE IF EXISTS `wx_customer_group`;
CREATE TABLE `wx_customer_group`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `contact_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '联系表id',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称',
  `link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业微信客服链接，限255字',
  `open_kfid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业微信客服账号ID',
  `scene` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业微信客服场景值',
  `scene_link` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '带scene的企业微信客服基础链接',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注，限255字',
  `area_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分区',
  `phone` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电话',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-禁用 1-启用',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_cid`(`contact_id` ASC) USING BTREE,
  INDEX `idx_contact_area_status`(`contact_id` ASC, `area_type` ASC, `status` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '企业微信客服组表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_base_data
-- ----------------------------
DROP TABLE IF EXISTS `xm_base_data`;
CREATE TABLE `xm_base_data`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `round_no` date NOT NULL COMMENT '年月日',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基地名称',
  `sale` bigint NULL DEFAULT 0 COMMENT '销量数据',
  `onsale` bigint NULL DEFAULT 0 COMMENT '上架数据',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `round_no`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 128 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货基地相关统计数据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_actual_price
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_actual_price`;
CREATE TABLE `xm_bulky_actual_price`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号',
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货位号',
  `expend_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实际支出运费',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-已创建 1-已确认',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sendno`(`send_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货实际运费表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_after_sale
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_after_sale`;
CREATE TABLE `xm_bulky_after_sale`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `purchaser_id` bigint NOT NULL COMMENT 'xm_bulky_purchaser表主键id',
  `nickname` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户昵称',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'xm_bulky_order用户订单表order_sn：用户订单号',
  `pay_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付方式 0：微信支付 1：寻梦平台账户支付 2：字节担保支付',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后类型 1:极速退款（未发货） 2:普通退款',
  `expect_amount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '期望退款金额',
  `amount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款金额合计',
  `pictures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '退款凭证图片链接数组',
  `videos` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '退款凭证视频链接数组',
  `more_pictures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '平台补充图片视频链接数组',
  `reason_type` tinyint UNSIGNED NOT NULL COMMENT '退款原因： 0:产品质量 1：服务态度 2：物流效率 3：其他 4：缺货赔付',
  `comment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '买家退款说明',
  `after_sale_status` tinyint UNSIGNED NOT NULL COMMENT '用户订单售后状态 0:无售后 1:售后申请中 2:售后同意 3:售后拒绝',
  `after_sale_agree_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后同意类型 0:无 1:发货前售后同意; 2:发货后售后同意;',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单退款状态 0:无退款 1:申请退款中 2:退款成功 3:退款失败',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注（平台客服）',
  `wx_refund_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信退款单号',
  `wx_refund_channel` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款渠道 详见 https://pay.weixin.qq.com/wiki/doc/apiv3/apis/chapter3_5_9.shtml 枚举',
  `wx_refund_success_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款成功时间',
  `handle_time` datetime NULL DEFAULT NULL COMMENT '管理员操作时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_uptime`(`update_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17126 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货售后表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_after_sale_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_after_sale_log`;
CREATE TABLE `xm_bulky_after_sale_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `after_sale_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_after_sale售后表主键id',
  `user_type` tinyint UNSIGNED NOT NULL COMMENT '操作者类型 1:采购方; 2:平台客服; 3:供应商',
  `user_id` bigint NOT NULL COMMENT '操作者id',
  `user_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作者名称',
  `item_id` bigint UNSIGNED NOT NULL COMMENT 'xm_bulky_order_item订单商品表主键id',
  `after_sale_status` tinyint UNSIGNED NOT NULL COMMENT '处理类型 1:用户申请; 2:用户取消; 3:售后同意; 4:售后拒绝; 5:微信退款成功消息',
  `content` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '处理信息（系统生成）',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注（用户生成）',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_after_sale_id`(`after_sale_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2045 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货售后操作表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_after_sale_priority
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_after_sale_priority`;
CREATE TABLE `xm_bulky_after_sale_priority`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `channel` tinyint NOT NULL COMMENT '真实渠道 1-寻梦 2-优花速达 3-繁花惠 4-分销商 5-城市仓',
  `priority_num` tinyint NOT NULL COMMENT '优先级序号，数字越小优先级越高，0=T0；T0必须存在',
  `levels` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '该优先级对应的客户等级集合，逗号分隔的 vip_level 列表；无等级体系渠道为空字符串',
  `sla_minutes` int NULL DEFAULT NULL COMMENT 'SLA时长，统一按分钟存储，NULL表示不设时效',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '最近操作人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最近操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_channel_priority`(`channel` ASC, `priority_num` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 78 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '售后分配-渠道优先级配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_after_sale_staff
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_after_sale_staff`;
CREATE TABLE `xm_bulky_after_sale_staff`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint NOT NULL COMMENT '客服用户id，xm_bulky_auth_user_role.user_id',
  `channel` tinyint NOT NULL COMMENT '真实渠道 1-寻梦 2-优花速达 3-繁花惠 4-分销商 5-城市仓',
  `area_type` int NULL DEFAULT NULL COMMENT '大区，取值同 xm_bulky_purchaser.area_type：1-5 寻梦一~五区，6-8 繁花北/南/西区；无大区体系的渠道为NULL',
  `staff_level` tinyint NOT NULL COMMENT '客服等级 1-初级 2-中级 3-高级',
  `handle_levels` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '可处理客户等级，逗号分隔的 vip_level 列表，如 \"7,8\"；无等级体系的渠道为空字符串',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '最近操作人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最近操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 41 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '售后分配-客服扩展配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_cart
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_cart`;
CREATE TABLE `xm_bulky_agency_cart`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `is_hour_delivery` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否是小时达 0: 不是 1：是',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小时达wareId 0大件批发 大于0小时达',
  `platform` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '平台 0：大件批发 1：花仓库',
  `is_sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否代卖购物车 0：不是 1：是',
  `product_id` bigint NOT NULL COMMENT '商品id',
  `product_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `supplier_id` bigint NOT NULL COMMENT '供应商id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品主图',
  `in_price` decimal(20, 2) NOT NULL COMMENT '加入购物车的价格',
  `buy_count` int NOT NULL COMMENT '购买数量',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态：0：默认 -1：已提交 -100：已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11105 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货购物车表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_order`;
CREATE TABLE `xm_bulky_agency_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_purchaser采购方表主键id',
  `vip_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '会员卡名称',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号（唯一）',
  `order_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:普通订单 1:代下订单 默认0',
  `delivery_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '物流配送方式 1：物流配送  2：自提 默认1',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `distribution_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '配送方式 0-无 1-送货上门 2-城市仓自提',
  `is_addition` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否加单 0:否; 1:是;',
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单平台 0：微信 1：抖音',
  `has_third_good` tinyint NOT NULL DEFAULT 0 COMMENT '订单是否包含第三方平台商品，默认0不包含，1包含',
  `is_zq_settlement` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否结算给珍情 0:没有 1:已结算',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号，当天同一货架号发货单号相同',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次编号：yyyy-MM-dd',
  `order_num` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '每天流水号',
  `total_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '花材总扎数',
  `total_weight` int UNSIGNED NOT NULL COMMENT '花材总重(g)',
  `origin_total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原花材总重 单位：克',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '按物流和重量场次结束时生成的货架号',
  `sub_shelf_sn` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  `express` int UNSIGNED NOT NULL COMMENT '运输方式配置表id',
  `express_region` bigint NOT NULL COMMENT '运输方式下对应的配送区域id',
  `express_time` tinyint NULL DEFAULT NULL COMMENT '航空物流：0: 早、 1: 中、 2:晚班',
  `express_price` decimal(20, 2) UNSIGNED NOT NULL COMMENT '预估运费',
  `real_express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际物流id 0时不改物流',
  `real_express_region` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际物流配送区域id',
  `coupon_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单剩余优惠金额(用于结算)',
  `origin_coupon_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单原优惠金额',
  `add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加价（元）',
  `origin_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原加价（元）',
  `warehouse_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓加价（元）',
  `origin_warehouse_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原城市仓加价（元）',
  `express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓物流加价（元）',
  `origin_express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原城市仓物流加价（元）',
  `delivery_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '配送费（元）',
  `origin_delivery_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原始配送费（元）',
  `modify_express_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '变更物流后预估运费',
  `is_change_express` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已修改物流 0:否; 1:是;',
  `actual_express_price` decimal(20, 2) UNSIGNED NULL DEFAULT NULL COMMENT '实际运费',
  `origin_supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商品合计供货价',
  `product_total_price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '商品合计价格（供货价+基础服务费）* 购买数量',
  `origin_product_total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原商品合计价格（供货价+基础服务费）* 购买数量',
  `service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总服务费（服务费单价*花材总重量）',
  `origin_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总服务费（服务费单价*花材总重量）',
  `vip_discount_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'vip减免服务费',
  `origin_vip_discount_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原vip减免服务费',
  `platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台总补贴',
  `origin_platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原平台总补贴',
  `base_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总基础服务费：二级分类基础服务费 * 数量',
  `origin_base_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总基础服务费：二级分类基础服务费 * 数量',
  `total_price` decimal(20, 2) UNSIGNED NOT NULL COMMENT '订单合计金额=商品合计金额+运费+服务费',
  `origin_total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原订单合计金额=商品合计金额+运费+服务费',
  `origin_use_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '下单时原使用寻梦币',
  `use_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当前订单使用寻梦币金额，不含发货前退款的',
  `rebate_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单返点给用户的寻梦币金额',
  `origin_rebate_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原订单返点给用户的寻梦币金额',
  `actual_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付金额 = 订单合计金额 - 订单使用寻梦币金额',
  `origin_actual_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原实付金额（最初付的钱，不含部分退），用于微信退款',
  `apply_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后申请商品总金额',
  `actual_refund` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后阶段实际退款金额（不超过申请售后商品的总价格+服务费）',
  `actual_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后阶段赔付寻梦币（小于等于售后申请商品总金额）',
  `paid_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付阶段总赔付金额（小于等于商品金额+服务费-实际退款金额）',
  `paid_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付阶段总赔付寻梦币（小于等于总供货价-售后赔付寻梦币）',
  `pay_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付方式 0：微信支付 1：寻梦平台账户支付 2：字节微信支付 3：字节支付宝支付',
  `pay_on_delivery` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否到付 0:否; 1:是 默认：0',
  `receive_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人名称',
  `receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人手机号',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `district` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `detail` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `receive_address` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址',
  `adcode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址adcode',
  `buyer_memo` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '买家留言',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台备注',
  `order_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单状态 0:待付款 1:已付款待发货 2:已发货待收货 3:已完成 4:已关闭 5:已取消',
  `after_sale_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单售后状态 0:无售后 1:售后申请中 2:售后同意 3:售后拒绝',
  `return_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款退货状态 0:无退货; 1:申请退货; 2:同意退货;',
  `after_sale_agree_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后同意类型 0:无 1:发货前售后同意; 2:发货后售后同意;',
  `after_sale_count` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后申请次数，（待发货：取消订单不计）',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单退款状态 0:无退款 1:申请退款中 2:退款成功 3:退款失败 4:极速退款中 5:极速退款成功 6:极速退款失败',
  `print_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已打印 0:否; 1:是;',
  `wx_pay_time` datetime NULL DEFAULT NULL COMMENT '微信付款时间',
  `wx_pay_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信付款编号',
  `send_time` datetime NULL DEFAULT NULL COMMENT '发货时间',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认收货时间',
  `extra_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '额外信息',
  `coupon_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户优惠券id，0:没有用优惠券',
  `is_comment` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单是否已评价 0：未评价 1：已评价 默认0',
  `is_open_after_sale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启售后 0：关闭（正常售后） 1：开启（开启后强制用户端显示售后按钮）',
  `is_cotton` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否保温棉 0:否; 1:是;',
  `flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '旗帜 0:灰',
  `bear_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后承担方 0:无; 1:梦晟; 2:昆明;',
  `is_bear_station_fee` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商是否承担提货站运费 0:否; 1:是;',
  `origin_total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原提货站运费总价=单价*sum(origin_item_num)',
  `total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '提货站运费当前总价=单价*sum(item_num)',
  `is_presale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为预售订单 0：不是 1：是 默认0',
  `is_sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为代卖订单 0不是 1是',
  `is_hour_delivery` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否是小时达 0: 不是 1：是',
  `order_tag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:正 1：场 2：加',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `unqualified_way` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '质检不合格处理方式 0:无 1:退货 2:降级',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id，代下单时为下单客服userid',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `is_deliver` tinyint NULL DEFAULT NULL COMMENT '（废弃）',
  `is_bond` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）是否履约（代供应商履约标记） 0:否; 1:是;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_send_no`(`send_no` ASC) USING BTREE,
  INDEX `idx_round_no`(`round_no` ASC) USING BTREE,
  INDEX `idx_purchaserid_wareid`(`purchaser_id` ASC, `ware_id` ASC) USING BTREE,
  INDEX `idx_wxpaytime_ordersn`(`wx_pay_time` ASC, `order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 33 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货用户订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_agency_order_cancel_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_order_cancel_record`;
CREATE TABLE `xm_bulky_agency_order_cancel_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `record_type` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '记录类型0：取消订单 1：部分退款',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `refund_purchaser` decimal(10, 2) UNSIGNED NULL DEFAULT 0.00 COMMENT '退给用户的',
  `deduct_supplier` decimal(10, 2) UNSIGNED NULL DEFAULT 0.00 COMMENT '扣供应商的',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 608 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件批发订单取消订单（已支付）、部分退款记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_order_edit
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_order_edit`;
CREATE TABLE `xm_bulky_agency_order_edit`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '记录id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户订单号',
  `field` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '字段',
  `old_data` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '旧数据',
  `new_data` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '新数据',
  `operator_id` bigint UNSIGNED NOT NULL COMMENT '操作用户id',
  `operator_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作用户姓名',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2249 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货订单编辑记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_order_item
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_order_item`;
CREATE TABLE `xm_bulky_agency_order_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方用户id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `order_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '每天货架号',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '按物流和重量 场次结束时生成的货架号',
  `sub_shelf_sn` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'xm_bulky_order表order_sn：用户订单号',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次编号：yyyy-MM-dd',
  `supplier_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商订单号',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_product商品表主键id',
  `product_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '等级123456->ABCDEO',
  `sku_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品图片',
  `spec_and_num` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格数量+规格名称',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单商品描述',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单商品备注，限128字',
  `supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价',
  `pay_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付单价',
  `platform_discount_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台补贴单价 元/扎',
  `coupon_pay_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '优惠后实付单价',
  `add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加价单价（元）',
  `warehouse_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓加价单价（元）',
  `express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓物流加价单价（元）',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单商品数量',
  `origin_item_num` int UNSIGNED NOT NULL COMMENT '订单创建时商品数量，值不变',
  `after_sale_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后退的商品数量（生成送货单的商品数量=购买数量-售后退的数量）',
  `prepare_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '代卖配货数量',
  `after_sale_refund` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后退的金额（由售后退的数量计算得来或者是客服手动填入）',
  `bond_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）代履约的商品数量（这部分商品供货价的钱不结算给供应商）',
  `after_sale_supplier_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商售后承担商品数量（小于等于售后退的商品数量，小于等于item_num-bond_item_num）',
  `actual_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付单价x数量',
  `origin_actual_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原实付单价x数量',
  `total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价x数量',
  `origin_total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原供货价x数量',
  `total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品总重量 g',
  `origin_total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原商品总重',
  `is_comment` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否评价 0:未评价; 1:已评价;',
  `after_sale_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单售后状态 0:无售后 1:售后申请中 2:售后同意 3:售后拒绝',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款状态 0:无退款 1:申请退款中 2:退款成功',
  `printer_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小票打印状态 0：未打印  1：已打印',
  `printer_time` int UNSIGNED NULL DEFAULT 0 COMMENT '打印时间',
  `is_deliver` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已配货 0:未配货; 1:已配货;（配货用字段）',
  `is_rebate` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否返点 0:否; 1:是;',
  `third_good_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '第三方商品id，默认0，大于0 表示三方平台商品',
  `deliver_time` datetime NULL DEFAULT NULL COMMENT '订单商品配货时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_roundno`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 43 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货订单商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_product
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_product`;
CREATE TABLE `xm_bulky_agency_product`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id 0为未指定二级分类',
  `third_good_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '三方平台商品id 0为我们平台供应商的商品',
  `product_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品类型 0-花材批发 1-城市仓小时达',
  `is_sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否代卖商品 0：不是 1：是',
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小时达商品firstId, 0大件批发 大于0小时达',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小时达商品ware_id，0大件批发 大于0小时达',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商ID',
  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品编码',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '等级12345->ABCDE',
  `sku_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '颜色',
  `pic_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `detail_pic_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品详情图片',
  `price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品描述',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品备注，限128字',
  `after_sale_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后笔数（不看商品数量）',
  `sell_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销售笔数（不看商品数量）',
  `today_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '今日销量',
  `last_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '上一场次销量',
  `month_sell_count` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品近30天销量',
  `sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销量',
  `max_stock` int UNSIGNED NOT NULL DEFAULT 9999 COMMENT '最大库存',
  `remain_stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '剩余库存',
  `offline_stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '线下库存（不上线展示）',
  `offline_switch` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:更改剩余库存 1:更改线下库存',
  `limit_switch` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '限购开关 0-不限购 1-限购',
  `limit_sale` int UNSIGNED NOT NULL DEFAULT 9999 COMMENT '限购数量',
  `product_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品状态 0:下架; 1:上架; 2:冻结; 3:过期（定时任务更新）',
  `freeze_reason` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '冻结原因，限50字',
  `is_hot` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否热销 0:否; 1:是;',
  `on_sale_time_str` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '上架时间，如：08:00:00',
  `not_sale_time_str` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '下架时间，如：12:00:00',
  `is_close_auto` tinyint NOT NULL DEFAULT 0 COMMENT '是否关闭自动上下架 0:否; 1:是;',
  `is_rebate` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否返点 0:否; 1:是; 默认1',
  `is_special` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否特价 1:否; 2:是;',
  `special_sort` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '特价商品排序值',
  `is_seckill` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否秒杀 1:否; 2:是;',
  `seckill_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加价（元）',
  `platform_discount_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台补贴（元）',
  `seckill_sort` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '秒杀商品排序值',
  `plan_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '秒杀计划id',
  `seckill_deadline` datetime NULL DEFAULT NULL COMMENT '秒杀加价截止时间',
  `is_prefer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否优选 0:否 1:是',
  `prefer_time` datetime NULL DEFAULT NULL COMMENT '优选设置时间',
  `prefer_end_time` datetime NULL DEFAULT NULL COMMENT '优选结束时间',
  `expire_time` datetime NOT NULL COMMENT '过期时间（当前时间超过该值就过期）',
  `replenish_auto_onsale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补货自动上架 0-否 1-是',
  `return_processing` tinyint NOT NULL DEFAULT 0 COMMENT '退货处理 0-我要退货 1-转入代卖',
  `sell_prefer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否销量优选 0-否 1-是',
  `auto_sell_prefer` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否自动设置销量优选 0-否 1-是 默认1',
  `seven_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '7日销量（前7个场次）',
  `seven_no_lower_rank` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否7日无降级 0-否 1-是',
  `seven_no_refund` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否7日无退货 0-否 1-是',
  `seven_no_lack` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否7日无缺货 0-否 1-是',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `is_presale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）是否为预售商品 0：不是 1：是 默认0',
  `presale_end_time` datetime NULL DEFAULT NULL COMMENT '（废弃）预售截止时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_second_id`(`second_id` ASC) USING BTREE,
  INDEX `idx_rank_num`(`rank_num` ASC) USING BTREE,
  INDEX `idx_thirdgoodid`(`third_good_id` ASC) USING BTREE,
  INDEX `idx_supplierid_firstid`(`supplier_id` ASC, `first_id` ASC) USING BTREE,
  INDEX `idx_planid_sid`(`plan_id` ASC, `supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 200264 AVG_ROW_LENGTH = 526 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货代卖商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_product_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_product_log`;
CREATE TABLE `xm_bulky_agency_product_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作内容',
  `user_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作用户类型 0:系统 1:平台 2:供应商',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_createtime_supplierid_productid`(`create_time` ASC, `supplier_id` ASC, `product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2188 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货商品日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_purchaser
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_purchaser`;
CREATE TABLE `xm_bulky_agency_purchaser`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `zq_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '珍情用户id',
  `platform` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认0，0表示未区分，1、花材批发、2花仓酷，3、双用户(历史数据)',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认0  大于0 城市仓',
  `xm_account` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '寻梦账号(手机号)',
  `company_direct_sale_store` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '寻梦平台账号店铺类型：1：直营店铺 2：头部商家 0：无',
  `company_level` tinyint UNSIGNED NOT NULL DEFAULT 6 COMMENT '寻梦平台账号店铺合作等级：1、2、3、4、5、6 默认最低等级',
  `xm_coin` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '寻梦币',
  `xm_coin_income` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '寻梦币收入',
  `xm_coin_expend` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '寻梦币支出',
  `xm_coin_give` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '补贴寻梦币余额',
  `xm_coin_rebate` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '返点寻梦币余额',
  `xm_coin_paid` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付寻梦币余额',
  `phone_number` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '手机号',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '密码',
  `salt` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '盐值',
  `open_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微信openId',
  `zc_open_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '资材openId',
  `session_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微信登录会话KEY',
  `gender` tinyint NULL DEFAULT NULL COMMENT '性别：0：未知 1男，2女',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '市',
  `country` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区',
  `nickname` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户昵称或网络名称',
  `remark` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台备注，限20字符',
  `avatar_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户头像图片',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最近一次登录时间',
  `last_login_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最近一次登录IP地址',
  `class_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '分类类型 1:外部类型; 2:内部类型;',
  `contact_supplier_count` int UNSIGNED NOT NULL DEFAULT 3 COMMENT '可联系供应商次数，默认3次',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '预设货架号',
  `config_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认物流id',
  `first_buy_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '首次购买时间',
  `last_buy_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近购买时间',
  `data_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户状态 0：正常 -1：禁用  -100：删除',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_phone_number`(`phone_number` ASC) USING BTREE COMMENT '用户手机号',
  INDEX `idx_xm_account`(`xm_account` ASC) USING BTREE COMMENT '寻梦账号手机号',
  INDEX `idx_helpid`(`help_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 100060 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货采购方用户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_purchaser_account_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_purchaser_account_log`;
CREATE TABLE `xm_bulky_agency_purchaser_account_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL COMMENT '采购方用户id',
  `year` int UNSIGNED NOT NULL COMMENT '年份',
  `month` int UNSIGNED NOT NULL COMMENT '月份',
  `day` int UNSIGNED NOT NULL COMMENT '日',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单编号',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id  0不是城市仓',
  `business_type` tinyint UNSIGNED NOT NULL COMMENT '业务类型：0：订单支付 1：订单退款',
  `pay_type` tinyint UNSIGNED NOT NULL COMMENT '支付方式 0：微信支付 1：寻梦平台账户支付',
  `money` decimal(10, 2) NOT NULL COMMENT '发生金额',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3790 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购方用户账单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_purchaser_address
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_purchaser_address`;
CREATE TABLE `xm_bulky_agency_purchaser_address`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `type` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '0：默认，1：城市仓',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人姓名',
  `phone_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人手机号',
  `longitude` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `province_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '行政区域表的省code',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `city_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '行政区域表的市code',
  `country` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `country_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '行政区域表的区县code',
  `address_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '搜索带的地址名称',
  `address_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '搜索带的详细地址',
  `detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `is_default` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为默认地址 0：不是 1：是',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态 0：默认 -100：删除',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9833 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购方收货地址类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_refund
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_refund`;
CREATE TABLE `xm_bulky_agency_refund`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户类型 1:采购方 2:供应商 3:平台客服 4:系统',
  `refund_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款类型 1:用户申请一键退款 2:用户申请部分退款 3:用户申请售后 4:客服申请一键退款 5:客服申请部分退款 6:客服申请售后 7:客服申请退运费',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '来源：0：大件批发 1：抖音 2：花仓库',
  `pay_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付方式 0：微信支付 1：寻梦平台账户支付',
  `apply_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '申请状态 0:申请中 1:已通过 2:已拒绝',
  `apply_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请总金额（可以为0）=申请商品金额+申请服务费+申请运费',
  `apply_product_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请商品金额',
  `apply_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请服务费',
  `apply_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请运费',
  `apply_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '买家退款说明',
  `reason_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款原因： 0:产品质量 1：服务态度 2：物流效率 3：其他 4：缺货赔付',
  `pictures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '退款凭证图片链接数组',
  `videos` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '退款凭证视频链接数组',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款状态 0:已创建 1:退款中 2:退款成功 3:退款失败',
  `wx_refund_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信退款单号',
  `wx_refund_success_time` datetime NULL DEFAULT NULL COMMENT '退款成功时间',
  `refund_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款金额=退款商品金额+退款服务费+退款运费-退款优惠金额',
  `refund_product_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款商品金额',
  `refund_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款服务费',
  `refund_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款运费',
  `refund_coupon_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款优惠券金额',
  `refund_vip_discount_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款会员优惠服务费金额',
  `paid_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付寻梦币',
  `bear_platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供应商承担补贴金额（客服售后填写）',
  `supplier_bear_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供应商承担金额',
  `city_warehouse_bear_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓承担金额',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '客服备注，限255字',
  `flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '旗帜 0:灰',
  `refund_result` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款返回结果',
  `duty_reason` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '责任描述，限64字',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_date` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建日期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_createtime_purchaserid`(`create_time` ASC, `purchaser_id` ASC) USING BTREE,
  INDEX `idx_wareid_datastatus`(`ware_id` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_ordersn_status`(`order_sn` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_cdate_pid`(`create_date` ASC, `purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 143333 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货退款申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_refund_item
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_refund_item`;
CREATE TABLE `xm_bulky_agency_refund_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_refund.`id`',
  `refund_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款类型 1:用户申请一键退款 2:用户申请部分退款 3:用户申请售后 4:客服申请一键退款 5:客服申请部分退款 6:客服申请售后 7:客服申请退运费',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `order_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_order_item.`id`',
  `apply_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请总金额（可以为0）=申请商品金额+申请服务费+申请运费',
  `apply_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '申请退款扎数',
  `apply_item_sub_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '申请售后枝数',
  `apply_product_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请商品金额',
  `apply_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请服务费',
  `apply_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请运费',
  `refund_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款金额=退款商品金额+退款服务费+退款运费',
  `refund_product_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款商品金额',
  `refund_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款服务费',
  `refund_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款运费',
  `refund_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款扎数',
  `paid_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付寻梦币',
  `supplier_bear_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供应商承担金额',
  `city_warehouse_bear_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓承担金额',
  `bear_platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供应商承担补贴金额',
  `apply_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '申请状态 0:申请中 1:已通过 2:已拒绝',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_refund_id_itemid`(`refund_id` ASC, `order_item_id` ASC) USING BTREE,
  INDEX `idx_order_item_id`(`order_item_id` ASC) USING BTREE,
  INDEX `idx_createtime`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 138263 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货退款商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_refund_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_refund_log`;
CREATE TABLE `xm_bulky_agency_refund_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款申请id',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `user_type` tinyint NOT NULL COMMENT '操作者类型 1:采购方 2:平台客服 3:供应商',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作者id',
  `user_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作者名称',
  `content` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '处理信息',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 630 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货退款操作记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_supplier_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_supplier_order`;
CREATE TABLE `xm_bulky_agency_supplier_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `order_num` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '每天流水号',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '按物流和重量 场次结束时生成的货架号',
  `sub_shelf_sn` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `is_addition` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否加单 0:否; 1:是;',
  `receive_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人名称',
  `receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人手机号',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_supplier供应商表主键id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `supplier_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商订单号（唯一）',
  `delivery_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '送货单编号',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次编号：yyyy-MM-dd',
  `supply_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供货价，为sum(商品供货价x数量)',
  `origin_supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原供货价，为sum(商品供货价x数量)',
  `actual_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实付费用，为sum(商品售价x数量)',
  `origin_actual_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原实付费用，为sum(商品售价x数量)',
  `platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台总补贴',
  `origin_platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原平台总补贴',
  `take_xm_coin` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商订单抽点的寻梦币金额',
  `origin_take_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原供应商订单抽点的寻梦币金额',
  `take_ratio` decimal(3, 3) UNSIGNED NOT NULL DEFAULT 0.000 COMMENT '供应商抽点比例',
  `after_sale_supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后申请总供货价',
  `after_sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '售后承担金额（不超过申请售后商品的总供货价）',
  `paid_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '赔付承担金额（小于等于供货价-售后承担金额）',
  `paid_coin` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '赔付承担寻梦币（小于等于供货价）',
  `order_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单状态 0:待付款 1:已付款待发货 2:已发货待收货 3:已完成 4:已关闭 5:已取消',
  `wx_pay_time` datetime NULL DEFAULT NULL COMMENT '微信付款时间',
  `after_sale_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后状态 0:无售后 1:售后申请中 2:售后同意 3:售后拒绝',
  `after_sale_agree_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后同意类型 0:无 1:发货前售后同意; 2:发货后售后同意;',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款状态 0:无退款 1:申请退款中 2:退款成功 3:退款失败 4:极速退款中 5:极速退款成功 6:极速退款失败',
  `sort_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已分拣 0:否; 1:是;',
  `delivery_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已送货 0:否; 1:是;',
  `is_presale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为预售订单 0：不是 1：是 默认0',
  `is_deliver` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商订单是否已配货 0:未配货; 1:配货中; 2:已配货;（配货用字段）',
  `is_bear_station_fee` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商是否承担提货站运费 0:否; 1:是;',
  `station_fee` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '提货站运费单价（扎item_num）',
  `origin_total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原提货站运费总价=单价*sum(origin_item_num)',
  `total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '提货站运费当前总价=单价*sum(item_num)',
  `after_sale_coin` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '（废弃）售后承担寻梦币（小于等于after_sale_supply_price）',
  `is_sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0普通订单 1:代卖订单',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `is_bond` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）是否履约 0:否; 1:是;',
  `bond_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '（废弃）履约商品总金额：sum(供货价单价x履约数量)',
  `bond_paid_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）代履约赔付金额',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_supplier_no`(`supplier_no` ASC) USING BTREE,
  INDEX `idx_wx_pay_time`(`wx_pay_time` ASC) USING BTREE,
  INDEX `idx_order_sn_union`(`order_sn` ASC, `supplier_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货供应商订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agency_tag_product
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agency_tag_product`;
CREATE TABLE `xm_bulky_agency_tag_product`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_class_second表主键id',
  `tag_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_tag标签表主键id（二级标签）',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_product商品表主键id',
  `template_product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_product_template模板商品表主键id',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_second_id`(`second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货标签商品关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agreement
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agreement`;
CREATE TABLE `xm_bulky_agreement`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `platform_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '平台类型 1-寻梦批发 2-花仓酷 3-优花速达 4-繁花惠 5-供应商 8-包邮分销商 9-非包邮分销商 10-分销商',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 1-交易规则 2-隐私政策 3-用户协议 4-入驻协议 5-代配协议 6-开票协议',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '协议名称',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '协议模板内容',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-关闭 1-开启',
  `notify_supplier` tinyint NOT NULL DEFAULT 0 COMMENT '上一次是否选择通知供应商 0-否 1-是',
  `last_notify_summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上一次填写的协议更新简要说明',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ptype_type`(`platform_type` ASC, `type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '协议配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_agreement_update
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_agreement_update`;
CREATE TABLE `xm_bulky_agreement_update`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `agreement_id` bigint NOT NULL COMMENT '协议id',
  `update_summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '协议更新简要说明',
  `is_show` tinyint NOT NULL DEFAULT 1 COMMENT '是否展示 0-否 1-是',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_agreement_id`(`agreement_id` ASC) USING BTREE,
  INDEX `idx_show_data_status_id`(`is_show` ASC, `data_status` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '协议更新通知记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_allocate_driver
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_allocate_driver`;
CREATE TABLE `xm_bulky_allocate_driver`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '司机id',
  `user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '司机名称',
  `base_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '基地配置',
  `allocate_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '车队长id',
  `allocate_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '车队长名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_allocate_user`(`allocate_user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '司机每日配置基地信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_allocation_config
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_allocation_config`;
CREATE TABLE `xm_bulky_allocation_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `area_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区域名称，限20字',
  `start_shelf` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '开始货架号',
  `end_shelf` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '结束货架号（>=开始货架号）',
  `dispatch_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '配货员id',
  `dispatch_id_str` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配货员id集合 ,12345,12346,',
  `pack_id_str` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '打包员id集合 ,12345,12346,',
  `sequence` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序 顺序 默认时间戳',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 52 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货配货区域配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_api_statistics_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_api_statistics_log`;
CREATE TABLE `xm_bulky_api_statistics_log`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` bigint NULL DEFAULT NULL COMMENT '供应商id',
  `type` int NOT NULL DEFAULT 0 COMMENT '访问服务类型 1.供应商',
  `source` int NOT NULL DEFAULT 0 COMMENT '访问来源 1. web 2.app  3.小程序',
  `api_code` int NOT NULL DEFAULT 0 COMMENT '请求接口代码（由前端定义）',
  `api_str` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接口详细',
  `count` int NOT NULL DEFAULT 0 COMMENT '请求数量',
  `date` date NOT NULL COMMENT '访问日期',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_userId_type_source_apiCode_date`(`user_id` ASC, `type` ASC, `source` ASC, `api_code` ASC, `date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 977 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '批发业务接口访问流量统计' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_app
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_app`;
CREATE TABLE `xm_bulky_app`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称，限50字',
  `mch_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_appid`(`app_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 351 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货app表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_app_template
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_app_template`;
CREATE TABLE `xm_bulky_app_template`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `template_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '模板id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '模板名称',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片url',
  `vip_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否会员 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tid`(`template_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'app模板表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_auth_area_permission
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_auth_area_permission`;
CREATE TABLE `xm_bulky_auth_area_permission`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `route_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '路由权限名，区分大小写',
  `area_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '' COMMENT '区域唯一标识，区分大小写',
  `area_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区域描述',
  `dom_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'DOM类型',
  `default_value` tinyint NOT NULL DEFAULT 1 COMMENT '新增角色区域权限关系时默认是否启用：0-否，1-是',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0-正常 -100-删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_route_area`(`route_name` ASC, `area_name` ASC) USING BTREE,
  INDEX `idx_route_status`(`route_name` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1083 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '页面区域子权限定义表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_auth_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_auth_operation_log`;
CREATE TABLE `xm_bulky_auth_operation_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '日志ID',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '业务类型 PERMISSION/PERMISSION_GROUP/POSITION/USER_POSITION/POSITION_APPLY',
  `biz_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '业务对象ID',
  `biz_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '业务对象名称快照',
  `operation_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作类型 CREATE/UPDATE/DELETE/BIND/UNBIND/SUBMIT/APPROVE/REJECT/CANCEL',
  `operation_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作摘要',
  `before_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作前JSON快照',
  `after_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作后JSON快照',
  `result_status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '操作结果 0-失败 1-成功',
  `fail_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '失败原因',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人ID，系统操作为0',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_biz_time`(`biz_type` ASC, `biz_id` ASC, `create_time` ASC, `id` ASC) USING BTREE,
  INDEX `idx_operator_time`(`operator_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_operation_time`(`operation_type` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 518 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货权限体系操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_auth_permission
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_auth_permission`;
CREATE TABLE `xm_bulky_auth_permission`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `pid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT 'pid 等于0为权限组',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '权限名称',
  `perm` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '权限tag pid大于0使用',
  `can_index` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '能否被路由 0-否 1-是',
  `important_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '重要标记 0-一般 1-重要',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_perm`(`perm` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 354 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货权限表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_auth_position
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_auth_position`;
CREATE TABLE `xm_bulky_auth_position`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '角色ID',
  `position_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '角色名称',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '角色描述',
  `important_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '重要标记 0-一般 1-重要，由关联权限组重算',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近操作人ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '数据状态 0-正常 -100-删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_position_name_status`(`position_name` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_important_status`(`important_flag` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 71 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货新角色表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_auth_position_apply
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_auth_position_apply`;
CREATE TABLE `xm_bulky_auth_position_apply`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '申请ID',
  `target_position_id` int UNSIGNED NOT NULL COMMENT '申请目标角色ID',
  `target_position_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '申请目标角色名称快照',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审批状态 0-待审批 1-已通过 2-已驳回',
  `apply_user_id` bigint UNSIGNED NOT NULL COMMENT '申请人ID',
  `apply_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '申请人姓名',
  `approve_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审批人ID',
  `approve_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审批人姓名',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '驳回原因',
  `apply_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '申请时间',
  `approve_time` datetime NULL DEFAULT NULL COMMENT '审批时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status_apply_time`(`status` ASC, `apply_time` ASC, `id` ASC) USING BTREE,
  INDEX `idx_target_position_status`(`target_position_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 58 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货重要角色申请批次表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_auth_position_apply_user
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_auth_position_apply_user`;
CREATE TABLE `xm_bulky_auth_position_apply_user`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '申请账户明细ID',
  `apply_id` bigint UNSIGNED NOT NULL COMMENT '申请批次ID',
  `apply_type` tinyint UNSIGNED NOT NULL COMMENT '申请类型 1-首次绑定 2-切换角色',
  `user_type` tinyint UNSIGNED NOT NULL COMMENT '用户类型 0-主账号 1-子账号',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '用户ID',
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名称快照',
  `nickname` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户姓名快照',
  `current_position_id` int UNSIGNED NULL DEFAULT NULL COMMENT '申请时已生效角色ID，无角色时为空',
  `current_position_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '申请时已生效角色名称快照',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_apply_user`(`apply_id` ASC, `user_type` ASC, `user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 72 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货重要角色申请账户明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_auth_position_role
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_auth_position_role`;
CREATE TABLE `xm_bulky_auth_position_role`  (
