  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_position_role`(`position_id` ASC, `role_id` ASC) USING BTREE,
  INDEX `idx_role_status`(`role_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 71 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货角色权限组关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
