  INDEX `idx_apply_user_time`(`apply_user_id` ASC, `apply_time` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货角色权限组调整申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
