-- ----------------------------
-- Table structure for xm_bulky_auth_role
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_auth_role`;
CREATE TABLE `xm_bulky_auth_role`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '角色id',
  `role_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '角色名称，如管理员，限20字',
  `description` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '角色描述，限50字',
  `important_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '重要标记 0-一般 1-重要，由关联权限项重算',
  `role_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '权限组类型 0-运营端权限组 1-梦花仓管权限组',
  `base_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '基地配置开关 0-否 1-是',
  `area_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '配货区域配置开关 0-否 1-是',
  `logistics_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流配置开关 0-否 1-是',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2342 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货权限组表（历史角色表）' ROW_FORMAT = Dynamic;

