  INDEX `idx_area_permission_status`(`area_permission_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3367 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '角色区域子权限关系表' ROW_FORMAT = Dynamic;

