  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '数据状态 0-正常 -100-删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user`(`user_type` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_position_status`(`position_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货用户角色关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_auth_user_role
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_auth_user_role`;
CREATE TABLE `xm_bulky_auth_user_role`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `role_id` int UNSIGNED NOT NULL COMMENT '角色id，xm_bulky_role.id',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '用户id，xm_admin.userid',
  `user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '登录账号，限20字',
  `nickname` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '姓名，限16字',
  `is_sub` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为子账号 0:否; 1:是;',
  `perm_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '权限配置{\"baseConfig\":[],\"expressConfig\":[]}',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_userId_roleId`(`user_id` ASC, `role_id` ASC) USING BTREE,
  INDEX `idx_role_id`(`role_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 971 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货用户角色表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_ban_supplier
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_ban_supplier`;
CREATE TABLE `xm_bulky_ban_supplier`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1270 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户拉黑的供应商' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_bank_account
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_bank_account`;
CREATE TABLE `xm_bulky_bank_account`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `payee_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '对公对私标志 0:对公; 1:个人; 默认个人',
  `account_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '银行卡号（不重复），限32字',
  `owner_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '持有人名称，限50字',
  `bank_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '总行联行号，限50字',
  `bank_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '总行名称，限128字',
  `account_bank_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '银行名称，限50字',
  `account_bank_address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收款账号分行',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_account_no`(`account_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货银行账户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_bank_transfer_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_bank_transfer_record`;
CREATE TABLE `xm_bulky_bank_transfer_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `biz_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '提现打款主体 0-无 1-梦晟 2-昆明寻梦 xm_bulky_withdraw_payer.id',
  `payer_type` tinyint UNSIGNED NOT NULL COMMENT '付款方账户类型 1:工商银行; 2:支付宝;',
  `payer_account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '付款方账号，限64字',
  `payer_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '付款方账户名称，限100字',
  `amount` decimal(20, 2) UNSIGNED NOT NULL COMMENT '金额（元）',
  `supplier_id` bigint UNSIGNED NOT NULL COMMENT '供应商id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供应商名称',
  `account_id` bigint UNSIGNED NOT NULL COMMENT 'account表主键id',
  `payee_account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款方账号',
  `payee_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款方账户名称',
  `payee_bank_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款方总行联行号',
  `payee_bank_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款方总行名称',
  `payee_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '对公对私标志：0：对公；1：个人',
  `record_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '提现编码',
  `f_seq_no` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '指令包序列号',
  `uni_busi_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '业务唯一编号',
  `i_seq_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '指令序号',
  `serial_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台交易流水号（指令编号），限64字',
  `pay_desc` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交易摘要',
  `pay_site` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交易场所',
  `remark` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '交易状态 -1:失败; 0:已提交打款; 1:打款成功;',
  `status_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '交易状态描述，限255字',
  `pay_resp` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '提交打款接口返回结果',
  `operator_id` bigint UNSIGNED NOT NULL COMMENT '操作用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作用户名称',
  `success_time` datetime NULL DEFAULT NULL COMMENT '银行打款成功时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_payee_bank_no`(`payee_bank_no` ASC) USING BTREE,
  INDEX `idx_record_code`(`record_code` ASC) USING BTREE,
  INDEX `idx_i_seq_no`(`i_seq_no` ASC) USING BTREE,
  INDEX `idx_ctime_status`(`create_time` ASC, `status` ASC) USING BTREE,
  INDEX `idx_status_time`(`status` ASC, `data_status` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11059 AVG_ROW_LENGTH = 671 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货银行转账记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_banner
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_banner`;
CREATE TABLE `xm_bulky_banner`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）城市仓id 默认0',
  `router_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '跳转类型 1:网站; 2:一级分类; 3:二级分类 4:商品 5:公告 6:小程序链接 7:小时达分类',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'banner标题',
  `image` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'banner图url地址',
  `color_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '颜色代码，#FF79BC',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'banner图跳转的地方 可能是链接，商品、分类',
  `is_show` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否展示 0：隐藏 1：展示',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序 升序',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 91 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货banner图表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_base_config
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_base_config`;
CREATE TABLE `xm_bulky_base_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '基地名称 限16字',
  `short_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '（唯一）基地简称 限10字',
  `area_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '所属片区id(hub_area.id) 0-未分配',
  `area_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `area_leader` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `contact_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系电话 限20字',
  `station_fee` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '集货站运费（元/扎）',
  `call_fee_standard` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `dounan_avg_duration_minutes` int UNSIGNED NOT NULL DEFAULT 0,
  `single_base_task_avg_duration_minutes` int UNSIGNED NOT NULL DEFAULT 0,
  `multi_base_task_avg_duration_minutes` int UNSIGNED NOT NULL DEFAULT 0,
  `avg_departure_time` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `credit_require` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '保证金要求（元）',
  `sequence` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序 升序',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-正常 1-停用',
  `latest_check_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最晚签到时间 HH:mm:ss',
  `late_auto_punish` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '迟到是否自动处罚 0-否 1-是',
  `single_punish_amount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '单次处罚金额',
  `longitude` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `address` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '地址',
  `adcode` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'adcode',
  `helper` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '助理信息',
  `outsource_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否外包 0-否 1-是',
  `outsource_user_id` bigint NULL DEFAULT NULL COMMENT '外包负责人子账号id(xm_bulky_sub_account.id)，使用现有【基地入场员】角色',
  `outsource_user_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外包负责人姓名(冗余，用于列表展示)',
  `base_volume` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '外包基础货量标准(扎/场次)',
  `base_salary` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '外包基础月薪(元/月)',
  `subsidy_unit_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '超出基础货量补贴收益单价(元/扎)',
  `outsource_income_rule_id` bigint NULL DEFAULT NULL COMMENT '当前外包收益规则ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sn`(`short_name` ASC) USING BTREE,
  UNIQUE INDEX `uk_base_outsource_user`(`outsource_user_id` ASC) USING BTREE,
  INDEX `idx_area_id`(`area_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 61 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '基地配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_base_outsource_income
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_base_outsource_income`;
CREATE TABLE `xm_bulky_base_outsource_income`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次编号：yyyy-MM-dd',
  `base_id` bigint NOT NULL COMMENT '基地id',
  `base_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基地名称',
  `user_id` bigint NOT NULL COMMENT '外包人员子账号userId',
  `income_rule_id` bigint NULL DEFAULT NULL COMMENT '本次计算使用的外包收益规则ID',
  `total_num` int NOT NULL DEFAULT 0 COMMENT '基地当日总货量',
  `base_volume` int NOT NULL DEFAULT 0 COMMENT '基础货量',
  `subsidy_volume` int NOT NULL DEFAULT 0 COMMENT '补贴货量 max(total_num-base_volume,0)',
  `subsidy_unit_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '补贴单价',
  `base_salary` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '基础工资（场次底薪）',
  `session_income` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '场次收益 = base_salary + subsidy_volume * subsidy_unit_price',
  `settle_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否结算 0-未结算 1-已结算',
  `settle_supplier_id` bigint NULL DEFAULT 0 COMMENT '结算到的供应商id',
  `settle_time` datetime NULL DEFAULT NULL COMMENT '结算时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_base_round`(`base_id` ASC, `round_no` ASC) USING BTREE,
  INDEX `idx_user_round`(`user_id` ASC, `round_no` ASC) USING BTREE,
  INDEX `idx_settle_round`(`settle_flag` ASC, `round_no` ASC) USING BTREE,
  INDEX `idx_income_rule_id`(`income_rule_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '基地外包场次收益表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_base_outsource_income_rule
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_base_outsource_income_rule`;
CREATE TABLE `xm_bulky_base_outsource_income_rule`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `base_id` bigint NOT NULL COMMENT '基地ID',
  `rule_version` int NOT NULL COMMENT '基地内规则版本号',
  `base_salary` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '基础工资（元/月）',
  `level_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '阶梯区间标准化JSON（MySQL 5.6字符串存储）',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人ID',
  `operator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常 -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_base_rule_version`(`base_id` ASC, `rule_version` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '基地外包收益规则快照表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_burial_point
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_burial_point`;
CREATE TABLE `xm_bulky_burial_point`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '埋点类型 1：修改昵称入口的点击次数 2：1. 通过修改昵称进入修改成功昵称账号数量 ',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '请求IP',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '透传埋点数据',
  `count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '次数',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pid_type`(`purchaser_id` ASC, `type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9189 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '埋点统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_cart
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_cart`;
CREATE TABLE `xm_bulky_cart`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `product_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品类型 废弃字段',
  `is_hour_delivery` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否是小时达 0: 不是 1：是',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小时达wareId 0大件批发 大于0小时达',
  `platform` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '平台 0：大件批发 1：花仓库',
  `is_sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否代卖购物车 0：不是 1：是',
  `partner_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `product_id` bigint NOT NULL COMMENT '商品id',
  `product_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `supplier_id` bigint NOT NULL COMMENT '供应商id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品主图',
  `in_price` decimal(20, 2) NOT NULL COMMENT '加入购物车的价格',
  `buy_count` int NOT NULL COMMENT '购买数量',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态：0：默认 -1：已提交 -100：已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 909027875 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货购物车表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_category
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_category`;
CREATE TABLE `xm_bulky_category`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自动增长ID',
  `ware_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '仓库类型 0-寻梦批发 1-城市仓',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类名',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类图标',
  `router_type` tinyint UNSIGNED NOT NULL DEFAULT 2 COMMENT '跳转类型 1:网站; 2:一级分类; 3:二级分类 4:商品 5:小程序页面',
  `redirect` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '跳转的页面',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '显示顺序，升序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `last_operator_id` bigint NOT NULL COMMENT '最后操作的用户id',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态；0：正常；-100：删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 49 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大厅页面 分类信息类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_channel
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_channel`;
CREATE TABLE `xm_bulky_channel`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '渠道名称',
  `channel_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '渠道id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '地推渠道信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_channel_user_info
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_channel_user_info`;
CREATE TABLE `xm_bulky_channel_user_info`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `channel_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '渠道id',
  `open_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信openid',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最后一次登录时间',
  `last_login_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最后一次登录ip',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态 0:正常 -100删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_channel_id_open_id`(`channel_id` ASC, `open_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '渠道用户信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_chat_chat_message
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_chat_chat_message`;
CREATE TABLE `xm_bulky_chat_chat_message`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `conversation_id` bigint NOT NULL COMMENT '关联conversation.id',
  `sender_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户类型',
  `sender_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发送人ID（商家ID/用户ID）',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '消息内容',
  `msg_subtype` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息子类型：TEXT/IMAGE/VIDEO/CARD',
  `extra_json` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扩展字段（订单卡片/图片URL等）',
  `client_msg_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户端消息ID，用于重试幂等/消息对账',
  `send_time` datetime NOT NULL COMMENT '发送时间',
  `is_revoke` tinyint NULL DEFAULT 0 COMMENT '是否撤回：0否 1是',
  `revoke_time` datetime NULL DEFAULT NULL COMMENT '撤回时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sender_client_msg`(`sender_type` ASC, `sender_id` ASC, `client_msg_id` ASC) USING BTREE,
  INDEX `idx_conv_time`(`conversation_id` ASC, `send_time` ASC) USING BTREE,
  INDEX `idx_sender_in_conv`(`conversation_id` ASC, `sender_type` ASC, `sender_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1765 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '聊天消息内容（单聊/群聊统一表）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_chat_conversation
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_chat_conversation`;
CREATE TABLE `xm_bulky_chat_conversation`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '会话ID',
  `con_type` tinyint NOT NULL COMMENT '1=单聊(商家-用户), 2=群聊, 3=系统通知会话(虚拟)',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户类型',
  `msg_type` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息枚举类型;用户端:订单:1,物流:2,售后:3,会员:4,活动:5,通知:6\r\n供应商端:账号:7,商品:8,订单:9,配换货:10,处罚:11,售后:12,开票:13',
  `source_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发起方ID（商家ID/系统/花店）',
  `target_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '接收方类型',
  `target_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '接收方ID（用户ID）',
  `last_msg_content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最后消息预览（系统通知/聊天）',
  `last_msg_time` datetime NULL DEFAULT NULL COMMENT '最后消息时间用于排序',
  `last_msg_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '消息类型（TEXT/IMAGE/CARD）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_single_chat`(`source_type` ASC, `source_id` ASC, `target_type` ASC, `target_id` ASC, `con_type` ASC, `msg_type` ASC) USING BTREE,
  INDEX `idx_target`(`target_id` ASC, `msg_type` ASC, `target_type` ASC, `con_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 275728 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会话索引（统一消息流入口）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_chat_conversation_user
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_chat_conversation_user`;
CREATE TABLE `xm_bulky_chat_conversation_user`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `conversation_id` bigint NOT NULL COMMENT '关联conversation.id',
  `user_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户类型',
  `user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会话内用户ID',
  `unread_count` int NULL DEFAULT 0 COMMENT '该用户在该会话的未读数',
  `target_avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对方头像',
  `target_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对方名称',
  `top_flag` tinyint NULL DEFAULT 0 COMMENT '是否置顶,用户手动置顶',
  `top_time` datetime NULL DEFAULT NULL COMMENT '置顶时间用于判断多条置顶的顺序',
  `last_read_message_id` bigint NULL DEFAULT NULL COMMENT '最后已读消息ID用于一次性跳转到最后一次已读',
  `mute_flag` tinyint NULL DEFAULT 0 COMMENT '是否免打扰：0否 1是',
  `delete_flag` tinyint NULL DEFAULT 0 COMMENT '会话是否已删除：0正常 1删除,重新进入会话变为正常',
  `delete_time` datetime NULL DEFAULT NULL COMMENT '会话删除时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_conv_user`(`conversation_id` ASC, `user_type` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_user_conv`(`user_type` ASC, `user_id` ASC, `conversation_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 376728 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会话-用户关系（会话级状态管理）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_chat_message_template
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_chat_message_template`;
CREATE TABLE `xm_bulky_chat_message_template`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '模板ID',
  `biz_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务类型(消息类型子类型)',
  `msg_type` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息枚举类型;用户端:订单:1,物流:2,售后:3,会员:4,活动:5,通知:6\r\n供应商端:账号:7,商品:8,订单:9,配换货:10,处罚:11,售后:12,开票:13',
  `title_template` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题模板（含占位符，如：订单{order_id}已支付）',
  `content_template` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '内容模板（含占位符，如：您的订单{order_id}已支付，金额{amount}元）',
  `status` tinyint(1) UNSIGNED ZEROFILL NULL DEFAULT 1 COMMENT '是否激活：0-停用 1-启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_people` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_people` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改者',
  `extra_json` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扩展字段',
  `path` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '跳转路径',
  `btn_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '跳转按钮名称',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_biz_msg`(`biz_type` ASC, `msg_type` ASC) USING BTREE,
  INDEX `idx_msg`(`msg_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 70 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '消息模板配置表（动态拼接消息内容）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_chat_private_permission
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_chat_private_permission`;
CREATE TABLE `xm_bulky_chat_private_permission`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户类型：USER/SUPPLIER',
  `user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户名',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'NORMAL' COMMENT '权限状态：NORMAL/RESTRICTED/DISABLED',
  `mute_start_time` datetime NULL DEFAULT NULL COMMENT '禁言开始时间',
  `mute_end_time` datetime NULL DEFAULT NULL COMMENT '禁言结束时间',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原因',
  `operator_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user`(`user_type` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_mute_end_time`(`mute_end_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '私聊权限表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_chat_sys_message
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_chat_sys_message`;
CREATE TABLE `xm_bulky_chat_sys_message`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `msg_type` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息枚举类型;用户端:订单:1,物流:2,售后:3,会员:4,活动:5,通知:6\r\n供应商端:账号:7,商品:8,订单:9,配换货:10,处罚:11,售后:12,开票:13',
  `biz_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务类型(消息类型子类型)  ',
  `biz_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务ID（如订单ID）',
  `biz_unique_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务幂等键（防止重复发送）',
  `sender_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发送者类型',
  `sender_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发送者ID（SYSTEM/商家ID/花店等）',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '消息标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息内容（系统通知正文）',
  `extra_json` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扩展字段（订单ID/跳转参数等）',
  `success_count` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '总发送数',
  `revoke_status` tinyint NULL DEFAULT 0 COMMENT '撤回状态：0正常 1已撤回',
  `revoke_time` datetime NULL DEFAULT NULL COMMENT '撤回时间',
  `send_time` datetime NOT NULL COMMENT '发送时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_biz`(`biz_type` ASC, `biz_id` ASC) USING BTREE,
  INDEX `idx_type`(`msg_type` ASC) USING BTREE,
  INDEX `idx_send_time`(`send_time` ASC) USING BTREE,
  INDEX `idx_revoke`(`revoke_status` ASC) USING BTREE,
  INDEX `idx_sender`(`sender_type` ASC, `sender_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 103656 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '系统通知/业务消息主体' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_chat_user_message
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_chat_user_message`;
CREATE TABLE `xm_bulky_chat_user_message`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户类型',
  `user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '接收人ID（用户ID）',
  `send_time` datetime NULL DEFAULT NULL COMMENT '消息发送时间(冗余)',
  `message_id` bigint NOT NULL COMMENT '关联message.id',
  `msg_type` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '冗余消息类型，用于快速查询过滤',
  `biz_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务类型',
  `read_status` tinyint NULL DEFAULT 0 COMMENT '0未读 1已读',
  `read_time` datetime NULL DEFAULT NULL COMMENT '阅读时间',
  `delete_flag` tinyint NULL DEFAULT 0 COMMENT '0正常 1已删除',
  `delete_time` datetime NULL DEFAULT NULL COMMENT '删除时间',
  `revoke_flag` tinyint NULL DEFAULT 0 COMMENT '0未撤回 1已撤回（独立于message表）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_msg`(`user_type` ASC, `user_id` ASC, `message_id` ASC) USING BTREE,
  INDEX `idx_user_read`(`user_id` ASC, `read_status` ASC) USING BTREE,
  INDEX `idx_user_time`(`user_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_user_msg_full`(`user_id` ASC, `user_type` ASC, `msg_type` ASC, `read_status` ASC, `send_time` ASC) USING BTREE,
  INDEX `idx_message_id`(`message_id` ASC) USING BTREE,
  INDEX `idx_userid_msgtype_usertype_deleteflag_sendtime`(`user_id` ASC, `msg_type` ASC, `user_type` ASC, `delete_flag` ASC, `send_time` ASC) USING BTREE,
  INDEX `idx_cleanup_send_time_id`(`send_time` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 376735 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户消息状态（含撤回标记）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_city_customer_daily_statistics
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_city_customer_daily_statistics`;
CREATE TABLE `xm_bulky_city_customer_daily_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `stat_date` date NOT NULL COMMENT '统计日期，按订单或售后创建时间归属自然日',
  `ware_id` int UNSIGNED NOT NULL COMMENT '城市仓ID',
  `purchaser_id` bigint UNSIGNED NOT NULL COMMENT '采购方ID',
  `total_consumption` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '订单消费金额合计',
  `item_num` bigint NOT NULL DEFAULT 0 COMMENT '订单扎数合计，取total_item_num',
  `order_count` bigint NOT NULL DEFAULT 0 COMMENT '有效下单次数，同一用户同一城市仓同一天计1次',
  `purchase_count` bigint NOT NULL DEFAULT 0 COMMENT '合并购买次数，按场次和收货地址去重，仅用于售后订单比例',
  `after_sale_count` bigint NOT NULL DEFAULT 0 COMMENT '成功售后单数',
  `after_sale_amount` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '成功售后退款金额',
  `after_sale_purchase_count` bigint NOT NULL DEFAULT 0 COMMENT '合并购买中已成功售后的次数，仅用于售后订单比例',
  `after_sale_purchase_amount` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '合并购买产生的成功售后退款金额，仅用于售后金额比例',
  `first_buy_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '该日最早购买时间，跨日聚合为用户在该仓首次购买时间',
  `last_buy_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '该日最近购买时间，跨日聚合为用户在该仓最近购买时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_stat_date_ware_purchaser`(`stat_date` ASC, `ware_id` ASC, `purchaser_id` ASC) USING BTREE,
  INDEX `idx_ware_purchaser_date`(`ware_id` ASC, `purchaser_id` ASC, `stat_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 66445 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市仓客户日汇总' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_city_second_subsidy
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_city_second_subsidy`;
CREATE TABLE `xm_bulky_city_second_subsidy`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `city_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '市id',
  `adcode` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市行政编码',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级id',
  `subsidy_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '补贴品种数量',
  `subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '补贴单价',
  `supplier_perm` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商类型权限',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_cityid_secondid`(`city_id` ASC, `second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 69 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市二级分类单品补贴配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
