  `sku_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '补贴sku数量',
  `max_subsidy` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '每场次补贴金额上限',
  `round_subsidy` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次临时补贴上限json',
