  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_cityid`(`city_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 121 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '城市单品补贴日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_city_subsidy_product
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_city_subsidy_product`;
CREATE TABLE `xm_bulky_city_subsidy_product`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `adcode` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市adcode',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '补贴金额',
  `record_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '本条记录key=adcode_second_id_rank_num，方便查找更新',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '默认0正常 -100删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_adcode_secondid`(`adcode` ASC, `second_id` ASC) USING BTREE,
  INDEX `uk_adcode_pid`(`adcode` ASC, `product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 58 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_class_first
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_class_first`;
CREATE TABLE `xm_bulky_class_first`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '一级分类名称，限50字',
  `sequence` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）一级分类排序 数字越大排位越靠前',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序值 升序',
  `tag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '一级分类标签，限10字',
  `tag_start_time` datetime NULL DEFAULT NULL COMMENT '标签展示开始时间',
  `tag_end_time` datetime NULL DEFAULT NULL COMMENT '标签展示结束时间',
  `notice` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '一级分类横幅，如果为空就展示notice表type=0的横幅，限1024字',
  `guide` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '养护指南',
  `class_kind` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '分类种类 1-正常分类（永久分类） 2-活动分类',
  `class_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '分类类型 1:外部类型; 2:内部类型;',
  `spec_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '规格展示开关 0-否 1-是',
  `sort_kind` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '二级分类排序方式 1-按销量排 2-按品种排 3-手动排序',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `group_tag_id` bigint NOT NULL DEFAULT 0 COMMENT '标签体系重构-默认标签组id，0表示未关联',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sequence`(`sequence` ASC) USING BTREE,
  INDEX `idx_sortnum`(`sort_num` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 130 AVG_ROW_LENGTH = 240 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货一级分类表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_class_second
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_class_second`;
CREATE TABLE `xm_bulky_class_second`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级分类id 0为未指定一级分类',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级分类名称，限50字',
  `class_tag` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级分类标签，限50字',
  `rank_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '等级区分开关 0-无等级 1-区分等级',
  `relate_first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '关联一级分类id',
  `relate_first_id_str` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '关联一级分类id列表 逗号拼接',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级分类图片',
  `notice` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级分类横幅，限1024字',
  `sequence` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）分类排序 数字越大排位越靠前',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序值 升序',
  `today_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类今日销量',
  `last_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类上一场次销量',
  `month_sell_count` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类下所有商品近30天销量和',
  `sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销量',
  `ka_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT 'KA销量',
  `stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '库存',
  `spec_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '规格数字',
  `spec` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格单位 如：枝/扎',
  `pack` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '包装 如：瓦楞纸+细网',
  `color_lib_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT 'color_lib表主键id',
  `sku_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `rank_str` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '（即将废弃）等级ABCDE',
  `weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '（即将废弃）重量(g/扎)',
  `volume` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '（即将废弃）体积(cm3)',
  `pack_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（即将废弃）基础打包费',
  `service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '基础服务费',
  `take_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台抽点单价（KA订单抽点）',
  `min_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '最小供货价',
  `max_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '最大供货价',
  `credit_require` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 1000.00 COMMENT '保证金要求，默认1000',
  `class_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '分类类型 1:外部类型; 2:内部类型;',
  `guide` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '养护指南',
  `is_open_price_mgr` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类是否开启价目管理  0不是 1:是 ',
  `quality_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否品质花材筛选 0-否 1-是',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_first_id`(`first_id` ASC) USING BTREE,
  INDEX `idx_name_datastatus`(`name` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13827 AVG_ROW_LENGTH = 350 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货二级分类表' ROW_FORMAT = DYNAMIC;

