-- ----------------------------
-- Table structure for xm_bulky_class_second_rank_sku
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_class_second_rank_sku`;
CREATE TABLE `xm_bulky_class_second_rank_sku`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `second_id` bigint UNSIGNED NOT NULL COMMENT '二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL COMMENT '等级123456->ABCDEO',
  `weight` int UNSIGNED NOT NULL COMMENT '重量(g/扎)',
  `volume` decimal(14, 5) NOT NULL DEFAULT 3000.00000 COMMENT '体积(cm³/扎)，保留Excel原始精度',
  `add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加价（元）',
  `description` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '描述',
  `avg_price` decimal(10, 2) UNSIGNED NULL DEFAULT 0.00 COMMENT '近两小时售出均价（元）',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_second_id_rank_num`(`second_id` ASC, `rank_num` ASC) USING BTREE,
  INDEX `idx_second_id`(`second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 48676 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货二级分类等级sku表' ROW_FORMAT = Dynamic;

