  `relation_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '关联二级分类id',
  `relation_alias` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '关联别名',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_secondid_relationid`(`second_id` ASC, `relation_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 213 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货二级分类关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_class_second_sort
