) ENGINE = InnoDB AUTO_INCREMENT = 2996 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '一级分类下二级分类手动排序表' ROW_FORMAT = Dynamic;

