-- ----------------------------
-- Table structure for xm_bulky_class_tag_rule
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_class_tag_rule`;
CREATE TABLE `xm_bulky_class_tag_rule`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 1-一级分类 2-二级分类',
  `class_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分类id 一级分类id或二级分类id',
  `tag_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '标签id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_classid_type_tagid`(`class_id` ASC, `type` ASC, `tag_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 87 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货分类标签规则表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_coin_detail_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_coin_detail_log`;
CREATE TABLE `xm_bulky_coin_detail_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `purchaser_id` bigint UNSIGNED NOT NULL COMMENT '采购方用户id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单编号',
  `business_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0：入账增加，1：出账减少，默认：0',
  `xm_coin_give` decimal(10, 2) UNSIGNED NOT NULL COMMENT '补贴的金额',
  `xm_coin_rebate` decimal(10, 2) NOT NULL COMMENT '返点的金额',
  `xm_coin_paid` decimal(10, 2) UNSIGNED NOT NULL COMMENT '赔付的金额',
  `reason` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '动账原因 0:花材返点; 1:订单支付; 2:订单退款; 3:赔付返还; 4:平台运费退款; 5:已完成订单退款扣除返点寻梦币; 6:取消未支付订单退回预扣寻梦币; 7:补贴; 8:多补扣除; 默认:0',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE COMMENT '订单号'
) ENGINE = InnoDB AUTO_INCREMENT = 19303 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦币动账超详细记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_coin_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_coin_log`;
CREATE TABLE `xm_bulky_coin_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `purchaser_id` bigint UNSIGNED NOT NULL COMMENT '采购方用户id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单编号',
  `refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后退款id',
  `origin_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0：大件批发平台记录 1：寻梦平台补贴等记录',
  `business_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0：入账增加，1：出账减少，默认：0',
  `old_money` decimal(20, 2) UNSIGNED NOT NULL COMMENT '动账前余额',
  `money` decimal(10, 2) NOT NULL COMMENT '变动余额',
  `new_money` decimal(20, 2) UNSIGNED NOT NULL COMMENT '新余额',
  `reason` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '动账原因 0:花材返点; 1:订单支付; 2:订单退款; 3:赔付返还; 4:平台运费退款; 5:已完成订单退款扣除返点寻梦币; 6:取消未支付订单退回预扣寻梦币; 7:补贴; 8:多补扣除; 9:发货单退运费 默认:0',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注，最大长度255',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_ctime_btype_reason`(`create_time` ASC, `business_type` ASC, `reason` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21721 AVG_ROW_LENGTH = 107 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦币动账记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_cold_contact_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_cold_contact_log`;
CREATE TABLE `xm_bulky_cold_contact_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `cold_stock_id` bigint NOT NULL COMMENT '冷库库存主表id',
  `purchaser_id` bigint NOT NULL COMMENT '客户id',
  `ship_confirm` tinyint NULL DEFAULT NULL COMMENT '联系结果 1:今日出库 2:继续暂存 3:联系不上 4:取消暂存',
  `next_plan_ship_date` date NULL DEFAULT NULL COMMENT '下次计划发货日期',
  `content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '联系内容',
  `image_urls` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '图片url(逗号分隔)',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '登记人id',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '登记人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_cold_stock_id`(`cold_stock_id` ASC) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 220 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '冷库暂存客服联系记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_cold_out_task
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_cold_out_task`;
CREATE TABLE `xm_bulky_cold_out_task`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `cold_stock_id` bigint NOT NULL COMMENT '冷库库存主表id',
  `out_type` tinyint NOT NULL COMMENT '出库方式 1:关联发货单 2:直接出库 3:转代卖',
  `purchaser_id` bigint NOT NULL COMMENT '客户id',
  `store_type` tinyint NOT NULL COMMENT '暂存类型(冗余) 1:包裹 2:裸花',
  `link_send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联发货单号(out_type=1)',
  `link_purchaser_nick` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联发货单客户昵称',
  `link_purchaser_mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联发货单客户注册手机号',
  `link_receive_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联发货单收货人',
  `link_receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联发货单收货电话',
  `link_receive_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联发货单收货地址',
  `link_shelf_sn` int NULL DEFAULT NULL COMMENT '关联发货单主货位号',
  `link_sub_shelf_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联发货单子货位号',
  `link_zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联发货单区-货位号',
  `out_package_num` int NOT NULL DEFAULT 0 COMMENT '本次出库包裹数',
  `out_bunch_num` int NOT NULL DEFAULT 0 COMMENT '本次出库裸花扎数',
  `finish_bunch_num` int NULL DEFAULT NULL COMMENT '仓库确认最终出库扎数(转代卖任务)',
  `box_repack_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否拆箱重打 0:否 1:是',
  `express_id` bigint NULL DEFAULT NULL COMMENT '发货物流id(直接出库)',
  `express_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发货物流名称',
  `task_status` tinyint NOT NULL DEFAULT 10 COMMENT '任务状态 10:待出库 15:出库中 20:已出库 30:已撤销',
  `out_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '出库备注',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '客服操作人id',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客服操作人姓名',
  `operator_mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客服操作人手机号',
  `operate_time` datetime NULL DEFAULT NULL COMMENT '操作时间',
  `finish_user_id` bigint NULL DEFAULT NULL COMMENT '仓管出库完成人id',
  `finish_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '仓管出库完成人姓名',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '出库完成时间',
  `finish_image_urls` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '出库照片(逗号分隔url)',
  `finish_remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '出库备注',
  `cancel_user_id` bigint NULL DEFAULT NULL COMMENT '撤销人id',
  `cancel_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '撤销人姓名',
  `cancel_time` datetime NULL DEFAULT NULL COMMENT '撤销时间',
  `cancel_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '撤销原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_cold_stock_id`(`cold_stock_id` ASC) USING BTREE,
  INDEX `idx_link_send_no`(`link_send_no` ASC) USING BTREE,
  INDEX `idx_task_status`(`task_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 680 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '冷库暂存出库任务' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_cold_out_task_package
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_cold_out_task_package`;
CREATE TABLE `xm_bulky_cold_out_task_package`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `out_task_id` bigint NOT NULL COMMENT '出库任务id',
  `cold_stock_package_id` bigint NOT NULL COMMENT '冷库暂存包裹明细id',
  `express_package_id` bigint NOT NULL COMMENT '包裹表id',
  `package_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '包裹码',
  `box_repack_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否拆箱重打 0:否 1:是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_out_task_id`(`out_task_id` ASC) USING BTREE,
  INDEX `idx_express_package_id`(`express_package_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1278 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '冷库暂存出库任务包裹明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_cold_stock
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_cold_stock`;
CREATE TABLE `xm_bulky_cold_stock`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint NOT NULL COMMENT '客户(采购方)id xm_bulky_purchaser.id',
  `purchaser_mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户注册手机号(冗余)',
  `purchaser_nick` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户昵称(冗余)',
  `ware_id` bigint NULL DEFAULT NULL COMMENT '城市仓id city_warehouse.id，城市仓货架暂存时有值',
  `store_type` tinyint NOT NULL COMMENT '暂存类型 1:包裹暂存 2:裸花暂存',
  `store_round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '暂存场次 yyyy-MM-dd',
  `location_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '暂存货位号 如 #01-005',
  `origin_send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '暂存货物原发货单号',
  `source_enter_item_id` bigint NULL DEFAULT NULL COMMENT '裸花扫码对应入场花材id',
  `image_urls` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '入库照片，逗号分隔',
  `stock_key` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '活动库存唯一键，出清后置空',
  `package_total` int NOT NULL DEFAULT 0 COMMENT '包裹暂存:总包裹数',
  `package_out` int NOT NULL DEFAULT 0 COMMENT '已出库包裹数',
  `bunch_num` int NOT NULL DEFAULT 0 COMMENT '裸花扎数',
  `remaining_bunch_num` int NULL DEFAULT NULL COMMENT '剩余扎数，仓库确认实际出库后扣减',
  `stock_status` tinyint NOT NULL DEFAULT 10 COMMENT '库存状态 10:待发货 20:待关联 30:已关联 40:待出库 50:已出库',
  `ship_confirm` tinyint NULL DEFAULT NULL COMMENT '最新发货确认 1:今日出库 2:继续暂存 3:联系不上 4:取消暂存',
  `plan_ship_date` date NULL DEFAULT NULL COMMENT '计划发货日期(空=客户通知发货)',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户备注',
  `in_user_id` bigint NULL DEFAULT NULL COMMENT '入库人id(仓库登记)',
  `in_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '入库人姓名',
  `in_time` datetime NULL DEFAULT NULL COMMENT '入库时间',
  `service_user_id` bigint NULL DEFAULT NULL COMMENT '关联客服id',
  `service_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联客服姓名',
  `abnormal_flag` tinyint NOT NULL DEFAULT 0 COMMENT '异常标记 0:正常 1:异常',
  `abnormal_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '异常说明',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_active_stock_key`(`stock_key` ASC) USING BTREE,
  INDEX `idx_purchaser`(`purchaser_id` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_purchaser_mobile`(`purchaser_mobile` ASC) USING BTREE,
  INDEX `idx_stock_status`(`stock_status` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_store_round_no`(`store_round_no` ASC) USING BTREE,
  INDEX `idx_origin_send_no`(`origin_send_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 840 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '冷库暂存库存主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_cold_stock_package
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_cold_stock_package`;
CREATE TABLE `xm_bulky_cold_stock_package`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `cold_stock_id` bigint NOT NULL COMMENT '冷库库存主表id',
  `express_package_id` bigint NOT NULL COMMENT '关联 xm_bulky_wms_express_package.id',
  `package_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '包裹码',
  `origin_round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '原场次(跨场次记录)',
  `location_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '货位',
  `pkg_status` tinyint NOT NULL DEFAULT 10 COMMENT '明细状态 10:暂存中 15:待出库锁定 20:已出库 30:已打包无需出库',
  `in_user_id` bigint NULL DEFAULT NULL COMMENT '扫码入库人id',
  `in_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '扫码入库人姓名',
  `in_time` datetime NULL DEFAULT NULL COMMENT '扫码入库时间',
  `out_task_id` bigint NULL DEFAULT NULL COMMENT '关联出库任务id',
  `out_user_id` bigint NULL DEFAULT NULL COMMENT '出库人id(扫码/整单出库为仓库人员，拆箱重打为客服)',
  `out_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '出库人姓名',
  `out_time` datetime NULL DEFAULT NULL COMMENT '出库时间',
  `active_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '活动包裹唯一键，出库后置空',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_active_package_key`(`active_key` ASC) USING BTREE,
  INDEX `idx_express_package_id`(`express_package_id` ASC) USING BTREE,
  INDEX `idx_package_code`(`package_code` ASC) USING BTREE,
  INDEX `idx_stock_package`(`cold_stock_id` ASC, `express_package_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1594 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '冷库暂存包裹明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_color_lib
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_color_lib`;
CREATE TABLE `xm_bulky_color_lib`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `color_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '颜色名称',
  `color_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '颜色参考代码，#FF79BC',
  `pic_url` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '颜色图片',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 59 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货颜色表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_common
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_common`;
CREATE TABLE `xm_bulky_common`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` tinyint UNSIGNED NOT NULL COMMENT '类型 1:运费预收系数 2:服务费单价 3:极速退款时间 11:自营店返点 12:头部商家返点 13:一级合作返点 14:二级及以下返点 21:商品加价规则',
  `type_str` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '类型说明',
  `price` decimal(10, 3) UNSIGNED NOT NULL DEFAULT 0.000 COMMENT '值 type=21时，0:按rank表加价 1:阶梯加价',
  `config_str` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配置json 默认空串',
  `tips` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配置含义',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_type`(`type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 74 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货全局变量' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_complain
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_complain`;
CREATE TABLE `xm_bulky_complain`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型 1-供应商端',
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '平台 1-批发 2-城市仓 3-分销商',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `complain_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '申诉类型 1.商品申诉 2.售后申诉 3:处罚申诉',
  `punish_link` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '处罚环节 0：售后处罚 1：质检处罚 2:代卖处罚',
  `relate_id` bigint NOT NULL COMMENT '申诉关联id',
  `supplier_tag` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '基地名称',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '申诉理由',
  `reason_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后申诉类型',
  `appeal_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '诉求类型',
  `appeal_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '诉求说明',
  `pictures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '申诉图片',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人ID',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `operation_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作内容',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型： 1:申诉中 2.申诉同意 3.申诉拒绝',
  `return_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申诉退回金额',
  `account_change_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_supplier_account_change.id',
  `subsidy_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '补款金额',
  `subsidy_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '补款扎数',
  `subsidy_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补款id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `handle_time` datetime NULL DEFAULT NULL COMMENT '处理时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_userid`(`user_id` ASC) USING BTREE,
  INDEX `idx_cptype_ctime`(`complain_type` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_handletime`(`handle_time` ASC, `partner_id` ASC, `ware_id` ASC) USING BTREE,
  INDEX `idx_rid_ctype`(`relate_id` ASC, `complain_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 930000036 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '申诉表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_contact
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_contact`;
CREATE TABLE `xm_bulky_contact`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `ware_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）仓库类型 0-寻梦批发 1-城市仓 2-供应商',
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `type` tinyint UNSIGNED NOT NULL COMMENT '类型 1:客服微信; 2:企业微信; 3:客服QQ; 4:客服电话; 5:投诉电话;',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称，限20字',
  `icon` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '客服图标URL',
  `pic_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片列表',
  `qq` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'QQ，限20字符',
  `phone` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电话，限512字符',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注，限255字符',
  `work_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '工作时间 限32字',
  `wx_link` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信链接 限128字',
  `link_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '链接名称 限20字',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 301 AVG_ROW_LENGTH = 216 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货联系信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_contact_supplier_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_contact_supplier_log`;
CREATE TABLE `xm_bulky_contact_supplier_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购端用户id',
  `order_sn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商用户id',
  `supplier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `op` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认0:消耗次数  1:增加次数',
  `times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '消耗或增加的次数',
  `contact_date` date NULL DEFAULT NULL COMMENT '联系日期，若增加次数，则为空',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建日期',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新日期',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_supplier_id_op`(`user_id` ASC, `supplier_id` ASC, `op` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 333 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '花店联系供应商日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_coupon
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_coupon`;
CREATE TABLE `xm_bulky_coupon`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `coupon_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '优惠券编号（唯一）',
  `coupon_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '优惠券名称，限20字符',
  `description` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '优惠券描述，限128字符',
  `coupon_type` tinyint UNSIGNED NOT NULL COMMENT '优惠券类型 1:立减券; 2:满减券; 3:扎数满减券; 4:折扣券',
  `discount_rate` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '折扣券折扣率',
  `discount_max_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '最高折扣金额',
  `coupon_price` decimal(8, 2) UNSIGNED NOT NULL COMMENT '优惠券金额',
  `limit_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '使用扎数门槛',
  `limit_price` decimal(8, 2) UNSIGNED NOT NULL COMMENT '使用门槛金额（立减券时为0）',
  `limit_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '领取规则 0:限领 >0:每n天限领',
  `limit_count` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '限领数量，小于5',
  `coupon_source` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '发券方 1-平台 2-城市仓 3-分销商',
  `coupon_channel` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '优惠券渠道 1-寻梦批发 2-花仓酷 3-分销商 4-博纳资材',
  `biz_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '业务类型 1-花材 2-花材积分商城 3-资材 4-会员',
  `ware_user_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '优惠券使用范围 0-寻梦批发 1-全部仓可用 2-部分仓可用 3-分销商可用 4-指定供应商',
  `ware_id_str` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '城市仓id列表逗号分隔 如 ,101,102,103,',
  `ware_name_str` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '城市仓名称列表逗号分隔 如 ,宣城仓,杭州仓, 要求城市仓名称不能有逗号不能有特殊字符',
  `ware_ratio` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '发券方（城市仓分销商）承担比例 范围0~1',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `partner_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分销商名称',
  `help_id_str` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '推广员id列表逗号分隔 如 ,101,102,103,',
  `help_name_str` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '推广员名称列表逗号分隔',
  `promoter_id_str` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分销推广员id列表逗号分隔',
  `promoter_name_str` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分销推广员名称列表逗号分隔',
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级分类id。券使用分类限制，0则不限分类',
  `user_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '可领券的用户类型 1:新客&老客; 2:新客; 3:老客; 4:指定用户;',
  `stock` int UNSIGNED NOT NULL COMMENT '券的库存，小于10万',
  `send_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '券已发放数量',
  `use_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '券已使用数量',
  `get_time` datetime NOT NULL COMMENT '领券开始时间（小于等于领券结束时间和券生效时间）',
  `down_time` datetime NOT NULL COMMENT '领券结束时间（小于等于券失效时间）',
  `effect_type` tinyint UNSIGNED NOT NULL COMMENT '生效类型 1:限定生效时间段; 2:领取生效; 3:循环领取',
  `available_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否限制区域：0-不限制 1-限制',
  `available_area` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '限制使用的区域，例如：[\"杭州“, \"武汉\"]',
  `start_time` datetime NULL DEFAULT NULL COMMENT '券生效时间（限定生效时间段时用），可以为null',
  `end_time` datetime NULL DEFAULT NULL COMMENT '券失效时间（限定生效时间段时用），可以为null',
  `effect_period` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '券生效周期',
  `validity_days` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '券使用有效期（天），小于30（领取生效时用）',
  `is_auto_send` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '注册时是否自动发放 0:否; 1;是;',
  `detail_info` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细信息 限1024字',
  `extra_info` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '额外信息',
  `pop_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '弹窗图片url',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_partnerid`(`partner_id` ASC) USING BTREE,
  INDEX `uk_coupon_no`(`coupon_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21287 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货优惠券配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_coupon_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_coupon_log`;
CREATE TABLE `xm_bulky_coupon_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `coupon_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '优惠券表主键id',
  `field` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '字段',
  `old_data` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '旧数据',
  `new_data` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '新数据',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_couponid`(`coupon_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 708 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '优惠券日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_coupon_user
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_coupon_user`;
CREATE TABLE `xm_bulky_coupon_user`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `purchaser_id` bigint UNSIGNED NOT NULL COMMENT '采购方id',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `coupon_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '优惠券编号',
  `coupon_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '优惠券名称，限20字符',
  `description` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '优惠券描述',
  `coupon_type` tinyint UNSIGNED NOT NULL COMMENT '优惠券类型',
  `coupon_price` decimal(8, 2) UNSIGNED NOT NULL COMMENT '优惠券金额',
  `limit_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '使用扎数门槛',
  `limit_price` decimal(8, 2) UNSIGNED NOT NULL COMMENT '使用门槛金额',
  `coupon_source` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '发券方 1-平台 2-城市仓 3-分销商',
  `distribute_coupon_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发放优惠券原因',
  `draw_source` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '领取优惠券来源',
  `coupon_channel` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '优惠券渠道 1-寻梦批发 2-花仓酷 3-分销商 4-博纳资材',
  `biz_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '业务类型 1-花材 2-花材积分商城 3-资材 4-会员',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id（券在领取时设置）',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id（券在领取时设置）',
  `ware_ratio` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '发券方（城市仓分销商）承担比例 范围0~1',
  `first_id` bigint UNSIGNED NOT NULL COMMENT '一级分类id。券使用分类限制，0则不限分类',
  `effect_type` tinyint UNSIGNED NOT NULL COMMENT '生效类型 1:限定生效时间段; 2:领取生效;',
  `available_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否限制区域：0-不限制 1-限制',
  `available_area` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '限制使用的区域，例如：[\"杭州\", \"武汉\"]',
  `start_time` datetime NULL DEFAULT NULL COMMENT '券生效时间（领取生效时为领取时间）',
  `end_time` datetime NULL DEFAULT NULL COMMENT '券失效时间（领取生效时为领取时间+券使用有效期）',
  `validity_days` tinyint UNSIGNED NOT NULL COMMENT '券使用有效期，小于30天（领取生效时用）',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `coupon_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已使用 0:否; 1:是; 2:平台置为已过期;',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;（过期一段时间定时任务置为删除）',
  `user_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '可领券的用户类型 1:新客&老客; 2:新客; 3:老客; 4:指定用户;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_coupon_no`(`coupon_no` ASC) USING BTREE,
  INDEX `idx_update_time`(`update_time` ASC) USING BTREE,
  INDEX `idx_utime_cstatus_cprice_wratio`(`update_time` ASC, `coupon_status` ASC, `coupon_price` ASC, `ware_ratio` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10065114 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货用户优惠券表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_customer
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_customer`;
CREATE TABLE `xm_bulky_customer`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '客服名称，限20字',
  `nickname` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '简称，限20字',
  `description` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '描述，限64字',
  `wx_service_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业微信客服链接',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电话，限20字',
  `service_scope` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '服务范围',
  `work_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '工作时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `ware_type` tinyint NOT NULL DEFAULT 0 COMMENT '类型 0-采购 1-供应商',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货客服表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_daily_subsidy
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_daily_subsidy`;
CREATE TABLE `xm_bulky_daily_subsidy`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `subsidy_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '已补贴金额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_roundno`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货每日补贴表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_data_statistics
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_data_statistics`;
CREATE TABLE `xm_bulky_data_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `yyyy_mm_dd` date NOT NULL COMMENT '年月日，如2022-01-20',
  `turnover` decimal(20, 2) NOT NULL COMMENT '当日营业额（按支付时间）',
  `all_total_price` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '用户支付金额',
  `all_actual_refund` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '售后金额',
  `all_order_paid` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付金额',
  `all_refund_express_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '运费退款',
  `all_express_fill` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '运费补差',
  `withdraw_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日提现手续费（按审核时间）',
  `all_use_xm_coin` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '用户支付寻梦币',
  `use_xm_coin` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '当日订单使用寻梦币金额（按支付时间）',
  `platform_coin` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '当日平台发放寻梦币金额',
  `coupon_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日订单使用优惠券金额',
  `ware_coupon_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓优惠券承担金额',
  `send_num` int UNSIGNED NOT NULL COMMENT '当日发货单数（按支付时间）',
  `order_num` int UNSIGNED NOT NULL COMMENT '当日订单数（按支付时间）',
  `item_num` int UNSIGNED NOT NULL COMMENT '当日售卖商品数（按支付时间）',
  `item_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日售卖订单商品数（按支付时间）',
  `product_kind_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）当日售卖商品种类数',
  `product_form` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当日所有商品售卖数量json（按支付时间）',
  `supplier_due` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '当日供应商所得（按支付时间）',
  `supplier_punish` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '当日供应商处罚',
  `supplier_after_sale_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日供应商售后承担',
  `supplier_order_paid` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日供应商赔付承担',
  `total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供应商承担的提货站运费（按场次）',
  `sa_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供应商代卖承担的集货站运费',
  `express_price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '当日预估运费（排除到付）',
  `order_refund_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）当日退款运费（按订单时间）',
  `refund_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）当日退款运费（按处理时间）',
  `base_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）当日总基础服务费',
  `service_fee` decimal(10, 2) UNSIGNED NOT NULL COMMENT '当日总服务费',
  `total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日物流总重（g）',
  `self_total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日自提总重（g）',
  `take_xm_coin` decimal(10, 2) UNSIGNED NOT NULL COMMENT '当日供应商抽点',
  `take_xm_coin_return` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日供应商抽点返还',
  `sa_take_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '代卖供应商抽点',
  `add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日加价',
  `subsidy` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '当日补贴',
  `rebate_xm_coin` decimal(10, 2) UNSIGNED NOT NULL COMMENT '当日用户返点',
  `new_purchaser_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日新用户数',
  `old_purchaser_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日老用户数',
  `register_purchaser_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日注册用户数',
  `increased_supplier_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日新增供应商数（不更新）',
  `increased_supplier_form` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '当日新增供应商组成成分json（不更新）',
  `accumulated_supplier_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日累计供应商数（不更新）',
  `accumulated_supplier_form` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '当日累计供应商组成成分json（不更新）',
  `order_after_sale_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日售后单量（按订单时间，只看售后成功）',
  `order_after_sale_purchaser` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日售后人次（按订单时间）',
  `order_supplier_after_sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商售后承担（按场次）',
  `order_after_sale_form` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当日售后类型组成成分json（按订单时间，只看售后成功）',
  `order_after_sale_rate` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日售后率（按订单时间售后单量除以订单数，单位%）',
  `order_after_sale_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日售后金额（按订单时间，只看售后成功）',
  `order_after_sale_price_form` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当日售后金额组成成分json（按订单时间，只看售后成功）',
  `after_sale_num` int UNSIGNED NOT NULL COMMENT '当日售后单量（按处理时间，只看售后成功）',
  `after_sale_purchaser` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日售后人次（按处理时间）',
  `after_sale_form` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当日售后类型组成成分json（按处理时间，只看售后成功）',
  `after_sale_price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '当日售后金额（按处理时间，只看售后成功）',
  `after_sale_price_form` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当日售后金额组成成分json（按处理时间，只看售后成功）',
  `ware_after_sale_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓当日售后单量（按处理时间）',
  `ware_after_sale_purchaser` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓当日售后人次（按处理时间）',
  `ware_after_sale_form` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '城市仓当日售后类型组成成分json（按处理时间）',
  `ware_after_sale_price` decimal(10, 0) UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓当日售后金额（按处理时间）',
  `ware_after_sale_price_form` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '城市仓当日售后金额组成成分json（按处理时间）',
  `order_paid_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日赔付单量（按订单时间）',
  `order_paid_form` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当日赔付类型组成成分json（按订单时间）',
  `order_paid_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日赔付金额（按订单时间）',
  `order_paid_price_form` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当日赔付金额组成成分json（按订单时间）',
  `paid_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日赔付单量（按处理时间）',
  `paid_form` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当日赔付类型组成成分（按处理时间）',
  `paid_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当日赔付金额（按处理时间）',
  `paid_price_form` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当日赔付金额组成成分json（按处理时间）',
  `subsidy_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '单品补贴金额',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_date`(`yyyy_mm_dd` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1065 AVG_ROW_LENGTH = 3675 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货数据统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_data_statistics_bulky
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_data_statistics_bulky`;
CREATE TABLE `xm_bulky_data_statistics_bulky`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `yyyy_mm_dd` date NOT NULL COMMENT '年月日，如2022-01-20',
  `all_total_price` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '纯批发渠道用户支付金额（已扣除退款商品金额）',
  `order_after_sale_price` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '纯批发渠道按订单场次统计的售后金额',
  `all_refund_express_price` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '纯批发渠道运费退款',
  `all_express_fill` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '纯批发渠道运费补差',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '纯批发渠道商品销量',
  `order_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '纯批发渠道订单数',
  `send_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '纯批发渠道货物数',
  `use_xm_coin` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '纯批发渠道订单使用寻梦币（已扣除退款寻梦币）',
  `platform_coin` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '纯批发渠道平台发放寻梦币',
  `all_use_xm_coin` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '纯批发渠道用户支付寻梦币',
  `take_xm_coin` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '纯批发渠道供应商抽点',
  `take_xm_coin_return` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '纯批发渠道供应商抽点返还',
  `express_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '纯批发渠道预估运费',
  `service_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '纯批发渠道服务费',
  `add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '纯批发渠道加价',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_date`(`yyyy_mm_dd` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '纯批发渠道数据统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_delivery_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_delivery_order`;
CREATE TABLE `xm_bulky_delivery_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商表主键id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `round_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '白晚场 0白 2晚场',
  `delivery_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '送货单编号（唯一）',
  `total_prices` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '金额：sum(供货价x数量)',
  `total_nums` int NOT NULL DEFAULT 0 COMMENT '花材总数量',
  `order_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '送货单状态 0：待送货 1：已送货 2:待质检; 3:质检不合格; 4:质检合格待分拣; 5:已分拣',
  `order_start_time` datetime NOT NULL COMMENT '订单交易开始时间',
  `order_end_time` datetime NOT NULL COMMENT '订单交易结束时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '质检员id',
  `operator_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '质检员名称',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常 -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_delivery_no`(`delivery_no` ASC) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_roundNo`(`round_no` ASC) USING BTREE,
  INDEX `idx_utime`(`update_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1862791 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货送货单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_delivery_order_item
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_delivery_order_item`;
CREATE TABLE `xm_bulky_delivery_order_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `delivery_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '送货单编号',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品表主键id',
  `product_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '等级12345->ABCDE',
  `sku_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `spec_and_num` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格数量+规格名称',
  `supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '送货单该商品的数量',
  `total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价x数量',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_delivery_no`(`delivery_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 563110 AVG_ROW_LENGTH = 342 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货送货单商品表' ROW_FORMAT = DYNAMIC;

