  `total_prices` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '金额：sum(供货价x数量)',
  `total_nums` int NOT NULL DEFAULT 0 COMMENT '花材总数量',
  `order_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '送货单状态 0：待送货 1：已送货 2:待质检; 3:质检不合格; 4:质检合格待分拣; 5:已分拣',
