-- ----------------------------
-- Table structure for xm_bulky_exchange_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_exchange_log`;
CREATE TABLE `xm_bulky_exchange_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `code_content` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '扫码内容',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `enter_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'enterItem主键id',
  `num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '数量',
  `handle_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '已处理数量',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '价格（单价）',
  `sku_config` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku',
  `user_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '员工id',
  `user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '员工姓名',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0：扫码枪 1：手动',
  `handle_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已处理 0未处理 1已处理',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0：正常 -100删除',
  `supplier_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(31) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `product_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `zone_shelf` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架号',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架号',
  `sub_shelf_sn` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_content`(`code_content` ASC, `status` ASC) USING BTREE,
  INDEX `idx_roundno_product`(`round_no` ASC, `product_id` ASC) USING BTREE,
  INDEX `idx_enterItem`(`enter_item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 990000027 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商换货表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_exchange_voice_call_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_exchange_voice_call_record`;
CREATE TABLE `xm_bulky_exchange_voice_call_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `notify_id` bigint NOT NULL COMMENT '场次供应商通知汇总id',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '换货场次，yyyy-MM-dd',
  `supplier_id` bigint NOT NULL COMMENT '供应商id',
  `notify_no` tinyint NOT NULL COMMENT '本场次供应商第几次通知，范围1至3',
  `trigger_type` tinyint NOT NULL COMMENT '触发方式：1单个 2批量',
  `task_status` tinyint NOT NULL COMMENT '任务状态：0待执行 1发送中 2等待回执 3已接听 4失败',
  `dispatch_time` datetime NULL DEFAULT NULL COMMENT '开始调用阿里云时间',
  `operator_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '通知人姓名',
  `operator_id` bigint NOT NULL COMMENT '通知操作人id',
  `tts_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '阿里云审核模板Code',
  `out_id` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '阿里云扩展回传标识',
  `request_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '阿里云请求id',
  `call_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '阿里云呼叫id',
  `result_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '系统、接口或运营商结果码',
  `result_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '系统、接口或运营商结果说明',
  `originate_time` datetime NULL DEFAULT NULL COMMENT '呼叫发起时间',
  `call_end_time` datetime NULL DEFAULT NULL COMMENT '通话结束时间',
  `duration_seconds` int NULL DEFAULT NULL COMMENT '通话时长秒数',
  `callback_time` datetime NULL DEFAULT NULL COMMENT '最终结果更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_notify_no`(`notify_id` ASC, `notify_no` ASC) USING BTREE,
  UNIQUE INDEX `uk_out_id`(`out_id` ASC) USING BTREE,
  UNIQUE INDEX `uk_call_id`(`call_id` ASC) USING BTREE,
  INDEX `idx_pending_task`(`task_status` ASC, `id` ASC) USING BTREE,
  INDEX `idx_notify_history`(`notify_id` ASC, `id` ASC) USING BTREE,
  INDEX `idx_round_supplier`(`round_no` ASC, `supplier_id` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 56 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '换货语音外呼记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_exchange_voice_notify
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_exchange_voice_notify`;
CREATE TABLE `xm_bulky_exchange_voice_notify`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '换货场次，yyyy-MM-dd',
  `supplier_id` bigint NOT NULL COMMENT '供应商id',
  `call_status` tinyint NOT NULL DEFAULT 0 COMMENT '公开状态：0未通知 1呼叫中 2已接听 3通知失败',
  `notify_count` tinyint NOT NULL DEFAULT 0 COMMENT '本场次供应商已受理通知次数，最大3次',
  `current_call_record_id` bigint NULL DEFAULT NULL COMMENT '当前外呼记录id',
  `answered_call_record_id` bigint NULL DEFAULT NULL COMMENT '首次确认已接听的外呼记录id',
  `last_notify_time` datetime NULL DEFAULT NULL COMMENT '最后一次通知受理时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_round_supplier`(`round_no` ASC, `supplier_id` ASC) USING BTREE,
  INDEX `idx_round_status`(`round_no` ASC, `call_status` ASC, `notify_count` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 56 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '场次供应商换货语音通知汇总表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_express_bill_import_log
