  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 80 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '运费账单导入记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_express_change_apply
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_express_change_apply`;
CREATE TABLE `xm_bulky_express_change_apply`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `express_refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'express_refund主键id',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-申请中 1-已补差 2-已撤销 3-已退款 4-超时未支付',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号',
  `modify_all` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '修改类型 0-单个订单 1-发货单下所有订单',
  `new_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '新物流金额',
  `amount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '补差金额',
  `refunded_amount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '已退款金额',
  `express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '新物流id',
  `express_name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '新物流名称',
  `express_region_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '新物流区域id',
  `restore_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '还原状态 0-未还原 1-已还原',
  `extra_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '额外信息',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_pid`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_sendno`(`send_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 81 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流变更申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_express_price_redress
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_express_price_redress`;
CREATE TABLE `xm_bulky_express_price_redress`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL COMMENT '采购端用户id',
  `business_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务单号（唯一）',
  `send_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发货单号',
  `business_type` tinyint UNSIGNED NOT NULL COMMENT '业务类型 0:切换 1:补差 2:退款',
  `old_money` decimal(10, 2) UNSIGNED NOT NULL COMMENT '旧的运费总和',
  `new_money` decimal(10, 2) UNSIGNED NOT NULL COMMENT '新的运费总和',
  `money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '补差/退款金额',
  `pay_type` tinyint NULL DEFAULT NULL COMMENT '支付方式 0：微信支付 1：寻梦平台账户支付 2：字节微信支付 3：字节支付宝支付',
  `use_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '支付寻梦币',
  `wx_pay_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微信付款编号',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '支付时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `extra_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '额外信息',
  `redress_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补差/多退状态：0:申请中; 1:审核通过; 2:成功; 3;失败;',
  `operator_id` bigint UNSIGNED NOT NULL COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_business_no`(`business_no` ASC) USING BTREE,
  INDEX `idx_send_no`(`send_no` ASC) USING BTREE COMMENT '补差单号（发货单号）'
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货运费补差、退款记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_express_redress_refund
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_express_redress_refund`;
CREATE TABLE `xm_bulky_express_redress_refund`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '发货单号',
  `settle_batch` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '运费结算批次号',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `source_type` tinyint NOT NULL DEFAULT 1 COMMENT '补差来源 1-物流变更补差',
  `source_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补差来源主键 xm_bulky_express_change_apply.id',
  `express_refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补差支付单 xm_bulky_express_refund.id',
  `pay_out_trade_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '原支付商户单号',
  `pay_trade_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '原支付渠道流水号',
  `pay_type` int NOT NULL DEFAULT 0 COMMENT '补差支付方式',
  `refund_amount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '本次退款金额',
  `out_refund_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '退款单号',
  `refund_status` tinyint NOT NULL DEFAULT 0 COMMENT '0-待退款 1-退款中 2-退款成功 3-退款失败',
  `fail_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '失败原因',
  `retry_count` int NOT NULL DEFAULT 0 COMMENT '重试次数',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '运费补差退款记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_express_refund
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_express_refund`;
CREATE TABLE `xm_bulky_express_refund`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户订单号',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `pay_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补差时支付方式 默认0-无 1-微信 2-寻梦支付',
  `refund_type` tinyint UNSIGNED NOT NULL COMMENT '退款类型 1:发货前退款; 2:发货后退款; 3:运费补差;',
  `seq_no` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '同订单同 refund_type 序号，从 1 递增',
  `refund_express_price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '退款运费（0即不用退款）',
  `refund_status` tinyint UNSIGNED NOT NULL COMMENT '运费退款状态 0:无退款 1:同意退款 2:退款中 3:退款成功 4:退款失败 5:已创建未确认运费补差 6:已确认运费补差; 7:已支付运费补差',
  `wx_refund_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信退款单号',
  `mch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户号',
  `old_express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '旧物流id',
  `new_express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '新物流id',
  `wx_refund_channel` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款渠道',
  `wx_refund_success_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款成功时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_sn_refund_type_seq`(`order_sn` ASC, `refund_type` ASC, `seq_no` ASC) USING BTREE,
  INDEX `idx_updatetime`(`update_time` ASC) USING BTREE,
  INDEX `idx_purchaserid_refundstatus_refundtype`(`purchaser_id` ASC, `refund_status` ASC, `refund_type` ASC) USING BTREE,
  INDEX `idx_refund_status`(`refund_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 126799 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货运费退款表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_expressid
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_expressid`;
CREATE TABLE `xm_bulky_expressid`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `config_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流基础费用配置表主键id，可以为0',
  `express_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '快递类型 0:见config表; 1:中通; 2:顺丰; 3:EMS; 4:圆通; 5:邮政快递;',
  `cp_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sf:顺丰速运 dp:德邦',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户订单号（可重复）',
  `express_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '物流单号',
  `receive_tel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收件人电话，用于顺丰查询',
  `is_effect` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否生效 0;否; 1:是;',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_express_code`(`express_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 262 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '（废弃）寻梦大件货快递打印单号记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_external_distribution_contractor_account
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_external_distribution_contractor_account`;
CREATE TABLE `xm_bulky_external_distribution_contractor_account`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `contractor_user_id` bigint NOT NULL COMMENT '外包配货负责人子账号ID',
  `employee_user_id` bigint NOT NULL COMMENT '配货员工子账号ID',
  `last_operator_id` bigint NULL DEFAULT NULL COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_contractor_employee`(`contractor_user_id` ASC, `employee_user_id` ASC) USING BTREE,
  INDEX `idx_contractor_status`(`contractor_user_id` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_employee_user_id`(`employee_user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '外包配货负责人员工账号关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_favorite_flower
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_favorite_flower`;
CREATE TABLE `xm_bulky_favorite_flower`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '用户id',
  `second_id` bigint UNSIGNED NOT NULL COMMENT '二级分类id (type为1时是商品id)',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '收藏的类型 0: 二级分类 1: 商品',
  `data_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态：0：非常用 1：设为常用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 651 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户常用花材表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_favorite_supplier
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_favorite_supplier`;
CREATE TABLE `xm_bulky_favorite_supplier`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '用户id',
  `supplier_id` bigint UNSIGNED NOT NULL COMMENT '供应商id',
  `data_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态：0：不关注 1：关注',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_userid_supplierid`(`user_id` ASC, `supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 512 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户关注供应商店铺表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_fhh_trade_funnel_event
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_fhh_trade_funnel_event`;
CREATE TABLE `xm_bulky_fhh_trade_funnel_event`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `event_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '唯一事件编号',
  `purchaser_id` bigint NOT NULL COMMENT '采购商用户ID',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '场次号 yyyy-MM-dd',
  `event_type` tinyint NOT NULL COMMENT '事件类型 1购物车变更 2进入提单页 3成功建单 4支付请求到达 5提交订单请求到达',
  `cart_action` tinyint NULL DEFAULT NULL COMMENT '购物车动作 1新增 2修改 3删除',
  `cart_id` bigint NULL DEFAULT NULL COMMENT '购物车ID',
  `product_id` bigint NULL DEFAULT NULL COMMENT '商品ID',
  `buy_count` int NULL DEFAULT NULL COMMENT '变更后的购买数量',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '订单号',
  `content` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '补充信息',
  `create_time` datetime NOT NULL COMMENT '事件时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_event_no`(`event_no` ASC) USING BTREE,
  INDEX `idx_round_user_type`(`round_no` ASC, `purchaser_id` ASC, `event_type` ASC) USING BTREE,
  INDEX `idx_order_type`(`order_sn` ASC, `event_type` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '繁花交易链路事件' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_financial_data
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_financial_data`;
CREATE TABLE `xm_bulky_financial_data`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `yyyy_mm_dd` date NOT NULL COMMENT '年月日，如2022-01-20',
  `withdrawal_of` decimal(20, 2) UNSIGNED NOT NULL COMMENT '提现中金额，非负',
  `balance` decimal(20, 2) NOT NULL COMMENT '总余额',
  `deposit` decimal(20, 2) NOT NULL COMMENT '总保证金',
  `withdrawing` decimal(20, 2) UNSIGNED NOT NULL COMMENT '待结算金额，非负',
  `withdrawal_of_other` decimal(20, 2) UNSIGNED NOT NULL COMMENT '提现中金额（非自营），非负',
  `balance_other` decimal(20, 2) NOT NULL COMMENT '总余额（非自营）',
  `deposit_other` decimal(20, 2) NOT NULL COMMENT '总保证金（非自营）',
  `withdrawing_other` decimal(20, 2) UNSIGNED NOT NULL COMMENT '待结算金额（非自营），非负',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_yyyy_mm_dd`(`yyyy_mm_dd` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 603 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货平台财务数据表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_freeze
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_freeze`;
CREATE TABLE `xm_bulky_freeze`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 1:商品; 2:供应商;',
  `biz_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '业务id',
  `frozen_until` datetime NOT NULL COMMENT '冻结到期时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_bizid_type`(`type` ASC, `biz_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 331 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '冻结表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_freeze_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_freeze_operation_log`;
CREATE TABLE `xm_bulky_freeze_operation_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '日志ID',
  `freeze_id` bigint UNSIGNED NOT NULL COMMENT '冻结父项ID',
  `detail_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '冻结子项ID；父项创建事件可为空',
  `related_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '关联冻结父项ID',
  `related_detail_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '关联冻结子项ID',
  `action` tinyint UNSIGNED NOT NULL COMMENT '动作 1-创建 2-提交审核 3-审核通过 4-审核拒绝 5-取消 6-执行冻结 7-执行失败 8-重试 9-替代 10-人工解除 11-到期 12-历史接管',
  `before_status` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '变更前执行状态',
  `after_status` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '变更后执行状态',
  `before_review_status` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '变更前审核状态',
  `after_review_status` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '变更后审核状态',
  `is_changed` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否实际改变对象冻结状态或期限 0-否 1-是',
  `operator_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '操作人类型 1-系统 2-平台 3-供应商',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人ID，系统为0',
  `operator_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人名称',
  `remark` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作原因或说明',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_freeze_time`(`freeze_id` ASC, `create_time` ASC, `id` ASC) USING BTREE,
  INDEX `idx_detail_time`(`detail_id` ASC, `create_time` ASC, `id` ASC) USING BTREE,
  INDEX `idx_related_detail`(`related_detail_id` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '统一冻结操作日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_freeze_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_freeze_record`;
CREATE TABLE `xm_bulky_freeze_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '冻结父项ID',
  `source_type` tinyint UNSIGNED NOT NULL COMMENT '来源 1-人工 2-质检 3-商品售后 4-供应商售后 5-供应商审核 6-历史接管 7-其他',
  `source_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '来源业务ID',
  `supplier_id` bigint UNSIGNED NOT NULL COMMENT '所属供应商ID',
  `reason` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '冻结原因',
  `operator_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '发起人类型 1-系统 2-平台 3-供应商',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '发起人ID，系统为0',
  `operator_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发起人名称',
  `request_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '同一次业务请求稳定编号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_source_request`(`source_type` ASC, `request_no` ASC) USING BTREE,
  INDEX `idx_supplier_time`(`supplier_id` ASC, `create_time` ASC, `id` ASC) USING BTREE,
  INDEX `idx_source_id`(`source_type` ASC, `source_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '统一冻结父项' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_freeze_record_item
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_freeze_record_item`;
CREATE TABLE `xm_bulky_freeze_record_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '冻结子项ID',
  `freeze_id` bigint UNSIGNED NOT NULL COMMENT '冻结父项ID',
  `object_type` tinyint UNSIGNED NOT NULL COMMENT '对象类型 1-商品 2-供应商',
  `object_id` bigint UNSIGNED NOT NULL COMMENT '商品或供应商ID',
  `object_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '对象名称快照',
  `review_status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '审核状态 1-无需审核 2-待审核 3-已通过 4-已拒绝 5-已取消',
  `reviewer_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '审核人ID',
  `reviewer_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人名称',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `review_remark` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核意见',
  `second_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '商品二级分类ID；供应商为空',
  `rank_num` int UNSIGNED NULL DEFAULT NULL COMMENT '商品等级或供应商冻结档位',
  `sku_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品SKU配置快照；供应商为空',
  `pay_off_mode` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '供应商清退方式 0-不自动清退 1-自动清退；商品为空',
  `duration` bigint UNSIGNED NULL DEFAULT NULL COMMENT '申请冻结时长，单位秒；固定截止或永久可为空',
  `is_permanent` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否永久 0-否 1-是',
  `time_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '期限类型 1-按时长 2-固定截止时间',
  `request_end_time` datetime NULL DEFAULT NULL COMMENT '申请指定的固定截止时间',
  `start_time` datetime NULL DEFAULT NULL COMMENT '实际生效时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '实际采用的原定结束时间；永久为空',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '实际到期处理、解除、替代或取消时间',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '执行状态 1-待执行 2-生效中 3-执行失败 4-已到期 5-已解除 6-已替代 7-已取消',
  `replace_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '接管本条记录的新冻结子项ID',
  `end_reason` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '解除、替代或取消原因',
  `end_user_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '结束操作人ID，系统为0',
  `end_user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结束操作人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_freeze_object`(`freeze_id` ASC, `object_type` ASC, `object_id` ASC) USING BTREE,
  INDEX `idx_review_time`(`review_status` ASC, `create_time` ASC, `id` ASC) USING BTREE,
  INDEX `idx_expire`(`status` ASC, `is_permanent` ASC, `end_time` ASC, `id` ASC) USING BTREE,
  INDEX `idx_replace_id`(`replace_id` ASC) USING BTREE,
  INDEX `idx_object_status`(`object_type` ASC, `object_id` ASC, `status` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '统一冻结对象子项' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_freeze_stats
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_freeze_stats`;
CREATE TABLE `xm_bulky_freeze_stats`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `product_freeze_count` bigint NULL DEFAULT 0 COMMENT '商品冻结次数',
  `supplier_freeze_count` int NULL DEFAULT 0 COMMENT '供应商冻结次数',
  `stats_date` date NOT NULL COMMENT '统计日期',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_supplier_date`(`supplier_id` ASC, `stats_date` ASC) USING BTREE,
  INDEX `idx_stats_date`(`stats_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商冻结数据统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_gift
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_gift`;
CREATE TABLE `xm_bulky_gift`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `gift_no` int UNSIGNED NOT NULL COMMENT '奖品编号',
  `activity_id` int UNSIGNED NOT NULL COMMENT '活动id，1:春节大转盘',
  `activity_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '活动名称',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '奖品名称',
  `pic_url` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '奖品图片url',
  `price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '实物价值',
  `description` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '描述',
  `stock` int UNSIGNED NOT NULL COMMENT '库存',
  `send_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '抽到的数量',
  `is_material` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否包含实物 0:否; 1:是;',
  `head_store_ratio` int NOT NULL COMMENT '头部商家，直营，一级合作抽中概率，单位千分位',
  `second_store_ratio` int NOT NULL COMMENT '二级及以下合作花店抽中概率，单位千分位',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_gift_no`(`gift_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货实物表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_gift_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_gift_log`;
CREATE TABLE `xm_bulky_gift_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL COMMENT '采购方id',
  `activity_id` int UNSIGNED NOT NULL COMMENT '活动id',
  `activity_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动名称',
  `activity_info` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动描述',
  `gift_no` int UNSIGNED NOT NULL COMMENT '奖品编号',
  `gift_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '奖品名称（包括实物+优惠券）',
  `pic_url` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '奖品图片url',
  `description` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '奖品描述',
  `is_material` tinyint UNSIGNED NOT NULL COMMENT '是否包含实物 0:否; 1:是;',
  `is_used` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已使用 0:否; 1:是;',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 830 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货礼包记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_group
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_group`;
CREATE TABLE `xm_bulky_group`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分组表',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分组表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_group_detail
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_group_detail`;
CREATE TABLE `xm_bulky_group_detail`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `group_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分组id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `nickname` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '分组内容表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_help
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_help`;
CREATE TABLE `xm_bulky_help`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型 1-供应商 2-寻梦采购端 3-花仓酷 4-博纳资材 5-优花速达',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `com_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '公司id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名称，限20字',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '姓名，限20字',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电话，限20字',
  `show_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '展示电话号码',
  `wx_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信手机号，限20字',
  `wx_register_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信推广url，限255字',
  `pic_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片，限512字',
  `month_promotion` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '本月推广人数',
  `total_promotion` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '累计推广人数',
  `month_flower_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '本月花材款（按当月，可能为负）',
  `total_flower_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '累计花材款（可能为负）',
  `month_deduction` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '本月提成',
  `total_deduction` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '累计提成（可能为负）',
  `month_material_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '本月资材款（按当月）',
  `total_material_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '累计资材款（按当月）',
  `month_material_deduction` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '本月资材提成',
  `total_material_deduction` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '累计资材提成',
  `sale_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否达人 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_userid_type`(`user_id` ASC, `type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 564 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '推广员表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_help_customer
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_help_customer`;
CREATE TABLE `xm_bulky_help_customer`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id（推广员的账号id）',
  `platform_type` tinyint UNSIGNED NOT NULL DEFAULT 2 COMMENT '平台类型 help表type',
  `type` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型 1-新用户 时间戳-老用户',
  `customer_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '被推广的花店用户id',
  `expire_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '绑定关系失效时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_customerid_helpid_ptype`(`customer_id` ASC, `help_id` ASC, `platform_type` ASC) USING BTREE,
  UNIQUE INDEX `uk_customerid_type_ptype`(`customer_id` ASC, `type` ASC, `platform_type` ASC) USING BTREE,
  INDEX `idx_ctime_helpid`(`create_time` ASC, `help_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8564 AVG_ROW_LENGTH = 106 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '推广用户记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_help_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_help_log`;
CREATE TABLE `xm_bulky_help_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `help_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '被推广用户id',
  `phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '被推广用户手机号',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '被推广头像',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '失败原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_help_id`(`help_id` ASC) USING BTREE COMMENT '推广员id'
) ENGINE = InnoDB AUTO_INCREMENT = 271 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '推广记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_help_order_detail
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_help_order_detail`;
CREATE TABLE `xm_bulky_help_order_detail`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `yyyy_mm_dd` date NOT NULL COMMENT '年月日，如2024-05-12',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `biz_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '业务类型 1-花材 2-资材',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `pay_time` datetime NOT NULL COMMENT '订单支付时间',
  `customer_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广用户id（采购方id）',
  `flower_money_income` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '花材款收入',
  `flower_money_outcome` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '花材款支出',
  `deduct_ratio` decimal(6, 3) UNSIGNED NULL DEFAULT 0.000 COMMENT '提成比例 默认0',
  `is_settle` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否结算 0-否 1-是',
  `settle_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '结算id',
  `settle_time` datetime NULL DEFAULT NULL COMMENT '结算时间（默认null）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_date_ordersn`(`yyyy_mm_dd` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_userid_date`(`user_id` ASC, `yyyy_mm_dd` ASC) USING BTREE,
  INDEX `idx_paytime`(`pay_time` ASC) USING BTREE,
  INDEX `idx_helpid_yyyymmdd`(`help_id` ASC, `yyyy_mm_dd` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9346 AVG_ROW_LENGTH = 128 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '推广订单明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_help_settle
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_help_settle`;
CREATE TABLE `xm_bulky_help_settle`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `month` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'yyyy-MM 年月',
  `user_id` bigint NOT NULL COMMENT '用户id（可能是子账号可能不是寻梦的）',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '结算金额（可能为负）',
  `is_count` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已计提 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_month_userid`(`month` ASC, `user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 169 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '推广结算表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_home_page
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_home_page`;
CREATE TABLE `xm_bulky_home_page`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `show_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '显示类型 1-banner 2-金刚位 3-宫格图片 4-宣传图 5-下单宫格图 6-弹窗 7-分销首页二类banner 8-繁花惠banner 9-繁花惠宫格',
  `router_type` int UNSIGNED NOT NULL DEFAULT 2 COMMENT '跳转类型 1:网站; 2:一级分类; 3:二级分类 4:商品 5:公告 6:小程序链接 7:小时达分类 8：跳转自定义页面 9：锚点 10:优惠券',
  `title` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `color_code` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '颜色代码 #FF79BC',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序 升序',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '跳转目标',
  `show_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否展示 0-否 1-是 默认1',
  `extra_info` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '额外信息',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_appid_showtype`(`app_id` ASC, `show_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9642 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货首页配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_inspection
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_inspection`;
CREATE TABLE `xm_bulky_inspection`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `date` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `enter_item_id` bigint NOT NULL COMMENT 'enterItem主键id',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架号',
  `zoen_shelf` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架号',
  `sub_shelf_sn` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `product_id` bigint NOT NULL DEFAULT 0 COMMENT 'product主键id',
  `product_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花材名称',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '花材等级',
  `sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '花材数量',
  `receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `supplier_id` bigint NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `big_order` tinyint NULL DEFAULT 0 COMMENT '大订单',
  `inspection_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否重点质检',
  `focus_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否重点关注',
  `focus_quality_mark_id` bigint NULL DEFAULT NULL COMMENT '运营端重点质检标记ID',
  `focus_quality_source` tinyint NOT NULL DEFAULT 0 COMMENT '重点质检来源 0规则生成 1运营端标记',
  `focus_quality_status` tinyint NULL DEFAULT 1 COMMENT '重点质检任务有效状态 1有效 2已取消',
  `new_order` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '新用户新订单',
  `new_supplier` tinyint UNSIGNED NULL DEFAULT NULL,
  `old_supplier` tinyint UNSIGNED NULL DEFAULT NULL,
  `refund_product` tinyint UNSIGNED NULL DEFAULT NULL,
  `quality_product` tinyint UNSIGNED NULL DEFAULT NULL,
  `quality_flag` tinyint UNSIGNED NULL DEFAULT NULL,
  `exchange_supplier` tinyint UNSIGNED NULL DEFAULT NULL,
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '质检状态 0:未质检 1：质检通过 2：质检良好（推荐） 10：质检不合格',
  `user_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人id',
  `user_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `assigned_user_id` bigint NULL DEFAULT NULL COMMENT '分配质检员子账号ID',
  `assigned_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分配质检员名称',
  `assign_time` datetime NULL DEFAULT NULL COMMENT '分配时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `delete_time` datetime NULL DEFAULT NULL COMMENT '删除时间，NULL表示未删除',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '质检备注',
  `inspection_images` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_date_assigned_status`(`date` ASC, `assigned_user_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_date_shelf_sub_shelf`(`date` ASC, `shelf_sn` ASC, `sub_shelf_sn` ASC) USING BTREE,
  INDEX `idx_focus_quality_mark_id`(`focus_quality_mark_id` ASC) USING BTREE,
  INDEX `idx_focus_quality_shelf`(`date` ASC, `shelf_sn` ASC, `sub_shelf_sn` ASC, `focus_quality_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5875892 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质检重点关注表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_inspection_assign_snapshot
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_inspection_assign_snapshot`;
CREATE TABLE `xm_bulky_inspection_assign_snapshot`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次，格式yyyy-MM-dd',
  `user_id` bigint NOT NULL COMMENT '质检员子账号ID',
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '质检员姓名快照',
  `leader_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否为质检负责人：0否 1是',
  `special_area_flag` tinyint NOT NULL DEFAULT 0 COMMENT '质检角色是否只负责二十一区或七十七区：0否 1是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `good_flower_video_required_num` int NOT NULL DEFAULT 0 COMMENT '该场次好花视频要求数量，0未纳入考核',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_round_user`(`round_no` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_round_leader`(`round_no` ASC, `leader_flag` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '每日质检人员名单快照' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_inspection_assign_user
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_inspection_assign_user`;
CREATE TABLE `xm_bulky_inspection_assign_user`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint NOT NULL COMMENT '质检员子账号ID',
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '质检员名称',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：1启用，0禁用',
  `attendance_status` tinyint NULL DEFAULT 1 COMMENT '假勤状态 1出勤 0休息，空值按出勤处理',
  `attendance_update_time` datetime NULL DEFAULT NULL COMMENT '假勤状态更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_status_user`(`status` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_status_attendance_status`(`status` ASC, `attendance_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 67 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质检任务分配人员配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_inspection_attendance_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_inspection_attendance_log`;
CREATE TABLE `xm_bulky_inspection_attendance_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `assign_user_id` bigint NOT NULL COMMENT '质检人员配置ID',
  `user_id` bigint NOT NULL COMMENT '质检员用户ID',
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '质检员姓名',
  `before_status` tinyint NOT NULL COMMENT '原假勤状态 0休息 1出勤',
  `after_status` tinyint NOT NULL COMMENT '目标假勤状态 0休息 1出勤',
  `operator_id` bigint NOT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作人姓名',
  `operation_source` tinyint NOT NULL COMMENT '来源 1运营端 2移动端',
  `batch_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作批次号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_time`(`user_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_batch_no`(`batch_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 214 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质检人员假勤变更日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_inspection_focus_mark
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_inspection_focus_mark`;
CREATE TABLE `xm_bulky_inspection_focus_mark`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发货单号',
  `round_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次 yyyy-MM-dd',
  `shelf_sn` int NULL DEFAULT NULL COMMENT '货位号（统一下发时回填）',
  `sub_shelf_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '子货位号（统一下发时回填）',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区-货位号（统一下发时回填）',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '标记状态 1已标记 2已取消',
  `generate_status` tinyint NOT NULL DEFAULT 0 COMMENT '生成状态 0待统一下发 1已生成',
  `task_type` tinyint NOT NULL DEFAULT 1 COMMENT '任务类型 1新客户',
  `source_type` tinyint NOT NULL DEFAULT 1 COMMENT '来源 1运营端手动标记',
  `remark` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '标记人ID',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标记人名称',
  `mark_time` datetime NULL DEFAULT NULL COMMENT '标记时间',
  `cancel_operator_id` bigint NULL DEFAULT NULL COMMENT '取消人ID',
  `cancel_operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取消人名称',
  `cancel_time` datetime NULL DEFAULT NULL COMMENT '取消时间',
  `generate_time` datetime NULL DEFAULT NULL COMMENT '生成时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_send_no`(`send_no` ASC) USING BTREE,
  INDEX `idx_round_status_generate`(`round_no` ASC, `status` ASC, `generate_status` ASC) USING BTREE,
  INDEX `idx_shelf`(`round_no` ASC, `shelf_sn` ASC, `sub_shelf_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '运营端重点质检标记表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_inspection_video_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_inspection_video_record`;
CREATE TABLE `xm_bulky_inspection_video_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '视频记录ID',
  `user_id` bigint NULL DEFAULT NULL COMMENT '提交视频的质检员子账号ID',
  `date` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '视频所属场次，yyyy-MM-dd',
  `snapshot_id` bigint NOT NULL COMMENT '关联xm_bulky_inspection_assign_snapshot.id',
  `enter_item_id` bigint NOT NULL COMMENT '入场花材ID',
  `product_id` bigint NOT NULL COMMENT '商品ID',
  `item_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花材名称',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `supplier_tag` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商标签',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区及货位',
  `video_url` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '视频地址',
  `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拍摄说明',
  `rank_num` int NULL DEFAULT NULL COMMENT '花材等级',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `shelf_sn` int NULL DEFAULT NULL COMMENT '货架流水号',
  `create_time` datetime NOT NULL COMMENT '首次提交时间',
  `update_time` datetime NOT NULL COMMENT '最近重拍时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_snapshot_id`(`snapshot_id` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '好花视频提交记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_integral_mall
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_integral_mall`;
CREATE TABLE `xm_bulky_integral_mall`  (
  `id` bigint NOT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_invoice_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_invoice_order`;
CREATE TABLE `xm_bulky_invoice_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人手机号（发货后手机号不再更改）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_pid_tel_ordersn`(`purchaser_id` ASC, `receive_tel` ASC, `order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 AVG_ROW_LENGTH = 85 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货开票订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_invoice_quota_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_invoice_quota_log`;
CREATE TABLE `xm_bulky_invoice_quota_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `target_type` tinyint NOT NULL COMMENT '调整对象类型：1供应商 2花店',
  `target_id` bigint NOT NULL COMMENT '供应商ID或花店ID',
  `adjust_type` tinyint NOT NULL COMMENT '调整类型：1手动增加 2手动减少 3系统调整',
  `adjust_amount` decimal(12, 2) NOT NULL COMMENT '调整金额',
  `before_amount` decimal(12, 2) NOT NULL COMMENT '调整前额度',
  `after_amount` decimal(12, 2) NOT NULL COMMENT '调整后额度',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调整原因',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_target`(`target_type` ASC, `target_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '额度调整日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_invoice_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_invoice_record`;
CREATE TABLE `xm_bulky_invoice_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `time_period` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '时间范围',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '链接',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_purchaserid`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '开票订单导出记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_invoice_registration
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_invoice_registration`;
CREATE TABLE `xm_bulky_invoice_registration`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `registration_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '登记单号',
  `purchaser_id` bigint NOT NULL COMMENT '花店ID',
  `purchaser_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '花店手机号',
  `purchaser_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '花店名称',
  `invoice_title_id` bigint NULL DEFAULT NULL COMMENT '发票抬头ID',
  `title_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抬头名称（冗余）',
  `tax_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '税号（冗余）',
  `total_amount` decimal(12, 2) NOT NULL COMMENT '申请开票总金额',
  `assigned_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '已分配金额（已发起申请的金额）',
  `remaining_amount` decimal(12, 2) NOT NULL COMMENT '剩余待分配金额',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0待分配 1部分分配 2已完成 3已取消',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '登记人ID',
  `operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '登记人姓名',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_registration_no`(`registration_no` ASC) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '发票申请登记表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_invoice_request
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_invoice_request`;
CREATE TABLE `xm_bulky_invoice_request`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `request_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请单号',
  `purchaser_id` bigint NOT NULL COMMENT '花店ID',
  `purchaser_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '花店手机号',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `supplier_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `invoice_title_id` bigint NULL DEFAULT NULL COMMENT '发票抬头ID',
  `title_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抬头名称（冗余）',
  `tax_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '税号（冗余）',
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开户银行（冗余）',
  `bank_account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '银行账号（冗余）',
  `company_address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业地址（冗余）',
  `company_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业电话（冗余）',
  `request_amount` decimal(12, 2) NOT NULL COMMENT '申请开票金额',
  `invoice_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发票图片/PDF地址',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0待开票 1已开票 2已逾期 3已撤销 4已转代开',
  `invoice_platform_status` tinyint UNSIGNED NULL DEFAULT 0,
  `parent_id` bigint NULL DEFAULT NULL COMMENT '父申请ID（转代开时关联原单）',
  `registration_id` bigint NULL DEFAULT NULL COMMENT '关联的登记单ID',
  `deadline` datetime NULL DEFAULT NULL COMMENT '截止日期（申请日+30天）',
  `upload_time` datetime NULL DEFAULT NULL COMMENT '发票上传时间',
  `overdue_time` datetime NULL DEFAULT NULL COMMENT '逾期时间',
  `is_overdue` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否逾期补开：0否 1是',
  `punish_id` bigint NULL DEFAULT NULL COMMENT '关联的处罚记录ID',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人姓名',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `source` tinyint NOT NULL DEFAULT 0 COMMENT '来源:0管理后台 1花店自助',
  `application_id` bigint NULL DEFAULT NULL COMMENT '花店申请单ID(source=1时)',
  `order_sns` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '关联订单号(source=1时，多个逗号分隔)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `invoice_item_type` tinyint NOT NULL DEFAULT 0 COMMENT '开票项目类型 0:花材款 1:服务费(供应链服务费,平台) 2:物流费(平台) 3:利润部分(平台服务费,平台)',
  `partner_id` int NOT NULL DEFAULT 0 COMMENT '所属平台(分销商id) 0:寻梦批发 3:优花速达 140:繁花惠',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_request_no`(`request_no` ASC) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_deadline`(`deadline` ASC) USING BTREE,
  INDEX `idx_registration_id`(`registration_id` ASC) USING BTREE,
  INDEX `idx_parent_id`(`parent_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_application_id`(`application_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 132 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '发票申请主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_invoice_title
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_invoice_title`;
CREATE TABLE `xm_bulky_invoice_title`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `purchaser_id` bigint NOT NULL COMMENT '花店ID',
  `title_type` tinyint NOT NULL DEFAULT 1 COMMENT '抬头类型：1企业 2个人',
  `title_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '抬头名称',
  `tax_number` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '银行账号',
  `company_address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业地址',
  `company_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业电话',
  `is_default` tinyint NOT NULL DEFAULT 0 COMMENT '是否默认：0否 1是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0正常 -100删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_data_status`(`data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 65 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '花店发票抬头表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_invoice_upload_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_invoice_upload_log`;
CREATE TABLE `xm_bulky_invoice_upload_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `invoice_request_id` bigint NOT NULL COMMENT '发票申请单ID',
  `request_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请单号',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `old_invoice_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '被覆盖的旧发票地址',
  `operate_type` tinyint NOT NULL COMMENT '操作类型：1-重新上传覆盖',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_invoice_request_id`(`invoice_request_id` ASC) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '发票重新上传日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_late_pay_refund
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_late_pay_refund`;
CREATE TABLE `xm_bulky_late_pay_refund`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '订单号',
  `order_type` tinyint NOT NULL COMMENT '订单类型 0:主订单 1:本地仓订单',
  `pay_type` int NOT NULL COMMENT '支付方式',
  `pay_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '支付流水号',
  `out_refund_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '固定退款单号',
  `refund_fee` int NOT NULL COMMENT '本次到账退款金额，单位分',
  `channel_refund_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '渠道退款单号',
  `refund_status` tinyint NOT NULL DEFAULT 0 COMMENT '退款状态 0:待退款 1:处理中 2:成功 3:失败',
  `refund_result` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '退款结果或失败原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_out_refund_no`(`out_refund_no` ASC) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '订单关闭后迟到支付退款记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_limit_distribution_cancel_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_limit_distribution_cancel_log`;
CREATE TABLE `xm_bulky_limit_distribution_cancel_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `enter_item_id` bigint NULL DEFAULT NULL,
  `order_item_id` bigint NULL DEFAULT NULL,
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `supplier_id` bigint NULL DEFAULT NULL,
  `user_id` bigint NULL DEFAULT NULL,
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_enter_item_id`(`enter_item_id` ASC) USING BTREE,
  INDEX `idx_order_item_id`(`order_item_id` ASC) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 83 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '取消限制配货日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_link_manage
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_link_manage`;
CREATE TABLE `xm_bulky_link_manage`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型 1-供应商 2-采购端 3-花仓酷 4-分销商',
  `title` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题，限32字',
  `path` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序路径，限64字',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `params` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '{}' COMMENT '参数params，会拼接在path后面，限255字',
  `permanent` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '有效期 0-短期有效 1-永久有效',
  `wx_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信链接',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信小程序图片链接',
  `new_wx_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分销城市仓微信链接',
  `new_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分销城市仓二维码',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 41 AVG_ROW_LENGTH = 1092 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '微信链接管理' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_login_jpush
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_login_jpush`;
CREATE TABLE `xm_bulky_login_jpush`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `supplier_id` bigint NOT NULL COMMENT '公司id',
  `regid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '极光手机推送标签',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0：未处理 1：已处理',
  `create_time` int UNSIGNED NOT NULL COMMENT '时间戳',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '登录时极光推送失败' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_logistics_activity
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_logistics_activity`;
CREATE TABLE `xm_bulky_logistics_activity`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流活动名称 限25字',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-未启用 1-已启用 2-已停用',
  `active_start` datetime NOT NULL COMMENT '活动开始时间',
  `active_end` datetime NOT NULL COMMENT '活动结束时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货物流活动表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_logistics_activity_region
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_logistics_activity_region`;
CREATE TABLE `xm_bulky_logistics_activity_region`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `activity_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流活动id',
  `config_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流配置id',
  `logistics_region_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流配置区域id',
  `logistics_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流方式 1-快递物流 2-冷链运输 3-航空运输',
  `tag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '徽标内容，限10字',
  `region_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '区域id',
  `region_name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区域名称，限25字',
  `pay_on_delivery` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流结算方式 0-其他 1-到付 2-日结 3-月结',
  `charge_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '计费方式 0-单价模式 1-底价模式',
  `price_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '接替费用json数组，最多5组（快递冷链用）如：[{\"limit\":20,\"price\":5}]',
  `multi_price_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '多首重收费配置数组',
  `morning_price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '空运-早班运费（元/kg）（空运用），99999为无',
  `nooning_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '空运-午班运费（元/kg）（空运用），99999为无',
  `evening_price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '空运-晚班运费（元/kg）（空运用），99999为无',
  `is_enable` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否启用 0-否 1-是 默认1',
  `picker_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '提货人名称，限20字',
  `picker_mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '提货人电话，限20字',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_activityid`(`activity_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货物流活动区域表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_logistics_config_template_mapping
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_logistics_config_template_mapping`;
CREATE TABLE `xm_bulky_logistics_config_template_mapping`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `config_id` bigint NOT NULL COMMENT '物流配置id',
  `template_id` bigint NOT NULL COMMENT '物流模板id',
  `print_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '打印名称',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_user_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人id',
  `create_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人名称',
  `update_user_id` bigint NOT NULL DEFAULT 0 COMMENT '更新人id',
  `update_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0=正常，-100=删除/停用',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_template_id`(`template_id` ASC) USING BTREE,
  INDEX `idx_data_status`(`data_status` ASC) USING BTREE,
  INDEX `uk_config_id`(`config_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 47 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件物流配置模板映射表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_logistics_cost_config
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_logistics_cost_config`;
CREATE TABLE `xm_bulky_logistics_cost_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `logistics_name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流服务商名称',
  `brand` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流商品牌',
  `phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '服务商电话，如0563-8888888，限30字',
  `logistics_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流方式 1:快递物流; 2:冷链运输; 3:航空运输;',
  `expected_time_str` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '预计送达（省会/一线城市）如：24~36小时',
  `expected_time_hours` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '预计送达时长（小时）',
  `delay_time_num` int UNSIGNED NOT NULL COMMENT '确认送达延后时间(小时h)',
  `is_to_shop` tinyint UNSIGNED NOT NULL COMMENT '是否送货到店 0:不到店需自提; 1:可配送到店; 2:需另付费配送到店',
  `transfer_cost` decimal(10, 2) UNSIGNED NOT NULL COMMENT '航空运输-空运短运费',
  `is_separate_display` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否单独展示 0:否; 1:是;',
  `is_enable` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否启用该配置 0:否; 1:是;',
  `rule_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流规则id',
  `first_heavy` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）计重用：首重(g)  单位(g/扎)',
  `first_heavy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）计重用：首重价格',
  `charge_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）计费类型 1:计重; 2:计件;',
  `continue_heavy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）计重用：续重单价(元/kg)',
  `is_transfer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否中转 0:否; 1:是;',
  `need_pick_fee` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否需要提货费和中转费 0:否; 1:是;',
  `small_item_recommend` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否小件推荐物流（推荐角标） 0:否; 1:是;',
  `logistics_shift` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流班次 0:无 1:早班物流 2:午班物流 3:晚班物流',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '仓库排序值 升序',
  `show_sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '展示排序值 升序',
  `description` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流描述',
  `delivery_time` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '每日交货时间',
  `picker_phone` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拉货人手机号',
  `need_fill_express_price` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否需要填报运费 0-不需要 1-必填 2-选填',
  `need_fill_weight` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否需要填报重量 0-不需要 1-必填 2-选填',
  `need_weight_photo` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否需要上传称重照片 0-不需要 1-必填 2-选填',
  `out_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '小程序端是否能出库 0-否 1-是',
  `pack_timeout_punish_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启超时打包处罚 0:否; 1:是;',
  `promotion_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否活动物流 0-否 1-是 默认0',
  `promotion_start` datetime NULL DEFAULT NULL COMMENT '活动开始时间',
  `promotion_end` datetime NULL DEFAULT NULL COMMENT '活动结束时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `send_area` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '废弃）寄送区域，限255字',
  `is_invoice_marked` tinyint NOT NULL DEFAULT 0 COMMENT '是否合作可开票物流商 0:否 1:是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_name`(`logistics_name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 990022 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货物流基础费用配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_logistics_cost_region
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_logistics_cost_region`;
CREATE TABLE `xm_bulky_logistics_cost_region`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `config_id` bigint UNSIGNED NOT NULL COMMENT '物流费用配置表主键id',
  `region_id` int UNSIGNED NOT NULL COMMENT 'xm_region.id',
  `adcode` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市编码',
  `region_name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '城市名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '描述',
  `first_heavy` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 10.00 COMMENT '首重（kg）',
  `first_heavy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 30.00 COMMENT '首重价格',
  `pay_on_delivery` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流结算方式 0:其他 1:到付 2:日结 3:月结',
  `charge_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '计费方式 0-单价模式 1-底价模式 2-多首重模式',
  `price_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '阶梯费用json数组，最多5组如：[{\"limit\":20,\"price\":5}]',
  `multi_price_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '多首重收费配置数组',
  `weight_range_data` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '重量区间收费配置json数组，区间前开后闭(min,max]，最多15组，如：[{\"min\":0,\"max\":1.7,\"trunkPrice\":2,\"shopPrice\":20}]',
  `trunk_charge_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '重量区间模式-干线费计费方式 0-固定金额 1-重量单价',
  `shop_charge_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '重量区间模式-到店费计费方式 0-固定金额 1-重量单价',
  `xm_special_line` tinyint NOT NULL DEFAULT 0 COMMENT '是否寻梦冷链专线 0-否 1-是',
  `trans_city` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '中转城市，限100字',
  `activity_price_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '活动阶梯费用json数组，最多5组 如：[{\"price\":5}]',
  `continue_heavy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）续重单价（元/kg）（快递冷链用）',
  `morning_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）空运-早班运费（元/kg）（空运用），99999为无',
  `nooning_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）空运-午班运费（元/kg）（空运用），99999为无',
  `evening_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）空运-晚班运费（元/kg）（空运用），99999为无',
  `is_enable` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否启用该区域 0:否; 1:是; 默认1',
  `picker_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '提货员名称，限20字',
  `picker_mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '提货员手机号，限20字',
  `expected_time_str` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '预计送达时间，如：24~36小时',
  `expected_time_hours` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '预计送达时长（小时），0表示沿用物流商配置',
  `delivery_time` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '每日交货时间',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `start_round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1970-01-01' COMMENT '生效开始场次 yyyy-MM-dd',
  `end_round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '9999-12-31' COMMENT '生效结束场次 yyyy-MM-dd',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_config_id`(`config_id` ASC) USING BTREE,
  INDEX `idx_adcode_data_status`(`adcode` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_config_effective`(`config_id` ASC, `is_enable` ASC, `data_status` ASC, `start_round_no` ASC, `end_round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 931103513 AVG_ROW_LENGTH = 332 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货物流配置区域费用表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_logistics_fail_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_logistics_fail_record`;
CREATE TABLE `xm_bulky_logistics_fail_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `type` tinyint NOT NULL COMMENT '失败类型：1发货失败(下单失败) 2打印失败',
  `send_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发货单号',
  `logistics_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物流单号(xmLogisticsOrderNo)',
  `mail_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递面单号，无则空字符串',
  `reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '失败原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_send_no`(`send_no` ASC) USING BTREE,
  INDEX `idx_logistics_no`(`logistics_no` ASC) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货发货/打印失败记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_logistics_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_logistics_order`;
CREATE TABLE `xm_bulky_logistics_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `source` tinyint NOT NULL DEFAULT 1 COMMENT '物流订单请求来源 1.大件货 2.资材商城 3.外部',
  `account_id` bigint NOT NULL DEFAULT 0 COMMENT '物流账号配置ID',
  `supplier_id` bigint NOT NULL DEFAULT 1 COMMENT '商户ID（区分平台）',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发货单号，当天同一货架号发货单号相同（唯一），限32字',
  `logistics_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1.德邦相关物流 2.顺丰相关物流 3.中通相关物流',
  `logistics_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '寻梦物流订单号',
  `logistics_num` int NOT NULL DEFAULT 1 COMMENT '应发物流单数量',
  `mail_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '第三方运单号',
  `config_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '内部物流类型：124 德邦冷链到店，22 德邦空运到店，154 中通空运到店，146 中通冷链到店，142 顺丰冷链到店，93 顺丰空运到店',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '物流单状态 0:数据入表; 1:物流单创建成功; ',
  `is_valid` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有效 0：未检测 1：有效  2：检测无效',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_logisticsno`(`logistics_no` ASC) USING BTREE,
  INDEX `idx_sendno_mailno`(`send_no` ASC, `mail_no` ASC) USING BTREE,
  INDEX `idx_mailno`(`mail_no` ASC) USING BTREE,
  INDEX `idx_logistics_mail_config`(`mail_no` ASC, `config_id` ASC, `status` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9399999252 AVG_ROW_LENGTH = 137 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货物流订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_logistics_order_detail
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_logistics_order_detail`;
CREATE TABLE `xm_bulky_logistics_order_detail`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `logistics_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '寻梦物流订单号',
  `service_brand` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '物流品牌',
  `service_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '服务名称',
  `agent_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '打印机',
  `print_id` bigint NOT NULL COMMENT '模版Id',
  `cargo_Type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '1.鲜花',
  `send_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '寄件人信息：寄件人省、市、区、detail、name、phone 配置json',
  `receive_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '收件人信息：收件人省、市、区、detail、name、phone 配置json',
  `weight` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '重量',
  `self_sn` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架号',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `item_num` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '扎数',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `route_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '二三段码，如：235 789',
  `sortation_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '大字与一段码，如：110',
  `consolidation_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '集包地名称，如：上海中转包',
  `consolidation_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '集包地代码，如：10112，圆通公司需要提供此代码',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_logisticsno`(`logistics_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 849117 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货物流订单详情表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_logistics_remind_push_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_logistics_remind_push_log`;
CREATE TABLE `xm_bulky_logistics_remind_push_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `task_id` bigint UNSIGNED NOT NULL COMMENT '关联xm_bulky_logistics_remind_task.id',
  `push_date` date NOT NULL COMMENT '推送日期',
  `time_point` int NOT NULL COMMENT '时间点，HHmm，如1000/1735',
  `push_status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '1成功 2失败',
  `push_content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '推送内容',
  `error_msg` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_task_date_time`(`task_id` ASC, `push_date` ASC, `time_point` ASC) USING BTREE,
  INDEX `idx_push_date`(`push_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流钉钉提醒推送日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_logistics_remind_task
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_logistics_remind_task`;
CREATE TABLE `xm_bulky_logistics_remind_task`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `brand_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流品牌（支持自定义）',
  `selected_config_ids` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '选中的物流config_id，逗号分隔',
  `selected_logistics_names` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '选中的物流名称快照（展示用）',
  `status` tinyint NOT NULL DEFAULT -1 COMMENT '0进行中 -1已结束',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0,
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0,
  `close_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0,
  `close_time` datetime NULL DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 -1删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status_data`(`status` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 900011 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流钉钉提醒任务配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_logistics_template
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_logistics_template`;
CREATE TABLE `xm_bulky_logistics_template`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `template_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板编码',
  `template_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板名称',
  `logistics_type` int NOT NULL COMMENT '物流类型',
  `service_brand` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '物流服务品牌',
  `default_print_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '默认打印名称',
  `service_code_rule` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '服务编码规则JSON',
  `kb_template_rule` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '快宝模板规则JSON',
  `cargo_type` int NOT NULL DEFAULT 1 COMMENT '货物类型',
  `account_id` bigint NOT NULL DEFAULT 0 COMMENT '物流账号id',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_user_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人id',
  `create_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人名称',
  `update_user_id` bigint NOT NULL DEFAULT 0 COMMENT '更新人id',
  `update_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0=正常，-100=删除/停用',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_template_code`(`template_code` ASC) USING BTREE,
  INDEX `idx_data_status`(`data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件物流模板表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_main_account
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_main_account`;
CREATE TABLE `xm_bulky_main_account`  (
  `user_id` bigint UNSIGNED NOT NULL COMMENT '主账号ID，对应xm_admin.userid',
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '登录账号快照',
  `nickname` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '姓名快照',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '数据状态 0-正常 -100-删除',
  PRIMARY KEY (`user_id`) USING BTREE,
  INDEX `idx_name_status`(`nickname` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货主账号转储表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_mall_activity_msg
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_mall_activity_msg`;
CREATE TABLE `xm_bulky_mall_activity_msg`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `activity_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动名称，限50字',
  `begin_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `send_time` datetime NOT NULL COMMENT '推送时间',
  `content` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动内容，限50字',
  `tips` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '温馨提示，限50字',
  `activity_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:未推送 1:已推送',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 66 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货活动订阅消息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_mall_vip
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_mall_vip`;
CREATE TABLE `xm_bulky_mall_vip`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '会员卡名称',
  `price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '会员卡价格',
  `valid_day` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '有效期（天）',
  `discount` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '折扣（默认服务费减0.5/kg）',
  `last_operator_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '最后一次操作用户id',
  `last_operator_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最后一次操作用户',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '默认 0：正常 -100：删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_mall_vip_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_mall_vip_order`;
CREATE TABLE `xm_bulky_mall_vip_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `vip_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_mall_vip.id',
  `vip_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '会员名称 如半年卡',
  `phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `transaction_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信方订单号',
  `pay_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0：微信支付 1：寻梦支付',
  `pay_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付状态：0：未支付 1：已支付',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款状态：默认0：无退款 1：已退款',
  `refund_success_time` datetime NULL DEFAULT NULL COMMENT '退款成功时间',
  `money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '购买价格',
  `buy_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '购买时间（支付完成）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_buytime`(`buy_time` ASC) USING BTREE,
  INDEX `idx_wareid`(`ware_id` ASC) USING BTREE,
  INDEX `idx_purchaserid`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 131 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会员购买记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_mall_vip_user
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_mall_vip_user`;
CREATE TABLE `xm_bulky_mall_vip_user`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `vip_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '会员名称：如季卡会员',
  `with_vip_days` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '会员陪伴天数',
  `total_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总优惠',
  `first_buy_time` datetime NULL DEFAULT NULL COMMENT '首次购买时间',
  `valid_date` date NULL DEFAULT NULL COMMENT '生效截止日期',
  `vip_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认0 正常 1 已过期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0：正常 -100：删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_purchaserid`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_wareid`(`ware_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户会员表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_nfc
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_nfc`;
CREATE TABLE `xm_bulky_nfc`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `sn` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `sn_str` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `scheme` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信小程序scheme',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区-货架',
  `order_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架号',
  `type` tinyint UNSIGNED NULL DEFAULT NULL,
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态 -100删除或遗失',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sn`(`sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 686 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Nfc 短链和货架号绑定关系' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_notice
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_notice`;
CREATE TABLE `xm_bulky_notice`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `kind` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '公告类型 1-普通公告 2-小课堂',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '公告类别 0:横幅 1:通知; 2:行业; 3:新闻; 10;其他; ',
  `show_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '（废弃）可见用户类型 1:给所有人看; 2:给买家看; 3:给卖家看; 4:给城市仓买家看 5:给新代卖用户看',
  `platform_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '平台类型 xm_bulky_platform.id',
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `header` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题，50字内',
  `header_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '头图，65535字内',
  `header_list_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '列表头图',
  `introduction` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '简介，20字内',
  `notice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '公告（横幅），4096字内',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序 升序',
  `carousel_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否参与首页轮播：0-否，1-是',
  `view_count` bigint NULL DEFAULT NULL,
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_appid_sortnum`(`app_id` ASC, `sort_num` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 419 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货公告表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_notice_read
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_notice_read`;
CREATE TABLE `xm_bulky_notice_read`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '阅读端口  1:供应商端; 2:采购端; 3:运营端',
  `notice_id` int NOT NULL DEFAULT 0 COMMENT '公告ID',
  `user_id` int NOT NULL DEFAULT 0 COMMENT 'userid',
  `read_time` datetime NOT NULL DEFAULT '0000-00-00 00:00:00' COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `id`(`id` ASC) USING BTREE,
  INDEX `notice_id`(`notice_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 43 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '阅览公告列表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_onsale_price
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_onsale_price`;
CREATE TABLE `xm_bulky_onsale_price`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级分类ID',
  `second_id` bigint NOT NULL COMMENT '二级分类id',
  `second_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级分类名称',
  `rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '标准价',
  `update_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新类型 0:系统更新 1:手动更新',
  `update_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新说明',
  `push_onsale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否更新到线上 0:不更新 1:更新',
  `push_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近一次更新日志',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_onsale_statistics
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_onsale_statistics`;
CREATE TABLE `xm_bulky_onsale_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `yyyy_mm_dd` date NOT NULL COMMENT '年月日yyyyMMdd，如2023-12-14',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `on_sale_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类在售数量',
  `on_sale_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '{}' COMMENT '在售详细信息json 按等级分',
  `supplier_on_sale_detail` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商在售信息json 包含在售供应商数量和花材扎数按供应商类型分',
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级分类id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_secondid_date`(`second_id` ASC, `yyyy_mm_dd` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1458 AVG_ROW_LENGTH = 161 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货在售统计表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_open_access
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_open_access`;
CREATE TABLE `xm_bulky_open_access`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `app_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开放平台ID',
  `app_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开放平台密钥',
  `access_token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开放平台token',
  `expire_time` bigint NOT NULL COMMENT 'token过期时间',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商ID',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_app_id`(`app_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '（废弃）寻梦大件货开放平台账户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_operation_log`;
CREATE TABLE `xm_bulky_operation_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '用户类型 0:系统; 1:平台; 2:供应商;',
  `operation_type` tinyint UNSIGNED NOT NULL DEFAULT 3 COMMENT '操作类型 1:分类; 2:供应商; 3:商品 4:标签; 5:营业时间; 6:公告; 7:物流配置; 8:用户订单; 9:供应商提现; 10:优惠券; 11:售后; 12:赔付; 13:供应商订单; 14:礼物; 15:退款退货 16:全局参数 17:采购方 18:虚拟账户 19:KA供应商提现 20:发货单',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作用户id（寻梦userid 供应商supplier_id）',
  `operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作用户姓名',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作内容，做了什么，请求的参数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_operation_type`(`operation_type` ASC) USING BTREE,
  INDEX `idx_createtime_userid_usertype`(`create_time` ASC, `operator_id` ASC, `user_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29005 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_order`;
CREATE TABLE `xm_bulky_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_purchaser采购方表主键id',
  `vip_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '会员卡名称',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号（唯一）',
  `order_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:普通订单 1:代下订单 默认0',
  `delivery_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '物流配送方式 1：物流配送  2：自提 默认1',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `partner_model` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认0 历史订单 1、不合并服务费且不包邮 2、合并服务费且不包邮 3、合并服务费且包邮',
  `merchant_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信支付商户号',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appId',
  `open_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信openId',
  `distribution_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '配送方式 0-无 1-送货上门 2-城市仓自提',
  `is_addition` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否加单 0:否; 1:是;',
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单平台 0：微信 1：抖音',
  `has_third_good` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单是否包含第三方平台商品，默认0不包含，1包含',
  `is_zq_settlement` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否结算给珍情 0:没有 1:已结算',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号，当天同一货架号发货单号相同',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次编号：yyyy-MM-dd',
  `order_num` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '每天流水号',
  `total_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '花材总扎数',
  `total_weight` int UNSIGNED NOT NULL COMMENT '花材总重(g)',
  `origin_total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原花材总重 单位：克',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '按物流和重量场次结束时生成的货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `zone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区-货架号',
  `express` bigint NOT NULL COMMENT '运输方式配置表id',
  `express_region` bigint NOT NULL COMMENT '运输方式下对应的配送区域id',
  `express_time` tinyint NULL DEFAULT NULL COMMENT '航空物流：0: 早、 1: 中、 2:晚班',
  `express_price` decimal(20, 2) UNSIGNED NOT NULL COMMENT '预估运费',
  `activity_express_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动物流名称',
  `before_activity_express_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '物流价格（活动优惠前）',
  `real_express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际物流id 0时不改物流',
  `real_express_region` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际物流配送区域id',
  `coupon_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单剩余优惠金额(用于结算)',
  `origin_coupon_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单原优惠金额',
  `add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加价（元）',
  `origin_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原加价（元）',
  `warehouse_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '城市仓加价（元）',
  `origin_warehouse_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '原城市仓加价（元）',
  `express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓物流加价（元）',
  `origin_express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原城市仓物流加价（元）',
  `delivery_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '配送费（元）',
  `origin_delivery_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原始配送费（元）',
  `modify_express_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '变更物流后预估运费',
  `is_change_express` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已修改物流 0:否; 1:是;',
  `actual_express_price` decimal(20, 2) UNSIGNED NULL DEFAULT NULL COMMENT '实际运费',
  `origin_supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商品合计供货价',
  `product_total_price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '商品合计价格（供货价+基础服务费）* 购买数量',
  `origin_product_total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原商品合计价格（供货价+基础服务费）* 购买数量',
  `service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总服务费（服务费单价*花材总重量）',
  `origin_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总服务费（服务费单价*花材总重量）',
  `extra_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '额外服务费',
  `origin_extra_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原额外服务费',
  `vip_discount_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'vip减免服务费',
  `origin_vip_discount_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原vip减免服务费',
  `platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台总补贴',
  `origin_platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原平台总补贴',
  `subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总单品补贴',
  `origin_subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总单品补贴',
  `negate_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓负加价',
  `origin_negate_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原城市仓负加价',
  `base_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总基础服务费：二级分类基础服务费 * 数量',
  `origin_base_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总基础服务费：二级分类基础服务费 * 数量',
  `partner_add_service_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分销商加价服务费',
  `origin_partner_add_service_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '原分销商加价服务费',
  `total_price` decimal(20, 2) UNSIGNED NOT NULL COMMENT '订单合计金额=商品合计金额+运费+服务费',
  `origin_total_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原订单合计金额=商品合计金额+运费+服务费',
  `origin_use_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '下单时原使用寻梦币',
  `use_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当前订单使用寻梦币金额，不含发货前退款的',
  `rebate_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单返点给用户的寻梦币金额',
  `origin_rebate_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原订单返点给用户的寻梦币金额',
  `actual_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付金额 = 订单合计金额 - 订单使用寻梦币金额',
  `origin_actual_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原实付金额（最初付的钱，不含部分退），用于微信退款',
  `ot_exp_add_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '繁花物流一次性加价（实际）',
  `origin_ot_exp_add_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '繁花物流一次性加价（原）',
  `platform_reduce_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台满减优惠金额（剩余），部分退款时按退回商品满减扣减',
  `origin_platform_reduce_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原平台满减优惠金额（下单时，不随部分退款变更）',
  `apply_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后申请商品总金额',
  `actual_refund` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后阶段实际退款金额（不超过申请售后商品的总价格+服务费）',
  `actual_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后阶段赔付寻梦币（小于等于售后申请商品总金额）',
  `paid_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付阶段总赔付金额（小于等于商品金额+服务费-实际退款金额）',
  `paid_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付阶段总赔付寻梦币（小于等于总供货价-售后赔付寻梦币）',
  `pay_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付方式 0：微信支付 1：寻梦平台账户支付 2：字节微信支付 3：字节支付宝支付',
  `pay_on_delivery` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否到付 0:否; 1:是 默认：0',
  `receive_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人名称',
  `receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人手机号',
  `nation_code` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '86' COMMENT '国际电话区号 默认86',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `district` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `receive_address` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址',
  `adcode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址adcode',
  `buyer_memo` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '买家留言',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台备注',
  `order_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单状态 0:待付款 1:已付款待发货 2:已发货待收货 3:已完成 4:已关闭 5:已取消',
  `after_sale_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单售后状态 0:无售后 1:售后申请中 2:售后同意 3:售后拒绝',
  `after_sale_agree_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后同意类型 0:无 1:发货前售后同意; 2:发货后售后同意;',
  `after_sale_count` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后申请次数，（待发货：取消订单不计）',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单退款状态 0:无退款 1:申请退款中 2:退款成功 3:退款失败 4:极速退款中 5:极速退款成功 6:极速退款失败',
  `print_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已打印 0:否; 1:是;',
  `wx_pay_time` datetime NULL DEFAULT NULL COMMENT '微信付款时间',
  `wx_pay_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信付款编号',
  `send_time` datetime NULL DEFAULT NULL COMMENT '发货时间',
  `delay_ddl` datetime NULL DEFAULT NULL COMMENT '人工售后截止时间',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认收货时间',
  `extra_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '额外信息',
  `coupon_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户优惠券id，0:没有用优惠券',
  `is_comment` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单是否已评价 0：未评价 1：已评价 默认0',
  `is_open_after_sale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启售后 0：关闭（正常售后） 1：开启（开启后强制用户端显示售后按钮）',
  `is_deliver` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）是否已配送 0:否; 1:是;（配货用字段）',
  `is_bond` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否履约（代供应商履约标记） 0:否; 1:是;',
  `is_cotton` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否保温棉 0:否; 1:是;',
  `flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '旗帜 0:灰',
  `bear_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后承担方 0:无; 1:梦晟; 2:昆明;',
  `is_bear_station_fee` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商是否承担提货站运费 0:否; 1:是;',
  `origin_total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原提货站运费总价=单价*sum(origin_item_num)',
  `total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '提货站运费当前总价=单价*sum(item_num)',
  `is_presale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为预售订单 0：不是 1：是 默认0',
  `is_sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为代卖订单 0-不是 1-是',
  `order_tag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:正 1：场 2：加',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `pid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商推广id',
  `ship_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '微信发货状态 默认0 无需发货 1 待发货 2 已发货',
  `unqualified_way` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '质检不合格处理方式 0:无 1:退货 2:降级 3:换货',
  `assign_customer_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分配客服id',
  `assign_customer_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分配客服姓名',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id，代下单时为下单客服userid',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_send_no`(`send_no` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_roundno_paytime_ordersn`(`round_no` ASC, `wx_pay_time` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_tel_ordersn_wareid`(`receive_tel` ASC, `order_sn` ASC, `ware_id` ASC) USING BTREE,
  INDEX `idx_is_sale_agency`(`is_sale_agency` ASC) USING BTREE,
  INDEX `idx_wxpaytime_ordersn`(`wx_pay_time` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_zone_shelf`(`zone_shelf` ASC) USING BTREE,
  INDEX `idx_wareid_ptime_ostatus`(`ware_id` ASC, `wx_pay_time` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_partnerid_ordersn`(`partner_id` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_helpid_roundno_status`(`help_id` ASC, `round_no` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_ordersn_wxpaytime`(`order_sn` ASC, `wx_pay_time` ASC) USING BTREE,
  INDEX `idx_roundno_wareid_sendno`(`round_no` ASC, `ware_id` ASC, `send_no` ASC) USING BTREE,
  INDEX `idx_ostatus_rno_osn`(`order_status` ASC, `round_no` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_shelfsn_wxpaytime_orderstatus`(`shelf_sn` ASC, `wx_pay_time` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_receivename`(`receive_name` ASC) USING BTREE,
  INDEX `idx_puid_wid_pid_os`(`purchaser_id` ASC, `ware_id` ASC, `partner_id` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_wxpaytime_orderstatus`(`wx_pay_time` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_wxpaytime_receiveaddress_orderstatus`(`wx_pay_time` ASC, `receive_address` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_ordersn_roundno_orderstatus`(`order_sn` ASC, `round_no` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_rno_ostatus_createtime_or`(`round_no` ASC, `order_status` ASC, `create_time` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_tel_paytime_ostatus`(`receive_tel` ASC, `wx_pay_time` ASC, `order_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 93048963 AVG_ROW_LENGTH = 1264 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货用户订单表' ROW_FORMAT = DYNAMIC;

