  `print_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已打印 0:否; 1:是;',
  `wx_pay_time` datetime NULL DEFAULT NULL COMMENT '微信付款时间',
  `wx_pay_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信付款编号',
  `send_time` datetime NULL DEFAULT NULL COMMENT '发货时间',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认收货时间',
  `extra_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '额外信息',
  `coupon_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户优惠券id，0:没有用优惠券',
  `is_comment` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单是否已评价 0：未评价 1：已评价 默认0',
  `is_open_after_sale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启售后 0：关闭（正常售后） 1：开启（开启后强制用户端显示售后按钮）',
  `is_deliver` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）是否已配送 0:否; 1:是;（配货用字段）',
  `is_bond` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否履约（代供应商履约标记） 0:否; 1:是;',
  `is_cotton` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否保温棉 0:否; 1:是;',
  `flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '旗帜 0:灰',
  `bear_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后承担方 0:无; 1:梦晟; 2:昆明;',
  `is_bear_station_fee` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商是否承担提货站运费 0:否; 1:是;',
  `origin_total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原提货站运费总价=单价*sum(origin_item_num)',
  `total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '提货站运费当前总价=单价*sum(item_num)',
  `is_presale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为预售订单 0：不是 1：是 默认0',
  `is_sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为代卖订单 0-不是 1-是',
  `order_tag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:正 1：场 2：加',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `pid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销推广id',
  `unqualified_way` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '质检不合格处理方式 0:无 1:退货 2:降级 3:换货',
  `assign_customer_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分配客服id',
  `assign_customer_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分配客服姓名',
  `ship_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '微信发货状态 默认0 无需发货 1 待发货 2 已发货',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id，代下单时为下单客服userid',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_send_no`(`send_no` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_purchaserid_wareid`(`purchaser_id` ASC, `ware_id` ASC) USING BTREE,
  INDEX `idx_roundno_paytime_ordersn`(`round_no` ASC, `wx_pay_time` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_tel_ordersn_wareid`(`receive_tel` ASC, `order_sn` ASC, `ware_id` ASC) USING BTREE,
  INDEX `idx_is_sale_agency`(`is_sale_agency` ASC) USING BTREE,
  INDEX `idx_wxpaytime_ordersn`(`wx_pay_time` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_zone_shelf`(`zone_shelf` ASC) USING BTREE,
  INDEX `idx_wareid_ptime_ostatus`(`ware_id` ASC, `wx_pay_time` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_partnerid_ordersn`(`partner_id` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_helpid_roundno_status`(`help_id` ASC, `round_no` ASC, `order_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4396455 AVG_ROW_LENGTH = 1264 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货用户订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_order_cancel_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_order_cancel_record`;
CREATE TABLE `xm_bulky_order_cancel_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `record_type` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '记录类型0：取消订单 1：部分退款',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `refund_purchaser` decimal(10, 2) UNSIGNED NULL DEFAULT 0.00 COMMENT '退给用户的',
  `deduct_supplier` decimal(10, 2) UNSIGNED NULL DEFAULT 0.00 COMMENT '扣供应商的',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1785 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件批发订单取消订单（已支付）、部分退款记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_order_comment
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_order_comment`;
CREATE TABLE `xm_bulky_order_comment`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL COMMENT '用户id',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户昵称',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `score` tinyint UNSIGNED NOT NULL DEFAULT 5 COMMENT '评分：1-5颗星',
  `content` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '评价内容',
  `pictures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '评价图片',
  `comment_time` datetime NOT NULL COMMENT '评价时间',
  `reply_admin_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '回复人id',
  `reply_admin_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '回复人名称',
  `reply_content` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '回复内容',
  `reply_pictures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '回复图片',
  `reply_time` datetime NULL DEFAULT NULL COMMENT '回复时间',
  `is_show` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否展示 0:否; 1:是;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_sn`(`order_sn` ASC) USING BTREE COMMENT '订单编号',
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE COMMENT '用户id'
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户订单评价表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_order_edit
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_order_edit`;
CREATE TABLE `xm_bulky_order_edit`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '记录id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户订单号',
  `field` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '字段',
  `old_data` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '旧数据',
  `new_data` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '新数据',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作用户id',
  `operator_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作用户姓名',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_field_ordersn`(`field` ASC, `order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5526391 AVG_ROW_LENGTH = 140 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货订单编辑记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_order_info
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_order_info`;
CREATE TABLE `xm_bulky_order_info`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单orderSn',
  `send_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单发货单',
  `api_order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '三方订单号',
  `has_cotton` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有保温品 默认0 没有 1有',
  `cotton_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '保温品信息',
  `promote_merchant_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推广商家 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_sendno`(`send_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2121093 AVG_ROW_LENGTH = 330 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单详情表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_order_item
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_order_item`;
CREATE TABLE `xm_bulky_order_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方用户id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `order_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '每天货架号',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '按物流和重量 场次结束时生成的货架号',
  `sub_shelf_sn` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'xm_bulky_order表order_sn：用户订单号',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次编号：yyyy-MM-dd',
  `supplier_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商订单号',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_product商品表主键id',
  `product_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '等级123456->ABCDEO',
  `sku_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品图片',
  `spec_and_num` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格数量+规格名称',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单商品描述',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单商品备注，限128字',
  `supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价单价',
  `pay_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付单价',
  `platform_discount_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台补贴单价 元/扎',
  `subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '单品补贴单价 元/扎',
  `coupon_pay_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '优惠后实付单价',
  `total_discount_refundable` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `origin_total_discount_refundable` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原总的优惠后的金额（可退）',
  `coupon_discount_per_bundle` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '每一扎优惠券优惠多少（元）',
  `full_reduction_discount_per_bundle` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '每一扎满减的优惠多少（元）',
  `add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加价单价（元）',
  `total_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当前剩余平台加价合计',
  `origin_total_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '创建时平台加价合计',
  `warehouse_add_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '城市仓加价单价（元）',
  `negate_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓负加价单价（元）',
  `station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '提货站运费单价（扎item_num）',
  `express_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓物流加价单价（元）',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单商品数量',
  `origin_item_num` int UNSIGNED NOT NULL COMMENT '订单创建时商品数量，值不变',
  `after_sale_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后退的商品数量（生成送货单的商品数量=购买数量-售后退的数量）',
  `after_sale_refund` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后退的金额（由售后退的数量计算得来或者是客服手动填入）',
  `bond_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）代履约的商品数量（这部分商品供货价的钱不结算给供应商）',
  `after_sale_supplier_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商售后承担商品数量（小于等于售后退的商品数量，小于等于item_num-bond_item_num）',
  `actual_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付单价x数量',
  `origin_actual_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原实付单价x数量',
  `service_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '服务费单价',
  `partner_add_service_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '每扎分销商加价服务费（元）',
  `total_partner_add_service_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '该商品行总分销商加价服务费（元）',
  `total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价x数量',
  `origin_total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原供货价x数量',
  `total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品总重量 g',
  `origin_total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原商品总重',
  `is_comment` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否评价 0:未评价; 1:已评价;',
  `after_sale_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单售后状态 0:无售后 1:售后申请中 2:售后同意 3:售后拒绝',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款状态 0:无退款 1:申请退款中 2:退款成功',
  `printer_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小票打印状态 0：未打印  1：已打印',
  `printer_time` int UNSIGNED NULL DEFAULT 0 COMMENT '打印时间',
  `is_deliver` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已配货 0:未配货; 1:已配货;（配货用字段）',
  `is_rebate` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否返点 0:否; 1:是;',
  `third_good_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '第三方商品id，默认0，大于0 表示三方平台商品',
  `is_no_quality_issue` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否7天0质检 默认 0不是 1是',
  `is_prefer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为优选商品 默认0不是 1是',
  `quality_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否品质花材 0-否 1-是',
  `deliver_time` datetime NULL DEFAULT NULL COMMENT '订单商品配货时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_roundno`(`round_no` ASC) USING BTREE,
  INDEX `idx_sid_rno_osn`(`supplier_id` ASC, `round_no` ASC, `order_sn` ASC) USING BTREE,
  INDEX `idx_round_product_user`(`round_no` ASC, `product_id` ASC, `purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36881471 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货订单商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_order_item_comment
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_order_item_comment`;
CREATE TABLE `xm_bulky_order_item_comment`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型：0：默认好评 1：主动有图 2：主动无图',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `nickname` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户昵称',
  `avatar_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '用户头像',
  `phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户手机号',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `order_item_id` bigint UNSIGNED NULL DEFAULT 0 COMMENT '订单商品主键id',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appId',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `score` tinyint UNSIGNED NOT NULL DEFAULT 5 COMMENT '评分：1-5颗星',
  `words` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '评价预设词汇',
  `content` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '评价内容',
  `pictures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '评价图片',
  `videos` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '评价视频',
  `comment_time` datetime NOT NULL COMMENT '评价时间',
  `reply_admin_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '回复人id',
  `reply_admin_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '回复人名称',
  `reply_content` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '回复内容',
  `reply_pictures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '回复图片',
  `reply_time` datetime NULL DEFAULT NULL COMMENT '回复时间',
  `is_show` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否展示 0:否; 1:是;',
  `is_show_shop` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否店铺评价展示 0:否; 1:是;',
  `is_show_product` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否商品评价展示 0:否; 1:是;',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE COMMENT '订单编号',
  INDEX `idx_cmtime`(`comment_time` ASC) USING BTREE,
  INDEX `idx_productid_isshow_commenttime`(`product_id` ASC, `is_show` ASC, `comment_time` ASC) USING BTREE,
  INDEX `idx_supplierid_type_commenttime`(`supplier_id` ASC, `type` ASC, `comment_time` ASC) USING BTREE,
  INDEX `idx_app_status_show_type_time_product`(`app_id` ASC, `data_status` ASC, `is_show` ASC, `type` ASC, `comment_time` ASC, `product_id` ASC) USING BTREE,
  INDEX `idx_supplierid_isshow_commenttime`(`supplier_id` ASC, `is_show` ASC, `comment_time` ASC) USING BTREE,
  INDEX `idx_pr_ty_ct_dt`(`purchaser_id` ASC, `type` ASC, `comment_time` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_purchaserid_commenttime`(`purchaser_id` ASC, `comment_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9506283 AVG_ROW_LENGTH = 558 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户订单商品评价表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_order_local
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_order_local`;
CREATE TABLE `xm_bulky_order_local`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_purchaser采购方表主键id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号（唯一）',
  `order_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:普通订单 1:代下订单 默认0',
  `is_addition` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否加单 0:否; 1:是;',
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单平台 0：微信 1：抖音',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号，当天同一货架号发货单号相同',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次编号：yyyy-MM-dd',
  `order_num` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '每天货架号',
  `total_weight` int UNSIGNED NOT NULL COMMENT '花材总重(g)',
  `express` int UNSIGNED NOT NULL COMMENT '运输方式配置表id',
  `express_region` bigint NOT NULL COMMENT '运输方式下对应的配送区域id',
  `express_time` tinyint NULL DEFAULT NULL COMMENT '航空物流：0: 早、 1: 中、 2:晚班',
  `express_price` decimal(20, 2) UNSIGNED NOT NULL COMMENT '预估运费',
  `add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加价（元）',
  `modify_express_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '变更物流后预估运费',
  `is_change_express` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已修改物流 0:否; 1:是;',
  `actual_express_price` decimal(20, 2) UNSIGNED NULL DEFAULT NULL COMMENT '实际运费',
  `product_total_price` decimal(20, 2) UNSIGNED NOT NULL COMMENT '商品合计价格（供货价+基础服务费）* 购买数量',
  `service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总服务费（服务费单价*花材总重量）',
  `base_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总基础服务费：二级分类基础服务费 * 数量',
  `total_price` decimal(20, 2) UNSIGNED NOT NULL COMMENT '订单合计金额=商品合计金额+运费+服务费',
  `origin_use_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '下单时原使用寻梦币',
  `use_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '当前订单使用寻梦币金额，不含发货前退款的',
  `rebate_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单返点给用户的寻梦币金额',
  `actual_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付金额 = 订单合计金额 - 订单使用寻梦币金额',
  `origin_actual_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原实付金额（最初付的钱，不含部分退），用于微信退款',
  `apply_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后申请商品总金额',
  `actual_refund` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后阶段实际退款金额（不超过申请售后商品的总价格+服务费）',
  `actual_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后阶段赔付寻梦币（小于等于售后申请商品总金额）',
  `paid_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付阶段总赔付金额（小于等于商品金额+服务费-实际退款金额）',
  `paid_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付阶段总赔付寻梦币（小于等于总供货价-售后赔付寻梦币）',
  `pay_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付方式 0：微信支付 1：寻梦平台账户支付 2：字节微信支付 3：字节支付宝支付',
  `pay_on_delivery` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否到付 0:否; 1:是 默认：0',
  `receive_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人名称',
  `receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人手机号',
  `receive_address` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址',
  `adcode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址adcode',
  `buyer_memo` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '买家留言',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台备注',
  `order_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单状态 0:待付款 1:已付款待发货 2:已发货待收货 3:已完成 4:已关闭 5:已取消',
  `after_sale_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单售后状态 0:无售后 1:售后申请中 2:售后同意 3:售后拒绝',
  `return_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款退货状态 0:无退货; 1:申请退货; 2:同意退货;',
  `after_sale_agree_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后同意类型 0:无 1:发货前售后同意; 2:发货后售后同意;',
  `after_sale_count` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后申请次数，（待发货：取消订单不计）',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单退款状态 0:无退款 1:申请退款中 2:退款成功 3:退款失败 4:极速退款中 5:极速退款成功 6:极速退款失败',
  `print_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已打印 0:否; 1:是;',
  `wx_pay_time` datetime NULL DEFAULT NULL COMMENT '微信付款时间',
  `wx_pay_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信付款编号',
  `send_time` datetime NULL DEFAULT NULL COMMENT '发货时间',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认收货时间',
  `extra_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '额外信息',
  `coupon_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户优惠券id，0:没有用优惠券',
  `is_comment` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单是否已评价 0：未评价 1：已评价 默认0',
  `is_open_after_sale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启售后 0：关闭（正常售后） 1：开启（开启后强制用户端显示售后按钮）',
  `is_bond` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否履约（代供应商履约标记） 0:否; 1:是;',
  `is_cotton` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否保温棉 0:否; 1:是;',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id，代下单时为下单客服userid',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `is_deliver` tinyint NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_send_no`(`send_no` ASC) USING BTREE,
  INDEX `idx_wx_pay_time`(`wx_pay_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19603 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货用户订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_order_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_order_log`;
CREATE TABLE `xm_bulky_order_log`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `pid` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '唯一标识',
  `order_sn` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户订单号',
  `wx_pay_id` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微信支付单号',
  `time` datetime NULL DEFAULT NULL COMMENT '付款时间',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单类型',
  `pay_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '支付当时',
  `order_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单分类',
  `total_price` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '订单金额',
  `paid_coin` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '使用返点币',
  `paid_coin_new` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '使用补贴币新',
  `wechat_pay` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '微信支付',
  `xm_credit` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '寻梦授信',
  `xm_balance` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '寻梦余额',
  `xm_wholesale` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '批发余额',
  `product_price` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '商品价格',
  `service_fee` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '服务费',
  `express_price` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '运费',
  `ware_price` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '城市仓结算',
  `supply_price` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '供应商结算',
  `take_ratio` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '抽点金额',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pid`(`pid` ASC) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_time`(`time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 64 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户订单日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_order_paid
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_order_paid`;
CREATE TABLE `xm_bulky_order_paid`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户订单号',
  `reason_type` tinyint UNSIGNED NOT NULL COMMENT '赔付原因 1:缺货赔付 2:二次售后 10:其他',
  `paid_reason` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '赔付原因说明，限128字',
  `user_type` tinyint UNSIGNED NOT NULL COMMENT '用户类型 1:采购方（赔付）; 2:供应商（承担）;',
  `purchaser_id` bigint UNSIGNED NOT NULL COMMENT '采购方id',
  `supplier_id` bigint UNSIGNED NOT NULL COMMENT '供应商id（用户类型为供应商时用，采购方时为0）',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '金额（采购方：同一用户订单号的金额之和不超过总供货价+服务费，供应商：同一用户订单号的供应商承担金额之和不超过供应商订单总供货价）',
  `xm_coin` decimal(10, 2) UNSIGNED NOT NULL COMMENT '寻梦币（采购方：同一用户订单号的寻梦币之和不超过总供货价，供应商：同一用户订单号的寻梦币之和不超过总供货价）',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款状态 0:无退款 1:同意退款 2:退款中 3:退款成功 4:退款失败',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;（只有无退款可以删）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3674 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货用户订单赔付（不包括运费）表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_order_reconciliation
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_order_reconciliation`;
CREATE TABLE `xm_bulky_order_reconciliation`  (
  `source_channel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '来源渠道：分销商/花仓酷/寻梦批发',
  `source_id` bigint NOT NULL COMMENT '来源业务表主键',
  `statement_date` date NOT NULL COMMENT '对账日期',
  `platform_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '平台/仓类型',
  `partner_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分销商名称',
  `merchant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商户号',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户订单号',
  `payment_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '支付单号/退款单号',
  `business_time` datetime NOT NULL COMMENT '支付、退款成功或补运费时间',
  `order_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '支付/退货/售后/退运费/补运费',
  `payment_method` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '支付方式',
  `order_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '订单金额',
  `rebate_coin_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '返点币/币',
  `subsidy_coin_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '补贴币',
  `online_payment_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '微信、通联、B2B、微企付等在线支付金额',
  `coupon_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '优惠券',
  `platform_reduce_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '满减优惠',
  `credit_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '寻梦授信',
  `xunmeng_balance_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '寻梦余额',
  `wholesale_balance_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '批发余额',
  `distributor_balance_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '分销余额',
  `product_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '商品价格',
  `service_fee` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '服务费',
  `freight_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '运费',
  `distributor_markup_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '分销商加价',
  `city_warehouse_settlement` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '城市仓结算',
  `xunmeng_markup_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '寻梦加价',
  `item_subsidy_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '单品补贴',
  `supplier_settlement` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商结算',
  `commission_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '抽点金额',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '首次写入时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后同步时间',
  PRIMARY KEY (`source_channel`, `order_type`, `source_id`) USING BTREE,
  INDEX `idx_payment_no`(`payment_no` ASC) USING BTREE,
  INDEX `idx_business_time`(`business_time` ASC) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_statement_date`(`statement_date` ASC) USING BTREE
) ENGINE = InnoDB AVG_ROW_LENGTH = 581 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '花材批发用户订单维度对账单' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Table structure for xm_bulky_order_remark_history
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_order_remark_history`;
CREATE TABLE `xm_bulky_order_remark_history`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `remark_md5` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注md5，用于查找是否有相同备注了',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE COMMENT '用户id'
) ENGINE = InnoDB AUTO_INCREMENT = 408 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单备注历史记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_pack_config
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_pack_config`;
CREATE TABLE `xm_bulky_pack_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `pack_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '包装名称，限20字',
  `pack_weight` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 1.00 COMMENT '包装重量（kg）',
  `flower_weight` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 1.00 COMMENT '预估花材重量（kg）',
  `flower_volume` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '预估可装花材体积（cm³），0表示不参与体积推荐',
  `pack_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '耗材单价（元）',
  `labor_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '打包人工单价（元）',
  `logistics_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '物流出库人工单价（元）',
  `pic_url` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片 限128字',
  `remark` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注，限36字',
  `sort` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序值',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 46 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '包装配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_package_benefit
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_package_benefit`;
CREATE TABLE `xm_bulky_package_benefit`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `package_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '打包人姓名',
  `package_user_id` bigint UNSIGNED NULL DEFAULT 0 COMMENT '打包人id',
  `ware_id` bigint UNSIGNED NULL DEFAULT 0 COMMENT '城市仓id',
  `ware_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '城市仓名称',
  `shelf_sn` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货架号',
  `date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '场次',
  `total_weight` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '总重量',
  `total_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '价格',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '包裹打包受益' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_package_box_modify_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_package_box_modify_record`;
CREATE TABLE `xm_bulky_package_box_modify_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架号',
  `package_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '包裹ID',
  `origin_pack_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '原箱型ID',
  `origin_pack_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '原箱型名称',
  `target_pack_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '目标箱型ID',
  `target_pack_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '目标箱型名称',
  `operate_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '修改人ID',
  `operate_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '修改人姓名',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '修改备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '数据状态 0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_round_shelf`(`round_no` ASC, `shelf_sn` ASC) USING BTREE,
  INDEX `idx_package_id`(`package_id` ASC) USING BTREE,
  INDEX `idx_operate_user_id`(`operate_user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 42 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '批发业务包裹箱型修改记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_package_deadline_snapshot
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_package_deadline_snapshot`;
CREATE TABLE `xm_bulky_package_deadline_snapshot`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `team_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '打包团队id',
  `team_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '打包团队名称',
  `leader_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '快照时负责人id',
  `leader_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '快照时负责人名称',
  `area_name_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '快照时负责分区名称JSON',
  `zone_code_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '快照时有效分区编码JSON',
  `shelf_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '去重主货架数量',
  `package_deadline_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '快照时打包要求完成时间规则',
  `required_complete_time` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '要求完成时间HH:mm',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_round_team`(`round_no` ASC, `team_id` ASC) USING BTREE,
  INDEX `idx_round_leader_update`(`round_no` ASC, `leader_id` ASC, `update_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '打包要求完成时间快照表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_package_modify_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_package_modify_record`;
CREATE TABLE `xm_bulky_package_modify_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架号',
  `package_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '包裹ID',
  `origin_express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '原物流ID',
  `origin_express_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '原物流名称',
  `target_express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '目标物流ID',
  `target_express_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '目标物流名称',
  `operate_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '修改人ID',
  `operate_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '修改人姓名',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '修改备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '数据状态 0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_round_shelf`(`round_no` ASC, `shelf_sn` ASC) USING BTREE,
  INDEX `idx_package_id`(`package_id` ASC) USING BTREE,
  INDEX `idx_operate_user_id`(`operate_user_id` ASC) USING BTREE,
  INDEX `idx_sendno`(`send_no` DESC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '批发业务包裹物流修改记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_package_volume_compare
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_package_volume_compare`;
CREATE TABLE `xm_bulky_package_volume_compare`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `round_no` date NOT NULL COMMENT '场次',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货位号',
  `express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流ID，多个取第一个',
  `express_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流名称，多个用/拼接',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '入场总扎数（不含虚拟商品）',
  `total_volume` decimal(20, 5) NOT NULL DEFAULT 0.00000 COMMENT '去除特殊花材后的花材总体积（cm³）',
  `no_volume_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '体积为0的扎数（无等级sku，不含特殊花材）',
  `normal_package_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '正常状态面单数',
  `normal_suggest_pack` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '正常状态推荐箱型汇总，如：110*50*50箱x2;蝴蝶兰x1',
  `delete_package_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '删除状态面单数',
  `delete_suggest_pack` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '删除状态推荐箱型汇总',
  `actual_package_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际使用箱数（正常状态且已选箱）',
  `actual_pack` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '实际使用箱型汇总',
  `volume_package_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '按体积推荐箱数（含特殊花材专用箱）',
  `volume_suggest_pack` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '按体积推荐箱型汇总',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_round_shelf`(`round_no` ASC, `shelf_sn` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '包裹按体积推荐对比' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_part_distributor_income
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_part_distributor_income`;
CREATE TABLE `xm_bulky_part_distributor_income`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `date` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次',
  `num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '配货总数',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '金额',
  `type` tinyint NOT NULL DEFAULT 1 COMMENT '收益类型：1 配货，2 理货',
  `user_id` bigint NOT NULL COMMENT '兼职配货员id',
  `username` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '兼职配货员姓名',
  `detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '明细（分区、扎数、单价、收益）',
  `settle_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已提现至余额，0：否 1：是',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_userId_date`(`date` DESC, `user_id` ASC, `type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51640 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '兼职配货员收益表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_part_logistics
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_part_logistics`;
CREATE TABLE `xm_bulky_part_logistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `date` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '兼职物流员id',
  `user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '兼职物流员姓名',
  `manage_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '管理id',
  `manage_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '管理名称',
  `start_manage_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '开始管理id',
  `start_manage_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开始管理名称',
  `end_manage_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '结束管理id',
  `end_manage_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '结束管理名称',
  `start_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '单价',
  `total_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '薪资',
  `duration` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '时长（小时）',
  `settle_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否结算至余额，0否 1是',
  `user_type` tinyint NOT NULL DEFAULT 1 COMMENT '打卡类型 (1: 物流员; 2:配货员; 默认 1)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_date`(`date` ASC) USING BTREE,
  INDEX `idx_startTime`(`start_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 184 AVG_ROW_LENGTH = 273 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '兼职物流员工资结算' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_part_logistics_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_part_logistics_log`;
CREATE TABLE `xm_bulky_part_logistics_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `part_logistics_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '结算id',
  `old_start_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新前开工时间',
  `new_start_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新后开工时间',
  `old_end_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新前收工时间',
  `new_end_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新后收工时间',
  `duration` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '工作时长变化（可负）',
  `content` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '修改内容',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pid`(`part_logistics_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 104 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '兼职物流员工资结算修改记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_pay_type
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_pay_type`;
CREATE TABLE `xm_bulky_pay_type`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `biz_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '业务类型 1-寻梦批发 2-花仓酷 3-寻梦代卖 4-寻梦供应商 5-分销商',
  `name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付方式名称',
  `channel_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '渠道code',
  `mch_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户id',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-关闭 1-启用',
  `sort` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序 顺序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货支付方式表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_phone_call
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_phone_call`;
CREATE TABLE `xm_bulky_phone_call`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `call_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '回执 ID',
  `duration` int UNSIGNED NOT NULL COMMENT '通话时间',
  `create_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_phone_change_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_phone_change_log`;
CREATE TABLE `xm_bulky_phone_change_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `purchaser_id` bigint NOT NULL COMMENT '采购用户ID',
  `old_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '脱敏后的原手机号',
  `old_phone_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '原手机号SHA-256，用于历史开票查询',
  `new_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '脱敏后的新手机号',
  `operator_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'PURCHASER/ADMIN',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `reason` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '运营换绑原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_phone_change_purchaser_time`(`purchaser_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_phone_change_old_phone_hash`(`old_phone_hash` ASC) USING BTREE,
  INDEX `idx_phone_change_operator_time`(`operator_type` ASC, `operator_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '采购用户手机号换绑记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_platform
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_platform`;
CREATE TABLE `xm_bulky_platform`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货平台表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_platform_bind
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_platform_bind`;
CREATE TABLE `xm_bulky_platform_bind`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `session_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '会话密钥',
  `open_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '用户在当前小程序的ID',
  `platform` tinyint UNSIGNED NULL DEFAULT 1 COMMENT '平台：1：抖音',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '0：正常 -100：删除，默认0',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_open_id`(`open_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购端用户账号和第三方平台绑定关系表（不含微信，微信绑定关系已存在于用户表里）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_platform_invoice
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_platform_invoice`;
CREATE TABLE `xm_bulky_platform_invoice`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `request_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请单号',
  `purchaser_id` bigint NOT NULL COMMENT '花店ID',
  `purchaser_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '花店手机号',
  `registration_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '登记单ID',
  `invoice_type` tinyint NOT NULL COMMENT '类型：1运费 2服务费',
  `title_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抬头名称',
  `tax_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '税号',
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '银行账号',
  `company_address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业地址',
  `company_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业电话',
  `amount` decimal(12, 2) NOT NULL COMMENT '开票金额',
  `invoice_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发票地址',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0待开票 1已开票 2已逾期',
  `deadline` datetime NULL DEFAULT NULL COMMENT '截止日期',
  `upload_time` datetime NULL DEFAULT NULL COMMENT '发票上传时间',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人姓名',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_request_no`(`request_no` ASC) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_invoice_type`(`invoice_type` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '平台开票记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_price_mgr_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_price_mgr_log`;
CREATE TABLE `xm_bulky_price_mgr_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `old_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '更新前价格',
  `new_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '更新后价格',
  `version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '版本',
  `opeartor_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人id',
  `opeartor_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `is_success` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否更新成功 0失败 1成功 默认0',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_second_id_rank_num`(`second_id` ASC, `rank_num` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 372239 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '价目管理日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_price_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_price_operation_log`;
CREATE TABLE `xm_bulky_price_operation_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `biz_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务对象id，新增失败等尚未生成id的场景允许为空',
  `biz_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '业务对象名称快照',
  `operation_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '操作类型编码：CREATE-新增 UPDATE-修改 DELETE-删除 ENABLE-启用 DISABLE-停用 BIND-绑定 UNBIND-解绑 BATCH_SET-批量配置 REFRESH-刷新重算',
  `operation_desc` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '操作内容摘要，用于列表直接展示',
  `before_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '操作前数据快照，JSON字符串',
  `after_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '操作后数据快照，JSON字符串',
  `result_status` tinyint NOT NULL DEFAULT 1 COMMENT '操作结果：0失败 1成功',
  `fail_reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '失败原因，成功时为空字符串',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人id，系统操作允许为空',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '操作人姓名，系统操作可存系统或任务名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_operator_time`(`operator_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 133 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '价格操作审计日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_price_rule
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_price_rule`;
CREATE TABLE `xm_bulky_price_rule`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '加价规则名称',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规则说明',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建人',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最后操作人',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0-正常 -100-删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_name`(`name` ASC) USING BTREE,
  INDEX `idx_data_status`(`data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '平台加价规则' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_price_rule_class
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_price_rule_class`;
CREATE TABLE `xm_bulky_price_rule_class`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rule_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '加价规则ID',
  `class_level` tinyint NOT NULL COMMENT '分类层级 1一级分类 2二级分类',
  `class_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分类ID（class_level=1 为 xm_bulky_class_first.id，=2 为 xm_bulky_class_second.id）',
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '所属一级分类ID（class_level=2 时冗余，便于搜索）',
  `add_price_a` decimal(5, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'A级加价 元/扎',
  `add_price_b` decimal(5, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'B级加价 元/扎',
  `add_price_c` decimal(5, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'C级加价 元/扎',
  `add_price_d` decimal(5, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'D级加价 元/扎',
  `add_price_e` decimal(5, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'E级加价 元/扎',
  `add_price_o` decimal(5, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'O级加价 元/扎',
  `add_price_none` decimal(5, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '无等级(rank_num=0)加价 元/扎',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_rule_class`(`rule_id` ASC, `class_level` ASC, `class_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 190 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '平台加价规则-分类等级加价' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_price_strategy
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_price_strategy`;
CREATE TABLE `xm_bulky_price_strategy`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '策略名称',
  `strategy_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '策略类型 1普通批发 2渠道策略（创建后不可修改）',
  `rule_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '绑定的加价规则ID',
  `effect_type` tinyint UNSIGNED NOT NULL DEFAULT 2 COMMENT '生效方式 1指定区间 2永久生效',
  `effect_start_time` datetime NULL DEFAULT NULL COMMENT '生效开始时间（effect_type=1 必填）',
  `effect_end_time` datetime NULL DEFAULT NULL COMMENT '生效结束时间（effect_type=1 必填）',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '开启状态 0关闭 1开启',
  `operator_id` bigint UNSIGNED NULL DEFAULT 0 COMMENT '创建人',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NULL DEFAULT 0 COMMENT '最后操作人',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0-正常 -100-删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_type_status`(`strategy_type` ASC, `status` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_rule_id`(`rule_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 37 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '平台加价策略' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_price_strategy_target
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_price_strategy_target`;
CREATE TABLE `xm_bulky_price_strategy_target`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `strategy_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '策略ID',
  `target_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '对象类型 1省份 2城市 3分销商 4城市仓',
  `target_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '对象标识：省/城市=adcode，分销商=xm_bulky_supplier.id(type=6)，城市仓=city_warehouse.id',
  `target_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '对象名称冗余（列表摘要展示）',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_strategy_target`(`strategy_id` ASC, `target_type` ASC, `target_code` ASC) USING BTREE,
  INDEX `idx_target`(`target_type` ASC, `target_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1507 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '平台加价策略-关联对象' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_print_config
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_print_config`;
CREATE TABLE `xm_bulky_print_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint NOT NULL DEFAULT 1 COMMENT '三方商户ID',
  `environment` tinyint NOT NULL DEFAULT 0 COMMENT '环境 0:测试环境 1.正式环境',
  `source` tinyint NOT NULL DEFAULT 1 COMMENT '请求来源 1.大件批发 2.资材商城（物流固定配置不区分）',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配置名称',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 0-地址 1-顺丰 2-中通 3-德邦',
  `info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配置json',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 334 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货打印配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_print_device
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_print_device`;
CREATE TABLE `xm_bulky_print_device`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备id',
  `pic_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片二维码，限512字',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货打印设备表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_print_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_print_log`;
CREATE TABLE `xm_bulky_print_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `cp_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sf:顺丰速运 dp:德邦',
  `operation_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作数据',
  `operation_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作结果',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作用户名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 61 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货打印记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_print_logistics
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_print_logistics`;
CREATE TABLE `xm_bulky_print_logistics`  (
  `print_logistics_id` bigint NOT NULL COMMENT '主键',
  `servicebrand` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '服务商标识：dp/sf/zt/sto/yd/yt/jd/ky',
  `printemplate` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'KB云打印模板ID（ky跨越自有打印，可为空）',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '打印物流名称',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NULL DEFAULT 0 COMMENT '数据状态 0=正常 -100=删除',
  `source` tinyint UNSIGNED NULL DEFAULT 1 COMMENT '来源默认是1大件2资材3其他',
  `ids` bigint NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`ids` DESC) USING BTREE,
  UNIQUE INDEX `uk_servicebrand`(`servicebrand` ASC) USING BTREE,
  UNIQUE INDEX `uk_source_print_logistics`(`print_logistics_id` ASC, `source` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '打印物流表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_print_logistics_config
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_print_logistics_config`;
CREATE TABLE `xm_bulky_print_logistics_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `configid` bigint NOT NULL COMMENT '关联现有configId（对应LogisticsUtil中的configId常量）',
  `print_logistics_id` bigint NOT NULL COMMENT 'FK → xm_bulky_print_logistics.id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配置名称',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NULL DEFAULT 0 COMMENT '数据状态 0=正常 -100=删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_configid`(`configid` ASC) USING BTREE,
  INDEX `idx_print_logistics_id`(`print_logistics_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '打印物流配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_print_printers
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_print_printers`;
CREATE TABLE `xm_bulky_print_printers`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint NOT NULL DEFAULT 0 COMMENT '商户Id',
  `source` tinyint NOT NULL DEFAULT 1 COMMENT '请求来源 1.大件批发 2.资材商城 3.',
  `agent_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '打印机key',
  `remark` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '打印机备注',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT ' 0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 62 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货打印机列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_print_template
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_print_template`;
CREATE TABLE `xm_bulky_print_template`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称，限32字',
  `template_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板编号，限64字',
  `is_show` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否显示 0:否 1:是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_templateid`(`template_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '打印模板表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_product
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product`;
CREATE TABLE `xm_bulky_product`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id 0为未指定二级分类',
  `third_good_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '三方平台商品id 0为我们平台供应商的商品',
  `product_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品类型 0-花材批发 1-城市仓小时达 2-新代卖',
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小时达商品firstId, 0大件批发 大于0小时达',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '小时达商品ware_id，0大件批发 大于0小时达',
  `is_sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否代卖商品 0：不是 1：是',
  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品编码',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `product_tag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品标签 限10字',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '等级12345->ABCDE',
  `sku_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '颜色',
  `pic_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `price` decimal(10, 1) UNSIGNED NOT NULL DEFAULT 0.0 COMMENT '供货价',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品描述',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品备注，限128字',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商ID',
  `after_sale_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后笔数（不看商品数量）',
  `sell_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销售笔数（不看商品数量）',
  `today_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '今日销量',
  `last_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '上一场次销量',
  `month_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30天销量',
  `sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销量',
  `max_stock` int UNSIGNED NOT NULL DEFAULT 9999 COMMENT '最大库存',
  `remain_stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '剩余库存',
  `offline_stock` int NOT NULL DEFAULT 0 COMMENT '线下库存（不上线展示）',
  `offline_switch` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:更改剩库存 1:更改线下库存',
  `limit_switch` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '限购开关 0-不限购 1-限购',
  `limit_sale` int UNSIGNED NOT NULL DEFAULT 9999 COMMENT '限购数量',
  `night_sale_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否参与晚场加单 0:不参与 1:参与',
  `product_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品状态 0:下架; 1:上架; 2:冻结; 3:过期（定时任务更新）',
  `freeze_reason` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '冻结原因，限50字',
  `low_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否降权 0-否 1-是',
  `low_level` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '降权等级',
  `is_hot` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否热销 0:否; 1:是;',
  `on_sale_time_str` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '上架时间，如：08:00:00',
  `not_sale_time_str` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '下架时间，如：12:00:00',
  `is_close_auto` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否关闭自动上下架 0:否; 1:是;',
  `is_rebate` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否返点 0:否; 1:是; 默认1',
  `is_special` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否特价 1:否; 2:是;',
  `special_sort` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '特价商品排序值',
  `is_seckill` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否秒杀 1:否; 2:是;',
  `seckill_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加价（元）',
  `seckill_deadline` datetime NULL DEFAULT NULL COMMENT '加价截止时间',
  `seckill_sort` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '秒杀商品排序值',
  `plan_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '秒杀计划id',
  `platform_discount_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台补贴（元）',
  `subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '单品补贴金额（元）补贴给用户',
  `is_presale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为预售商品 0：不是 1：是 默认0',
  `quasi_prefer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否准优选 0-否 1-是（价格以外因素）',
  `is_prefer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否优选 0:否 1:是',
  `prefer_time` datetime NULL DEFAULT NULL COMMENT '优选设置时间',
  `prefer_end_time` datetime NULL DEFAULT NULL COMMENT '优选结束时间',
  `presale_end_time` datetime NULL DEFAULT NULL COMMENT '预售截止时间',
  `expire_time` datetime NOT NULL COMMENT '过期时间（当前时间超过该值就过期）',
  `replenish_auto_onsale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补货自动上架 0-否 1-是',
  `return_processing` tinyint NOT NULL DEFAULT 0 COMMENT '退货处理 0-我要退货 1-转入代卖',
  `sell_prefer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否销量优选 0-否 1-是',
  `auto_sell_prefer` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否自动设置销量优选 0-否 1-是 默认1',
  `seven_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '7日销量（前7个场次）',
  `seven_no_lower_rank` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否7日无降级 0-否 1-是',
  `seven_no_refund` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否7日无退货 0-否 1-是',
  `seven_no_lack` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否7日无缺货 0-否 1-是',
  `seven_no_aftersale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否7天0售后 0-否 1-是',
  `thirty_no_aftersale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否30天0售后 0-否 1-是',
  `quality_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否品质花材 0-否 1-是',
  `freeze_level` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '冻结等级',
  `last_block_record` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '近期冻结记录数组',
  `show_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否展示（到场货）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `recommend_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推荐次数',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_rank_num`(`rank_num` ASC) USING BTREE,
  INDEX `idx_supplierid_firstid`(`supplier_id` ASC, `first_id` ASC) USING BTREE,
  INDEX `idx_quflag`(`quality_flag` ASC) USING BTREE,
  INDEX `idx_product_status`(`product_status` ASC) USING BTREE,
  INDEX `idx_prefer`(`is_prefer` ASC, `sell_prefer` ASC) USING BTREE,
  INDEX `idx_sid_ps_ds_pt_expt`(`second_id` ASC, `product_status` ASC, `data_status` ASC, `product_type` ASC, `expire_time` ASC) USING BTREE,
  INDEX `idx_supplierid_createtime_secondid`(`supplier_id` ASC, `create_time` ASC, `second_id` ASC) USING BTREE,
  INDEX `idx_createtime_status_supplierid`(`create_time` ASC, `product_status` ASC, `supplier_id` ASC) USING BTREE,
  INDEX `idx_supplier_status_data_expire_stock_show`(`supplier_id` ASC, `product_status` ASC, `data_status` ASC, `expire_time` ASC, `remain_stock` ASC, `sell_count` ASC, `show_flag` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 400042 AVG_ROW_LENGTH = 514 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货商品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_product_comment_score_daily
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_comment_score_daily`;
CREATE TABLE `xm_bulky_product_comment_score_daily`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `score_date` date NOT NULL COMMENT '统计日期',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `praise_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '好评数',
  `comment_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '评价数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pid_date`(`product_id` ASC, `score_date` ASC) USING BTREE,
  INDEX `idx_date`(`score_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 216 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品每日评价统计' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_product_comment_stats
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_comment_stats`;
CREATE TABLE `xm_bulky_product_comment_stats`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `product_id` bigint UNSIGNED NOT NULL COMMENT '商品id',
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '最终展示渠道appId',
  `good_comment_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近90天好评数（不含stat_date当天）',
  `comment_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近90天评价数（不含stat_date当天）',
  `stat_date` date NOT NULL COMMENT '统计日期',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_app_product`(`app_id` ASC, `product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 196 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品分渠道近90天评价统计' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_product_daily_sell
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_daily_sell`;
CREATE TABLE `xm_bulky_product_daily_sell`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `product_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `supplier_tag` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '基地名称',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次日期',
  `sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销量',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_round_no`(`round_no` ASC) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_supplier_tag`(`supplier_tag` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2136 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品销量统计' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_product_info
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_info`;
CREATE TABLE `xm_bulky_product_info`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `praise_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近期好评人数',
  `praise_ratio` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '近期好评率',
  `positive_rating_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否展示好评率：0-否，1-是',
  `recent_sale_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近期销量',
  `favorite_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '收藏数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pid`(`product_id` ASC) USING BTREE,
  INDEX `idx_utime`(`update_time` ASC) USING BTREE,
  INDEX `idx_positive_rating_product`(`positive_rating_flag` ASC, `product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3831 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品详情标签指标信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_product_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_log`;
CREATE TABLE `xm_bulky_product_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint NOT NULL DEFAULT 0 COMMENT '操作类型 0.默认其他 1.上下架 2.修改库存 3:修改价格 4:冻结 5:解冻 6:视频上传 7:解除降权',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '价格变动值',
  `stock_num` int NOT NULL DEFAULT 0 COMMENT '库存变动值',
  `source` tinyint UNSIGNED NULL DEFAULT NULL,
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作内容',
  `user_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作用户类型 0:系统 1:平台 2:供应商',
  `freeze_day` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '冻结天数',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_createtime_supplierid_productid`(`create_time` ASC, `supplier_id` ASC, `product_id` ASC) USING BTREE,
  INDEX `idx_type_supplier_time`(`type` ASC, `supplier_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_productid_supplierid`(`product_id` ASC, `supplier_id` ASC) USING BTREE,
  INDEX `idx_supplierid`(`supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11802 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货商品日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_product_quality_parameter
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_quality_parameter`;
CREATE TABLE `xm_bulky_product_quality_parameter`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '质检场次yyyy-MM-dd',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品等级1-5对应A-E',
  `source_punish_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '聚合的原始质检处罚记录数',
  `problem_num` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日质检问题扎数',
  `supply_num` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '当日实际供货扎数',
  `problem_ratio` decimal(10, 4) NOT NULL DEFAULT 0.0000 COMMENT '质检问题扎数占比',
  `recent_effective_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '含当前场次的近30天有效质检处罚次数',
  `upgrade_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否提档:0否 1是',
  `rule_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '规则计算状态:0待计算 1已计算 2数据异常',
  `rule_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '质检规则版本',
  `calculated_at` datetime NULL DEFAULT NULL COMMENT '规则计算完成时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_round_product`(`round_no` ASC, `product_id` ASC) USING BTREE,
  INDEX `idx_supplier_round`(`supplier_id` ASC, `round_no` ASC) USING BTREE,
  INDEX `idx_product_round`(`product_id` ASC, `round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 128 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品质检统计参数及提档标记表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_product_quality_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_quality_record`;
CREATE TABLE `xm_bulky_product_quality_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `dn_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否斗南供应商',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `round_no` date NOT NULL COMMENT '场次',
  `thirty_sale_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否近30天已售',
  `thirty_sale_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30天已售天数',
  `seven_sale_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否近7天已售',
  `seven_sale_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近7天已售天数',
  `thirty_prefer_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否近30天优选',
  `thirty_prefer_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30天优选天数',
  `thirty_quasi_prefer_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30天准优选天数',
  `thirty_quality_quasi_prefer_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30天品质优选或准优选天数',
  `thirty_quality_prefer_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30天品质优选或优选天数',
  `seven_prefer_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否近7天优选',
  `seven_prefer_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近7天优选天数',
  `seven_quasi_prefer_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近7天准优选天数',
  `seven_quality_quasi_prefer_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近7天品质优选或准优选天数',
  `seven_quality_prefer_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近7天品质优选或优选天数',
  `three_prefer_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否近3天优选',
  `three_prefer_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近3天优选天数',
  `three_quasi_prefer_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近3天准优选天数',
  `three_quality_quasi_prefer_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近3天品质优选或准优选天数',
  `three_quality_prefer_day` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近3天品质优选或优选天数',
  `thirty_praise_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否好评',
  `thirty_praise_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30天主动好评数',
  `thirty_praise_ratio` decimal(6, 3) UNSIGNED NOT NULL DEFAULT 0.000 COMMENT '近30天好评率',
  `thirty_repurchase_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否回购',
  `thirty_repurchase_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近3个月回购人数',
  `quality_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否品质优选',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `uk_roundno_pid`(`round_no` ASC, `product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14204 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '品质花材打标记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_product_repurchase_stats
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_repurchase_stats`;
CREATE TABLE `xm_bulky_product_repurchase_stats`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `product_id` bigint NOT NULL COMMENT '商品ID',
  `second_id` bigint NULL DEFAULT NULL COMMENT '二级分类ID',
  `repurchase_count` int NOT NULL COMMENT '回购人数（近90天购买≥2次）',
  `stat_date` date NOT NULL COMMENT '统计日期（例如：2026-03-10）',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_product_date`(`product_id` ASC, `stat_date` ASC) USING BTREE COMMENT '唯一约束：商品+日期',
  INDEX `idx_stat_second_repurchase_product`(`stat_date` ASC, `second_id` ASC, `repurchase_count` ASC, `product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4831 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品近90天回购人数统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_product_restrict_detail
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_restrict_detail`;
CREATE TABLE `xm_bulky_product_restrict_detail`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `rule_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '限购规则id xm_bulky_product_restrict_detail.id',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_productid_ruleid`(`product_id` ASC, `rule_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 206 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品限购明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_product_restrict_rule
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_restrict_rule`;
CREATE TABLE `xm_bulky_product_restrict_rule`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '限购规则名称，限20字',
  `restrict_num` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '限购扎数',
  `product_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '参加限购商品数量（展示用）',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '开启状态 0-关闭 1-开启',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品限购规则表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_product_sale_parameter
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_sale_parameter`;
CREATE TABLE `xm_bulky_product_sale_parameter`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次yyyy-MM-dd',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `seven_after_sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '七天质量问题售后金额',
  `seven_refund_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '七天质检处罚金额',
  `seven_exchange_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '七天换货金额',
  `seven_sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '七天已售金额',
  `seven_ratio` decimal(10, 4) NOT NULL DEFAULT 0.0000 COMMENT '七天供应商承担金额比例',
  `fourteen_after_sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '十四天质量问题售后金额',
  `fourteen_refund_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '十四天质检处罚金额',
  `fourteen_exchange_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '十四天换货金额',
  `fourteen_sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '十四天已售金额',
  `fourteen_ratio` decimal(10, 4) NOT NULL DEFAULT 0.0000 COMMENT '十四天供应商承担金额比例',
  `thirty_after_sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '三十天质量问题售后金额',
  `thirty_refund_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '三十天质检处罚金额',
  `thirty_exchange_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '三十天换货金额',
  `thirty_sale_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '三十天已售金额',
  `thirty_ratio` decimal(10, 4) NOT NULL DEFAULT 0.0000 COMMENT '三十天供应商承担金额比例',
  `seven_num` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '前3-9天扎数',
  `fourteen_num` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '前14天扎数',
  `thirty_num` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '前3-30天扎数',
  `seven_no_aftersale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否7天0售后',
  `fourteen_no_aftersale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否14天0售后',
  `thirty_no_aftersale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否30天0售后',
  `sell_prefer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否优选',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `base_rate` decimal(10, 4) NOT NULL DEFAULT 0.0000 COMMENT '加权质量售后率(0.6*近7动销场次+0.4*近14动销场次)',
  `smooth_rate` decimal(10, 4) NOT NULL DEFAULT 0.0000 COMMENT '平滑质量售后率(贝叶斯平滑后，分类内排名用)',
  `second_rate` decimal(10, 4) NOT NULL DEFAULT 0.0000 COMMENT '所属二级分类近7场次整体质量售后率',
  `recent_num` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近7个自然场次销量扎数(销量门槛/分层/直通用)',
  `recent_active_round` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '近7个自然场次的动销场次数(销量门槛用)',
  `sale_tier` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '销量分层 0-未进候选 1-高销量层 2-低销量层',
  `prefer_way` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '准优选入选方式 0-未入选 1-仅排名入选 2-仅低售后入选 3-两者都命中',
  `seven_capped_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '近7个动销场次封顶后质量售后额(质量售后率分子)',
  `seven_complain_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '近7个动销场次申诉成功扣减金额',
  `fourteen_capped_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '近14个动销场次封顶后质量售后额(质量售后率分子)',
  `fourteen_complain_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '近14个动销场次申诉成功扣减金额',
  `thirty_capped_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '近30个自然场次封顶后质量售后额(质量售后率分子)',
  `thirty_complain_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '近30个自然场次申诉成功扣减金额',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_roundno_pid`(`round_no` ASC, `product_id` ASC) USING BTREE,
  INDEX `idx_pid`(`product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1478 AVG_ROW_LENGTH = 174 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品售卖参数分析表' ROW_FORMAT = Dynamic;

