-- ----------------------------
-- Table structure for xm_bulky_product_sell_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_sell_record`;
CREATE TABLE `xm_bulky_product_sell_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `product_id` bigint UNSIGNED NOT NULL COMMENT '商品id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `start_date` date NOT NULL COMMENT '开始日期，年月日，如2022-08-09',
  `end_date` date NOT NULL COMMENT '结束日期，年月日，如2022-08-09',
  `after_sale_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '开始结束期间的售后笔数（闭区间）',
  `sell_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '开始结束期间的销售笔数（闭区间）',
  `sell_volume` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销售扎数',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_product_id`(`product_id` ASC) USING BTREE,
  INDEX `idx_date`(`start_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29546 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货供应商商品销量记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_product_subsidy
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_subsidy`;
CREATE TABLE `xm_bulky_product_subsidy`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `app_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '生效应用AppID',
  `config_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补贴配置id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id(冗余,便于清理)',
  `rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级(冗余)',
  `subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '该App下单品补贴金额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_config_product_app`(`product_id` ASC, `app_id` ASC, `config_id` ASC) USING BTREE,
  INDEX `idx_config_second_rank`(`config_id` ASC, `second_id` ASC, `rank_num` ASC) USING BTREE,
  INDEX `idx_second_rank`(`second_id` ASC, `rank_num` ASC) USING BTREE,
  INDEX `idx_app_id`(`app_id` ASC) USING BTREE,
  INDEX `idx_config_id`(`config_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 501 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品按App落地的单品补贴金额' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_product_task
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_task`;
CREATE TABLE `xm_bulky_product_task`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `task_time_str` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '任务执行时间，如：08:00:00',
  `task_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '任务类型：1：上架  2：下架',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_product_id`(`product_id` ASC) USING BTREE,
  INDEX `idx_task_time_str`(`task_time_str` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 61 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货商品定时任务表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_product_template
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_template`;
CREATE TABLE `xm_bulky_product_template`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id 0为未指定二级分类',
  `third_good_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '三方平台商品id 0为我们平台供应商的商品',
  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品编码',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '等级12345->ABCDE',
  `color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '颜色',
  `pic_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供货价',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品描述',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品备注，限128字',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '模板表主键id',
  `after_sale_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后笔数（不看商品数量）',
  `sell_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销售笔数（不看商品数量）',
  `today_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '今日销量',
  `last_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '上一场次销量',
  `month_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30天销量',
  `sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销量',
  `max_stock` int UNSIGNED NOT NULL DEFAULT 9999 COMMENT '最大库存',
  `remain_stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '剩余库存',
  `limit_sale` int UNSIGNED NOT NULL DEFAULT 9999 COMMENT '限购数量',
  `product_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品状态 0:下架; 1:上架; 2:冻结; 3:过期（定时任务更新）',
  `freeze_reason` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '冻结原因，限50字',
  `is_hot` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否热销 0:否; 1:是;',
  `on_sale_time_str` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '上架时间，如：08:00:00',
  `not_sale_time_str` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '下架时间，如：12:00:00',
  `is_close_auto` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否关闭自动上下架 0:否; 1:是;',
  `is_rebate` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否返点 0:否; 1:是; 默认1',
  `is_special` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否特价 1:否; 2:是;',
  `special_sort` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '特价商品排序值',
  `is_seckill` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否秒杀 1:否; 2:是;',
  `seckill_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加价（元）',
  `seckill_deadline` datetime NULL DEFAULT NULL COMMENT '加价截止时间',
  `seckill_sort` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '秒杀商品排序值',
  `is_presale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为预售商品 0：不是 1：是 默认0',
  `is_prefer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否优选 0:否 1:是',
  `prefer_time` datetime NULL DEFAULT NULL COMMENT '优选设置时间',
  `prefer_end_time` datetime NULL DEFAULT NULL COMMENT '优选结束时间',
  `presale_end_time` datetime NULL DEFAULT NULL COMMENT '预售截止时间',
  `expire_time` datetime NOT NULL COMMENT '过期时间（当前时间超过该值就过期）',
  `replenish_auto_onsale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补货自动上架 0-否 1-是',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_second_id`(`second_id` ASC) USING BTREE,
  INDEX `idx_rank_num`(`rank_num` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 199 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货模板商品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_product_video
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_product_video`;
CREATE TABLE `xm_bulky_product_video`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `first_id` bigint NOT NULL DEFAULT 0 COMMENT '一级分类ID',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id 0为未指定二级分类',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商ID',
  `video_cover` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品视频封面',
  `video_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品视频',
  `water_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '带水印视频',
  `trans_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '转码是否成功 0-否 1-是',
  `trans_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '转码ID',
  `reject_reason` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝原因',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 2 COMMENT '视频状态 1.推广中 2.审核中 3.过期（虚拟） 4.违规 5.未拍摄（虚拟）',
  `expires_time` datetime NOT NULL COMMENT '过期时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_utime`(`update_time` ASC) USING BTREE,
  INDEX `idx_second_status_exp_product`(`second_id` ASC, `status` ASC, `expires_time` ASC, `product_id` ASC) USING BTREE,
  INDEX `idx_supplier_status_exp_product`(`supplier_id` ASC, `status` ASC, `expires_time` ASC, `product_id` ASC) USING BTREE,
  INDEX `idx_product_id`(`product_id` ASC) USING BTREE,
  INDEX `idx_status_expirestime`(`status` ASC, `expires_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 101774 AVG_ROW_LENGTH = 247 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货商品视频表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_purchaser
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_purchaser`;
CREATE TABLE `xm_bulky_purchaser`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `zq_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '珍情用户id',
  `platform` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认0，0表示未区分，1、花材批发、2花仓酷，3、双用户(历史数据)',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认0  大于0 城市仓',
  `xm_account` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '寻梦账号(手机号)',
  `xm_com_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '寻梦公司账号',
  `company_direct_sale_store` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '寻梦平台账号店铺类型：1：直营店铺 2：头部商家 0：无',
  `company_level` tinyint UNSIGNED NOT NULL DEFAULT 6 COMMENT '寻梦平台账号店铺合作等级：1、2、3、4、5、6 默认最低等级',
  `xm_coin` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '寻梦币',
  `xm_coin_income` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '寻梦币收入',
  `xm_coin_expend` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '寻梦币支出',
  `xm_coin_give` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '补贴寻梦币余额',
  `xm_coin_rebate` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '返点寻梦币余额',
  `xm_coin_paid` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付寻梦币余额',
  `phone_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '手机号',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '密码',
  `salt` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '盐值',
  `app_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appId',
  `open_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信openId',
  `zc_open_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '资材openId',
  `session_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信登录会话KEY',
  `gender` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '性别：0：未知 1男，2女',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `country` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `area_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分区 1-一区 2-二区 3-三区 4-四区 5-五区 6-繁花北区 7-繁花南区 8-繁花西区',
  `auto_area_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否自动分区 0-否 1-是 默认1',
  `nickname` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户昵称或网络名称',
  `remark` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台备注，限20字符',
  `avatar_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户头像图片',
  `pic_avatar_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花现用户头像图片',
  `pic_user_background_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花现用户背景图片',
  `pic_user_introduction` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '花现用户简介',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `ma_help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '资材推广员id',
  `pid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销推广员id（分销用户的id）',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最近一次登录时间',
  `last_login_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最近一次登录IP地址',
  `class_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '分类类型 1:外部类型; 2:内部类型;',
  `contact_supplier_count` int UNSIGNED NOT NULL DEFAULT 3 COMMENT '可联系供应商次数，默认3次',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '预设货架号',
  `config_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认物流id',
  `first_buy_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '首次购买时间',
  `last_buy_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近购买时间',
  `last_second_buy_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '上上次购买时间',
  `buy_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '购买次数（按场次来，场次结束后更新）',
  `ma_first_buy_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '资材首次购买时间',
  `ma_last_buy_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '资材最近购买时间',
  `ma_month_buy_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '资材近30天购买次数',
  `bb_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否绑定B2b 0-否 1-是',
  `month_consumption` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '近一个月消费金额',
  `total_consumption` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '总消费金额',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品数据',
  `last_recall_time` datetime NULL DEFAULT NULL COMMENT '上次召回时间',
  `month_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '月商品数据',
  `block_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否黑名单 0-否 1-下单拉黑 2-登录拉黑',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '用户状态 0：正常 -1：禁用  -100：删除',
  `holiday_white_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否节日白名单 0-否 1-是',
  `internal_employee_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否为内部员工：0-否 1-是',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `phone_change_time` datetime NULL DEFAULT NULL COMMENT '最近一次手机号换绑时间',
  `phone_change_version` int NOT NULL DEFAULT 0 COMMENT '手机号换绑版本',
  `express_recommend_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流推荐白名单：0-否，1-是',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_phone_number_app_id`(`phone_number` ASC, `app_id` ASC) USING BTREE,
  INDEX `idx_xm_account`(`xm_account` ASC) USING BTREE COMMENT '寻梦账号手机号',
  INDEX `idx_helpid`(`help_id` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE,
  INDEX `idx_appid_ctime`(`app_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_ftime`(`first_buy_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1091885 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货采购方用户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_purchaser_account_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_purchaser_account_log`;
CREATE TABLE `xm_bulky_purchaser_account_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL COMMENT '采购方用户id',
  `year` int UNSIGNED NOT NULL COMMENT '年份',
  `month` int UNSIGNED NOT NULL COMMENT '月份',
  `day` int UNSIGNED NOT NULL COMMENT '日',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单编号',
  `ware_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id  0不是城市仓',
  `business_type` tinyint UNSIGNED NOT NULL COMMENT '业务类型：0：订单支付 1：订单退款',
  `pay_type` tinyint UNSIGNED NOT NULL COMMENT '支付方式 0：微信支付 1：寻梦平台账户支付',
  `xm_refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '关联xm_bulky_refund表id',
  `xm_coin` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '发生寻梦币',
  `paid_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付寻梦币',
  `remark` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `money` decimal(10, 2) NOT NULL COMMENT '发生金额(不包含币)',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1514122 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购方用户账单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_purchaser_address
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_purchaser_address`;
CREATE TABLE `xm_bulky_purchaser_address`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0：默认，1：城市仓',
  `name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人姓名',
  `phone_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人手机号',
  `longitude` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
