-- ----------------------------
-- Table structure for xm_bulky_purchaser_authorize
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_purchaser_authorize`;
CREATE TABLE `xm_bulky_purchaser_authorize`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL COMMENT '用户id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称',
  `token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '校验token',
