  INDEX `idx_purchaser_id_token`(`purchaser_id` ASC, `token` ASC) USING BTREE COMMENT '用户id和token'
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购方代购授权信息表' ROW_FORMAT = DYNAMIC;

