-- ----------------------------
-- Table structure for xm_bulky_purchaser_invoice_application
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_purchaser_invoice_application`;
CREATE TABLE `xm_bulky_purchaser_invoice_application`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `application_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发票订单号',
  `purchaser_id` bigint NOT NULL COMMENT '花店ID',
  `invoice_title_id` bigint NOT NULL COMMENT '发票抬头ID',
  `title_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抬头名称(冗余)',
  `tax_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '税号(冗余)',
  `bank_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开户银行(冗余)',
  `bank_account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '银行账号(冗余)',
  `company_address` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业地址(冗余)',
  `company_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业电话(冗余)',
  `total_amount` decimal(12, 2) NOT NULL COMMENT '申请开票总金额',
  `supplier_count` int NOT NULL DEFAULT 0 COMMENT '涉及供应商数',
  `order_count` int NOT NULL DEFAULT 0 COMMENT '包含订单数',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0开票中 1已完成 2已撤销',
  `deadline` datetime NOT NULL COMMENT '截止日期(申请日+30天)',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_application_no`(`application_no` ASC) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 62 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '花店开票申请单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_purchaser_invoice_application_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_purchaser_invoice_application_order`;
CREATE TABLE `xm_bulky_purchaser_invoice_application_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `application_id` bigint NOT NULL COMMENT '申请单ID',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户订单号',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `supplier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `invoiceable_amount` decimal(12, 2) NOT NULL COMMENT '该订单该供应商可开票金额',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_application_id`(`application_id` ASC) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 133 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '花店开票申请单-订单明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_purchaser_invoice_quota
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_purchaser_invoice_quota`;
CREATE TABLE `xm_bulky_purchaser_invoice_quota`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `purchaser_id` bigint NOT NULL COMMENT '花店ID',
  `total_quota` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '总可开票额度（订单货款，剔除运费和服务费）',
  `invoicing_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '开票中金额（已申请未完成）',
  `invoiced_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '已开票金额',
  `available_quota` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '可用额度（total - invoicing - invoiced）',
  `freight_total` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '运费总额（平台开票用）',
  `freight_invoiced` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '运费已开票金额',
  `service_fee_total` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '服务费总额（平台开票用）',
  `service_fee_invoiced` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '服务费已开票金额',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（乐观锁）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_purchaser_id`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4384 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '花店开票额度表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_purchaser_tag
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_purchaser_tag`;
CREATE TABLE `xm_bulky_purchaser_tag`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `tag_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '标签id xm_bulky_user_tag.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `id_pid_tagid`(`purchaser_id` ASC, `tag_id` ASC) USING BTREE,
  INDEX `idx_tagid`(`tag_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 313 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '标签表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_quality_punish_sms_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_quality_punish_sms_record`;
CREATE TABLE `xm_bulky_quality_punish_sms_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次，格式yyyy-MM-dd',
  `purchaser_id` bigint NOT NULL COMMENT '采购客户ID',
  `masked_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '脱敏手机号',
  `variety_count` int NOT NULL DEFAULT 0 COMMENT '去重品种数，对应模板参数count',
  `total_punish_num` int NOT NULL DEFAULT 0 COMMENT '缺退货总扎数，对应模板参数num',
  `sms_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '阿里云短信模板编码，格式SMS_xxx',
  `submit_status` tinyint NOT NULL DEFAULT 0 COMMENT '平台提交状态：0发送中，1提交成功，2提交失败',
  `failure_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交失败原因',
  `platform_sms_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '短信平台返回的短信ID',
  `submit_time` datetime NULL DEFAULT NULL COMMENT '调用短信平台时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_round_purchaser`(`round_no` ASC, `purchaser_id` ASC) USING BTREE,
  INDEX `idx_submit_status_create_time`(`submit_status` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 69 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质检处罚缺退货短信提交记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_quick_reply
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_quick_reply`;
CREATE TABLE `xm_bulky_quick_reply`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型 1-售后 2-供应商审核 3-供应商申诉 4-拒绝售后',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快捷回复内容 限255字',
  `sequence` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序 升序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '快捷回复表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_receipt_application
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_receipt_application`;
CREATE TABLE `xm_bulky_receipt_application`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `receipt_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '电子收款凭证号',
  `purchaser_id` bigint NOT NULL COMMENT '采购方ID',
  `purchaser_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采购方手机号',
  `invoice_title_id` bigint NOT NULL COMMENT '发票抬头ID',
  `buyer_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '购买人名称',
  `buyer_certificate_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '购买人证照号',
  `total_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '收据总金额',
  `order_count` int NOT NULL DEFAULT 0 COMMENT '订单数',
  `item_count` int NOT NULL DEFAULT 0 COMMENT '商品明细数',
  `receipt_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '电子收据PDF地址',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：0申请中 1已开具',
  `apply_time` datetime NOT NULL COMMENT '申请时间',
  `issue_time` datetime NULL DEFAULT NULL COMMENT '开具时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `partner_id` int NOT NULL DEFAULT 0 COMMENT '所属平台(分销商id) 0:寻梦批发 3:优花速达 140:繁花惠',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_receipt_no`(`receipt_no` ASC) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE,
  INDEX `idx_purchaser_phone`(`purchaser_phone` ASC) USING BTREE,
  INDEX `idx_apply_time`(`apply_time` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '消费者电子收款凭证申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_receipt_application_item
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_receipt_application_item`;
CREATE TABLE `xm_bulky_receipt_application_item`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `receipt_id` bigint NOT NULL COMMENT '收据申请ID',
  `receipt_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '电子收款凭证号',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单编号',
  `round_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易场次',
  `supplier_id` bigint NULL DEFAULT NULL COMMENT '供应商ID',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `product_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `item_num` int NOT NULL DEFAULT 0 COMMENT '商品数量',
  `receipt_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '商品收据金额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `item_type` tinyint NOT NULL DEFAULT 0 COMMENT '票据项目类型 0:花材款 2:干线物流费',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_receipt_id`(`receipt_id` ASC) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 60 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '消费者电子收款凭证商品快照表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_receipt_application_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_receipt_application_order`;
CREATE TABLE `xm_bulky_receipt_application_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `receipt_id` bigint NOT NULL COMMENT '收据申请ID',
  `receipt_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '电子收款凭证号',
  `purchaser_id` bigint NOT NULL COMMENT '采购方ID',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单编号',
  `round_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易场次',
  `receipt_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '订单收据金额',
  `supplier_count` int NOT NULL DEFAULT 0 COMMENT '供应商数量',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '订单完成时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_receipt_id`(`receipt_id` ASC) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '消费者电子收款凭证订单快照表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_receipt_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_receipt_operation_log`;
CREATE TABLE `xm_bulky_receipt_operation_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `receipt_id` bigint NOT NULL COMMENT '收据申请ID',
  `receipt_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '电子收款凭证号',
  `action_type` tinyint NOT NULL COMMENT '操作类型：1系统开具 2预览 3下载',
  `operator_type` tinyint NOT NULL COMMENT '操作人类型：1采购方 2后台 3系统',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `operator_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人手机号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_receipt_id`(`receipt_id` ASC) USING BTREE,
  INDEX `idx_receipt_no`(`receipt_no` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 94 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '消费者电子收款凭证操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_refund
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_refund`;
CREATE TABLE `xm_bulky_refund`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `pid` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'pid',
  `user_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户类型 1:采购方 2:供应商 3:平台客服 4:系统',
  `refund_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款类型 1:用户申请一键退款 2:用户申请部分退款 3:用户申请售后 4:客服申请一键退款 5:客服申请部分退款 6:客服申请售后 7:客服申请退运费 8:质检处罚退款 9:售后申诉',
  `month_refund_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30天售后申请次数',
  `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称 限128字',
  `punish_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '处罚id',
  `punish_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '处罚类型 同punish表',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `platform` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '来源：0：大件批发 1：抖音 2：花仓库',
  `pay_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付方式 0：微信支付 1：寻梦平台账户支付',
  `partner_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商处理状态 0-待处理 1-同意 2-拒绝',
  `partner_apply_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '分销商建议申请金额',
  `partner_reason` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分销商售后原因',
  `apply_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '申请状态 0:申请中 1:已通过 2:已拒绝',
  `apply_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请总金额（可以为0）=申请商品金额+申请服务费+申请运费',
  `apply_product_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请商品金额',
  `apply_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请服务费',
  `apply_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请运费',
  `apply_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '买家退款说明',
  `reason_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款原因 0-产品质量 1-服务态度（废弃） 2-物流理赔 3-其他（废弃） 4-缺货赔付（缺货漏货） 5-退货赔付 6-理赔（废弃）7-降级赔付 8-断头损伤 9-错发货物',
  `pictures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '退款凭证图片链接数组',
  `videos` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '退款凭证视频链接数组',
  `supplementary_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '补充描述',
  `supplementary_picture` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '补充图片',
  `supplementary_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '补充材料时间',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_picture` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商凭证图片视频',
  `supplier_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商凭证说明',
  `wx_pay_time` datetime NULL DEFAULT NULL COMMENT '微信付款时间',
  `supplementary_video` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '补充视频',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款状态 0:已创建 1:退款中 2:退款成功 3:退款失败',
  `handle_time` datetime NULL DEFAULT NULL COMMENT '售后处理时间',
  `handle_record` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '售后处理记录',
  `punish_pic_url` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '处罚素材URL数组JSON字符串',
  `wx_refund_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信退款单号',
  `wx_refund_success_time` datetime NULL DEFAULT NULL COMMENT '退款成功时间',
  `refund_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款金额=退款商品金额+退款服务费+退款运费-退款优惠金额',
  `refund_product_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款商品金额',
  `refund_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款服务费',
  `refund_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款运费',
  `refund_coupon_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款优惠券金额',
  `refund_coupon_discount_goods` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '本次退款商品行优惠券优惠总额（元）',
  `refund_platform_reduce_goods` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '本次退款商品行平台满减总额（元）',
  `refund_extra_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款额外服务费',
  `refund_vip_discount_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款会员优惠服务费金额',
  `paid_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付寻梦币',
  `bear_platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供应商承担补贴金额（客服售后填写）',
  `supplier_should_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商应承担金额 记录用',
  `supplier_bear_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供应商承担金额',
  `dao_chang_huo_supplier_id` bigint NULL DEFAULT NULL COMMENT '到场货供应商ID，实际承担金额大于0时固定为10003',
  `dao_chang_huo_should_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '到场货供应商应承担金额',
  `dao_chang_huo_split_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '到场货供应商实际承担金额',
  `supplier_bear_ratio` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 1.00 COMMENT '供应商承担影响系数，默认1',
  `supplier_accord_bear_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供应商自愿承担金额',
  `is_prefer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否优选 0-否 1-是',
  `offline_refund_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有线下退款 0-否 1-是',
  `city_warehouse_bear_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓承担金额',
  `partner_bear_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '分销商承担金额',
  `refund_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台加价承担金额',
  `pack_bear_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '打包承担金额（可能为负）',
  `express_bear_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '物流承担金额（可能为负）',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '客服备注，限512字',
  `flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '旗帜 0:灰',
  `flag_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '旗帜备注，限255字',
  `platform_picture` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台图片',
  `assign_customer_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分配客服id',
  `assign_customer_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分配客服姓名',
  `assign_time` datetime NULL DEFAULT NULL COMMENT '售后分配-首次分配时间',
  `last_assign_time` datetime NULL DEFAULT NULL COMMENT '售后分配-最新分配时间',
  `refund_result` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款返回结果',
  `duty_reason` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '责任描述，限64字',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_date` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建日期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `apply_ot_exp_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请一次性物流加价退款',
  `refund_ot_exp_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '一次性物流加价退款',
  `refund_partner_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款分销服务费加价',
  `refund_partner_add_service_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '分销加价',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_createtime_purchaserid`(`create_time` ASC, `purchaser_id` ASC) USING BTREE,
  INDEX `idx_wareid_datastatus`(`ware_id` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_ordersn_status`(`order_sn` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_cdate_pid`(`create_date` ASC, `purchaser_id` ASC) USING BTREE,
  INDEX `idx_pid_status_ctime`(`partner_id` ASC, `data_status` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_wxpaytime`(`wx_pay_time` ASC) USING BTREE,
  INDEX `idx_handle_astatus_rtype_reason_bear`(`handle_time` ASC, `apply_status` ASC, `refund_type` ASC, `reason_type` ASC, `supplier_bear_price` ASC) USING BTREE,
  INDEX `idx_status_handle_supplier`(`refund_status` ASC, `data_status` ASC, `handle_time` ASC, `supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4112612 AVG_ROW_LENGTH = 569 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货退款申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_refund_duty
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_refund_duty`;
CREATE TABLE `xm_bulky_refund_duty`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_refund.id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号',
  `pay_time` datetime NOT NULL COMMENT '支付时间',
  `duty_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '责任类型 0-无 1-质检 2-复检 3-配货 4-打包 5-发货 6-退/缺货降级 7-仓库物流 8-物流理赔 9-冰瓶',
  `user_id_str` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '用户id集合 ,12345,12346,',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_refundid`(`refund_id` ASC) USING BTREE,
  INDEX `idx_createtime`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 419 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货退款责任表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_refund_item
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_refund_item`;
CREATE TABLE `xm_bulky_refund_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_refund.`id`',
  `refund_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款类型 1:用户申请一键退款 2:用户申请部分退款 3:用户申请售后 4:客服申请一键退款 5:客服申请部分退款 6:客服申请售后 7:客服申请退运费',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `order_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_order_item.`id`',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `apply_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请总金额（可以为0）=申请商品金额+申请服务费+申请运费',
  `apply_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '申请退款扎数',
  `apply_item_sub_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '申请售后枝数',
  `apply_product_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请商品金额',
  `apply_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请服务费',
  `apply_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请运费',
  `refund_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款金额=退款商品金额+退款服务费+退款运费',
  `refund_product_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款商品金额',
  `refund_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款服务费',
  `refund_partner_add_service_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退还给分销商加价服务费（元）',
  `refund_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款运费',
  `refund_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款扎数',
  `paid_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '赔付寻梦币',
  `supplier_bear_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供应商承担金额',
  `dao_chang_huo_supplier_id` bigint NULL DEFAULT NULL COMMENT '到场货供应商ID，实际承担金额大于0时固定为10003',
  `dao_chang_huo_should_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '到场货供应商应承担金额',
  `dao_chang_huo_split_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '到场货供应商实际承担金额',
  `city_warehouse_bear_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '城市仓承担金额',
  `refund_add_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台加价承担金额',
  `bear_platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '供应商承担补贴金额',
  `coupon_discount_per_bundle` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '每扎优惠券优惠（元）',
  `full_reduction_discount_per_bundle` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '每扎平台满减优惠（元）',
  `apply_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '申请状态 0:申请中 1:已通过 2:已拒绝',
  `is_prefer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否优选 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_refund_id_itemid`(`refund_id` ASC, `order_item_id` ASC) USING BTREE,
  INDEX `idx_order_item_id`(`order_item_id` ASC) USING BTREE,
  INDEX `idx_createtime`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 156378 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货退款商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_refund_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_refund_log`;
CREATE TABLE `xm_bulky_refund_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款申请id',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `user_type` tinyint NOT NULL COMMENT '操作者类型 1:采购方 2:平台客服 3:供应商',
  `platform_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否仅平台可见 0-否 1-是',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作者id',
  `user_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作者名称',
  `content` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '处理信息',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_rid`(`refund_id` ASC) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1641240 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货退款操作记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_refund_picture
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_refund_picture`;
CREATE TABLE `xm_bulky_refund_picture`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `record_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '记录类型 0:售后图片指纹缓存 1:售后图片历史 2:售后图片相似结果记录',
  `pic_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片URL',
  `origin_md5` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '原始上传图片MD5',
  `pic_md5` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '实际图片MD5',
  `normalized_md5` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标准化图片MD5',
  `phash` char(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片pHash',
  `dhash` char(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片dHash',
  `shoot_time` datetime NULL DEFAULT NULL COMMENT '图片拍摄时间',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方ID',
  `apply_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '售后申请时间',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后单ID',
  `refund_source` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后来源 0:普通订单 1:本地仓订单',
  `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `duplicate_pic_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '命中的历史图片ID',
  `match_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '匹配类型 MD5/NORMALIZED_MD5/PHASH_DHASH/CROP_PHASH_DHASH',
  `similarity` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '相似度',
  `phash_similarity` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'pHash相似度',
  `dhash_similarity` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'dHash相似度',
  `similarity_order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '相似度对应订单',
  `similarity_refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '相似度对应售后单',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常 -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pic_url`(`pic_url`(191) ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_refund`(`record_type` ASC, `refund_source` ASC, `refund_id` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_user_md5_time`(`record_type` ASC, `purchaser_id` ASC, `pic_md5` ASC, `apply_time` ASC) USING BTREE,
  INDEX `idx_similar_result`(`record_type` ASC, `purchaser_id` ASC, `apply_time` ASC) USING BTREE,
  INDEX `idx_user_product_time`(`record_type` ASC, `purchaser_id` ASC, `product_name` ASC, `data_status` ASC, `apply_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2646 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '售后图片指纹记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_refund_statistics
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_refund_statistics`;
CREATE TABLE `xm_bulky_refund_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `round_no` date NOT NULL COMMENT '年月日',
  `order_time_form` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '根据场次的售后数据',
  `refund_form` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '根据售后时间的售后数据',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `round_no`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货售后数据统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_region_airport
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_region_airport`;
CREATE TABLE `xm_bulky_region_airport`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `province_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '行政区域表的省code',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `city_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '行政区域表的市code',
  `airport_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '机场名称',
  `region_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'adcode',
  `is_enable` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否启用该机场 0:否; 1:是; 默认1',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 104 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '全国主要机场配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_region_extra
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_region_extra`;
CREATE TABLE `xm_bulky_region_extra`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL COMMENT '类型 1:保温棉;',
  `region_id` int UNSIGNED NOT NULL COMMENT 'xm_region.id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '城市名称',
  `parent_region_id` int UNSIGNED NOT NULL COMMENT 'xm_region.parent_id',
  `adcode` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '城市编码',
  `level` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '地区等级 province city district street',
  `is_select` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否选择 0:否; 1:是;',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_adcode`(`adcode` ASC) USING BTREE,
  INDEX `idx_type_parent_id`(`type` ASC, `parent_region_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 141162 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货区域其他配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_region_rule
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_region_rule`;
CREATE TABLE `xm_bulky_region_rule`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id，1为保温棉，不允许修改删除',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则名称，限20字符',
  `is_modify` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否可以修改 0:否; 1:是; 默认1',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货物流规则表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_region_statistics
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_region_statistics`;
CREATE TABLE `xm_bulky_region_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `yyyy_mm_dd` date NOT NULL COMMENT '年月日，如2024-04-15',
  `province` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `turnover` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '营业额',
  `send_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货单数',
  `order_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单数',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品销量',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_date_city_province`(`yyyy_mm_dd` ASC, `city` ASC, `province` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货区域统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_remit
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_remit`;
CREATE TABLE `xm_bulky_remit`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 1-赔付',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `open_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户openid',
  `mch_id` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信商户id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `amount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '金额',
  `apply_reason` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '申请原因 限128字',
  `reject_reason` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝理由 限128字',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-申请中 1-同意 2-拒绝',
  `agree_time` datetime NULL DEFAULT NULL COMMENT '同意时间',
  `out_biz_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付中心单号',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货赔付打款表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_replenish
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_replenish`;
CREATE TABLE `xm_bulky_replenish`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号',
  `apply_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请金额',
  `apply_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '申请状态 1:已创建 2:已撤销 3:财务拒绝 4:待审核 5:已完成',
  `file_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文件url，限512字',
  `responsible_party` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '责任方 1:平台 2:供应商',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `checker_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核人用户id',
  `checker_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人名称',
  `check_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核时间，默认空',
  `flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '旗帜 0:灰',
  `reject_reason` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝理由，限128字',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ordersn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '补货报销申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_replenish_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_replenish_log`;
CREATE TABLE `xm_bulky_replenish_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `replenish_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补货报销表主键id',
  `content` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '内容',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_replenishid`(`replenish_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 58 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '补货报销记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_restock_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_restock_log`;
CREATE TABLE `xm_bulky_restock_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `zone` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `zone_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区名称',
  `second_id` bigint UNSIGNED NOT NULL COMMENT '二级分类',
  `rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `num` int UNSIGNED NOT NULL COMMENT '数量',
  `user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '操作人id',
  `create_time` datetime NOT NULL COMMENT '时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_round`(`round_no` ASC, `zone` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_restock_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_restock_order`;
CREATE TABLE `xm_bulky_restock_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `shelf_sn` int NOT NULL DEFAULT 0 COMMENT '货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `type` tinyint NOT NULL DEFAULT 0 COMMENT '类别 1:缺货补货 2:退货补货',
  `enter_item_id` bigint NOT NULL DEFAULT 0 COMMENT '对应enterItemId',
  `product_id` bigint NOT NULL DEFAULT 0 COMMENT '原商品id',
  `item_num` int NOT NULL DEFAULT 0 COMMENT '原商品数量',
  `origin_rank_num` int NOT NULL DEFAULT 0 COMMENT '原等级',
  `origin_sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '原sku',
  `restock_product_id` bigint NOT NULL DEFAULT 0 COMMENT '补货商品id',
  `second_id` bigint NOT NULL DEFAULT 0 COMMENT 'secondId',
  `restock_num` int NOT NULL DEFAULT 0 COMMENT '缺货补货数量',
  `restock_rank_num` int NOT NULL DEFAULT 0 COMMENT '补货等级',
  `restock_sku_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '补货数量',
  `outbound_num` int NOT NULL DEFAULT 0 COMMENT '缺货补货出库数量',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `user_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人',
  `user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_roundNo`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '补单订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_sale_limit_rule
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_sale_limit_rule`;
CREATE TABLE `xm_bulky_sale_limit_rule`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `first_id` bigint NOT NULL COMMENT '一级分类ID',
  `second_id` bigint NULL DEFAULT NULL COMMENT '二级分类ID，NULL表示一级分类下全部二级',
  `supplier_types` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供应商类型，逗号分隔如1,2,3',
  `base_scope_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '基地范围类型 0-全部基地 1-指定基地',
  `base_ids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '指定基地ID列表，逗号分隔',
  `white_list_enable` tinyint(1) NOT NULL DEFAULT 0 COMMENT '白名单开关 0-不启用 1-启用',
  `operator` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0正常 -100删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_second_id`(`second_id` ASC) USING BTREE,
  INDEX `idx_first_id_status`(`first_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商限售规则' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_sale_limit_rule_white
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_sale_limit_rule_white`;
CREATE TABLE `xm_bulky_sale_limit_rule_white`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `rule_id` bigint NOT NULL COMMENT '规则ID',
  `supplier_id` bigint NOT NULL COMMENT '白名单供应商ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_rule_id`(`rule_id` ASC) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 416 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商限售规则白名单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_sale_statistics
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_sale_statistics`;
CREATE TABLE `xm_bulky_sale_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `yyyy_mm_dd` date NOT NULL COMMENT '年月日，如2022-01-20',
  `second_id` bigint UNSIGNED NOT NULL COMMENT '二级分类id',
  `average_price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '当日成交均价',
  `sale_volume` int UNSIGNED NOT NULL COMMENT '当日销量',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_yyyy_mm_dd`(`yyyy_mm_dd` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 171048 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货销量统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_search_history
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_search_history`;
CREATE TABLE `xm_bulky_search_history`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `app_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appId',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '搜索类型 鲜花0 供应商1 ',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '搜索内容',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_content`(`content`(20) ASC) USING BTREE,
  INDEX `idx_search_rank_stat`(`app_id` ASC, `type` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 302270 AVG_ROW_LENGTH = 82 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购端用户搜索记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_second_confirm
-- ----------------------------
