  INDEX `idx_punish`(`punish_id` ASC) USING BTREE,
  INDEX `idx_eid`(`enter_item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '退货二次质检' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_second_pic
-- ----------------------------
