  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_secondId`(`second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 41 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '二级分类图册表' ROW_FORMAT = Dynamic;

-- ----------------------------
