  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_purchaser_id`(`purchaser_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货采购方二级分类收藏表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_second_subsidy
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_second_subsidy`;
CREATE TABLE `xm_bulky_second_subsidy`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `config_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补贴配置id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `subsidy_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '补贴品种数量',
  `subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '补贴单价',
  `subsidy_price_str` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '补贴阶梯',
  `price_difference_str` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '补贴差价阶梯',
  `supplier_perm` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商类型权限',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_secondid_ranknum`(`second_id` ASC, `rank_num` ASC) USING BTREE,
  INDEX `idx_config_second_rank`(`config_id` ASC, `second_id` ASC, `rank_num` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 275 AVG_ROW_LENGTH = 94 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货二级分类补贴配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_second_subsidy_config
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_second_subsidy_config`;
CREATE TABLE `xm_bulky_second_subsidy_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配置名称',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `rule_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '绑定的补贴规则id',
  `subsidy_type` tinyint UNSIGNED NOT NULL DEFAULT 4 COMMENT '补贴类型 1-普通批发 2-繁花惠 3-优花速达 4-渠道补贴',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态 0-关闭 1-开启',
  `effect_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '生效方式 1-永久 2-指定区间',
  `start_time` datetime NULL DEFAULT NULL COMMENT '生效开始(effect_type=2)',
  `end_time` datetime NULL DEFAULT NULL COMMENT '生效结束(effect_type=2)',
  `is_default` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否默认配置 1-是',
  `apply_unbound` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '未关联App时是否兜底生效 1-是(仅默认配置)',
  `limit_default` decimal(12, 2) UNSIGNED NOT NULL DEFAULT 1000.00 COMMENT '该配置默认日补贴上限',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status`(`status` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_subsidy_type`(`subsidy_type` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '单品补贴配置主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_second_subsidy_config_app
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_second_subsidy_config_app`;
CREATE TABLE `xm_bulky_second_subsidy_config_app`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `config_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补贴配置id',
  `app_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '生效应用AppID',
  `app_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用名称冗余',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_config_id`(`config_id` ASC) USING BTREE,
  INDEX `idx_appid_alive`(`app_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 181 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '单品补贴配置生效渠道' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_second_subsidy_config_city
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_second_subsidy_config_city`;
CREATE TABLE `xm_bulky_second_subsidy_config_city`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `config_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补贴配置id',
  `subsidy_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '补贴类型 1-普通批发 2-繁花惠 3-优花速达',
  `city_adcode` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市adcode',
  `city_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市名称',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_type_city`(`subsidy_type` ASC, `city_adcode` ASC) USING BTREE,
  INDEX `idx_config_id`(`config_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5112 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '单品补贴配置生效城市' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_second_subsidy_new
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_second_subsidy_new`;
CREATE TABLE `xm_bulky_second_subsidy_new`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `rule_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补贴规则id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `subsidy_mode` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '补贴模式 1-金额档位 2-等级全补',
  `subsidy_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '补贴品种数量',
  `subsidy_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '补贴单价',
  `subsidy_price_str` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '补贴阶梯',
  `price_difference_str` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '补贴差价阶梯',
  `supplier_perm` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商类型权限',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_secondid_ranknum`(`second_id` ASC, `rank_num` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 382 AVG_ROW_LENGTH = 94 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '新大件货二级分类补贴配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_second_subsidy_rule
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_second_subsidy_rule`;
CREATE TABLE `xm_bulky_second_subsidy_rule`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '补贴规则名称',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规则说明',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_name_data_status`(`name` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '单品补贴规则主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_send_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_send_order`;
CREATE TABLE `xm_bulky_send_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '发货单表主键id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发货单号，当天同一货架号发货单号相同（唯一），限32字',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次编号：yyyy-MM-dd',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_purchaser采购方表主键id',
  `order_num` int UNSIGNED NULL DEFAULT 0,
  `ware_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货单流水号，每个城市仓从1开始',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '按物流和重量场次结束时生成的货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `zone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `shelf` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `delivery_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '物流配送方式 1:物流配送 2:自提 默认1',
  `distribution_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '配送方式 0-无 1-送货上门 2-城市仓自提',
  `actual_total_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际重量（g）',
  `expend_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实际支出运费（人工输入）',
  `pickup_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提货费，确认结算时计入最终运费',
  `express_price_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '运费结算状态 0-未填报 1-待结算 2-已结算',
  `freight_price_mode` tinyint NOT NULL DEFAULT 0 COMMENT '运费填报模式 0-未确定 1-包裹 2-运单 3-混合',
  `package_report_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '包裹填报价格合计',
  `waybill_report_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '第三方运单填报价格合计',
  `reconcile_sub_bill_id` bigint NOT NULL DEFAULT 0 COMMENT '运费子对账单id，0=未生成对账单',
  `compensate_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '补偿/赔付金额(抵减应付物流商,人工输入)',
  `expend_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '服务费支出（人工输入）',
  `estimate_express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '预估运费（系统维护）',
  `actual_package_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '实际包裹信息',
  `config_id` bigint UNSIGNED NOT NULL COMMENT '物流商id',
  `express_region` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流配送区域id',
  `real_express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际物流id 0时不改物流',
  `real_express_region` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '实际物流配送区域id',
  `month_buy` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30日购买次数',
  `receive_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人名称，限32字',
  `receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人手机号，限20字',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `district` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `receive_address` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货地址，限128字',
  `nation_code` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `adcode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址adcode',
  `longitude` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注 限128字',
  `city_remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市仓备注（自己人看） 限128字',
  `logistics_remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流专属备注，限128字',
  `send_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货单状态 0:待发货; 1:待收货; 2:已完成; 3:已取消',
  `logistics_status` tinyint NOT NULL DEFAULT 0 COMMENT '是否发送物流0.未发送1.发送',
  `express_change_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流变更状态 0:无; 1:申请中; 2:已同意; 3:已变更;',
  `print_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已打印 0:否; 1:是;',
  `is_sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0,
  `new_buyer` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否是新用户 0:否 1:是',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '推广员id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `order_create_time` datetime NULL DEFAULT NULL COMMENT '订单创建时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `waybill_print_status` tinyint NOT NULL DEFAULT 0 COMMENT '电子面单打印状态 0未打印 1已打印 -1打印失败',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_send_no`(`send_no` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
  INDEX `idx_roundno_wareid_shelfsn`(`round_no` ASC, `ware_id` ASC, `shelf_sn` ASC) USING BTREE,
  INDEX `idx_purchaserid_roundno`(`purchaser_id` ASC, `round_no` ASC) USING BTREE,
  INDEX `idx_receivetel_roundno`(`receive_tel` ASC, `round_no` ASC) USING BTREE,
  INDEX `idx_roundno_help_id_status`(`round_no` ASC, `help_id` ASC, `new_buyer` ASC, `send_status` ASC) USING BTREE,
  INDEX `idx_zone_shelf`(`zone_shelf` ASC) USING BTREE,
  INDEX `idx_reconcile_sub_bill`(`reconcile_sub_bill_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9400008159 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货发货单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_send_order_coin_refund
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_send_order_coin_refund`;
CREATE TABLE `xm_bulky_send_order_coin_refund`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发货单号',
  `xm_coin` decimal(10, 2) UNSIGNED NOT NULL COMMENT '退的寻梦币',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_send_no`(`send_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货发货单退寻梦币表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_sf_logistics_config
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_sf_logistics_config`;
CREATE TABLE `xm_bulky_sf_logistics_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `config_id` bigint NOT NULL COMMENT '物流配置id',
  `monthly_card` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '顺丰月结卡号',
  `password` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '顺丰月结卡密码',
  `force_weight` decimal(10, 2) NULL DEFAULT NULL COMMENT '强制下单重量kg',
  `inner_test_switch_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '内测开关redis key',
  `dynamic_rule` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'NONE' COMMENT '动态规则：NONE/SF_LL_WEIGHT_THRESHOLD/SF_KY_CUSTOMER',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_user_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人id',
  `create_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人名称',
  `update_user_id` bigint NOT NULL DEFAULT 0 COMMENT '更新人id',
  `update_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0=正常，-100=删除/停用',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_config_id`(`config_id` ASC) USING BTREE,
  INDEX `idx_data_status`(`data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件顺丰物流下单配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_shelf_package_status
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_shelf_package_status`;
CREATE TABLE `xm_bulky_shelf_package_status`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `round_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次',
  `shelf_sn` int NOT NULL COMMENT '货架号',
  `ware_id` int NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `zone` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `zone_shelf` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '区-货架',
  `express_id` int NOT NULL DEFAULT 0 COMMENT '物流方式',
  `package_status` tinyint NOT NULL DEFAULT 0 COMMENT '是否打包完成 1:完成 0:未完成',
  `complete_type` tinyint NOT NULL DEFAULT 0 COMMENT '完成方式 1:手动 0:自动',
  `box_time` datetime NULL DEFAULT NULL COMMENT '设箱时间',
  `complete_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `outbound_time` datetime NULL DEFAULT NULL COMMENT '出库时间',
  `restock_status` tinyint NOT NULL DEFAULT 0 COMMENT '待补状态 0:无待补 1:存在待补货 2:补货已完成',
  `distribution_status` tinyint NOT NULL DEFAULT 0 COMMENT '配货完成状态 0:未完成 1:已完成',
  `has_sub_shelf` tinyint NOT NULL DEFAULT 0 COMMENT '是否有子货位 0:无 1:有',
  `manual_user_id` bigint NOT NULL DEFAULT 0 COMMENT '手动完成用户ID',
  `self_pickup` tinyint NOT NULL DEFAULT 0 COMMENT '是否自提 1:是 0:否',
  `delivery_time` time NOT NULL COMMENT '发货时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_round_shelf_status`(`round_no` ASC, `shelf_sn` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_shelf_sn`(`shelf_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 906206 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '货架打包状态表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_standard_price
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_standard_price`;
CREATE TABLE `xm_bulky_standard_price`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级分类ID',
  `first_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '一级分类名称',
  `second_id` bigint NOT NULL COMMENT '二级分类id',
  `second_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级分类名称',
  `rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '标准价',
  `is_update` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近一次是否更新了标准价 0未更新 1有更新',
  `flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0：ok 1：更新失败 2：价格预警',
  `version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '版本',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注信息',
  `push_buy_price` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推送收购价 0:不推送 1:推送',
  `buy_price_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '收购价方式 0:加 1:乘',
  `buy_price_num` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '加减的数值或乘除的数值',
  `push_onsale_price` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推送售卖价 0 ：不推送 1:推送',
  `onsale_price_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售卖价方式 0:加 1:乘',
  `onsale_price_num` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '加减的数值或乘除的数值',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `crate_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_second_id`(`second_id` ASC) USING BTREE,
  INDEX `idx_rank_num`(`rank_num` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 379444 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '每小时的商品正价' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_sub_account
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_sub_account`;
CREATE TABLE `xm_bulky_sub_account`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '子账号用户id，起始200001',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '用户类型 0-无 1-昆明 2-城市仓 3-分销商 4-花艺师',
  `user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '子账号登录名（唯一），不能有空格，限20字',
  `pass` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '密码密文',
  `salt` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '盐',
  `sex` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '性别 0:未知; 1:男; 2:女;',
  `nickname` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '姓名，不能有空格，限16字',
  `full_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '全职员工 0：不是 1：是',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机号，限20字',
  `description` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '描述，限128字',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '绑定供应商id',
  `logistics_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流绑定供应商',
  `base_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '基地配置',
  `admin_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否admin 0-否 1-是 1可以创建子账号',
  `job_number` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '工号',
  `password_version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '密码版本号（改密码自增）',
  `smart_locker_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '智能柜身份码',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id，为主账号userid',
  `operator_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建用户姓名，为主账号nickname',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最近一次登录时间，从未登录为NULL',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0:已冻结; 1:正常; -100:删除;',
  `need_change_password` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否需要强制修改密码 0-否 1-是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_name`(`user_name` ASC) USING BTREE,
  INDEX `idx_sid`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_jobnumber`(`job_number` ASC) USING BTREE,
  INDEX `idx_phone`(`phone` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 204602 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货子账号表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_suggestion
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_suggestion`;
CREATE TABLE `xm_bulky_suggestion`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自动增长ID',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 6 COMMENT '反馈类型 1：产品功能 2：物流状况 3：客服服务 4：商品相关 5：产品体验 6：其他问题 7：质检廉洁投诉 8：员工投诉反馈 9：基地投诉 10：对寻梦的建议 11:侵权投诉',
  `source` tinyint UNSIGNED NULL DEFAULT NULL,
  `contact` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系方式',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '反馈信息',
  `app_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '小程序appId',
  `image_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '反馈图片集',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '用户ID',
  `is_read` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已读 0:否; 1:是;',
  `handle_result` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '处理分类 1：无效反馈 2：处理完成',
  `handle_message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '处理描述',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '处理人id',
  `operator_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '处理人姓名',
  `create_time` datetime NOT NULL COMMENT '添加时间',
  `update_time` datetime NOT NULL COMMENT '最后修改时间',
  `data_status` tinyint NULL DEFAULT 0 COMMENT '状态；0：已提交,待处理；1:后台已处理；-100：删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_cTime_source`(`create_time` ASC, `source` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3113 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货反馈意见表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_suggestion_product_snapshot
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_suggestion_product_snapshot`;
CREATE TABLE `xm_bulky_suggestion_product_snapshot`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `suggestion_id` bigint NOT NULL COMMENT '投诉反馈ID',
  `product_id` bigint NOT NULL COMMENT '商品ID',
  `product_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称快照',
  `product_image_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '商品图片快照',
  `product_video_url` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品视频快照',
  `stem_length` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '枝干长度',
  `bud_size` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '花苞大小',
  `flower_advantage` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '花材优点',
  `uniformity` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '均匀度',
  `stem_thickness` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '枝干粗细',
  `curl_edge` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '卷边',
  `tag_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '商品详情全部属性展示文本',
  `rank_num` int NULL DEFAULT NULL COMMENT '商品等级原始值',
  `rank_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品等级展示值',
  `maturity` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生熟度',
  `product_tag` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品补充标签',
  `is_prefer` tinyint NOT NULL DEFAULT 0 COMMENT '是否优选：0否，1是',
  `quality_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否品质花材：0否，1是',
  `is_hot` tinyint NOT NULL DEFAULT 0 COMMENT '是否热销：0否，1是',
  `is_special` tinyint NOT NULL DEFAULT 1 COMMENT '是否特价：1否，2是',
  `is_seckill` tinyint NOT NULL DEFAULT 1 COMMENT '是否秒杀：1否，2是',
  `is_presale` tinyint NOT NULL DEFAULT 0 COMMENT '是否预售：0否，1是',
  `seven_no_aftersale` tinyint NOT NULL DEFAULT 0 COMMENT '是否7天0售后',
  `seven_no_lower_rank` tinyint NOT NULL DEFAULT 0 COMMENT '是否7日无降级',
  `seven_no_refund` tinyint NOT NULL DEFAULT 0 COMMENT '是否7日无退货',
  `seven_no_lack` tinyint NOT NULL DEFAULT 0 COMMENT '是否7日无缺货',
  `create_time` datetime NOT NULL COMMENT '快照创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_suggestion_id`(`suggestion_id` ASC) USING BTREE,
  INDEX `idx_product_id`(`product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '投诉商品快照表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier`;
CREATE TABLE `xm_bulky_supplier`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商类别 0:未选择 1:种植户 2:供应商 3:包花厂 4:寻梦员工 5:城市仓 6:分销商 7:寻梦物流员 8:农资服务商',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称，最长为50',
