  `default_entry` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认入场 0:否 1:是',
  `month_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30天销售扎数',
  `pay_off_mode` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '清退处理方式  0-不自动清退 1-到期自动清退',
  `partner_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否分销专属供应商 0-否 1-是',
  `invoice_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '可开票标记 0-未知 1-不可开票 2-可开票',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商地址坐标',
  `bear_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '自愿承担次数（售后）',
  `bear_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '自愿承担金额（售后）',
  `rename_time` datetime NULL DEFAULT NULL COMMENT '姓名更新时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常（未认证）; 1:已认证待审核;2:审核通过;3:审核不通过; 4:已清退 -100:删除;',
  `verify_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '验证电话',
  `verify_card_no` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '身份证手机号是否验证通过 0.无 1通过 2.不通过 3 审核中',
  `hand_card_url` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手持身份证图片',
  `verify_card_url` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '手持身份证图片是否验证通过 0.无 1通过  2.不通过',
  `verify_card_num` decimal(10, 10) NOT NULL DEFAULT 0.0000000000 COMMENT '验证手持身份证值',
  `license_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:未提交 1：已提交 2：机器审核成功 3：机器审核失败 4：人工审核成功 5人工审核失败',
  `ip` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'ip',
  `sign_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证签发日期',
  `expiration_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证失效日期',
  `comment_score` decimal(10, 2) NOT NULL DEFAULT 4.80 COMMENT '供应商分数',
  `biz_user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '通联会员自定义编码',
  `tl_user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '通联会员id',
  `acctid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '通联分账卡号',
  `promote_fee_balance` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '推广费余额',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_logintel_itemtype`(`login_tel` ASC, `item_type` ASC) USING BTREE,
  INDEX `idx_wx_open_id`(`wx_open_id` ASC) USING BTREE,
  INDEX `idx_thirdshopid`(`third_shop_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 304291 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_account
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_account`;
CREATE TABLE `xm_bulky_supplier_account`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `supplier_id` bigint NULL DEFAULT NULL COMMENT '供应商id',
  `owner_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '持有人姓名',
  `account_type` int NULL DEFAULT 0 COMMENT '收款账号类型：1：支付宝，2：银行卡号',
  `payee_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '对公对私标志：0：对公；1：个人 默认个人',
  `account_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款账号',
  `ali_pay_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付宝收款二维码',
  `bank_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '总行联行号',
  `bank_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '总行名称',
  `account_bank_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款账号银行，如中国工商银行',
  `account_bank_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分行联行号',
  `account_bank_address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款账号分行',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '银行卡手机号',
  `card_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证号码',
  `verify_account_no` tinyint NOT NULL DEFAULT 0 COMMENT '校验银行卡四要素是否通过 0.不通过 1.通过',
  `promote_fee_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推广费提现账户 0-否 1-是',
  `biz_user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_account_no`(`account_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24911 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商打款账户信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_account_change
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_account_change`;
CREATE TABLE `xm_bulky_supplier_account_change`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `supplier_id` bigint NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '变动类型 1:花材收入; 2:退款支出; 3:提现支出; 4:保证金补足 5:提现退回 6:缺货赔付 7:代履约罚款 8:多结算扣回 9:提货站运费支出 10:保证金退回 11:打包收入 12:抽点支出 13:抽点退回 14:城市仓加价收入 15：城市仓配送费收入 16：城市仓物流加价收入 17：服务费支出 18：城市仓物流费支出 19:城市仓售后承担 21:缺货处罚 22:未打勾处罚 23:迟到处罚 24:其他处罚 25:城市仓处罚支出 26:质检缺货处罚 27:退货处罚 28:退货补货处罚 30:取消处罚 32:代卖报损收入 33:代卖整单退回收入 34:代卖其他出库收入 35:配货收入 40: 优惠券城市仓承担 50:售后承担退回 51:其他补款 61:小时达收入 62:小时达退款 66:分销商扣运费 67:分销商补运费 68:城市仓资材加价收入 72：农资购买 73：农资退款 74：代配支出 77：农资收入 78：农资抽点 79：到场货支出 80：农资退回 81：农资抽点退回',
  `refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '对应refund表id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架号',
  `sub_shelf_sn` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  `weight` decimal(20, 0) UNSIGNED NOT NULL DEFAULT 0 COMMENT '重量',
  `old_money` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '变动前的账户余额',
  `money` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '变动金额 加钱为正 减钱为负',
  `new_money` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '变动后的账户余额',
  `refund_money` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `rebate_money` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '扣点金额',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`, `create_time`) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE,
  INDEX `idx_createtime_supplierid`(`create_time` ASC, `supplier_id` ASC) USING BTREE,
  INDEX `idx_ordersn_supplierid`(`order_sn` ASC, `supplier_id` ASC) USING BTREE,
  INDEX `idx_supplierid_ctime_type`(`supplier_id` ASC, `create_time` ASC, `type` ASC) USING BTREE,
  INDEX `idx_supplierid_ctime`(`supplier_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29157552 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商余额变动表' ROW_FORMAT = DYNAMIC PARTITION BY RANGE (to_days(`create_time`))
