CREATE TABLE `xm_bulky_supplier_address`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `base_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '基地ID',
