-- ----------------------------
-- Table structure for xm_bulky_supplier_app
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_app`;
CREATE TABLE `xm_bulky_supplier_app`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'appid',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sid_appid`(`supplier_id` ASC, `app_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商平台绑定表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_back
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_back`;
CREATE TABLE `xm_bulky_supplier_back`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商类别 0:未选择 1:种植户 2:供应商 3:包花厂 4:寻梦员工 5:城市仓 6:分销商 7:寻梦物流员 8:农资服务商',
  `own_product_status` tinyint NULL DEFAULT NULL,
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称，最长为50',
  `old_supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '曾用名',
  `supplier_images` varchar(1025) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商实力展示图集',
  `supplier_tag` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商标签，限50字',
  `third_shop_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '三方平台供货商id 0为我们平台的供货商',
  `operator_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '运营类型：0:非自运营 1：自运营',
  `item_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '销售业务类型 1:花材 :2资材 默认1',
  `is_quality` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否优质 0:否; 1:是;',
  `quality_sort` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '优质排序值 升序',
  `take_xm_coin_ratio` decimal(3, 3) UNSIGNED NOT NULL DEFAULT 0.000 COMMENT '供应商抽点 值不大于1',
  `auto_ratio` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否自动更新抽点 0-否 1-是',
  `agency_ratio_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '代卖抽点标志 0:不抽点 1:按照供应商抽点比例',
  `owner_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名',
  `owner_tel` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人电话',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商头像图片',
  `province_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '行政区域表的省code',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '行政区域表的市code',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `county_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '行政区域表的区县code',
  `country` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `address_detail` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `introduction` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商简介',
  `prove_type` tinyint NOT NULL DEFAULT 0 COMMENT '认证类型 1：个人认证 2：企业认证',
  `real_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名(法人姓名)',
  `card_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证号',
  `card_photo` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证照片正面',
  `card_photo_back` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证照片反面',
  `company_photo` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '营业执照照片',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业全称',
  `company_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '统一社会信用代码',
  `wx_open_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信登录openid',
  `wx_union_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信登录unionid',
  `session_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信登录会话KEY',
  `login_tel` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '登录手机号',
  `password` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '密码',
  `salt` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '盐值',
  `secondary_password` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级密码',
  `secondary_salt` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级密码盐值',
  `credit` int NOT NULL DEFAULT 100 COMMENT '供应商信用分',
  `credit_require` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '保证金要求，默认1000',
  `account_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '账户余额',
  `credit_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商保证金',
  `credit_standard` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否达到保证金标准 0：未达到 1：达到',
  `wait_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '待结算金额',
  `apply_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现中金额',
  `block_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '冻结金额',
  `is_block` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否冻结 0:否; 1:是;',
  `block_desc` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '冻结记录，取消冻结时置空，限20字符，如：2022-03-23 14:00:00',
  `last_block_record` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '近期冻结记录数组',
  `withdraw_block` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否提现冻结 0-否 1-是',
  `freeze_level` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '冻结等级',
  `withdraw_remark` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '提现备注 限64字',
  `is_open_rank_e` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）是否开放E等级 0:否; 1:是;',
  `after_sale_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后笔数',
  `sell_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销售笔数',
  `sell_volume` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销售扎数',
  `is_bear_station_fee` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商是否承担提货站运费 0:否; 1:是;',
  `station_fee` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.70 COMMENT '提货站运费单价（扎item_num，默认0.7）',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '助理id xm_bulky_help.id',
  `check_round` date NULL DEFAULT NULL COMMENT '审核通过场次',
  `check_time` datetime NULL DEFAULT NULL COMMENT '审核通过时间',
  `check_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核原因',
  `default_entry` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认入场 0:否 1:是',
  `month_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30天销售扎数',
  `pay_off_mode` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '清退处理方式  0-不自动清退 1-到期自动清退',
  `partner_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否分销专属供应商 0-否 1-是',
  `invoice_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '可开票标记 0-未知 1-不可开票 2-可开票',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商地址坐标',
  `bear_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '自愿承担次数（售后）',
  `bear_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '自愿承担金额（售后）',
  `rename_time` datetime NULL DEFAULT NULL COMMENT '姓名更新时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常（未认证）; 1:已认证待审核;2:审核通过;3:审核不通过; 4:已清退 -100:删除;',
  `verify_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '验证电话',
  `verify_card_no` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '身份证手机号是否验证通过 0.无 1通过 2.不通过 3 审核中',
  `hand_card_url` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手持身份证图片',
  `verify_card_url` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '手持身份证图片是否验证通过 0.无 1通过  2.不通过',
  `verify_card_num` decimal(10, 10) NOT NULL DEFAULT 0.0000000000 COMMENT '验证手持身份证值',
  `license_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:未提交 1：已提交 2：机器审核成功 3：机器审核失败 4：人工审核成功 5人工审核失败',
  `ip` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'ip',
  `sign_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证签发日期',
  `expiration_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证失效日期',
  `comment_score` decimal(10, 2) NOT NULL DEFAULT 4.80 COMMENT '供应商分数',
  `biz_user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '通联会员自定义编码',
  `tl_user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '通联会员id',
  `acctid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '通联分账卡号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_logintel_itemtype`(`login_tel` ASC, `item_type` ASC) USING BTREE,
  INDEX `idx_wx_open_id`(`wx_open_id` ASC) USING BTREE,
  INDEX `idx_thirdshopid`(`third_shop_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 304291 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_balance_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_balance_log`;
CREATE TABLE `xm_bulky_supplier_balance_log`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `supplier_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `account_money` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '余额',
  `credit_money` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '保证金',
  `create_time` datetime NOT NULL COMMENT '记录时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_id_time`(`supplier_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_time_sid`(`create_time` ASC, `supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 181154 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商余额记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_bill_assist
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_bill_assist`;
CREATE TABLE `xm_bulky_supplier_bill_assist`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `supplier_id` int NOT NULL COMMENT '供应商id',
  `supplier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `tenant_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业名称',
  `tax_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业税号',
  `digit_account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电子税务账号',
  `user_account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户账号',
  `bank_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开户行',
  `bank_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开户账号',
  `tax_rate` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '税率',
  `bai_wang_end_time` datetime NULL DEFAULT NULL COMMENT '百望云过期时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '发票助手过期时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_supplier_id`(`supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 102 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商发票助手及百望云设置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_bill_assist_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_bill_assist_order`;
CREATE TABLE `xm_bulky_supplier_bill_assist_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `supplier_id` int NOT NULL COMMENT '供应商id',
  `supplier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `tenant_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业名称',
  `tax_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业税号',
  `digit_account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电子税务账号',
  `user_account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户账号',
  `bank_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开户行',
  `bank_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开户账号',
  `tax_rate` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '税率',
  `bai_wang_end_time` datetime NULL DEFAULT NULL COMMENT '百望云过期时间',
  `start_time` datetime NULL DEFAULT NULL COMMENT '服务开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '服务结束时间',
  `order_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单金额',
  `order_status` tinyint NOT NULL DEFAULT 0 COMMENT '订单状态 0待支付 1已支付 2已关闭',
  `pay_type` tinyint NULL DEFAULT NULL COMMENT '支付方式 1余额支付 2微信支付',
  `mch_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信商户号',
  `wx_transaction_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信支付流水号',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '支付时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_no`(`order_no` ASC) USING BTREE,
  INDEX `idx_supplier_status`(`supplier_id` ASC, `order_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商发票助手订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_bill_settlement
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_bill_settlement`;
CREATE TABLE `xm_bulky_supplier_bill_settlement`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `supplier_id` bigint NOT NULL,
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `round_type` int NOT NULL,
  `order_status` int NULL DEFAULT NULL,
  `service_price` decimal(18, 2) NULL DEFAULT NULL,
  `origin_service_price` decimal(18, 2) NULL DEFAULT 0.00,
  `supplier_price` decimal(18, 2) NULL DEFAULT NULL,
  `qualify_price` decimal(18, 2) NULL DEFAULT NULL,
  `total_supplier_price` decimal(18, 2) NULL DEFAULT NULL,
  `station_fee` decimal(18, 2) NULL DEFAULT NULL,
  `product_num` int NULL DEFAULT NULL,
  `purchase_num` int NULL DEFAULT NULL,
  `item_num` int NULL DEFAULT NULL,
  `is_replace_match` int NULL DEFAULT NULL,
  `late_punish_price` decimal(18, 2) NULL DEFAULT NULL,
  `late_price` decimal(18, 2) NULL DEFAULT NULL,
  `stock_out_num` int NULL DEFAULT NULL,
  `demote_num` int NULL DEFAULT NULL,
  `after_sale` int NULL DEFAULT NULL,
  `return_num` int NULL DEFAULT NULL,
  `status` int NULL DEFAULT NULL,
  `order_sn_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `order_sn_list_all` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `create_time` datetime NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `data_status` int NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_supplier_round`(`supplier_id` ASC, `round_no` ASC, `round_type` ASC) USING BTREE,
  INDEX `idx_round`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 621 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_black_list
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_black_list`;
CREATE TABLE `xm_bulky_supplier_black_list`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商ID',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购端ID',
  `purchaser_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '客户姓名（脱敏）',
  `phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机号码',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注 限255字',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_supplier_purchase_phone`(`supplier_id` ASC, `purchaser_id` ASC, `phone` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 43 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商黑名单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_black_list_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_black_list_log`;
CREATE TABLE `xm_bulky_supplier_black_list_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `pid` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'pid',
  `operation_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '1.新增  2.删除',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商ID',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购端ID',
  `purchaser_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '客户姓名（脱敏）',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注 限255字',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 71 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商黑名单日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_class_second
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_class_second`;
CREATE TABLE `xm_bulky_supplier_class_second`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint UNSIGNED NOT NULL COMMENT '供应商id',
  `second_id` bigint UNSIGNED NOT NULL COMMENT '二级分类id',
  `rank_auth` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '[]' COMMENT 'rank权限[1,2,3,4,5,6]',
  `fes_limit_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否节日限制售卖 0-否 1-是',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_second_id`(`second_id` ASC) USING BTREE,
  INDEX `idx_recycle_auth`(`data_status` ASC, `update_time` ASC, `supplier_id` ASC, `second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1340461 AVG_ROW_LENGTH = 109 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货供应商二级分类rank权限表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_class_second_apply
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_class_second_apply`;
CREATE TABLE `xm_bulky_supplier_class_second_apply`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `second_id` bigint NOT NULL COMMENT '二级分类ID',
  `rank_auth` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '[]' COMMENT '申请等级权限JSON',
  `approved_rank_auth` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '[]' COMMENT '运营拟开通等级JSON，审核通过后为实际开通等级快照',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '审核状态：0待审核，1通过，2驳回',
  `active_flag` tinyint NULL DEFAULT 1 COMMENT '当前有效标记：1有效，NULL历史记录',
  `audit_user_id` bigint NULL DEFAULT NULL COMMENT '审核人ID',
  `audit_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人名称',
  `audit_remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0正常，-100删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_supplier_second_active`(`supplier_id` ASC, `second_id` ASC, `active_flag` ASC) USING BTREE,
  INDEX `idx_status_data_create`(`status` ASC, `data_status` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_second_id`(`second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 184 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商二级分类权限申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_class_second_auth_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_class_second_auth_log`;
CREATE TABLE `xm_bulky_supplier_class_second_auth_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint NOT NULL COMMENT '供应商id',
  `supplier_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `second_id` bigint NOT NULL COMMENT '二级分类id',
  `second_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二级分类名称',
  `second_pic_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二级分类图片',
  `before_rank_auth` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '[]' COMMENT '变更前rank权限',
  `after_rank_auth` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '[]' COMMENT '变更后rank权限',
  `operation_type` tinyint NOT NULL COMMENT '操作类型 1:授权 2:取消授权 3:修改授权',
  `cancel_auth_type` tinyint NULL DEFAULT NULL COMMENT '取消授权类型 1:手动取消 2:超期未卖出系统收回 3:二级品类下架',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人id，系统操作为0',
  `operator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_time`(`data_status` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_supplier_time`(`data_status` ASC, `supplier_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_second_time`(`data_status` ASC, `second_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_operation_time`(`data_status` ASC, `operation_type` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_cancel_auth_time`(`data_status` ASC, `cancel_auth_type` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_supplier_second_operation_time`(`data_status` ASC, `supplier_id` ASC, `second_id` ASC, `operation_type` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11853 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商二级分类权限变动日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_comment
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_comment`;
CREATE TABLE `xm_bulky_supplier_comment`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `purchaser_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名称',
  `phone` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户手机号',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `score` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '评分1-5颗星',
  `content` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '评价内容',
  `picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '评价图片',
  `reply_content` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '回复内容',
  `reply_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '回复图片',
  `reply_time` datetime NULL DEFAULT NULL COMMENT '回复时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_comment_score_daily
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_comment_score_daily`;
CREATE TABLE `xm_bulky_supplier_comment_score_daily`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `score_date` date NOT NULL COMMENT '统计日期',
  `supplier_id` bigint NOT NULL COMMENT '供应商id',
  `total_score` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '加权总分',
  `total_num` int NOT NULL DEFAULT 0 COMMENT '总扎数',
  `praise_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '好评数',
  `comment_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '评价数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_supplier_date`(`supplier_id` ASC, `score_date` ASC) USING BTREE,
  INDEX `idx_score_date`(`score_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 60 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商每日评价分统计' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_enter
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_enter`;
CREATE TABLE `xm_bulky_supplier_enter`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `type` tinyint NULL DEFAULT 1 COMMENT '入场方式 1.扫质检入场码、2.质检手动入场、3.NFC、4.系统签到 5.配货盘点入场 6：配货直接入场',
  `supplier_id` bigint NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `login_tel` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商电话',
  `date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次日期，如：2022-03-05',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id，为主账号userid',
  `enter_time` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '入场时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:未入场; 1:已入场',
  `night_enter_time` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '晚场入场时间',
  `night_data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:未入场 1：已入场',
  `night_open` tinyint NOT NULL DEFAULT 0 COMMENT '晚场是否展示 0:否; 1:是',
  `is_qualify` tinyint NOT NULL DEFAULT 0 COMMENT '是否存在不合格花材：0:合格 1:存在不合格',
  `is_late` tinyint NULL DEFAULT 0 COMMENT '是否迟到 0.没有迟到、1.迟到',
  `night_is_late` tinyint NOT NULL DEFAULT 0 COMMENT '晚场是否迟到:0否 1是',
  `is_force_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否是重点盘点 0:不是; 1:是',
  `quality_inspection_flag` tinyint NOT NULL DEFAULT 0 COMMENT '重点质检标识 0:不是 1：是',
  `distribution_overtime` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否允许超时配货 0:不允许; 1:允许',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_date`(`date` ASC) USING BTREE,
  INDEX `idx_data_status`(`data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1723767 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商入场表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_supplier_enter_item
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_enter_item`;
CREATE TABLE `xm_bulky_supplier_enter_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `enter_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商入场信息ID',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `order_num` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '货架号，流水号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `zone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `shelf` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `jump_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '跳货架号数量',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号',
  `date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次日期，如：2022-03-05',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `order_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_order_item.id',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品表主键id',
  `product_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '等级12345->ABCDE',
  `sku_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'sku配置',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品数量',
  `order_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT 'orderItemNum',
  `order_item_weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT 'orderItem商品重量',
  `is_position` tinyint NOT NULL DEFAULT 0 COMMENT '是否入位：0:未入位 1:已入位',
  `is_qualify` tinyint NOT NULL DEFAULT 0 COMMENT '是否存在不合格花材：1:合格 10:存在不合格',
  `not_qualify_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '不合格花材数量',
  `refund_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '退货花材数量',
  `lower_rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '降级花材数量',
  `lower_rank_level` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '降几级',
  `qualify_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '质检人ID',
  `qualify_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '质检人姓名',
  `prepare_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '配货人ID',
  `prepare_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配货人姓名',
  `prepare_time` datetime NULL DEFAULT NULL COMMENT '配货时间',
  `record_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '盘点数量',
  `handle_record_num` int NOT NULL DEFAULT 0 COMMENT '手动盘点数量',
  `prepare_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '配货数量',
  `re_qualify_user_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '复检人ID',
  `re_qualify_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '复检人姓名',
  `is_confirm_refund_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '复检员是否确认退货花材数量，0:未确认 1:已确认， 默认0',
  `is_confirm_lower_rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '复检员是否确认降级花材数量，0:未确认 1:已确认， 默认0',
  `is_confirm_lack_item_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '复检员是否确认缺货数量，0:未确认 1:已确认， 默认0',
  `is_re_qualify_user_confirm` tinyint NOT NULL DEFAULT 0 COMMENT '复检人是否全部确认 默认 0:未确认 1:已确认（缺货/降级/退货都确认了才为1）',
  `lack_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '缺货数量',
  `manual_lack_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '缺货数量（手动标记）',
  `restock_item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '补货数量',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款状态 0:无退款 1:已退款',
  `limit_distribution_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '限制配货 0无限制 1限制',
  `qualify_process_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）质检处理状态 0:未处理 1:已处理',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `lack_replenish_num` int NOT NULL DEFAULT 0 COMMENT '缺货补货数量',
  `lack_num` int NOT NULL DEFAULT 0 COMMENT '缺货不补数量',
  `already_restock_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '已补货数量',
  `return_num` int NOT NULL DEFAULT 0 COMMENT '退货不补数量',
  `focus_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '重点关注标识',
  `quality_inspection_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '重点质检标识',
  `return_replenish_num` int NULL DEFAULT NULL COMMENT '退货补货数量',
  `wms_restock_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '场地拿去补货数量',
  `duty_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否供应商全责， 0：不是 1：是',
  `duty_pic` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '全责凭证',
  `duty_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商全责备注',
  `print_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '打印标识',
  `no_after_sale_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否顾客不售后 0:售后 1:不售后',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ordersn_productid`(`order_sn` ASC, `product_id` ASC) USING BTREE,
  INDEX `idx_enter_id`(`enter_id` ASC) USING BTREE,
  INDEX `idx_supplierid_date`(`supplier_id` ASC, `date` ASC) USING BTREE,
  INDEX `idx_orderitemid`(`order_item_id` ASC) USING BTREE,
  INDEX `idx_date_ordernum`(`date` ASC, `order_num` ASC) USING BTREE,
  INDEX `idx_date_zone`(`date` ASC, `zone` ASC) USING BTREE,
  INDEX `idx_date_zoneshelf`(`date` ASC, `zone_shelf` ASC) USING BTREE,
  INDEX `idx_producti_date`(`product_id` ASC, `date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 990001695 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货入场商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_enter_item_back
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_enter_item_back`;
CREATE TABLE `xm_bulky_supplier_enter_item_back`  (
