  INDEX `idx_date`(`date` ASC) USING BTREE,
  INDEX `idx_supplierid_date`(`supplier_id` ASC, `date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5050049 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货入场商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_enter_package
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_enter_package`;
CREATE TABLE `xm_bulky_supplier_enter_package`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次日期，如：2022-03-05',
  `order_num` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '货架号，流水号',
  `zone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `shelf` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `package_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '打包师傅ID',
  `package_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '打包师傅姓名',
  `package_num` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '打包件数json，例：[{\"name\":\"60*60\",\"num\":\"3\"},{\"name\":\"50*60\",\"num\":\"2\"}]',
  `real_package_num` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流专员填写打包信息',
  `package_status` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '打包状态：0：配货中 1：可打包 10：打包中 100：打包完成',
  `package_write_status` tinyint UNSIGNED NULL DEFAULT NULL,
  `package_type` tinyint NOT NULL DEFAULT 0 COMMENT '打包类型：0:正常打包 1:缺货打包',
  `package_time` datetime NULL DEFAULT NULL COMMENT '打包完成时间',
  `biz_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流专员ID',
  `biz_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流专员姓名',
  `biz_status` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流登记状态：0：打包中 1：可填报 100：填报完成',
  `express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流配置表主键',
  `express_weight` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '预估重量，单位KG',
  `express_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '预估运费',
  `express_actual_weight` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实际重量，单位KG',
  `express_status` tinyint UNSIGNED NULL DEFAULT NULL,
  `express_actual_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实际运费',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图片、视频',
  `packager_income_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '打包工资结算状态 0：未结算 1：已结算',
  `limit_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否限制打包 0:无限制 1限制',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_num`(`order_num` ASC) USING BTREE,
  INDEX `idx_date`(`date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 117672 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货打包物流表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_experience_score
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_experience_score`;
CREATE TABLE `xm_bulky_supplier_experience_score`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `supplier_id` bigint NOT NULL DEFAULT 0 COMMENT '供应商ID',
  `total_score` decimal(5, 2) NOT NULL DEFAULT 100.00 COMMENT '综合体验分(总分100)',
  `base_sale_score` decimal(5, 2) NOT NULL DEFAULT 20.00 COMMENT '基础销售分(满分20)',
  `product_score` decimal(5, 2) NOT NULL DEFAULT 40.00 COMMENT '商品体验分(满分40)',
  `delivery_score` decimal(5, 2) NOT NULL DEFAULT 40.00 COMMENT '履约体验分(满分40)',
  `is_display` tinyint NOT NULL DEFAULT 1 COMMENT '是否展示 0:不展示 1:展示',
  `score_date` date NOT NULL DEFAULT '1970-01-01' COMMENT '评分日期(统计截止日期,往前推30天为统计周期)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '数据状态 0:正常 -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_supplier_date`(`supplier_id` ASC, `score_date` ASC) USING BTREE,
  INDEX `idx_score_date`(`score_date` ASC) USING BTREE,
  INDEX `idx_is_display`(`is_display` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 254013 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商综合体验分表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_info
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_info`;
CREATE TABLE `xm_bulky_supplier_info`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `register_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '统一社会信用代码',
  `license_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '营业执照名称',
  `license_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '营业执照url',
  `license_legal_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '营业执照法人姓名',
  `license_expire_date` date NULL DEFAULT NULL COMMENT '营业执照过期日期',
  `license_reject_reason` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '营业执照审核驳回原因',
  `own_product_images` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '供应商自产商品图片url',
  `own_product_reject_reason` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '自产自销认证审核驳回原因',
  `month_sales_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '每月花材销量',
  `qualify_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否符合质量要求 0:不符合 1符合',
  `top_rank_round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '热卖榜最佳场次',
  `top_rank_num` int NOT NULL DEFAULT 0 COMMENT '热卖榜最佳排名',
  `top_rank_first_type` int NOT NULL DEFAULT 0 COMMENT '热卖榜一级分类类型',
  `top_rank_first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '热卖榜一级分类ID',
  `top_rank_category_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '热卖榜分类展示名称',
  `top_rank_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '榜单类型：0-热卖榜 1-好评回购榜',
  `shop_repurchase_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '店铺回购人数',
  `shop_praise_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '店铺近30天好评数',
  `shop_praise_ratio` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '店铺近30天好评率',
  `favorite_supplier_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '店铺关注人数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `tag_update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '标签更新时间',
  `invoice_punish_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否发票逾期惩罚',
  `invoice_record_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '周一发票是否满足要求',
  `license_record_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '周一营业执照是否满足',
  `invoice_punish_record_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '周一发票处罚是否满足要求',
  `freeze_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30天冻结次数（含供应商及商品冻结）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_supplierId`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_tagtime`(`tag_update_time` ASC) USING BTREE,
  INDEX `idx_regno`(`register_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14261 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商额外信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_invoice_quota
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_invoice_quota`;
CREATE TABLE `xm_bulky_supplier_invoice_quota`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `total_quota` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '总可开票额度（定时任务累加）',
  `invoicing_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '开票中金额',
  `invoiced_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '已开票金额',
  `overdue_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '已逾期金额',
  `available_quota` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '可用额度（total - invoicing - invoiced - overdue）',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（乐观锁）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_supplier_id`(`supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商开票额度表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_invoice_set
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_invoice_set`;
CREATE TABLE `xm_bulky_supplier_invoice_set`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `supplier_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `tenant_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业名称',
  `tax_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业税号',
  `digit_account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电子税务账号',
  `bank_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开户行名称',
  `bank_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开户行账号',
  `good_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否已添加商品',
  `tax_rate` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0.01' COMMENT '商品税率',
  `bai_wang_end_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '百望云过期时间',
  `end_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '大件过期时间',
  `bai_wang_login_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '百望云登录账号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_supplier`(`supplier_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商百望云购买设置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_log`;
CREATE TABLE `xm_bulky_supplier_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作用户类型 0:系统 1:平台 2:供应商',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0.默认其他 1.冻结 2.解冻 3.修改名称 4:清退 5:修改基地 6:审核',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作内容',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_supplierid_type`(`supplier_id` ASC, `type` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1321 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货供应商日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_operation_money_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_operation_money_log`;
CREATE TABLE `xm_bulky_supplier_operation_money_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `supplier_id` bigint NULL DEFAULT NULL COMMENT '供应商id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '变动类型 1-增加 2-减少',
  `pay_reason` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收款事由 如:质保金 违规金',
  `pay_way` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收款方式 如:充值 货款账扣',
  `old_money` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '原保证金金额',
  `money` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '保证金增加（减少）金额',
  `new_money` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '新的保证金余额',
  `money_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '金额变动描述',
  `trade_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '保证金充值单号',
  `wx_pay_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信流水编号',
  `wx_pay_time` datetime NULL DEFAULT NULL COMMENT '微信申请时间',
  `receipt_url` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '保证金凭据url',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '数据状态 0：未支付 1：支付成功 -1：支付失败',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_tradeno`(`trade_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13483 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商保证金变动日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_order`;
CREATE TABLE `xm_bulky_supplier_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `order_num` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '每天流水号',
  `order_tag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:正 1：场 2：加',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '按物流和重量 场次结束时生成的货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `is_addition` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否加单 0:否; 1:是;',
  `receive_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人名称',
  `receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人手机号',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_supplier供应商表主键id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `supplier_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商订单号（唯一）',
  `delivery_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '送货单编号',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次编号：yyyy-MM-dd',
  `supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00,
  `origin_supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原供货价，为sum(商品供货价x数量)',
  `actual_price` decimal(10, 2) UNSIGNED NULL DEFAULT NULL,
  `origin_actual_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原实付费用，为sum(商品售价x数量)',
  `platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台总补贴',
  `origin_platform_discount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原平台总补贴',
  `take_xm_coin` decimal(10, 2) UNSIGNED NULL DEFAULT NULL,
  `origin_take_xm_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原供应商订单抽点的寻梦币金额',
  `take_ratio` decimal(3, 3) UNSIGNED NOT NULL DEFAULT 0.000 COMMENT '供应商抽点比例',
  `after_sale_supply_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '售后申请总供货价',
  `after_sale_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00,
  `paid_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00,
  `paid_coin` decimal(10, 2) UNSIGNED NULL DEFAULT NULL,
  `order_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单状态 0:待付款 1:已付款待发货 2:已发货待收货 3:已完成 4:已关闭 5:已取消',
  `wx_pay_time` datetime NULL DEFAULT NULL COMMENT '微信付款时间',
  `after_sale_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后状态 0:无售后 1:售后申请中 2:售后同意 3:售后拒绝',
  `after_sale_agree_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后同意类型 0:无 1:发货前售后同意; 2:发货后售后同意;',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款状态 0:无退款 1:申请退款中 2:退款成功 3:退款失败 4:极速退款中 5:极速退款成功 6:极速退款失败',
  `sort_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已分拣 0:否; 1:是;',
  `delivery_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已送货 0:否; 1:是;',
  `is_presale` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为预售订单 0：不是 1：是 默认0',
  `is_deliver` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商订单是否已配货 0:未配货; 1:配货中; 2:已配货;（配货用字段）',
  `is_bear_station_fee` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商是否承担提货站运费 0:否; 1:是;',
  `station_fee` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '提货站运费单价（扎item_num）',
  `origin_total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原提货站运费总价=单价*sum(origin_item_num)',
  `total_station_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '提货站运费当前总价=单价*sum(item_num)',
  `after_sale_coin` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '（废弃）售后承担寻梦币（小于等于after_sale_supply_price）',
  `is_sale_agency` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0普通订单 1:代卖订单',
  `is_invoice_marked` tinyint NOT NULL DEFAULT 0 COMMENT '是否打标（下单时供应商可开票状态快照）：0否 1是',
  `supplier_quota_added` tinyint NOT NULL DEFAULT 0 COMMENT '是否已计入供应商额度：0否 1是',
  `purchaser_quota_added` tinyint NOT NULL DEFAULT 0 COMMENT '是否已计入花店额度：0否 1是',
  `settle_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否结算 0-否 1-是',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `is_bond` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）是否履约 0:否; 1:是;',
  `bond_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00,
  `bond_paid_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '（废弃）代履约赔付金额',
  `zone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `shelf` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_supplier_no`(`supplier_no` ASC) USING BTREE,
  INDEX `idx_ptime_sid_ostatus_sprice`(`wx_pay_time` ASC, `supplier_id` ASC, `order_status` ASC, `supply_price` ASC) USING BTREE,
  INDEX `idx_round_supplier_status`(`round_no` ASC, `supplier_id` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_is_invoice_marked`(`is_invoice_marked` ASC, `supplier_id` ASC, `wx_pay_time` ASC) USING BTREE,
  INDEX `idx_supplier_quota_added`(`supplier_quota_added` ASC, `supplier_id` ASC, `wx_pay_time` ASC) USING BTREE,
  INDEX `idx_purchaser_quota_added`(`purchaser_quota_added` ASC, `order_status` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_ordersn_supplierid`(`order_sn` ASC, `supplier_id` ASC) USING BTREE,
  INDEX `idx_sid_ostatus_ptime_sprice`(`supplier_id` ASC, `order_status` ASC, `wx_pay_time` ASC, `supply_price` ASC) USING BTREE,
  INDEX `idx_zone_shelf`(`zone_shelf` ASC) USING BTREE,
  INDEX `idx_status_round_station_fee`(`order_status` ASC, `round_no` ASC, `total_station_fee` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 990003035 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货供应商订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_order_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_order_log`;
CREATE TABLE `xm_bulky_supplier_order_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `pid` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '唯一标识',
  `order_sn` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户订单号',
  `time` datetime NULL DEFAULT NULL COMMENT '付款时间',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单类型',
  `operator_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商类型',
  `supplier_id` int NULL DEFAULT NULL COMMENT '供应商id',
  `supplier_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `supply_price` decimal(20, 2) NULL DEFAULT NULL COMMENT '供应商结算',
  `take_ratio` decimal(20, 2) NULL DEFAULT NULL COMMENT '抽点金额',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pid`(`pid` ASC) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_time`(`time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 46 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商订单日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_order_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_order_record`;
CREATE TABLE `xm_bulky_supplier_order_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '用户订单号',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '付款时间',
  `record_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '记录类型 0：支付 1：售后 2：赔付',
  `supplier_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商类型 0：非自营 1：自营',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `supplier_get` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商所得',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件批发供应商订单发生金额记录表' ROW_FORMAT = Dynamic;

