  `purchaser_quota_added` tinyint NOT NULL DEFAULT 0 COMMENT '是否已计入花店额度：0否 1是',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_supplier_no`(`supplier_no` ASC) USING BTREE,
  INDEX `idx_ptime_sid_ostatus_sprice`(`wx_pay_time` ASC, `supplier_id` ASC, `order_status` ASC, `supply_price` ASC) USING BTREE,
  INDEX `idx_ordersn_supplierid`(`order_sn` ASC, `supplier_id` ASC) USING BTREE,
  INDEX `idx_zone_shelf`(`zone_shelf` ASC) USING BTREE,
  INDEX `idx_sid_ostatus_ptime_sprice`(`supplier_id` ASC, `order_status` ASC, `wx_pay_time` ASC, `supply_price` ASC) USING BTREE,
  INDEX `idx_round_supplier_status`(`round_no` ASC, `supplier_id` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_is_invoice_marked`(`is_invoice_marked` ASC, `supplier_id` ASC, `wx_pay_time` ASC) USING BTREE,
  INDEX `idx_supplier_quota_added`(`supplier_quota_added` ASC, `supplier_id` ASC, `wx_pay_time` ASC) USING BTREE,
  INDEX `idx_purchaser_quota_added`(`purchaser_quota_added` ASC, `order_status` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货供应商订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_punish
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_punish`;
CREATE TABLE `xm_bulky_supplier_punish`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `pid` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'pid',
  `round_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `zone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `shelf` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `zone_shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `supplier_id` bigint UNSIGNED NOT NULL COMMENT '供应商id',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供应商名称',
  `punish_type` tinyint UNSIGNED NOT NULL COMMENT '处罚类型 1:缺货处罚; 2:未打勾处罚; 3:迟到处罚; 4:其他; 5:城市仓处罚; 6：缺货补货处罚 7:退货不补处罚 8：退货补货处罚 9:缺货不补处罚10:取消处罚 11:退货不补转代卖处罚 12:退货补货转代卖处罚 13降一级处罚 14:迟到配货处罚15降两级处罚 16退款赠花  17超时转代卖 18换货 19配货错误处罚 20换货迟到配货处罚 21-供应商拒不开票处罚',
  `punish_kind` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '处罚类别 101-斗南未配300% 102-斗南漏配300% 103-斗南错配300% 104-斗南无记录300% 105-斗南轻罚15% 201-斗南待配无记录15% 301-其他无记录15%',
  `punish_link` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '处罚环节 0：售后处罚 1：质检处罚 2:代卖处罚 3:员工处罚 4：配错货处罚',
  `account_change_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_supplier_account_change.id',
  `money_log_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_supplier_operation_money_log.id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `order_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'item的主键',
  `enter_item_id` bigint UNSIGNED NULL DEFAULT NULL,
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号，可以为空，处罚理由为缺货处罚、未打钩处罚时，必须关联订单',
  `punish_proportion` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '0-100',
  `punish_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '处罚数量',
  `punish_price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '处罚金额（元），大于0',
  `pic_url` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '凭证照片视频，限2048字',
  `compensate_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款标识，0：不退款 1:退款',
  `compensate_price` decimal(10, 2) UNSIGNED NULL DEFAULT 0.00,
  `compensate_service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款服务费（元）',
  `compensate_coin` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款寻梦币（元）',
  `settle_flag` tinyint UNSIGNED NULL DEFAULT NULL,
  `settle_price` decimal(10, 2) UNSIGNED NULL DEFAULT NULL,
  `refund_result` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款申请结果',
  `refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '赔付id',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '处罚描述，限255字',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建用户姓名',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新用户姓名',
  `handle_status` tinyint UNSIGNED NULL DEFAULT NULL,
  `handle_time` datetime NULL DEFAULT NULL COMMENT '处理时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_orderitemid`(`order_item_id` ASC) USING BTREE,
  INDEX `idx_roundno_plink`(`round_no` ASC, `punish_link` ASC) USING BTREE,
  INDEX `idx_supplierid`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_ctime_hstatus_plink`(`create_time` ASC, `handle_status` ASC, `punish_link` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 921000626 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货供应商处罚表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_recharge
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_recharge`;
CREATE TABLE `xm_bulky_supplier_recharge`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `recharge_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型 1-线下汇款 2-扫码充值',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `ware_id` bigint NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `recharge_amount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '充值金额',
  `image_url` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片url',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `review_status` tinyint NOT NULL DEFAULT 0 COMMENT '申请状态：0-待审核 1-同意 2-拒绝 3-撤销',
  `reviewer_id` bigint NOT NULL DEFAULT 0 COMMENT '审核人id',
  `reviewer_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人姓名',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `review_remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核备注',
  `review_image_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核凭证图片url',
  `account_change_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '账单id',
  `apply_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '申请id',
  `out_trade_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户订单号',
  `create_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0-正常 -100-删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_partner_status`(`partner_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_status_review`(`status` ASC, `review_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 33 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商充值申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_recharge_apply
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_recharge_apply`;
CREATE TABLE `xm_bulky_supplier_recharge_apply`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `out_trade_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户订单号（唯一）',
  `trade_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台支付单号',
  `qrcode` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'qrcode',
  `money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '金额（元）',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付状态 0-已创建 1-支付成功 2-支付失败',
  `trade_ip` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '交易ip',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `payee_ent_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收款商户id',
  `payee_ent_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收款商户名称',
  `payer_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '付款openid',
  `payer_bank_sname` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '付款银行简称',
  `payer_acct_last` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '付款方付款银行后4位',
  `payer_acct_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '付款账户类型',
  `payer_bank_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '付款银行',
  `payer_ent_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '付款方企业名称',
  `pay_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付状态',
  `memo` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '附言',
  `attachment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单附加信息',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '支付成功时间',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_outid`(`out_trade_no` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 444 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商三方充值申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_reconciliation
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_reconciliation`;
CREATE TABLE `xm_bulky_supplier_reconciliation`  (
  `source_channel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '来源渠道：分销商/花仓酷/寻梦批发',
  `source_id` bigint NOT NULL COMMENT '供应商订单ID或退款商品明细ID',
  `statement_date` date NOT NULL COMMENT '对账日期',
  `partner_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分销商名称',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户订单号',
  `business_time` datetime NOT NULL COMMENT '支付或退款成功时间',
  `order_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '支付/退货/售后/退运费',
  `supplier_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '自营/非自营/珍情',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `supplier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `supplier_settlement` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商结算',
  `commission_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '抽点金额',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '首次写入时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后同步时间',
  PRIMARY KEY (`source_channel`, `source_id`, `order_type`) USING BTREE,
  INDEX `idx_business_time`(`business_time` ASC) USING BTREE,
  INDEX `idx_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_statement_date`(`statement_date` ASC) USING BTREE
) ENGINE = InnoDB AVG_ROW_LENGTH = 252 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '花材批发供应商订单维度对账单' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Table structure for xm_bulky_supplier_reg
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_reg`;
CREATE TABLE `xm_bulky_supplier_reg`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `reg_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '极光注册ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_reg_id`(`reg_id` ASC) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商极光注册ID绑定表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_repurchase_stats
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_repurchase_stats`;
CREATE TABLE `xm_bulky_supplier_repurchase_stats`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `supplier_id` bigint NOT NULL COMMENT '供应商id',
  `repurchase_count` int NOT NULL COMMENT '回购人数（近90天购买≥2次）',
  `stat_date` date NOT NULL COMMENT '统计日期（例如：2026-03-10）',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_supplier_date`(`supplier_id` ASC, `stat_date` ASC) USING BTREE,
  INDEX `idx_stat_repurchase_supplier`(`stat_date` ASC, `repurchase_count` ASC, `supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 558 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商近90天回购人数统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_score_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_score_log`;
CREATE TABLE `xm_bulky_supplier_score_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `supplier_id` bigint NOT NULL DEFAULT 0 COMMENT '供应商ID',
  `score_type` tinyint NOT NULL DEFAULT 1 COMMENT '积分类型 1:扣分 2:加分',
  `score_change` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '分数变动(扣分为负数,加分为正数)',
  `score_dimension` tinyint NOT NULL DEFAULT 0 COMMENT '扣分维度 0:无维度(加分) 1:基础销售分 2:商品体验分 3:履约体验分',
  `score_item` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '积分项',
  `score_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '积分原因',
  `source_type` tinyint NOT NULL DEFAULT 0 COMMENT '数据来源 0:无 1:处罚记录 2:售后单 3:订单 4:商品日志',
  `source_id` bigint NOT NULL DEFAULT 0 COMMENT '来源数据ID',
  `score_date` date NOT NULL DEFAULT '1970-01-01' COMMENT '积分日期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '数据状态 0:正常 -100:删除(申诉成功)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_score_date`(`score_date` ASC) USING BTREE,
  INDEX `idx_score_type`(`score_type` ASC) USING BTREE,
  INDEX `idx_score_dimension`(`score_dimension` ASC) USING BTREE,
  INDEX `idx_source`(`source_type` ASC, `source_id` ASC) USING BTREE,
  INDEX `idx_data_status`(`data_status` ASC) USING BTREE,
  INDEX `idx_supplier_score_date_type`(`supplier_id` ASC, `score_date` ASC, `score_type` ASC, `score_dimension` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 556304 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商体验分积分变动记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_second_sale_stat
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_second_sale_stat`;
CREATE TABLE `xm_bulky_supplier_second_sale_stat`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint UNSIGNED NOT NULL COMMENT '供应商id',
  `second_id` bigint UNSIGNED NOT NULL COMMENT '二级分类id',
  `last_sale_time` datetime NULL DEFAULT NULL COMMENT '最近有效售卖时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_supplier_second`(`supplier_id` ASC, `second_id` ASC) USING BTREE,
  INDEX `idx_last_sale_time`(`last_sale_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8197 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商二级品类最近售卖统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_sell_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_sell_record`;
CREATE TABLE `xm_bulky_supplier_sell_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint UNSIGNED NOT NULL COMMENT '供应商id',
  `start_date` date NOT NULL COMMENT '开始日期，年月日，如2022-08-09',
  `end_date` date NOT NULL COMMENT '结束日期，年月日，如2022-08-09',
  `after_sale_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '开始结束期间的售后笔数（闭区间）',
  `sell_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '开始结束期间的销售笔数（闭区间）',
  `sell_volume` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销售扎数',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_date`(`start_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9479 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货供应商销量记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_settlement_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_settlement_record`;
CREATE TABLE `xm_bulky_supplier_settlement_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单编号',
  `settle_date` date NOT NULL COMMENT '结算日期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_settle_date`(`settle_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 292 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商结算完成记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_sub
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_sub`;
CREATE TABLE `xm_bulky_supplier_sub`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代送员工名称',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代送员工手机号',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商手机号',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态 0：正常 -100删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_phone`(`phone` ASC) USING BTREE COMMENT '手机号',
  INDEX `idx_supplier_id`(`supplier_id` ASC) USING BTREE COMMENT '供应商id'
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商代送员工表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_subsidy
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_subsidy`;
CREATE TABLE `xm_bulky_supplier_subsidy`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '用户类型 1-供应商 2-员工 3-城市仓 4-分销商',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '员工id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型 1-发票补贴 2-售后承担退回 10-其他补款',
  `money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '补款金额（发票补贴上限30w，售后承担金额为供货价上限，其他补款上限1w）',
  `subsidy_ratio` decimal(6, 3) UNSIGNED NOT NULL DEFAULT 0.000 COMMENT '补贴比例（发票补贴用，上限0.02）',
  `invoice_value` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '发票金额（发票补贴用）',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号（售后承担用）',
  `file_url` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文件url 限4096字',
  `remark` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注 限2048字',
  `account_change_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补贴余额变动id',
  `cancel_change_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '补贴撤销余额变动id',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-已创建 1-已通过 2-已撤销',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `agree_time` datetime NULL DEFAULT NULL COMMENT '通过时间',
  `cancel_time` datetime NULL DEFAULT NULL COMMENT '撤销时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_supplierid`(`supplier_id` ASC) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 71 AVG_ROW_LENGTH = 356 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货供应商补款表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_tag
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_tag`;
CREATE TABLE `xm_bulky_supplier_tag`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `tag_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '标签id xm_bulky_user_tag.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `id_sid_tagid`(`supplier_id` ASC, `tag_id` ASC) USING BTREE,
  INDEX `idx_tagid`(`tag_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 146 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商标签表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_take_ratio_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_take_ratio_log`;
CREATE TABLE `xm_bulky_supplier_take_ratio_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `month_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '历史近30天销售扎数',
  `take_ratio` decimal(3, 3) UNSIGNED NOT NULL DEFAULT 0.000 COMMENT '历史抽点比例',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_createtime_supplierid`(`create_time` ASC, `supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23993 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货供应商抽点比例记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_temp
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_temp`;
CREATE TABLE `xm_bulky_supplier_temp`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商类别 0:未选择 1:种植户 2:供应商 3:包花厂 4:寻梦员工 5:城市仓 6:分销商 7:寻梦物流员 8:农资服务商',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称，最长为50',
  `old_supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '曾用名',
  `comment_score` decimal(20, 0) NULL DEFAULT NULL,
  `supplier_images` varchar(1025) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商实力展示图集',
  `supplier_tag` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商标签，限50字',
  `third_shop_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '三方平台供货商id 0为我们平台的供货商',
  `operator_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '运营类型：0:非自运营 1：自运营',
  `item_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '销售业务类型 1:花材 :2资材 默认1',
  `is_quality` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否优质 0:否; 1:是;',
  `quality_sort` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '优质排序值 升序',
  `take_xm_coin_ratio` decimal(3, 3) UNSIGNED NOT NULL DEFAULT 0.000 COMMENT '供应商抽点 值不大于1',
  `auto_ratio` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否自动更新抽点 0-否 1-是',
  `agency_ratio_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '代卖抽点标志 0:不抽点 1:按照供应商抽点比例',
  `owner_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名',
  `owner_tel` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人电话',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商头像图片',
  `province_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '行政区域表的省code',
  `province` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '行政区域表的市code',
  `city` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `county_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '行政区域表的区县code',
  `country` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `address_detail` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `introduction` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商简介',
  `prove_type` tinyint NOT NULL DEFAULT 0 COMMENT '认证类型 1：个人认证 2：企业认证',
  `real_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系人姓名(法人姓名)',
  `card_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证号',
  `card_photo` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证照片正面',
  `card_photo_back` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证照片反面',
  `company_photo` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '营业执照照片',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '企业全称',
  `company_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '统一社会信用代码',
  `wx_open_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信登录openid',
  `wx_union_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信登录unionid',
  `session_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信登录会话KEY',
  `login_tel` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '登录手机号',
  `password` varchar(125) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '密码',
  `salt` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '盐值',
  `secondary_password` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级密码',
  `secondary_salt` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级密码盐值',
  `credit` int NOT NULL DEFAULT 100 COMMENT '供应商信用分',
  `credit_require` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '保证金要求，默认1000',
  `account_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '账户余额',
  `credit_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商保证金',
  `credit_standard` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否达到保证金标准 0：未达到 1：达到',
  `wait_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '待结算金额',
  `apply_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '提现中金额',
  `block_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '冻结金额',
  `is_block` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否冻结 0:否; 1:是;',
  `block_desc` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '冻结记录，取消冻结时置空，限20字符，如：2022-03-23 14:00:00',
  `last_block_record` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '近期冻结记录数组',
  `withdraw_block` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否提现冻结 0-否 1-是',
  `freeze_level` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '冻结等级',
  `withdraw_remark` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '提现备注 限64字',
  `is_open_rank_e` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '（废弃）是否开放E等级 0:否; 1:是;',
  `after_sale_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后笔数',
  `sell_times` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销售笔数',
  `sell_volume` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销售扎数',
  `is_bear_station_fee` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商是否承担提货站运费 0:否; 1:是;',
  `station_fee` decimal(6, 2) UNSIGNED NOT NULL DEFAULT 0.70 COMMENT '提货站运费单价（扎item_num，默认0.7）',
  `help_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '助理id xm_bulky_help.id',
  `check_round` date NULL DEFAULT NULL COMMENT '审核通过场次',
  `check_time` datetime NULL DEFAULT NULL COMMENT '审核通过时间',
  `check_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核原因',
  `default_entry` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认入场 0:否 1:是',
  `month_sell_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近30天销售扎数',
  `pay_off_mode` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '清退处理方式  0-不自动清退 1-到期自动清退',
  `partner_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否分销专属供应商 0-否 1-是',
  `invoice_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '可开票标记 0-未知 1-不可开票 2-可开票',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商地址坐标',
  `bear_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '自愿承担次数（售后）',
  `bear_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '自愿承担金额（售后）',
  `rename_time` datetime NULL DEFAULT NULL COMMENT '姓名更新时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常（未认证）; 1:已认证待审核;2:审核通过;3:审核不通过; 4:已清退 -100:删除;',
  `verify_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '验证电话',
  `verify_card_no` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '身份证手机号是否验证通过 0.无 1通过 2.不通过 3 审核中',
  `hand_card_url` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手持身份证图片',
  `verify_card_url` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '手持身份证图片是否验证通过 0.无 1通过  2.不通过',
  `verify_card_num` decimal(10, 10) NOT NULL DEFAULT 0.0000000000 COMMENT '验证手持身份证值',
  `license_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:未提交 1：已提交 2：机器审核成功 3：机器审核失败 4：人工审核成功 5人工审核失败',
  `own_product_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商自产自销认证 0:未提交 1：已提交 2：审核成功 3：人工审核失败',
  `ip` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'ip',
  `sign_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证签发日期',
  `expiration_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '身份证失效日期',
  `biz_user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '通联会员自定义编码',
  `tl_user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '通联会员id',
  `acctid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '通联分账卡号',
  `avatar_audit_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '头像审核状态 0未审核/历史旧数据 100机器审核中 201机器审核通过 202机器审核失败 401人工审核通过 402人工审核失败',
  `avatar_audit_image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '待审核头像图片URL',
  `avatar_audit_trace_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微信头像审核trace_id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_logintel_itemtype`(`login_tel` ASC, `item_type` ASC) USING BTREE,
  INDEX `idx_wx_open_id`(`wx_open_id` ASC) USING BTREE,
  INDEX `idx_thirdshopid`(`third_shop_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 304276 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_supplier_withdrawal
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_supplier_withdrawal`;
CREATE TABLE `xm_bulky_supplier_withdrawal`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `record_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '提现编码（唯一，微信的partnerTradeNo）',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商ID',
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `account_id` bigint UNSIGNED NOT NULL COMMENT 'account表主键id',
  `purpose` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '1-供应商提现 2-配货员提现 3-物流员提现 4-农资服务商提现',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分配操作员id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分配操作员名称',
  `distribute_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分配id',
  `biz_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '提现打款主体 0-无 1-梦晟 2-昆明寻梦 xm_bulky_withdraw_payer.id',
  `apply_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '申请金额',
  `service_fee` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '手续费',
  `apply_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核状态 0:申请中; 1:同意; 2:拒绝;',
  `withdraw_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '提现状态 0:未提现; 1:提现中; 2:提现成功; 3:提现失败;',
  `withdraw_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '提现类型 0:无; 1:手动审核; 2:支付宝打款; 3:工行打款; 4:支付宝接口; 5:平台民生打款 6:支付中心打款',
  `channel_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付渠道code（xm_pay_channel.channel_code）',
  `out_biz_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付中心单号',
  `is_unusual` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否异常 0:否; 1:是;',
  `pic_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '交易凭证图片列表，不超过2048字符',
  `wx_payment_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信付款单号',
  `payment_time` datetime NULL DEFAULT NULL COMMENT '微信付款成功时间',
  `customer_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '处理客服ID',
  `customer_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '处理客服名称',
  `reject_reason` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝原因，限128字',
  `device_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0：默认（适配之前） 1：小程序 2：app（IOS） 3:PDA   4:APP(android)',
  `ip` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'ip',
  `apply_time` datetime NULL DEFAULT NULL COMMENT '审核时间，默认null',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `promote_fee_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推广费提现 0-否 1-是',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_record_code`(`record_code` ASC) USING BTREE,
  INDEX `idx_apply_status`(`apply_status` ASC) USING BTREE,
  INDEX `idx_distribution_id`(`distribute_id` ASC) USING BTREE,
  INDEX `idx_ctime_supplierid`(`create_time` ASC, `supplier_id` ASC) USING BTREE,
  INDEX `idx_supplierid_wstatus_applymoney`(`supplier_id` ASC, `withdraw_status` ASC, `apply_money` ASC) USING BTREE,
  INDEX `idx_wtype_wstatus`(`withdraw_type` ASC, `withdraw_status` ASC) USING BTREE,
  INDEX `idx_ds_name_account_supplier`(`data_status` ASC, `supplier_name` ASC, `account_id` ASC, `supplier_id` ASC) USING BTREE,
  INDEX `idx_ds_account_supplier`(`data_status` ASC, `account_id` ASC, `supplier_id` ASC) USING BTREE,
  INDEX `idx_ds_supplier_account`(`data_status` ASC, `supplier_id` ASC, `account_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 44114 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商提现记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_tag
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_tag`;
CREATE TABLE `xm_bulky_tag`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级分类id 0为基础标签',
  `parent_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '父id，0为父标签，大于0为子标签',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标签名称',
  `is_multi` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级标签是否多选 0:否; 1:是;',
  `need_flag` tinyint NOT NULL DEFAULT 0 COMMENT '是否必填：0-是 1-不是',
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标准说明(面向供应商)',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `can_modify` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '供应商能否修改 0-否 1-是',
  `sequence` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '标签排序 数字越大排位越靠前',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '标签体系重构-启用状态 0-停用 1-启用（仅父标签有意义）',
  `tag_type` tinyint NOT NULL DEFAULT 0 COMMENT '标签体系重构-体系归属：0-旧体系 1-新体系（基础标签及其规格均为1）',
  `max_count` int NOT NULL DEFAULT 0 COMMENT '标签体系重构-最大数量，仅存储供前端展示（仅基础标签有意义）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_parent_id`(`parent_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1611 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货商品标签表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_bulky_tag_product
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_tag_product`;
CREATE TABLE `xm_bulky_tag_product`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_class_second表主键id',
  `tag_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_tag标签表主键id（二级标签）',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_product商品表主键id',
  `template_product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'xm_bulky_product_template模板商品表主键id',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_second_id`(`second_id` ASC) USING BTREE,
  INDEX `idx_productid`(`product_id` ASC) USING BTREE,
  INDEX `idx_tagid_status_product`(`tag_id` ASC, `data_status` ASC, `product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9214005 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货标签商品关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_tag_second_rank
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_tag_second_rank`;
CREATE TABLE `xm_bulky_tag_second_rank`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '二级分类id',
  `rank_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级123456->ABCDEO',
  `tag_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '标签id',
  `type` tinyint NOT NULL DEFAULT 1 COMMENT '标签体系重构-配置类型：1-旧体系默认值(供应商端预填规格) 2-新体系等级可选规格范围(供应商只能在范围内选) 3-新体系默认值(供应商端锁定规格)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '标签体系重构-最近更新时间',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '标签体系重构-操作人id',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签体系重构-操作人姓名',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_secondid_ranknum_tagid_type`(`second_id` ASC, `rank_num` ASC, `tag_id` ASC, `type` ASC) USING BTREE,
  INDEX `idx_type_secondid`(`type` ASC, `second_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 37963 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '二级分类等级标签配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_tally_income_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_tally_income_record`;
CREATE TABLE `xm_bulky_tally_income_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `code_content` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '入库条码',
  `date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次日期',
  `user_id` bigint NOT NULL COMMENT '入库操作人ID',
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库操作人姓名',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.05 COMMENT '单扎理货费用',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '数据状态，0正常，-100删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_code_content`(`code_content` ASC) USING BTREE,
  INDEX `idx_date_user`(`date` ASC, `user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '理货收益原始记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_team
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_team`;
CREATE TABLE `xm_bulky_team`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '团队类型 1-供应商推广小组(废弃) 2-配货团队 3-打包团队 4-质检团队 5-出库团队 6-基地团队 7-物流团队',
  `name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '组名，限16字',
  `role_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '小组绑定角色id',
  `perm_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '权限配置',
  `package_deadline_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '打包要求完成时间档位配置JSON',
  `people_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '人数',
  `leader_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '组长id xm_admin.id xm_bulky_sub_account.id',
  `leader_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '组长名称，限20字',
  `charge_base` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '[]' COMMENT '负责基地json字符串，限255字',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `active_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否启用 0-禁用 1-启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 107 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货小组表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_team_user
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_team_user`;
CREATE TABLE `xm_bulky_team_user`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名称，限20字',
  `is_sub` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为子账号 0:否 1:是',
  `team_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '小组id xm_bulky_team.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_teamid_userid`(`team_id` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 958 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货小组成员表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_team_user_snapshot
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_team_user_snapshot`;
CREATE TABLE `xm_bulky_team_user_snapshot`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场次，格式yyyy-MM-dd',
  `team_id` int UNSIGNED NOT NULL COMMENT '团队ID，来源xm_bulky_team.id',
  `team_type` tinyint UNSIGNED NOT NULL COMMENT '团队类型 2-配货 3-打包 4-质检',
  `team_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '团队名称快照',
  `team_role_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '团队绑定角色ID快照',
  `team_perm_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '团队权限配置快照，包含负责分区',
  `team_charge_base` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '[]' COMMENT '团队负责基地快照',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '团队人员子账号ID',
  `user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '团队人员姓名快照',
  `is_sub` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否为子账号 0-否 1-是',
  `leader_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为团队负责人 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '快照创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_round_team_user`(`round_no` ASC, `team_id` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_round_type_leader`(`round_no` ASC, `team_type` ASC, `leader_flag` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3344 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '团队及团队人员场次扁平快照表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_telemarket
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_telemarket`;
CREATE TABLE `xm_bulky_telemarket`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `phone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '手机号（暂时是11位）',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户类型 0：拉新推广 1：促转化推广 2复购推广 3 活跃',
  `last_type` tinyint UNSIGNED NOT NULL COMMENT '最近一次用户类型',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0：正常 -1：删除 ',
  `call_status` tinyint UNSIGNED NOT NULL COMMENT '拨打状态 0：未拨打 1：已拨通 2：未接通 3无效号码',
  `call_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '拨打时间',
  `source` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '来源 1外部导入 2平台 3单个添加',
  `customer_service` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '客服',
  `allocation_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分配客服时间',
  `register_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '注册时间',
  `buy_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '购买时间',
  `remark` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注 用|进行分割',
  `invalid_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '无效时间',
  `create_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '插入时间',
  `update_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `phone`(`phone` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 536 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货拉新电销' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_telemarket_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_telemarket_log`;
CREATE TABLE `xm_bulky_telemarket_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `phone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '手机号',
  `user` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作人',
  `user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `operate_type` tinyint UNSIGNED NOT NULL COMMENT '操作类型1：导入来源 2：用户类型变更 3：标记客服 4：客服变更 5：拨打情况 6：备注变更',
  `old_content` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '旧数据',
  `new_content` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '新数据',
  `create_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `phone`(`phone` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1497 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货拉新电销记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_template
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_template`;
CREATE TABLE `xm_bulky_template`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `template_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '（废弃）寻梦大件货模板表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_third_purchaser
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_third_purchaser`;
CREATE TABLE `xm_bulky_third_purchaser`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `third_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '三方用户id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '三方平台类型 1-珍情',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_thirduserid_type`(`third_user_id` ASC, `type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货三方采购方表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_third_shelf
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_third_shelf`;
CREATE TABLE `xm_bulky_third_shelf`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号（唯一）',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `third_shelf` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '三方货位号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ordersn`(`order_sn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货三方货位号表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_trade_period
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_trade_period`;
CREATE TABLE `xm_bulky_trade_period`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '时间类型 0:营业时间; 1:每日休市时间; 2:节日休市时间;（2时开始结束时间为年月日时分秒）3:代卖营业时间 4：代卖截单时间',
  `open_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '02:00:00' COMMENT '开始时间，如：02:00:00',
  `close_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '20:00:00' COMMENT '结束时间，如：20:00:00',
  `refund_time` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '18:00:00' COMMENT '截止退款时间，如：18:00:00',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `operator_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货交易时段表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_transfer_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_transfer_record`;
CREATE TABLE `xm_bulky_transfer_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `purchaser_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购方id',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户订单号',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `refund_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后id',
  `amount` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '金额',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0-已创建 1-已打款',
  `transfer_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '转账单号，限64字',
  `file_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '凭证url数组',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ordersn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_refundid_datastatus`(`refund_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '转账记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_user_tag
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_user_tag`;
CREATE TABLE `xm_bulky_user_tag`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型 1-采购方 2-供应商',
  `tag_category` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '标签表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_virtual_account
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_virtual_account`;
CREATE TABLE `xm_bulky_virtual_account`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL COMMENT '账户类型 1:平台; 2:自营店;（不可修改）',
  `can_pay` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '财务是否能充值 0:否; 1:是;',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账户名称，限50字',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注，限255字',
  `account_money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '账户余额（可以为负）',
  `freeze_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '冻结金额（不能为负）',
  `is_enable` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否启用 0:否; 1:是; 默认不启用',
  `version` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '版本号',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1003 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货虚拟账户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_virtual_apply
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_virtual_apply`;
CREATE TABLE `xm_bulky_virtual_apply`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `record_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请编码，限32字',
  `virtual_account_id` bigint UNSIGNED NOT NULL COMMENT '虚拟账户id',
  `money_account_id` bigint UNSIGNED NOT NULL COMMENT '虚拟打款账户id',
  `spend_type` tinyint UNSIGNED NOT NULL COMMENT '支出/采购类型 3:物流费; 4:场地耗材; 5:人工薪资; 6:其他; 11:花款; 12:;',
  `apply_money` decimal(10, 2) UNSIGNED NOT NULL COMMENT '申请金额',
  `apply_user_id` bigint UNSIGNED NOT NULL COMMENT '申请用户id',
  `apply_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请用户名称',
  `apply_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '申请人备注，限255字',
  `agree_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '财务审核用户id',
  `agree_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '财务审核用户名称',
  `agree_time` datetime NULL DEFAULT NULL COMMENT '财务审核时间，默认null',
  `apply_status` tinyint UNSIGNED NOT NULL COMMENT '审核状态 0:已创建 1:已撤回; 2:已拒绝; 3:财务拒绝; 4:待审核; 5:已审核; 6:已打款;',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核备注，限255字',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_record_code`(`record_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 120 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货虚拟账户申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_virtual_apply_file
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_virtual_apply_file`;
CREATE TABLE `xm_bulky_virtual_apply_file`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `virtual_apply_id` bigint UNSIGNED NOT NULL COMMENT '申请id',
  `file_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文件url，限255字',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_virtual_apply_id`(`virtual_apply_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 210 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货虚拟申请附件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_virtual_apply_item
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_virtual_apply_item`;
CREATE TABLE `xm_bulky_virtual_apply_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `virtual_apply_id` bigint UNSIGNED NOT NULL COMMENT '申请id',
  `first_id` bigint UNSIGNED NOT NULL COMMENT '一级分类id',
  `first_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '一级分类名称',
  `second_id` bigint NOT NULL COMMENT '二级分类id',
  `second_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '二级分类名称',
  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品图片',
  `rank_num` tinyint UNSIGNED NOT NULL COMMENT '等级123456->ABCDEO',
  `spec_and_num` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规格数量+规格名称',
  `unit_price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '单价',
  `item_num` int UNSIGNED NOT NULL COMMENT '数量',
  `total_price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '总价=单价x数量',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_virtual_apply_id`(`virtual_apply_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 141 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货虚拟采购明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_virtual_bill
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_virtual_bill`;
CREATE TABLE `xm_bulky_virtual_bill`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `virtual_account_id` bigint UNSIGNED NOT NULL COMMENT '虚拟账户id',
  `virtual_account_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '虚拟账户名称',
  `virtual_apply_id` bigint UNSIGNED NOT NULL COMMENT '申请id，0为财务打款',
  `spend_type` tinyint UNSIGNED NOT NULL COMMENT '支出/采购类型 1:财务加钱; 2:财务扣钱; 3:物流费; 4:场地耗材; 5:人工薪资; 6:其他; 11:花款; 12:其他;',
  `business_type` tinyint UNSIGNED NOT NULL COMMENT '业务类型 1:入账增加; 2:出账减少;',
  `old_money` decimal(10, 2) NOT NULL COMMENT '变动前余额（可以为负）',
  `money` decimal(10, 2) NOT NULL COMMENT '变动金额（可以为负）',
  `new_money` decimal(10, 2) NOT NULL COMMENT '变动后余额（可以为负）',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_virtual_account_id`(`virtual_account_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 61 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货虚拟账单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_virtual_money_account
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_virtual_money_account`;
CREATE TABLE `xm_bulky_virtual_money_account`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `virtual_account_id` bigint UNSIGNED NOT NULL COMMENT '虚拟账户id',
  `account_type` tinyint UNSIGNED NOT NULL COMMENT '收款账户类型 1:支付宝; 2:银行卡;',
  `payee_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '对公对私标志 0:对公; 1:个人; 默认个人',
  `account_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收款账号（同一虚拟账户收款账号不重复），限32字',
  `owner_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '持有人名称，限50字',
  `ali_pay_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付宝收款码，限1024字',
  `bank_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '总行联行号，限50字',
  `bank_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '总行名称，限128字',
  `account_bank_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '银行名称，限50字',
  `account_bank_address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收款账号分行',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最近更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最近更新用户名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_virtual_account_id`(`virtual_account_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 81 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货虚拟打款账户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_virtual_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_virtual_operation_log`;
CREATE TABLE `xm_bulky_virtual_operation_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `virtual_apply_id` bigint UNSIGNED NOT NULL COMMENT '申请id',
  `content` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作内容，限64字',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户名称',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_virtual_apply_id`(`virtual_apply_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 130 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货虚拟操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_ware_pre_income
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_ware_pre_income`;
CREATE TABLE `xm_bulky_ware_pre_income`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `ware_id` int NOT NULL COMMENT '城市仓id',
  `ware_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '城市仓名称',
  `total_weight` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总重量',
  `total_item_num` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '总扎数',
  `package_pre_income` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '打包预计收益',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_date_zone`(`date` ASC, `ware_id` ASC) USING BTREE COMMENT '场次'
) ENGINE = InnoDB AUTO_INCREMENT = 262 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '统计每场次城市仓预计打包收益等信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_warm_config
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_warm_config`;
CREATE TABLE `xm_bulky_warm_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型 1:小件及天地盖 2:中件及大件',
  `min_temper` tinyint NOT NULL DEFAULT 0 COMMENT '最低温度',
  `max_temper` tinyint NOT NULL DEFAULT 0 COMMENT '最高温度',
  `warm_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '保温棉数量',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '（废弃）大件货保温棉配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_wecom_kf_binding
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_wecom_kf_binding`;
CREATE TABLE `xm_bulky_wecom_kf_binding`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `corp_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '??????ID',
  `agent_id` int NOT NULL DEFAULT 1000011 COMMENT '?????????????AgentId',
  `channel` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'bulky' COMMENT '?????bulky???fanhua??',
  `scene` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `scene_param` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `external_user_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `user_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'USER????SUPPLIER???',
  `user_id` bigint NOT NULL COMMENT '??user_type????????ID',
  `last_enter_time` datetime NULL DEFAULT NULL COMMENT '最近一次确认进入会话时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_corp_agent_external_user_id`(`corp_id` ASC, `agent_id` ASC, `external_user_id` ASC) USING BTREE,
  INDEX `idx_user_type_user_id`(`user_type` ASC, `user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '企业微信客服场景与采购商绑定' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_withdraw_biz
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_withdraw_biz`;
CREATE TABLE `xm_bulky_withdraw_biz`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称',
  `pay_com_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付公司id xm_pay_company.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货提现配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_withdraw_distribute
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_withdraw_distribute`;
CREATE TABLE `xm_bulky_withdraw_distribute`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分配名称，限30字',
  `money` decimal(20, 2) UNSIGNED NOT NULL COMMENT '分配金额',
  `withdraw_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分配笔数',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ctime`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1730 AVG_ROW_LENGTH = 216 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦大件货提现分配表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_wms_area
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_wms_area`;
CREATE TABLE `xm_bulky_wms_area`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '（唯一）分区编码，限10字',
  `area_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区名称，限10字',
  `start_shelf` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '开始货架号',
  `end_shelf` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '结束货架号（>=开始货架号）',
  `ware_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '仓库类型 0-寻梦批发 1-城市仓',
  `sort_config` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架排序配置 0-正常排序 1-专放小件 2-专放大件 3-自提早班 4-特小件 5-自提 6-早班 7-代卖',
  `sub_area` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子区间配置',
  `segment_area` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分段配置',
  `pack_income_config` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区打包收益配置，限4096字',
  `delivery_income` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '配货收益配置 元每扎',
  `standby` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '区域类型 0:主场区 1:备用区 2:虚拟区 默认0',
  `sequence` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '排序 顺序',
  `remark` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注，限32字',
  `area_manager_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分区负责人id',
  `area_manager_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区负责人名称',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建用户id',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建用户姓名',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新用户id',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新用户姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态 0-关闭 1-启用',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_code`(`code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 114 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货货架分区表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_wms_area_snapshot
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_wms_area_snapshot`;
CREATE TABLE `xm_bulky_wms_area_snapshot`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '快照主键ID',
  `round_no` date NOT NULL COMMENT '快照所属场次',
  `area_id` int UNSIGNED NOT NULL COMMENT '来源xm_bulky_wms_area.id',
  `code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区编码快照',
  `area_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区名称快照',
  `start_shelf` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '开始货架号快照',
  `end_shelf` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '结束货架号快照',
  `ware_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '仓库类型快照',
  `sort_config` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架排序配置快照',
  `sub_area` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子区间配置快照',
  `segment_area` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分段配置快照',
  `pack_income_config` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区打包收益配置快照',
  `delivery_income` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '配货收益配置快照',
  `standby` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '备用区配置快照',
  `sequence` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '排序快照',
  `remark` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注快照',
  `area_manager_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '分区负责人ID快照',
  `area_manager_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区负责人名称快照',
  `operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '来源创建用户ID',
  `operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '来源创建用户名称',
  `last_operator_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '来源更新用户ID',
  `last_operator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '来源更新用户名称',
  `create_time` datetime NOT NULL COMMENT '来源创建时间',
  `update_time` datetime NOT NULL COMMENT '来源更新时间',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '来源状态快照 0-关闭 1-启用',
  `snapshot_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '快照生成时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_round_area`(`round_no` ASC, `area_id` ASC) USING BTREE,
  UNIQUE INDEX `uk_round_code`(`round_no` ASC, `code` ASC) USING BTREE,
  INDEX `idx_round_code_status`(`round_no` ASC, `code` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 68 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仓库分区场次快照表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_wms_express_package
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_wms_express_package`;
CREATE TABLE `xm_bulky_wms_express_package`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` tinyint NOT NULL DEFAULT 0 COMMENT '类型 1昆明-店 2昆明-仓 3仓-店',
  `round_no` date NOT NULL COMMENT '场次',
  `ware_id` int NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `partner_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商id',
  `province` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '目的省',
  `city` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '目的城市',
  `send_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货单号',
  `shelf_sn` int NOT NULL DEFAULT 0 COMMENT '货架号',
  `sub_shelf_sn` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `self_take_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '自提方式 0-非自提 1-自提不打包 2-自提打包',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  `min_shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '最小货架号（type=2时专用）',
  `max_shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '最大货架号（type=2时专用）',
  `serial_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '序号',
  `package_num` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '包裹数量 序号为1时填',
  `total_weight` decimal(10, 3) UNSIGNED NOT NULL DEFAULT 0.000 COMMENT '总重（kg）序号为1时填',
  `item_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '总扎数 序号为1时填',
  `express_id` bigint NOT NULL DEFAULT 0 COMMENT '物流表主键',
  `region_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '物流区域主键id',
  `origin_express_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '原物流id',
  `origin_region_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '原物流区域id',
  `express_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '航空物流 0 无 1 早 2 中 3 晚班 和订单表express_time枚举不一样',
  `express_status` tinyint NOT NULL DEFAULT 0 COMMENT '包裹状态 0:待打包 10:打包完成 20:发货完成',
  `pickup_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '揽收状态 0-待揽收 1-已揽收',
  `pickup_time` datetime NULL DEFAULT NULL COMMENT '揽收时间',
  `pickup_operator_id` bigint NULL DEFAULT 0 COMMENT '揽收操作账号id',
  `pickup_operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '揽收操作人名称快照',
  `pickup_abnormal` tinyint NOT NULL DEFAULT 1 COMMENT '揽收是否异常：1-异常(默认)、0-正常',
  `abnormal_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '揽收异常原因',
  `report_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '填报价格（物流商手动填报）',
  `waybill_price_id` bigint NULL DEFAULT NULL COMMENT '关联的第三方运单报价记录id，为空表示普通包裹报价',
  `reconcile_sub_bill_id` bigint NOT NULL DEFAULT 0 COMMENT '运费子对账单id，0=未生成包裹对账详情',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核驳回理由',
  `out_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '出库类型：0：打包出库 1：未打包出库',
  `express_actual_weight` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际重量，单位KG',
  `express_actual_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实际价格',
  `express_user_id` bigint NOT NULL DEFAULT 0 COMMENT '打包人id',
  `express_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '打包人姓名',
  `package_user_id` bigint NOT NULL DEFAULT 0 COMMENT '打包人id',
  `package_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '打包人姓名',
  `url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '打包完成url',
  `ship_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流url',
  `package_time` datetime NULL DEFAULT NULL COMMENT '打包完成时间',
  `express_modifier_id` bigint NOT NULL DEFAULT 0 COMMENT '物流修改人id',
  `express_modifier_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流修改人姓名',
  `express_modify_time` datetime NULL DEFAULT NULL COMMENT '物流修改时间',
  `express_time` datetime NULL DEFAULT NULL COMMENT '出库时间',
  `package_id` tinyint NOT NULL DEFAULT 0 COMMENT '物流包裹主键id',
  `package_info` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流包裹名称',
  `suggest_pack_id` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '推荐物流包裹主键id',
  `suggest_pack_info` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '推荐物流包裹名称',
  `valid_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有效包裹 0-否 1-是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`, `round_no`) USING BTREE,
  INDEX `idx_sendno_type`(`send_no` ASC, `type` ASC) USING BTREE,
  INDEX `idx_round_pickup`(`round_no` ASC, `pickup_flag` ASC, `express_status` ASC) USING BTREE,
  INDEX `idx_round_ware_pickup`(`round_no` ASC, `ware_id` ASC, `pickup_flag` ASC) USING BTREE,
  INDEX `idx_express_round_pickup`(`express_id` ASC, `round_no` ASC, `pickup_flag` ASC) USING BTREE,
  INDEX `idx_package_waybill_price_id`(`waybill_price_id` ASC) USING BTREE,
  INDEX `idx_package_send_outbound_quote`(`send_no` ASC, `express_status` ASC, `valid_status` ASC, `data_status` ASC, `report_price` ASC, `waybill_price_id` ASC) USING BTREE,
  INDEX `idx_round_send_ware_serial`(`round_no` ASC, `send_no` ASC, `ware_id` ASC, `serial_num` ASC) USING BTREE,
  INDEX `idx_package_reconcile_sub_bill`(`reconcile_sub_bill_id` ASC, `pickup_flag` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 980817210 AVG_ROW_LENGTH = 355 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流包裹打包状态' ROW_FORMAT = Dynamic PARTITION BY RANGE (year(`round_no`))
PARTITIONS 9
(PARTITION `p2023` VALUES LESS THAN (2024) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2024` VALUES LESS THAN (2025) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2025` VALUES LESS THAN (2026) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2026` VALUES LESS THAN (2027) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2027` VALUES LESS THAN (2028) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2028` VALUES LESS THAN (2029) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2029` VALUES LESS THAN (2030) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2030` VALUES LESS THAN (2031) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p_future` VALUES LESS THAN (MAXVALUE) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 )
;

-- ----------------------------
-- Table structure for xm_bulky_wms_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_wms_log`;
CREATE TABLE `xm_bulky_wms_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `ware_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '城市仓id',
  `round_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `shelf_sn` int NOT NULL COMMENT '货架号',
  `sub_shelf_sn` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '子货架号',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区',
  `shelf` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '货架',
  `zone_shelf` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区-货架',
  `enter_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '入场花材id',
  `operator_id` bigint NOT NULL COMMENT '操作人id',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人名称',
  `phone` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人手机号',
  `role_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人角色名称',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作描述',
  `op_num` int NOT NULL DEFAULT 0 COMMENT '操作扎数（可负）',
  `delivery_income` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '配货收益配置 元每扎',
  `lower_rank_level` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '降几级',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作备注',
  `pictures` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `video` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '视频',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`, `create_time`) USING BTREE,
  INDEX `idx_enteritemid`(`enter_item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19186 AVG_ROW_LENGTH = 237 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仓库管理操作日志表' ROW_FORMAT = Dynamic PARTITION BY RANGE (year(`create_time`))
PARTITIONS 4
(PARTITION `p2023` VALUES LESS THAN (2024) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2024` VALUES LESS THAN (2025) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `p2025` VALUES LESS THAN (2026) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `pmax` VALUES LESS THAN (MAXVALUE) ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 )
;

-- ----------------------------
-- Table structure for xm_bulky_wms_pre_income
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_wms_pre_income`;
CREATE TABLE `xm_bulky_wms_pre_income`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `zone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分区名称',
  `min_shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '最小货架号',
  `max_shelf_sn` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '最大货架号',
  `shelf_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '货架数量',
  `total_weight` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '总重量',
  `total_item_num` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '总扎数',
  `prepare_pre_income` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '配货预计收益',
  `package_pre_income` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '打包预计收益',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uni_date_zone`(`date` ASC, `zone` ASC) USING BTREE COMMENT '场次'
) ENGINE = InnoDB AUTO_INCREMENT = 721 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '统计每场次预计配货收益和打包收益等信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_wms_prepare_op
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_wms_prepare_op`;
CREATE TABLE `xm_bulky_wms_prepare_op`  (
