  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_date`(`date` ASC) USING BTREE,
  INDEX `idx_enter_item_id`(`enter_item_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 623 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仓库管理配货表，配货到人' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_xmpay_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_xmpay_log`;
CREATE TABLE `xm_bulky_xmpay_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增id',
