  `order_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `money` decimal(20, 2) UNSIGNED NOT NULL COMMENT '涉及金额',
  `business_type` tinyint UNSIGNED NOT NULL COMMENT '业务类型 0：付款 1：退款',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6747 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_yhsd_fee_refund_retry
-- ----------------------------
DROP TABLE IF EXISTS `xm_bulky_yhsd_fee_refund_retry`;
CREATE TABLE `xm_bulky_yhsd_fee_refund_retry`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_id` bigint UNSIGNED NOT NULL COMMENT '订单ID',
  `order_sn` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '订单号',
  `send_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '发货单号',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '业务场次',
  `amount` decimal(10, 2) NOT NULL COMMENT '待退小件分拣费',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0待重试 1处理中 2成功 3终态失败',
  `retry_count` int NOT NULL DEFAULT 0 COMMENT '已重试次数',
  `next_retry_time` datetime NOT NULL COMMENT '下次重试时间',
  `lock_until` datetime NULL DEFAULT NULL COMMENT '任务占用截止时间',
  `last_error` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最近失败原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_sn`(`order_sn` ASC) USING BTREE,
  INDEX `idx_status_next_retry`(`status` ASC, `next_retry_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '优花速达小件分拣费退费重试' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_bulky_zq_product
-- ----------------------------
