CREATE TABLE `xm_bulky_zq_product`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `zq_product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '珍情商品ID',
  `zq_second_id` bigint NOT NULL DEFAULT 0 COMMENT '珍情品类ID',
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '寻梦商品ID',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_zq_product_id`(`zq_product_id` ASC) USING BTREE,
  INDEX `idx_product_id`(`product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦珍情商品关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_chat_account
-- ----------------------------
DROP TABLE IF EXISTS `xm_chat_account`;
CREATE TABLE `xm_chat_account`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '账号名称',
  `avatar` varchar(155) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '聊天头像',
  `auto_reply` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '自定义自动回复内容',
  `online_status` tinyint NOT NULL DEFAULT 1 COMMENT '在线状态 1=>在线 -1=>离线',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '账号状态 1=>正常 -1=>注销',
  `create_time` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  `last_active_time` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最后活跃时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 43022 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦聊天账号表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_chat_account_user
-- ----------------------------
DROP TABLE IF EXISTS `xm_chat_account_user`;
CREATE TABLE `xm_chat_account_user`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `chat_account_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '聊天账号id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型 1-采购方 2-花艺师',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `role` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户角色 0=>普通用户  1=>聊天账号管理员',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1=>正常  -1=>删除',
  `update_time` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '加入时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_type_userid`(`type` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_account`(`chat_account_id` ASC) USING BTREE,
  INDEX `idx_userid`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 40779 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦聊天用户和账号绑定关系表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_chat_conversation
-- ----------------------------
DROP TABLE IF EXISTS `xm_chat_conversation`;
CREATE TABLE `xm_chat_conversation`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id(会话id)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 123 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会话表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_chat_message
-- ----------------------------
DROP TABLE IF EXISTS `xm_chat_message`;
CREATE TABLE `xm_chat_message`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `conv_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '会话id xm_chat_conversation.id',
  `msg_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '消息id',
  `sender_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '发送方用户id',
  `msg_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '消息类型 见代码枚举',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '内容',
  `is_auto_reply` tinyint NOT NULL DEFAULT 0 COMMENT '是否自动回复',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态 1:正常 -1:撤回 -2:删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_msgid`(`msg_id` ASC) USING BTREE,
  INDEX `idx_conv_time`(`conv_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1777 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦聊天消息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_chat_quick_reply
-- ----------------------------
DROP TABLE IF EXISTS `xm_chat_quick_reply`;
CREATE TABLE `xm_chat_quick_reply`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id xm_chat_account.id',
  `msg_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '消息类型 见枚举',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '内容',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态 1:正常 -1:删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_userid_status`(`user_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦聊天快捷回复表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_chat_user_conversation
-- ----------------------------
DROP TABLE IF EXISTS `xm_chat_user_conversation`;
CREATE TABLE `xm_chat_user_conversation`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id xm_chat_account.id',
  `chat_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '对方id 单聊是对方userid 群聊是群id',
  `conv_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '会话id',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '会话类型 1-私聊 2-群聊',
  `latest_read_msgid` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最新已读消息id xm_chat_message.id',
  `latest_msgid` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最新收到的消息id xm_chat_message.id',
  `unread` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '未读数量',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1=>正常 -1=>删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_userid_chatid_type`(`user_id` ASC, `chat_id` ASC, `type` ASC) USING BTREE,
  UNIQUE INDEX `uk_convid_userid`(`conv_id` ASC, `user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 251 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '寻梦聊天用户会话关系表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for xm_ckgl_operate_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_ckgl_operate_log`;
CREATE TABLE `xm_ckgl_operate_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作员id',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作员名称',
  `role_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '角色名称',
  `num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '操作数量',
  `lower_level_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '降级数量',
  `refund_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款数量',
  `is_confirm` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否确认 0：否 1：是（没有缺货、退货则不需要确认）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仓库管理操作日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_group_tag
-- ----------------------------
DROP TABLE IF EXISTS `xm_group_tag`;
CREATE TABLE `xm_group_tag`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `group_tag` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标签组名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人id',
  `operator_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `status` int NOT NULL DEFAULT 0 COMMENT '状态：0-正常 -100-删除',
  `enable_status` tinyint NOT NULL DEFAULT 1 COMMENT '标签体系重构-启用状态：0-停用 1-启用',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签体系重构-标签组说明（运营内部）',
  `group_type` tinyint NOT NULL DEFAULT 0 COMMENT '标签体系重构-体系归属：0-旧体系 1-新体系',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 50 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '专用标签组配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_help_operate_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_help_operate_record`;
CREATE TABLE `xm_help_operate_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `biz_type` tinyint NOT NULL DEFAULT 0 COMMENT '业务类型：1-供应商 2-寻梦采购端 3-城市仓采购端 4-博纳资材 5-优花速达 6-繁花惠',
  `user_id` bigint NOT NULL DEFAULT 0 COMMENT '用户id',
  `user_type` tinyint NOT NULL DEFAULT 0 COMMENT '用户类型： 1-用户自己 2-平台用户 3-系统',
  `operate_type` tinyint NOT NULL DEFAULT 0 COMMENT '操作类型：1-绑定 2-解绑 3-换绑',
  `old_help_id` bigint NOT NULL DEFAULT 0 COMMENT '原推广员id',
  `new_help_id` bigint NOT NULL DEFAULT 0 COMMENT '新推广员id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 87 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '推广员绑定操作日志记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_inspection_reason_config
-- ----------------------------
DROP TABLE IF EXISTS `xm_inspection_reason_config`;
CREATE TABLE `xm_inspection_reason_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `parent_id` bigint NOT NULL DEFAULT 0 COMMENT '父级ID；一级分类为0，二级原因为一级分类ID',
  `reason_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名或原因名',
  `level` int NOT NULL DEFAULT 1 COMMENT '层级：1分类，2原因',
  `sequence` int NOT NULL DEFAULT 0 COMMENT '排序值，升序展示',
  `create_user_id` bigint NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `create_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人姓名',
  `update_user_id` bigint NOT NULL DEFAULT 0 COMMENT '更新人ID',
  `update_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '数据状态：0正常，-100删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_parent_status`(`parent_id` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_level_status`(`level` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_sequence`(`sequence` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 152 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质检原因配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_inspection_reason_record
-- ----------------------------
DROP TABLE IF EXISTS `xm_inspection_reason_record`;
CREATE TABLE `xm_inspection_reason_record`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `enter_item_id` bigint NOT NULL DEFAULT 0 COMMENT '入场花材ID',
  `order_item_id` bigint NOT NULL DEFAULT 0 COMMENT '订单商品ID',
  `code_content` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单扎扫码内容',
  `op` int NOT NULL DEFAULT 0 COMMENT '质检操作类型',
  `reason_id` bigint NOT NULL DEFAULT 0 COMMENT '二级原因ID',
  `reason_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '二级原因名称快照',
  `parent_reason_id` bigint NOT NULL DEFAULT 0 COMMENT '一级分类ID快照',
  `parent_reason_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '一级分类名称快照',
  `user_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人ID',
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '数据状态：0正常，-100删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_enter_code_status`(`date` ASC, `enter_item_id` ASC, `code_content` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_reason_status`(`reason_id` ASC, `data_status` ASC) USING BTREE,
  INDEX `idx_op_status`(`op` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 662 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质检原因记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_inspection_recommend
-- ----------------------------
DROP TABLE IF EXISTS `xm_inspection_recommend`;
CREATE TABLE `xm_inspection_recommend`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `product_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品id',
  `enter_item_id` bigint NOT NULL COMMENT 'enterItemId',
  `round_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `item_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `rank_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '等级',
  `supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '供应商id',
  `supplier_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商名称',
  `supplier_tag` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '供应商基地',
  `defect` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '7天质检问题',
  `recommend_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '近7天推荐次数',
  `total_recommend_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '历史推荐次数',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '理由',
  `url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图片',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `operation_id` int NOT NULL DEFAULT 0 COMMENT '操作人',
  `operation_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `review_operation_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核人',
  `review_operation_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核人姓名',
  `review_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '审核时间',
  `review_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核意见',
  `status` int NOT NULL DEFAULT 0 COMMENT '0:待审核 1:通过 -1：驳回',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_roundNo_suuplierId_enterItem`(`round_no` ASC, `operation_id` ASC, `enter_item_id` ASC) USING BTREE,
  INDEX `idx_roundNo_product`(`round_no` ASC, `product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 44 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质检推荐表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_inspection_relation
-- ----------------------------
DROP TABLE IF EXISTS `xm_inspection_relation`;
CREATE TABLE `xm_inspection_relation`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `sub_account_id` bigint UNSIGNED NOT NULL COMMENT '子账号',
  `area_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区code',
  `date_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0正常 -100 删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 130 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质检区域绑定' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_logistics_account_config
-- ----------------------------
DROP TABLE IF EXISTS `xm_logistics_account_config`;
CREATE TABLE `xm_logistics_account_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配置名称',
  `supplier_id` bigint NOT NULL DEFAULT 0 COMMENT '商户Id',
  `source` tinyint NOT NULL DEFAULT 1 COMMENT '请求来源 1.大件批发 2.资材商城  3.资材商城新（物流固定配置不区分）',
  `logistics_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '类型  1-顺丰 2-中通 3-德邦 4.申通',
  `info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置json',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大件货物流客户账号配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_payment_user_config
-- ----------------------------
DROP TABLE IF EXISTS `xm_payment_user_config`;
CREATE TABLE `xm_payment_user_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` bigint NOT NULL DEFAULT 0 COMMENT '用户id',
  `nickname` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名称',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0-正常 -100-删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '打款用户配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_peasant_account_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_peasant_account_log`;
CREATE TABLE `xm_peasant_account_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `buy_id` bigint NOT NULL DEFAULT 0 COMMENT '购买供应商id',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '变动金额',
  `business_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '业务类型：0：订单支付 1：订单退款',
  `pay_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '支付方式 1： 余额支付 2：微信支付 ',
  `xm_refund_id` bigint NOT NULL DEFAULT 0 COMMENT '关联xm_peasant_refund表id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_orderId`(`order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 185 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '资金记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_peasant_cart
-- ----------------------------
DROP TABLE IF EXISTS `xm_peasant_cart`;
CREATE TABLE `xm_peasant_cart`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '购物车ID',
  `buy_supplier_id` bigint NOT NULL DEFAULT 0 COMMENT '购买供应商ID',
  `sku_id` bigint NOT NULL DEFAULT 0 COMMENT '规格ID',
  `temp_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '加入购物车时的价格',
  `sku_num` int NOT NULL DEFAULT 0 COMMENT '商品数量',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态：0=默认，-1=已提交，-100=已删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_skuId_supplierId_dataStatus`(`buy_supplier_id` ASC, `sku_id` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 190 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '购物车表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_peasant_class_first
-- ----------------------------
DROP TABLE IF EXISTS `xm_peasant_class_first`;
CREATE TABLE `xm_peasant_class_first`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `icon` varchar(521) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类图标',
  `sell_status` int NULL DEFAULT 1 COMMENT '销售状态 1-在售，0停售',
  `sort` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态：0=默认 -100=已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '一级分类表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_peasant_class_second
-- ----------------------------
DROP TABLE IF EXISTS `xm_peasant_class_second`;
CREATE TABLE `xm_peasant_class_second`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '二级分类ID',
  `first_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级分类ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `icon` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类图标',
  `sell_status` int NULL DEFAULT 1 COMMENT '销售状态 1-在售，0停售',
  `sort` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态：0=默认 -100=已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '二级分类表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_peasant_order
-- ----------------------------
DROP TABLE IF EXISTS `xm_peasant_order`;
CREATE TABLE `xm_peasant_order`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `buy_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '购买供应商id',
  `base_name` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '基地名称',
  `peasant_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售卖供应商id',
  `date` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '场次',
  `order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `order_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单价格',
  `total_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单合计金额=订单价格 + 其他（未后续扩展保留）',
  `origin_total_price` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '原本总价',
  `wx_price` decimal(20, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '微信支付金额',
  `flower_price_balance` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '供应商余额支付金额',
  `pay_type` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付方式  1：寻梦平台账户支付 2：微信支付',
  `take_ratio` decimal(3, 3) NULL DEFAULT 0.000 COMMENT '抽点比例',
  `open_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户标识',
  `mch_id` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信商户id',
  `out_trade_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信支付OutTradeNo',
  `receive_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人名称',
  `receive_tel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人手机号',
  `receive_address` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货地址',
  `buyer_memo` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '买家留言',
  `order_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单状态 0:待付款 1:已付款待发货 2:已发货待收货 3:已完成 4:已关闭 5:已取消',
  `after_sale_status` tinyint NOT NULL DEFAULT 0 COMMENT '售后标记 0:无售后 1:售后申请中 2:售后同意 3:售后拒绝',
  `refund_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户订单退款状态 0:无退款 1:申请退款中 2:退款成功 3:退款失败 4:极速退款中 5:极速退款成功 6:极速退款失败',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '付款时间',
  `ship_time` datetime NULL DEFAULT NULL COMMENT '发货时间',
  `ship_pic` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货照片',
  `complete_time` datetime NULL DEFAULT NULL COMMENT '订单完成时间',
  `complete_pic` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单完成图片',
  `complete_user_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单完成用户id',
  `complete_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单完成用户名称',
  `wx_pay_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信付款编号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0=默认 -100=已删除',
  `settle_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '结算标识 0：未结算 1：已结算',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_orderid`(`order_id` ASC) USING BTREE,
  INDEX `idx_data_baseanme`(`base_name` ASC, `date` ASC, `order_status` ASC) USING BTREE,
  INDEX `idx_buyid_status_time`(`buy_supplier_id` ASC, `order_status` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 284 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_peasant_order_item
-- ----------------------------
DROP TABLE IF EXISTS `xm_peasant_order_item`;
CREATE TABLE `xm_peasant_order_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '订单商品ID',
  `buy_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '购买供应商ID',
  `peasant_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售卖供应商ID',
  `order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单ID（用户订单号）',
  `goods_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `sku_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'SKU规格ID',
  `img` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `goods_info` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品信息',
  `sku_info` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'SKU规格信息',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单商品备注',
  `take_ratio` decimal(10, 3) NOT NULL DEFAULT 0.000 COMMENT '抽点比例',
  `price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付单价',
  `total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实付总价',
  `origin_total_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '原始总价',
  `num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '购买数量',
  `origin_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原始购买数量',
  `order_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单状态 0:待付款 1:待发货 2:待收货 3:完成 4:关闭 5:取消',
  `after_sale_status` tinyint NOT NULL DEFAULT 0 COMMENT '售后状态 0:无 1:申请中 2:同意 3:拒绝',
  `refund_status` tinyint NOT NULL DEFAULT 0 COMMENT '用户订单退款状态 0:无退款 1:申请退款中 2:退款成功 3:退款失败 4:极速退款中 5:极速退款成功 6:极速退款失败',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0=默认 -100=已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_orderid`(`order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 329 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_peasant_product
-- ----------------------------
DROP TABLE IF EXISTS `xm_peasant_product`;
CREATE TABLE `xm_peasant_product`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '商品ID',
  `second_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品所属类目ID',
  `peasant_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售卖供应商id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `description` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品描述',
  `goods_img` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品图',
  `images` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品详情说明图片集',
  `sort` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序',
  `sell_count` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '销量',
  `stock` int UNSIGNED NOT NULL DEFAULT 9999 COMMENT '库存',
  `min_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '价格(元)',
  `dn_min_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '斗南价格（元）',
  `sell_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '销售状态,1-在售，0-停售',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态：0=默认 -100=已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_secondId_name_sell_data_status`(`second_id` ASC, `name` ASC, `sell_status` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 AVG_ROW_LENGTH = 655 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_peasant_product_sku
-- ----------------------------
DROP TABLE IF EXISTS `xm_peasant_product_sku`;
CREATE TABLE `xm_peasant_product_sku`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'SKU ID',
  `goods_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格名称',
  `img` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '规格图片',
  `price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '价格(元)',
  `dn_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '斗南价格（元）',
  `weight` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '重量(克)',
  `min_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '起购',
  `max_num` int UNSIGNED NOT NULL DEFAULT 9999 COMMENT '限购',
  `stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '库存',
  `sort` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序',
  `sell_count` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '销量',
  `sell_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '销售状态,1-在售，0-停售',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '状态：0=默认 -100=已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_goodIds_sell_data_status`(`goods_id` ASC, `sell_status` ASC, `data_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 77 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品 SKU 表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_peasant_refund
-- ----------------------------
DROP TABLE IF EXISTS `xm_peasant_refund`;
CREATE TABLE `xm_peasant_refund`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '售后服务ID',
  `order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单ID',
  `buy_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '购买供应商ID',
  `reason` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '售后原因',
  `reason_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '原因类型',
  `images` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '截图',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '售后状态：0-售后中，1-同意，2-拒绝，3-完成，4-退款中，5-退款成功，6-退款失败，7-已取消',
  `total_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '订单总金额',
  `refund_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '售后类型：1-仅退款，2-退货退款 3-其他',
  `good_state` tinyint(1) NOT NULL DEFAULT 0 COMMENT '商品状态：1-完好，2-破损',
  `wx_refund_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信退款ID',
  `reject_reason` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝原因',
  `return_flag` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已退货 0-否 1-是',
  `success_time` datetime NULL DEFAULT NULL COMMENT '退款成功时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_orderid`(`order_id` ASC) USING BTREE,
  INDEX `idx_time`(`create_time` DESC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 111 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '农资售后表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_peasant_refund_item
-- ----------------------------
DROP TABLE IF EXISTS `xm_peasant_refund_item`;
CREATE TABLE `xm_peasant_refund_item`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `peasant_refund_id` bigint UNSIGNED NOT NULL COMMENT '售后ID',
  `peasant_supplier_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '售卖供应商ID',
  `order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `order_item_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单商品ID',
  `goods_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `sku_id` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT 'SKU ID',
  `sku_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '单价',
  `sku_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后数量',
  `total_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '退款总金额',
  `status` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后状态：0-售后中，1-同意，2-拒绝，3-完成，4-退款中，5-退款成功，6-退款失败，7-已取消',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_refundid`(`peasant_refund_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 139 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '农资售后商品明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_peasant_sub_account_supplier_rel
-- ----------------------------
DROP TABLE IF EXISTS `xm_peasant_sub_account_supplier_rel`;
CREATE TABLE `xm_peasant_sub_account_supplier_rel`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `sub_account_id` bigint NOT NULL COMMENT '子账号ID',
  `peasant_supplier_id` bigint NOT NULL COMMENT '农资供应商ID',
  `last_operator_id` bigint NULL DEFAULT NULL COMMENT '最近更新用户id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最近更新时间',
  `data_status` int NOT NULL DEFAULT 0 COMMENT '0:正常; -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sub_account_supplier`(`sub_account_id` ASC, `peasant_supplier_id` ASC) USING BTREE,
  INDEX `idx_peasant_supplier_id`(`peasant_supplier_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '子账号与农资供应商绑定关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_peasant_supplier_refund_log
-- ----------------------------
DROP TABLE IF EXISTS `xm_peasant_supplier_refund_log`;
CREATE TABLE `xm_peasant_supplier_refund_log`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `peasant_refund_id` bigint UNSIGNED NOT NULL COMMENT '售后ID',
  `peasant_refund_item_id` bigint UNSIGNED NOT NULL COMMENT '售后item ID',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人id',
  `operator_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人名称',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作描述',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作备注',
  `status` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '售后状态：0-售后中，1-同意，2-拒绝，3-完成，4-退款中，5-退款成功，6-退款失败，7-已取消',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_refund_id`(`peasant_refund_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 136 AVG_ROW_LENGTH = 237 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '农资售后日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_quality_check_config
-- ----------------------------
DROP TABLE IF EXISTS `xm_quality_check_config`;
CREATE TABLE `xm_quality_check_config`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `category_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '原因分类',
  `description_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原因描述json数组，例：[\"蓟马\",\"蚜虫\"]',
  `sort_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序值，越小越靠前',
  `operation_id` bigint UNSIGNED NULL DEFAULT 0 COMMENT '操作人id',
  `operation_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `data_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0:正常 -100:删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_category_name`(`category_name` ASC) USING BTREE,
  INDEX `idx_status_sort_num`(`data_status` ASC, `sort_num` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质检问题配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_sale_agency_statistics
-- ----------------------------
DROP TABLE IF EXISTS `xm_sale_agency_statistics`;
CREATE TABLE `xm_sale_agency_statistics`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `round_no` date NOT NULL COMMENT '场次：yyyy-mm-dd',
  `sale_num` int NOT NULL DEFAULT 0 COMMENT '卖花量(白场+晚场)',
  `amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '卖花金额(白场+晚场)',
  `sale_daytime_num` int NOT NULL DEFAULT 0 COMMENT '白场单量(扎数)',
  `daytime_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '白场卖花金额',
  `sale_night_num` int NOT NULL DEFAULT 0 COMMENT '晚场加单量(扎数)',
  `night_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '晚场加单卖花金额',
  `sale_operator_num` int NOT NULL DEFAULT 0 COMMENT '晚场自营单量(扎数)',
  `operator_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '晚场自营卖花金额',
  `sale_external_num` int NOT NULL DEFAULT 0 COMMENT '外部供应商单量(扎数)',
  `external_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '外部供应商卖花金额',
  `receive_num` int NOT NULL DEFAULT 0 COMMENT '收花量',
  `receive_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '收花金额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建日期',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_roundNo`(`round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1109 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '到场货数据统计表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for xm_zcpf_supplier
-- ----------------------------
DROP TABLE IF EXISTS `xm_zcpf_supplier`;
CREATE TABLE `xm_zcpf_supplier`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
