-- ----------------------------
-- Triggers structure for table xm_bulky_cold_out_task
-- ----------------------------
DROP TRIGGER IF EXISTS `trg_cold_task_remaining_bunch_insert`;
delimiter ;;
CREATE TRIGGER `trg_cold_task_remaining_bunch_insert` AFTER INSERT ON `xm_bulky_cold_out_task` FOR EACH ROW UPDATE xm_bulky_mall.xm_bulky_cold_stock
SET remaining_bunch_num=GREATEST(COALESCE(remaining_bunch_num,0)-CASE
  WHEN NEW.data_status=0 AND NEW.task_status=20 AND NEW.out_bunch_num>0 AND (NEW.store_type=2 OR NEW.out_type=3)
  THEN COALESCE(NEW.finish_bunch_num,NEW.out_bunch_num) ELSE 0 END,0)
WHERE id=NEW.cold_stock_id
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table xm_bulky_cold_out_task
-- ----------------------------
DROP TRIGGER IF EXISTS `trg_cold_task_remaining_bunch_update`;
delimiter ;;
CREATE TRIGGER `trg_cold_task_remaining_bunch_update` AFTER UPDATE ON `xm_bulky_cold_out_task` FOR EACH ROW UPDATE xm_bulky_mall.xm_bulky_cold_stock
SET remaining_bunch_num=GREATEST(COALESCE(remaining_bunch_num,0)
  + CASE WHEN OLD.data_status=0 AND OLD.task_status=20 AND OLD.out_bunch_num>0 AND (OLD.store_type=2 OR OLD.out_type=3) THEN COALESCE(OLD.finish_bunch_num,OLD.out_bunch_num) ELSE 0 END
  - CASE WHEN NEW.data_status=0 AND NEW.task_status=20 AND NEW.out_bunch_num>0 AND (NEW.store_type=2 OR NEW.out_type=3) THEN COALESCE(NEW.finish_bunch_num,NEW.out_bunch_num) ELSE 0 END,0)
WHERE id=NEW.cold_stock_id
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table xm_bulky_cold_stock
-- ----------------------------
DROP TRIGGER IF EXISTS `trg_cold_stock_remaining_bunch_insert`;
delimiter ;;
CREATE TRIGGER `trg_cold_stock_remaining_bunch_insert` BEFORE INSERT ON `xm_bulky_cold_stock` FOR EACH ROW SET NEW.remaining_bunch_num = CASE
  WHEN NEW.store_type = 2 THEN NEW.bunch_num
  ELSE NEW.remaining_bunch_num
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
